-- Biology part 1 of 2: longer explanations for BIO-0001 to BIO-1284 (Biology 12 and the first part of Biology 11).
-- Longer explanations: each question's "why" now says in two or three sentences why the key is right, and each wrong
-- option gets a sentence or two on the mistake behind it. Facts checked against the source textbook named in each
-- question's source. Stems, options and answer keys are unchanged: every UPDATE also matches on the current key, so a
-- question whose key was edited since is left alone. Safe to run twice.

UPDATE questions SET why = 'Homeostasis depends on three elements working as a loop. Receptors detect a change, the control centre processes the information and decides on a response, and effectors carry out that response to bring the body back to its set point.', wrong = '{"0": "Neurons and hormones are ways of carrying messages between parts of the loop. They are not the three named elements of homeostasis.", "1": "Enzymes and blood are not parts of the homeostatic loop. Only the control centre in this list is one of the three elements.", "3": "Kidneys and skin are organs that can act as effectors in some responses, but they are not the three basic elements of homeostasis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0001' AND answer = 2;
UPDATE questions SET why = 'Receptors, also called sensors, are specialised organs, tissues, cells or parts of cells that detect a change in the internal or external environment. They pass this information to the control centre, for example skin receptors that sense temperature.', wrong = '{"1": "Effectors are muscles and glands that act on messages from the control centre. They respond to a change rather than detect it.", "2": "A set point is the optimal value the body tries to keep, such as 37 °C. It is a target value, not a structure that detects change.", "3": "Control centres receive information from receptors, process it and send messages to effectors. They do not detect the change themselves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0002' AND answer = 0;
UPDATE questions SET why = 'A control centre receives information from receptors, processes it and sends a suitable message to the effectors. The brain, the spinal cord and the endocrine glands are the control centres in homeostasis, so endocrine glands fit here.', wrong = '{"0": "Skeletal muscles are effectors. They respond to messages from the control centre by contracting, for example during shivering.", "2": "Receptor cells in the skin detect changes such as temperature. They send information to the control centre but do not process it.", "3": "Sweat is the product of an effector response by sweat glands. It is a result of the loop, not a part that controls it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0003' AND answer = 1;
UPDATE questions SET why = 'Effectors are the parts of the body that respond to messages from the control centre. Muscles and glands are the effectors: muscles respond by contracting and glands by releasing their secretions, and this restores the internal environment to its set point.', wrong = '{"0": "The brain and spinal cord are control centres. They process information and send messages to effectors rather than carry out the response.", "1": "Thermoreceptors in the skin are receptors. They detect changes in temperature and pass the information to the control centre.", "2": "Pressure receptors in blood vessels are receptors. They detect changes in blood pressure and do not produce the response."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0004' AND answer = 3;
UPDATE questions SET why = 'When the body is too cold it must make more heat and lose less. Shivering is rapid muscle contraction that produces heat, and vasoconstriction narrows skin blood vessels so less heat is lost from the surface. Together they raise body temperature back to the set point.', wrong = '{"0": "Sweating and vasodilation both increase heat loss. They are the responses to overheating, not to a drop in temperature.", "1": "Shivering is correct, but vasodilation widens skin vessels and increases heat loss, which would work against warming the body.", "3": "Vasoconstriction is correct, but sweating cools the body by evaporation, which would lower the temperature even further."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0005' AND answer = 2;
UPDATE questions SET why = 'In negative feedback the output or product of a system reduces the activity of that same system. This keeps a variable close to its set point, and it is the most common form of regulation in the body, used for body temperature, blood glucose and hormone secretion.', wrong = '{"0": "In positive feedback the output increases the activity of the system and strengthens the original stimulus, the opposite of what is described.", "1": "Anhydrobiosis is a dormant state that some invertebrates, such as tardigrades, enter when they lose almost all their body water.", "2": "Osmoconformity means letting the concentration of body fluids match the environment. It is not a feedback mechanism."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0006' AND answer = 3;
UPDATE questions SET why = 'Negative feedback keeps a variable within narrow limits by switching off the response once the set point is reached. Body temperature, blood glucose level and hormone secretion are the common examples. When blood glucose rises, insulin lowers it, and the fall in glucose then reduces insulin release.', wrong = '{"0": "Uterine contractions in labour are controlled by positive feedback. Contractions cause oxytocin release, which causes stronger contractions until birth.", "2": "Blood clotting is a positive feedback process, in which each step speeds up the next so a clot forms rapidly.", "3": "Cytokines released in severe inflammation stimulate more immune activity. This is positive feedback, which can be harmful if not regulated."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0007' AND answer = 1;
UPDATE questions SET why = 'When body temperature rises above 37 °C, thermoreceptors in the hypothalamus detect the change. The thermoregulatory centre, also in the hypothalamus, acts as the control centre and sends messages to the sweat glands, which produce sweat to cool the body.', wrong = '{"1": "The pituitary gland releases oxytocin in the childbirth feedback loop. It is not the control centre for body temperature.", "2": "The medulla oblongata controls breathing, heart rate and blood pressure. Temperature control is the job of the hypothalamus.", "3": "The dermis of the skin contains receptors and effectors such as sweat glands, but the control centre for temperature is in the brain."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0008' AND answer = 0;
UPDATE questions SET why = 'Sweating lowers body temperature, and this output then acts back on the thermoreceptors. Once the set point is reached they stop sending signals to the control centre, so sweating stops. The output has influenced the receptors negatively, which is the definition of negative feedback.', wrong = '{"0": "Amplifying the original stimulus is what positive feedback does. Here the output removes the stimulus instead.", "1": "The output clearly affects the receptors, because the receptors stop signalling once the temperature is back to normal.", "3": "Nothing in this loop is amplified. The response switches itself off, so it is negative feedback, not positive feedback."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0009' AND answer = 2;
UPDATE questions SET why = 'Positive feedback increases the activity of a system and strengthens the original stimulus. It is less common than negative feedback and is used where a rapid, large change is needed and must be carried through to an end point, such as blood clotting and childbirth.', wrong = '{"0": "Keeping a value constant within narrow limits is the role of negative feedback, which switches the response off at the set point.", "2": "Day-to-day control of body temperature is a standard example of negative feedback through sweating, shivering and blood vessel changes.", "3": "Positive feedback does not stop a process at once. It keeps strengthening the process until an end point is reached, such as the birth of the baby."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0010' AND answer = 1;
UPDATE questions SET why = 'During labour, contractions of the uterus send nerve impulses to the hypothalamus. The hypothalamus signals the pituitary gland to release oxytocin, which causes stronger contractions, which send more impulses. Oxytocin is therefore the hormone in this positive feedback loop.', wrong = '{"1": "Thyroxine is secreted by the thyroid gland and controls the metabolic rate. It plays no part in uterine contractions.", "2": "Insulin is secreted by the beta cells of the pancreas and lowers blood glucose. It is not involved in labour.", "3": "Antidiuretic hormone (ADH) increases water reabsorption in the kidney. It controls urine concentration, not labour."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0011' AND answer = 0;
UPDATE questions SET why = 'In labour each contraction causes more oxytocin release, and more oxytocin causes stronger contractions. A positive feedback loop needs an outside end point to stop it. Here the loop keeps running until the baby is born, which removes the stimulus of stretching and contractions.', wrong = '{"0": "The start of oxytocin secretion begins the loop. Oxytocin release is what keeps the cycle going, not what ends it.", "1": "The uterus keeps sending nerve impulses with every contraction. If it stopped at the first one, the loop would never build up.", "2": "Body temperature is not part of the labour loop. A return to 37 °C relates to thermoregulation, not childbirth."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0012' AND answer = 3;
UPDATE questions SET why = 'In severe infection or inflammation, immune cells release proteins called cytokines that stimulate the immune response even more, which leads to the release of more cytokines. If this positive feedback is not properly controlled, it causes excessive inflammation and damages tissue.', wrong = '{"0": "Positive feedback amplifies the immune response. The danger is too much response, not a complete stop.", "1": "This loop is linked with excessive inflammation and tissue damage, not with a fall of body temperature below the set point.", "2": "The problem is the reverse. Immune cells keep releasing more cytokines, which is why the response grows out of control."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0013' AND answer = 3;
UPDATE questions SET why = 'Osmoregulation is the maintenance of the balance of water and solutes in the body fluids. It stops body fluids from becoming too dilute or too concentrated, which is needed for proper blood pressure, organ function and metabolism.', wrong = '{"0": "Thermoregulation is the control of internal body temperature within a tolerable range, not the balance of water and solutes.", "2": "Excretion is the removal of metabolic wastes such as ammonia, urea and uric acid. It is often linked to osmoregulation but is a separate process.", "3": "Anhydrobiosis is a dormant state some invertebrates enter after losing almost all their body water. It is survival, not regulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0014' AND answer = 1;
UPDATE questions SET why = 'Osmoconformers do not regulate the water and solute concentration of their body fluids. Instead they let it change to match the surrounding medium, so their body fluids stay isotonic, meaning of equal solute concentration, to the environment.', wrong = '{"0": "Osmoregulators actively keep their internal water and solute concentration constant even when the environment changes.", "1": "Homeotherms keep a constant body temperature. The term refers to temperature, not to water and solute balance.", "3": "Uricotelic animals excrete uric acid as their main nitrogenous waste. The term describes excretion, not osmotic balance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0015' AND answer = 2;
UPDATE questions SET why = 'Osmoconformers include all marine invertebrates, some freshwater invertebrates and some marine vertebrates such as hagfishes, sharks and rays. Hagfishes let their body fluids match sea water, so they are osmoconformers.', wrong = '{"1": "Freshwater bony fishes are osmoregulators. They pass large volumes of dilute urine and actively take up salts to stay hypertonic to fresh water.", "2": "Birds are terrestrial osmoregulators. They conserve water, for example by excreting uric acid, which needs very little water.", "3": "The kangaroo rat is a desert mammal that conserves water and can live on metabolic water alone, so it is an osmoregulator."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0016' AND answer = 0;
UPDATE questions SET why = 'An osmoconformer cannot control the concentration of its body fluids, so it simply follows its surroundings. It can only survive where the solute concentration stays fairly constant, and sea water is the typical example of such a stable environment.', wrong = '{"0": "Estuaries change salinity quickly. An animal that cannot regulate its body fluids would be damaged by these swings.", "1": "Deserts demand strong water conservation. Surviving there needs active osmoregulation, not conforming to the environment.", "2": "Osmoconformers are described in terms of solute concentration of the surroundings. High temperature is not the deciding factor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0017' AND answer = 3;
UPDATE questions SET why = 'Freshwater animals have a higher solute concentration in their body fluids than the surrounding water, so they are hypertonic to it. Water therefore keeps entering their bodies by osmosis, mainly across the gills, while salts such as Na⁺ and Cl⁻ diffuse out.', wrong = '{"0": "Being hypotonic and losing water by osmosis describes most marine animals, whose surroundings are saltier than their body fluids.", "2": "Isotonic body fluids with no net water movement describe osmoconformers, not freshwater animals.", "3": "Hypertonic is correct, but salts diffuse out of freshwater animals into the dilute water, not into the body."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0018' AND answer = 1;
UPDATE questions SET why = 'Freshwater fishes are hypertonic to their surroundings, so water keeps flowing into them by osmosis. They get rid of this excess water by producing large volumes of dilute urine. They make up for lost salts by actively transporting salts back into the body, and they rarely drink.', wrong = '{"0": "Drinking would only add to the water flooding in. Freshwater animals rarely drink, while marine fishes drink sea water.", "1": "Small volumes of concentrated urine are produced by marine fishes, which need to save water, not get rid of it.", "3": "Chloride cells pumping salt out of the blood are found in marine fishes, which have too much salt. Freshwater fishes need to gain salt."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0019' AND answer = 2;
UPDATE questions SET why = 'Marine fishes gain salt by diffusion from the sea and by drinking sea water. Chloride cells in the gills use energy from ATP to pump the excess salt out of the blood and back into the sea. This is active transport, since salt moves against its concentration gradient.', wrong = '{"1": "Marine fishes already have too much salt. Absorbing more from sea water is the problem they face, not the job of chloride cells.", "2": "In a marine fish, water leaves the body by osmosis because the sea is saltier. Chloride cells deal with salt, not water entry.", "3": "Ammonia is converted into urea in the liver, not in the gills. Chloride cells are concerned with salt removal."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0020' AND answer = 0;
UPDATE questions SET why = 'Some marine fishes, such as sharks, have rectal glands, which are salt-excreting glands in the rectum. They remove excess salts from the blood into the digestive tract, and the salts then leave the body along with the faeces.', wrong = '{"0": "Rectal glands are salt-removing glands. Absorbing water from the faeces is not their role.", "2": "Urine is produced by the kidneys. Rectal glands secrete salt, not dilute urine.", "3": "Rectal glands do not store anything. Storing uric acid as crystals is not related to their function."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0021' AND answer = 1;
UPDATE questions SET why = 'Land animals reduce water loss with fairly waterproof outer layers. Reptiles have waterproof scales made of keratin. Insects instead have a waxy exoskeleton of chitin, and mammals and birds have dead, keratinised skin cells along with oil-secreting glands in the skin.', wrong = '{"0": "Insects are covered by a waxy exoskeleton made of chitin. Keratin scales belong to reptiles.", "1": "Mammals have dead, keratinised skin cells and oil glands. A waxy chitin exoskeleton is found in insects.", "2": "Birds, like mammals, have keratinised skin and oil glands. A chitin exoskeleton belongs to insects."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0022' AND answer = 3;
UPDATE questions SET why = 'Metabolic water is water produced as a by-product of cellular respiration. The kangaroo rat, a desert rodent, can survive entirely on this water. It feeds on carbohydrate-rich seeds and avoids daytime heat, so it hardly needs to drink at all.', wrong = '{"1": "The kangaroo rat lives in deserts where water is scarce. It survives without drinking, relying on metabolic water.", "2": "Excreting ammonia needs large amounts of water, about 500 mL per gram, which only aquatic animals can afford.", "3": "Dormancy lasting years until water returns is anhydrobiosis, described for tardigrades, not for the kangaroo rat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0023' AND answer = 0;
UPDATE questions SET why = 'Anhydrobiosis is a dormant state that certain invertebrates, such as tardigrades (water bears), enter when they lose almost all their body water. They can stay in this state for years and return to active life when water becomes available again.', wrong = '{"0": "Hibernation is a winter dormancy linked to cold and food shortage. The trigger here is loss of body water.", "1": "Osmoconformity means body fluids stay isotonic with the surroundings. It is not a dormant state after drying out.", "3": "Thermoregulation is control of body temperature. It has nothing to do with surviving the loss of body water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0024' AND answer = 2;
UPDATE questions SET why = 'Ammonia is highly toxic and very soluble, so it must be diluted with a lot of water. One gram of ammonia needs about 500 mL of water to bring it to a non-toxic level. Only freshwater animals, which have plenty of water, can afford to excrete ammonia.', wrong = '{"0": "50 mL per gram is the amount of water needed for urea, which is less toxic than ammonia.", "1": "1 mL per gram is the figure for uric acid, the least toxic of the three wastes and the one that saves most water.", "2": "5 mL is far too little. Ammonia is the most toxic nitrogenous waste and needs about 500 mL of water per gram."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0025' AND answer = 3;
UPDATE questions SET why = 'Animals are named after their main nitrogenous waste. Those that excrete mostly ammonia are called ammonotelic. Examples are most fishes, protozoans, sponges and coelenterates, which live in water and can afford the large volume of water ammonia needs.', wrong = '{"1": "Ureotelic animals, such as mammals, excrete mainly urea, which is made from ammonia in the liver.", "2": "Uricotelic animals, such as birds, insects and most reptiles, excrete mainly uric acid to save water.", "3": "Osmoconformers are named for how they handle water and solute balance, not for the type of nitrogenous waste they excrete."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0026' AND answer = 0;
UPDATE questions SET why = 'Ammonia is very toxic and needs about 500 mL of water per gram to dilute it, so only animals living in plenty of water can excrete it. Sponges are aquatic, along with most fishes, protozoans and coelenterates, so they are ammonotelic.', wrong = '{"0": "Birds must save water, so they excrete uric acid, which needs only about 1 mL of water per gram. They are uricotelic.", "2": "Insects face an extreme water-saving challenge on land and excrete uric acid, so they are uricotelic.", "3": "Most reptiles live in dry conditions and excrete uric acid to conserve water, so they are uricotelic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0027' AND answer = 1;
UPDATE questions SET why = 'Uric acid is a by-product of the breakdown of purines, produced in the liver. Normally most of it is excreted in urine, but when its level in blood is too high, uric acid crystals form in joints and tissues. This painful condition is called gout.', wrong = '{"0": "Diabetes mellitus is a problem of blood glucose control caused by a lack of insulin or poor response to it.", "1": "Goitre is an enlargement of the thyroid gland, usually caused by iodine deficiency, not by uric acid.", "3": "Anhydrobiosis is a dormant state some invertebrates enter after losing almost all their body water. It is not a human disease."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0028' AND answer = 2;
UPDATE questions SET why = 'Uric acid is made in the liver as a by-product of breaking down purines. Purines are nitrogen-containing bases found in nucleic acids and in many foods, especially meat. Humans excrete a small amount of this uric acid in urine.', wrong = '{"1": "Fatty acids contain only carbon, hydrogen and oxygen. With no nitrogen, they cannot give rise to a nitrogenous waste such as uric acid.", "2": "Glucose contains no nitrogen. It is broken down to carbon dioxide and water, not to uric acid.", "3": "Cholesterol is a lipid made of carbon, hydrogen and oxygen. It is not a source of uric acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0029' AND answer = 0;
UPDATE questions SET why = 'Uric acid is less toxic than urea and ammonia. It is poorly soluble in water and forms precipitates, so one gram can be excreted with only about 1 mL of water. The cost is that converting ammonia to uric acid uses a lot of energy.', wrong = '{"0": "Being the most toxic and very soluble describes ammonia, which needs about 500 mL of water per gram.", "1": "About 50 mL of water per gram is the figure for urea, not uric acid.", "3": "Making uric acid is costly. Animals that excrete it spend a lot of energy converting ammonia into uric acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0030' AND answer = 2;
UPDATE questions SET why = 'Insects, birds, desert animals and most reptiles face an extreme need to save water and cannot even afford to excrete urea. They spend a lot of energy converting ammonia into uric acid, which is less toxic, poorly soluble and needs only about 1 mL of water per gram.', wrong = '{"0": "Birds are uricotelic, and uric acid is less toxic than urea, not more. Both parts of this statement are wrong.", "2": "Freshwater fishes have plenty of water and excrete ammonia directly. They are mostly ammonotelic.", "3": "Uric acid is less soluble than urea. It forms precipitates, which is why it needs so little water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0031' AND answer = 1;
UPDATE questions SET why = 'The lipid bilayer of the cell membrane is sensitive to temperature. At high temperatures the membrane can lose its selective permeability, so it no longer controls what enters and leaves the cell. This is one reason body temperature must stay within a tolerable range.', wrong = '{"0": "Low temperatures do the opposite. They make membranes rigid and brittle, not more fluid and leaky.", "1": "The cell membrane is a lipid bilayer, and these lipids are sensitive to temperature changes.", "2": "Membranes become rigid and brittle at low temperatures. High temperatures cause loss of selective permeability."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0032' AND answer = 3;
UPDATE questions SET why = 'Every enzyme has an optimum temperature. Below it, molecules move more slowly, so enzymes and substrates collide less often and the metabolic rate drops. This effect is reversible, unlike the damage caused by very high temperatures.', wrong = '{"0": "Permanent denaturation happens when temperature rises well above the optimum, not when it falls below it.", "1": "Enzymes work fastest at their optimum temperature. Below the optimum their activity slows down.", "2": "Loss of selective permeability is caused by high temperature. Low temperature makes membranes rigid and brittle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0033' AND answer = 3;
UPDATE questions SET why = 'A lizard is an ectotherm, so it gets most of its heat from outside and controls its temperature through behaviour. Pressing its body against a warm rock transfers heat by direct contact, which is conduction. Basking in sunlight would be gaining heat by radiation.', wrong = '{"0": "Lizards are ectotherms. Burning brown adipose tissue to make heat is a response of endotherms such as mammals.", "1": "Ectotherm is correct, but heat gained by touching a warm surface is conduction. Radiation is heat gained from the sun.", "3": "Reptiles are poikilotherms. Shivering to produce heat is a response of endotherms such as birds and mammals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0034' AND answer = 2;
UPDATE questions SET why = 'Ectotherms such as fishes, amphibians and reptiles have a very low metabolic rate. They cannot produce enough internal heat to raise and keep a steady body temperature, so they depend on heat from the environment and use behaviour, such as basking, to control it.', wrong = '{"1": "Fishes, amphibians and reptiles do have a hypothalamus. Their dependence on outside heat comes from their low metabolic rate.", "2": "Insulation by fat, hair or feathers is a feature of endotherms. It helps keep internally produced heat in the body.", "3": "Ectotherms can move. They move into the sun, onto warm rocks or into shade as a way of controlling their temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0035' AND answer = 0;
UPDATE questions SET why = 'Endotherms generate most of their heat internally. In the cold they shiver, which is muscle contraction that produces heat, or burn brown adipose tissue, a special fat that releases heat. Ectotherms have too low a metabolic rate to make heat this way.', wrong = '{"0": "Basking in the sun to gain heat by radiation is a behavioural method used by ectotherms such as lizards.", "2": "Sitting on a warm rock to gain heat by conduction is a behavioural method used by ectotherms.", "3": "Becoming dormant during the coldest months is described for ectotherms living in very cold climates."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0036' AND answer = 1;
UPDATE questions SET why = 'Poikilotherms let their body temperature change with the surroundings, so they do not burn large amounts of food to keep a constant temperature. Needing much less food lets them survive in nutrient-poor environments where a homeotherm would starve.', wrong = '{"0": "Keeping a constant body temperature in all climates is the feature of homeotherms such as birds and mammals.", "1": "Poikilotherms usually have a low metabolic rate. A high metabolic rate is typical of animals that make their own heat.", "3": "All animals with tissues and organs have a nervous system. This has nothing to do with being a poikilotherm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0037' AND answer = 2;
UPDATE questions SET why = 'Humans produce most of their body heat by internal metabolism, so they are endotherms. They also keep their body temperature roughly constant at about 37 °C in both hot and cold surroundings, so they are homeotherms. Together this makes them endothermic homeotherms.', wrong = '{"0": "Humans do not depend on outside heat sources. They are endothermic, not ectothermic.", "2": "Humans are endothermic, but they keep their body temperature within narrow limits, so they are not poikilotherms.", "3": "Ectothermic poikilotherms describe fishes, amphibians and reptiles, whose temperature follows the environment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0038' AND answer = 1;
UPDATE questions SET why = 'When body temperature rises above 37 °C, the body tries to lose heat and make less of it. Along with vasodilation and sweating, the thyroid gland may reduce thyroxine secretion. Less thyroxine lowers the basal metabolic rate, so less heat is produced inside the body.', wrong = '{"1": "Constriction of skin capillaries reduces heat loss. It is a response to cooling, not to overheating.", "2": "Shivering produces heat through rapid muscle contraction. It happens when body temperature falls below 37 °C.", "3": "Contraction of hair erector muscles (goosebumps) traps air to keep heat in. It is a response to cold."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0039' AND answer = 0;
UPDATE questions SET why = 'Vasodilation is the widening of blood capillaries that lie just beneath the epidermis. More blood then flows close to the skin surface, so more heat passes from the blood to the surroundings. This helps bring body temperature back down to 37 °C.', wrong = '{"0": "Reducing blood flow to the skin is vasoconstriction. It keeps heat inside the body and is a response to cold.", "1": "Shivering is a separate response by skeletal muscles that produces heat. Vasodilation does not cause it.", "2": "A higher basal metabolic rate produces more heat. In overheating, the metabolic rate is lowered instead."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0040' AND answer = 3;
UPDATE questions SET why = 'Thermoreceptors send signals not only to the hypothalamus but also to the higher centres of the brain. This is why we consciously feel warm or cold. That feeling leads to voluntary actions, such as taking a bath or switching on a fan or heater.', wrong = '{"0": "Sweat glands are effectors that respond to messages from the hypothalamus. Conscious feeling arises in the brain, not in sweat glands.", "1": "The thyroid gland changes the metabolic rate by altering thyroxine secretion. It does not produce the sensation of warmth or cold.", "2": "The adrenal medulla secretes adrenaline in stress. It is not where the conscious feeling of temperature arises."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0041' AND answer = 3;
UPDATE questions SET why = 'In the cold, tiny muscles at the base of the hair follicles contract and pull the hairs upright, giving goosebumps. The raised hairs trap a layer of still air close to the skin. Air is a poor conductor of heat, so it acts as an insulator and reduces heat loss.', wrong = '{"0": "Sweating cools the body by evaporation. It is a response to overheating, not to cold.", "1": "Widening skin capillaries is vasodilation, which increases heat loss. In cold the capillaries narrow instead.", "3": "In cold the metabolic rate increases to produce more heat. Goosebumps work by insulation, not by changing metabolism."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0042' AND answer = 2;
UPDATE questions SET why = 'Besides removing urea and controlling water balance, the urinary system balances sodium, potassium and hydrogen ions in the blood. This keeps blood slightly basic, at a pH of about 7.4. Secretion of H⁺ into the filtrate is one way the kidneys do this.', wrong = '{"0": "A pH of 6.4 is acidic. Blood at this pH would be dangerously acidic, not slightly basic.", "1": "A pH of 8.4 is far more basic than normal blood and would be life-threatening.", "3": "A pH of 7.0 is exactly neutral. Normal blood is slightly basic, a little above 7."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0043' AND answer = 2;
UPDATE questions SET why = 'In humans, ammonia from protein breakdown is converted into urea in the liver. Urea, which is less toxic than ammonia, is carried in the blood to the kidneys, which filter it out and excrete it in urine. Humans are therefore ureotelic.', wrong = '{"0": "Ammonia is too toxic to build up in human blood. The liver converts it into urea before it reaches the kidneys.", "2": "Humans excrete only a small amount of uric acid, which comes from purine breakdown. Urea is the main nitrogenous waste.", "3": "Glucose contains no nitrogen and is not a waste. It is filtered but then fully reabsorbed in the proximal tubule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0044' AND answer = 1;
UPDATE questions SET why = 'The kidneys lie high in the abdominal cavity, one on each side of the vertebral column, between the 12th thoracic and 3rd lumbar vertebrae. Their upper parts are partly protected by the 11th and 12th ribs.', wrong = '{"0": "The 1st to 5th lumbar vertebrae lie lower down. The kidneys start higher, at the level of the 12th thoracic vertebra.", "1": "The 7th cervical to 12th thoracic vertebrae span the neck and chest region, which is too high for the kidneys.", "2": "The sacral vertebrae are in the pelvis, far below the kidneys. This region lies near the urinary bladder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0045' AND answer = 3;
UPDATE questions SET why = 'The liver is a large organ on the right side of the upper abdomen, just above the right kidney. Because the liver takes up this space, the right kidney sits slightly lower, and is also slightly smaller, than the left kidney.', wrong = '{"1": "The heart is in the thoracic cavity above the diaphragm. It does not press on either kidney.", "2": "The stomach lies mainly on the left side of the abdomen, so it cannot explain why the right kidney is lower.", "3": "The spleen is on the left side of the abdomen. It is near the left kidney, not the right one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0046' AND answer = 0;
UPDATE questions SET why = 'Each ureter is a tube about 25 cm long. It begins at the funnel-shaped renal pelvis of the kidney and runs downward to open into the single urinary bladder. Its muscular walls move urine along to the bladder.', wrong = '{"0": "5 cm is far too short. The ureter must run from the kidney high in the abdomen down to the bladder in the pelvis.", "1": "50 cm is about twice the real length. The ureter is about 25 cm long.", "2": "2.5 cm is ten times too short. This figure would not reach from the kidney to the bladder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0047' AND answer = 3;
UPDATE questions SET why = 'The renal hilum is a depressed area on the concave side of the kidney. Here the renal artery enters to bring blood in, and the renal vein and the ureter leave, carrying filtered blood and urine away from the kidney.', wrong = '{"0": "This reverses the direction of blood flow. The renal artery brings blood into the kidney and the renal vein carries it out.", "1": "The urethra carries urine from the urinary bladder to the outside. It is not attached to the kidney.", "3": "The adrenal gland sits on top of each kidney, not at the hilum on its concave side."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0048' AND answer = 2;
UPDATE questions SET why = 'Inside the kidney there are two regions. The outer renal cortex makes up about one-third of the kidney''s mass, and the inner renal medulla makes up the remaining two-thirds.', wrong = '{"0": "The cortex and medulla are not equal. The medulla is the larger part, about two-thirds of the mass.", "2": "Two-thirds is the share of the renal medulla, the inner part made of renal pyramids.", "3": "One-fifth is the fraction of plasma that is filtered into Bowman''s capsule, not the share of the cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0049' AND answer = 1;
UPDATE questions SET why = 'The kidney has an outer cortex and an inner medulla. The renal medulla is made up of a number of cone-shaped renal pyramids. Their tips point towards the renal pelvis, where urine is collected.', wrong = '{"1": "The renal cortex is the outer region. It contains the renal corpuscles and convoluted tubules, not the pyramids.", "2": "The renal pelvis is the funnel-shaped space in the centre of the kidney that collects urine and leads into the ureter.", "3": "The renal capsule is the fibrous outer covering around the kidney. It has no pyramids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0050' AND answer = 0;
UPDATE questions SET why = 'Nephrons are the microscopic tubules that form urine, so they are the functional units of the kidney. Each human kidney contains about one million of them, which gives a very large total surface for filtration and reabsorption.', wrong = '{"1": "One thousand is about a thousand times too few. Each kidney has roughly one million nephrons.", "2": "One hundred million is about a hundred times too many. The accepted figure is about one million per kidney.", "3": "Ten thousand is about a hundred times too few. Each kidney has roughly one million nephrons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0051' AND answer = 0;
UPDATE questions SET why = 'A nephron has two main parts: the renal corpuscle and the renal tubule. The renal corpuscle is made of the glomerulus, a network of capillaries from the afferent arteriole, and Bowman''s capsule, the cup-shaped double-walled sac that surrounds it.', wrong = '{"0": "The loop of Henle is part of the renal tubule, and the collecting duct lies beyond the nephron, collecting from many nephrons.", "1": "The proximal and distal convoluted tubules are the coiled parts of the renal tubule, not the renal corpuscle.", "3": "The afferent and efferent arterioles bring blood to and from the glomerulus, but they are not the corpuscle itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0052' AND answer = 2;
UPDATE questions SET why = 'Filtrate forms in Bowman''s capsule. It then flows into the highly coiled proximal convoluted tubule, down and up the U-shaped loop of Henle, and into the distal convoluted tubule, which drains into a collecting duct.', wrong = '{"0": "The proximal convoluted tubule comes straight after Bowman''s capsule, before the loop of Henle, not after it.", "1": "Filtrate is first formed in Bowman''s capsule, so the capsule must come before the proximal tubule.", "2": "After the capsule this order is reversed. The proximal tubule comes first and the distal tubule comes last."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0053' AND answer = 3;
UPDATE questions SET why = 'The distal convoluted tubules of several nephrons drain into one collecting duct. As collecting ducts pass down through the medulla, they join to form larger papillary ducts, which empty urine into the renal pelvis.', wrong = '{"0": "Ureters begin at the renal pelvis and leave the kidney at the hilum. They are not formed inside the cortex by collecting ducts.", "2": "Loops of Henle are part of each nephron and come before the distal tubule, so they lie upstream of the collecting ducts.", "3": "Afferent arterioles are blood vessels that carry blood into the glomerulus. They do not carry urine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0054' AND answer = 1;
UPDATE questions SET why = 'Juxtamedullary nephrons begin deep in the cortex near the medulla. Their loops of Henle are long and dip deep into the renal medulla, which helps make concentrated urine. Cortical nephrons have short loops.', wrong = '{"1": "About 85% of nephrons are cortical nephrons. Juxtamedullary nephrons are the smaller group.", "2": "Lying mainly in the renal cortex describes cortical nephrons. Juxtamedullary nephrons sit near the medulla.", "3": "Both types of nephron have a loop of Henle. The difference is the length of the loop."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0055' AND answer = 0;
UPDATE questions SET why = 'The kidneys are highly vascular organs. Although they are small, they receive about 20 to 25% of the total cardiac output, because a large volume of blood must pass through them to be filtered continuously.', wrong = '{"0": "2 to 5% is far too low for organs that filter the whole blood volume many times a day.", "2": "50 to 60% is far too high. The rest of the body, including the brain and muscles, also needs a large share.", "3": "75% is far too high. If the kidneys took three-quarters of the cardiac output, other organs would be starved of blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0056' AND answer = 1;
UPDATE questions SET why = 'Most capillary beds drain into venules. The glomerulus is unusual because its capillaries drain into another arteriole, the efferent arteriole. This arteriole then branches again into the peritubular capillaries around the tubules.', wrong = '{"0": "Blood from the glomerulus first passes through the efferent arteriole and peritubular capillaries before reaching veins and the renal vein.", "1": "Glomerular capillaries are supplied by the renal artery through afferent arterioles, so they carry oxygenated blood.", "2": "Glomeruli lie inside Bowman''s capsules in the cortex. The capillaries around the loops of Henle in the medulla are the vasa recta."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0057' AND answer = 3;
UPDATE questions SET why = 'In juxtamedullary nephrons, the efferent arterioles give rise to the vasa recta. These are long, straight capillaries in the medulla that run parallel to the loops of Henle. Water drawn out of the collecting duct enters the blood through them.', wrong = '{"0": "The capillaries inside Bowman''s capsule form the glomerulus, which is the site of filtration.", "1": "The vasa recta come from efferent arterioles. They join venules only after exchange, and are not branches of the renal vein.", "3": "Tubes that carry urine to the bladder are the ureters. The vasa recta are blood capillaries."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0058' AND answer = 2;
UPDATE questions SET why = 'After exchange in the kidney, capillaries join into venules and then larger veins, which form the renal vein. The renal vein leaves the kidney at the hilum and drains into the inferior vena cava, which returns the cleaned blood to the heart.', wrong = '{"0": "The superior vena cava drains blood from the head, neck and arms. The kidneys lie below the heart.", "2": "The hepatic portal vein carries blood from the digestive tract to the liver, not from the kidneys.", "3": "The aorta is an artery that carries blood away from the heart. The renal artery branches from it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0059' AND answer = 1;
UPDATE questions SET why = 'Blood enters the glomerulus through the afferent arteriole and leaves through the efferent arteriole. The efferent arteriole is narrower, so blood cannot leave as easily as it enters. This keeps the pressure in the glomerulus high and drives filtration.', wrong = '{"0": "This reverses the true sizes. A narrower inlet and wider outlet would lower glomerular pressure.", "1": "The glomerulus drains into the efferent arteriole, not a venule, and this is part of why pressure stays high.", "3": "The ureter does not block the renal vein in a healthy kidney. High pressure comes from the narrow efferent arteriole."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0060' AND answer = 2;
UPDATE questions SET why = 'High pressure pushes small molecules from the glomerulus into Bowman''s capsule, but plasma proteins such as albumin and globulins are too large to pass through the capillary walls. Albumin, like blood cells, therefore stays in the blood.', wrong = '{"1": "Glucose is a small molecule, so it is filtered into the capsule. It is then reabsorbed in the proximal tubule.", "2": "Urea is small and is filtered into the capsule. Much of it stays in the filtrate and is excreted in urine.", "3": "Amino acids are small enough to be filtered. They are then reabsorbed by active transport in the proximal tubule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0061' AND answer = 0;
UPDATE questions SET why = 'As blood passes through the glomerulus, about one-fifth (20%) of its fluid portion, the plasma, is forced into Bowman''s capsule. This fluid is the glomerular filtrate. The other four-fifths stays in the blood and leaves through the efferent arteriole.', wrong = '{"0": "One-half is too high. Removing so much fluid would make the blood too thick to flow onward.", "1": "Three-quarters is far too high. Only about one-fifth of the plasma is filtered.", "2": "One-hundredth is far too low. About 20% of the plasma is filtered, not 1%."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0062' AND answer = 3;
UPDATE questions SET why = 'The proximal convoluted tubule is where most reabsorption happens. Most of the filtered water returns to the blood here by osmosis, and glucose, amino acids and salts are taken back by active transport into the peritubular capillaries.', wrong = '{"0": "The distal convoluted tubule reabsorbs only some water and salts. It is also a site of tubular secretion.", "1": "The collecting duct is the final site of water reabsorption, adjusted by ADH, but it does not reabsorb the most.", "2": "The ascending limb pumps salts out but is impermeable to water, so it cannot be the main site of reabsorption."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0063' AND answer = 3;
UPDATE questions SET why = 'Glucose and amino acids are moved from the proximal tubule back into the blood by active transport. Carrier proteins use energy from ATP, which lets the tubule recover all of these useful nutrients even against a concentration gradient. Water then follows by osmosis.', wrong = '{"1": "Osmosis is the movement of water across a membrane. It does not move glucose or amino acids.", "2": "Filtration under pressure happens at the glomerulus and moves substances into the nephron, not back into the blood.", "3": "Tubular secretion moves substances from the blood into the filtrate, the opposite direction to reabsorption."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0064' AND answer = 0;
UPDATE questions SET why = 'When blood salt concentration falls after drinking a lot of water, the hypothalamus stops ADH secretion. The collecting duct walls become less permeable to water, so less water is reabsorbed and a large volume of dilute urine is excreted. Blood volume and pressure fall back to normal.', wrong = '{"0": "Rising ADH and concentrated urine are the response to dehydration or salty food, when water must be conserved.", "1": "Aldosterone is released when blood pressure or sodium is low. Retaining sodium and passing less urine would not remove extra water.", "3": "When ADH secretion stops, the collecting ducts become less permeable, not more, and blood volume falls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0065' AND answer = 2;
UPDATE questions SET why = 'The ascending limb of the loop of Henle is impermeable to water but actively pumps salts out of the tubule. This makes the fluid of the medulla salty while the filtrate inside becomes more dilute as it rises toward the cortex.', wrong = '{"0": "The descending limb is permeable to water but not to salts, the reverse of what is described.", "2": "Bowman''s capsule receives the glomerular filtrate. It is not part of the loop of Henle.", "3": "The proximal convoluted tubule reabsorbs much water and salt, but it comes before the loop and is not part of it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0066' AND answer = 1;
UPDATE questions SET why = 'In tubular secretion, cells of the distal tubule take hydrogen ions from the blood and secrete them into the filtrate. Removing H⁺ in this way stops the blood from becoming too acidic, so it helps keep blood pH near 7.4.', wrong = '{"0": "Calcium ions are reabsorbed from the proximal tubule into the blood. They are not secreted to control pH.", "1": "Chloride ions follow sodium out of the ascending limb into the medulla. They are not secreted to adjust pH.", "2": "Glucose is not an ion and does not affect pH here. It is fully reabsorbed in the proximal tubule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0067' AND answer = 3;
UPDATE questions SET why = 'Tubular secretion moves substances from the blood around the tubule into the filtrate. Cells of the distal tubule secrete hydrogen ions, ammonium, potassium ions, toxins and drug residues such as penicillin, so these leave the body in urine.', wrong = '{"1": "Selective reabsorption returns useful substances from the filtrate to the blood. It would keep penicillin in the body.", "2": "The counter-current mechanism keeps the medulla salty so water can be reabsorbed. It does not remove drugs.", "3": "The urethra only carries urine out of the bladder. Substances do not diffuse into urine through its walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0068' AND answer = 0;
UPDATE questions SET why = 'Urine volume depends on how much water the body needs to keep. A diet high in salt raises the salt concentration of the blood, so the body retains water to dilute it. More water is reabsorbed and urine output falls.', wrong = '{"0": "Drinking more fluids adds extra water to the body, so the kidneys pass more urine, not less.", "1": "Low ADH makes collecting ducts less permeable, so less water is reabsorbed and urine volume increases.", "3": "In cool weather little water is lost as sweat, so the kidneys do not need to conserve water and urine volume rises."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0069' AND answer = 2;
UPDATE questions SET why = 'The ascending limb pumps Na⁺ out and Cl⁻ follows, so the fluid around the loop and collecting duct stays very salty. Water then leaves the descending limb and the collecting duct by osmosis into this salty fluid and returns to the blood through the vasa recta.', wrong = '{"0": "Water is never pumped actively. It always moves by osmosis toward the saltier fluid.", "2": "The ascending limb is impermeable to water. This is essential, because it lets salt leave without water following.", "3": "A high, not low, salt concentration in the medulla is needed to draw water out of the tubules."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0070' AND answer = 1;
UPDATE questions SET why = 'The descending limb is permeable to water but not to salts. As filtrate moves down into the salty medulla, water leaves by osmosis while the salts stay inside, so the filtrate becomes more concentrated toward the bottom of the loop.', wrong = '{"1": "Being impermeable to water while moving salts out describes the ascending limb, not the descending limb.", "2": "The descending limb does let water out. If it held back both water and salts, no water would be reabsorbed there.", "3": "Active pumping of sodium happens in the ascending limb. The descending limb only lets water pass."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0071' AND answer = 0;
UPDATE questions SET why = 'The loops of Henle build up the high salt concentration in the medulla. Water leaves the collecting ducts only because the surrounding fluid is salty. Without this, little water would be drawn out, so a large volume of dilute urine would be produced.', wrong = '{"0": "Small volumes of concentrated urine depend on the salty medulla that the loops create, so this could not happen.", "2": "Glomerular filtration depends on blood pressure in the glomerulus, which the loops of Henle do not control.", "3": "Plasma proteins in urine point to damage of the glomerular filter, not to a failure of the loops of Henle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0072' AND answer = 1;
UPDATE questions SET why = 'Antidiuretic hormone is made by neurosecretory cells of the hypothalamus. It travels down their axons and is stored in, and released from, the posterior pituitary gland. This is why damage to the pituitary can cause a lack of ADH.', wrong = '{"0": "This reverses the roles and names the wrong lobe. ADH is made in the hypothalamus and released from the posterior pituitary.", "1": "The adrenal cortex secretes aldosterone, which controls sodium and potassium, not ADH.", "2": "The kidney is the target of ADH, where it acts on the collecting ducts. It does not make the hormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0073' AND answer = 3;
UPDATE questions SET why = 'ADH acts on the walls of the collecting ducts and makes them more permeable to water. More water then moves by osmosis from the filtrate into the salty fluid of the medulla and back into the blood. Less water is lost, so the urine becomes concentrated.', wrong = '{"0": "Increasing sodium reabsorption is the job of aldosterone, which acts on the distal tubule and collecting duct.", "1": "The ascending limb always stays impermeable to water. ADH does not act on it.", "3": "ADH does not act on the glomerulus. Filtration pressure is set by the sizes of the afferent and efferent arterioles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0074' AND answer = 2;
UPDATE questions SET why = 'Osmoreceptors are receptors that sense the salt concentration, or osmotic pressure, of the blood. Those in the hypothalamus detect the rise after salty food or dehydration. The hypothalamus then creates thirst and causes ADH release from the posterior pituitary.', wrong = '{"0": "Thermoreceptors in the skin detect changes in temperature, not the salt concentration of the blood.", "1": "The adrenal cortex releases aldosterone when blood pressure or blood sodium is low. It does not detect high salt.", "2": "Stretch receptors in the bladder wall sense how full the bladder is, not the salt concentration of the blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0075' AND answer = 3;
UPDATE questions SET why = 'Diabetes insipidus is caused by too little ADH, often from damage to the pituitary gland. Without ADH the collecting ducts stay poorly permeable to water, so a large volume of dilute urine is passed. The person risks severe dehydration and very low blood pressure.', wrong = '{"0": "Too little insulin with glucose in the urine describes diabetes mellitus, a disorder of blood sugar control.", "1": "Too much ADH would make the body keep more water and pass small volumes of concentrated urine.", "3": "Too much aldosterone causes sodium and water retention. Diabetes insipidus is a problem of ADH, not aldosterone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0076' AND answer = 2;
UPDATE questions SET why = 'Aldosterone is made by the adrenal cortex and released when blood pressure or blood sodium is low. It acts on the distal convoluted tubule and collecting duct to increase Na⁺ reabsorption into the blood. Water follows the sodium, which raises blood volume and pressure.', wrong = '{"1": "Glucose is reabsorbed in the proximal tubule by active transport. Aldosterone does not control this.", "2": "Aldosterone does not act on the glomerulus. It acts on the distal tubule and collecting duct.", "3": "Aldosterone increases water reabsorption, because water follows the sodium that is taken back into the blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0077' AND answer = 0;
UPDATE questions SET why = 'Aldosterone also promotes the excretion of potassium ions in urine. This prevents hyperkalaemia, a condition in which blood K⁺ becomes too high. A high potassium level can upset the heart''s rhythm and cause dangerous cardiac arrhythmias.', wrong = '{"0": "Reabsorbing more potassium into the blood would raise blood K⁺ and cause hyperkalaemia, not prevent it.", "2": "Stopping H⁺ secretion would upset blood pH. It is not how aldosterone controls potassium levels.", "3": "Potassium is a mineral ion and cannot be converted into urea. Urea is made from ammonia in the liver."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0078' AND answer = 1;
UPDATE questions SET why = 'The kidney has two capillary beds in sequence. Glomerular capillaries inside Bowman''s capsule filter blood under high pressure. Peritubular capillaries around the tubules work under low pressure, taking back water, glucose and ions and secreting toxins into the tubule.', wrong = '{"0": "High pressure and filtration describe the glomerular capillaries, not the peritubular capillaries.", "1": "The capillaries inside Bowman''s capsule are the glomerular capillaries. Peritubular capillaries surround the renal tubules.", "2": "Peritubular capillaries branch from the efferent arteriole, after blood has passed through the glomerulus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0079' AND answer = 3;
UPDATE questions SET why = 'Urinary tract infections are usually caused by bacteria, most commonly Escherichia coli from the gut. The bacteria enter through the urethra and can infect the bladder, ureters or kidneys. UTIs are treated with a course of antibiotics.', wrong = '{"0": "Plasmodium is a protozoan parasite spread by mosquitoes. It causes malaria, not urinary infections.", "1": "The influenza virus infects the respiratory tract and causes flu. UTIs are usually bacterial.", "3": "Candida is a yeast, a type of fungus. It can occasionally infect the urinary tract, but bacteria such as E. coli are the usual cause."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0080' AND answer = 2;
UPDATE questions SET why = 'Kidney stones are hard crystals of minerals that clump together in the kidney or urinary tract. About 70% of patients have calcium oxalate stones, which form when urine contains too much calcium (hypercalciuria) or too much oxalate (hyperoxaluria).', wrong = '{"0": "Uric acid stones are found in only about 10% of patients and are linked to high blood uric acid.", "2": "Calcium phosphate stones do occur, usually when urine is alkaline, but they are far less common than calcium oxalate stones.", "3": "Cholesterol is the main component of most gallstones in the gall bladder, not of kidney stones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0081' AND answer = 1;
UPDATE questions SET why = 'About 10% of kidney stone patients have stones made of uric acid. These are caused by hyperuricemia, an increased amount of uric acid in the blood, which spills into the urine and crystallises there, especially when urine is acidic.', wrong = '{"1": "Hypercalciuria, high calcium in urine, leads to calcium oxalate stones, not uric acid stones.", "2": "Drinking plenty of water dilutes urine and lowers the risk of stones. Continuous dehydration is what raises it.", "3": "Uric acid stones are tied to high uric acid in the blood. A low-protein diet would not be the cause."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0082' AND answer = 0;
UPDATE questions SET why = 'Lithotripsy means breaking stones. In extracorporeal shockwave lithotripsy, extracorporeal meaning outside the body, an instrument called a lithotripter sends shockwaves through the body to the stone. The stone breaks into small pieces, most of which pass out in urine.', wrong = '{"1": "Inserting a tube from the back into the kidney is percutaneous nephrolithotripsy (PNL), used for larger stones.", "2": "Antibiotics kill bacteria and are used for urinary tract infections. They cannot dissolve or break stones.", "3": "A dialyzer is the filter used in haemodialysis to clean blood. It is not used to treat stones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0083' AND answer = 0;
UPDATE questions SET why = 'Percutaneous nephrolithotripsy is used for larger stones. A tube is passed from the patient''s back into the kidney, and a small camera called a nephroscope is inserted to see the stone. Ultrasound equipment breaks it, and the pieces are pulled out.', wrong = '{"0": "A lithotripter produces shockwaves from outside the body in ECSWL. It is not a camera.", "1": "A dialyzer is the filter with a semipermeable membrane used in haemodialysis.", "3": "A stethoscope is used to listen to sounds of the heart and lungs. It cannot show a stone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0084' AND answer = 2;
UPDATE questions SET why = 'Chronic kidney failure develops slowly over a long time and is irreversible. It is often caused by long-standing diabetes, high blood pressure or kidney disease such as inflammation of the glomeruli. Acute failure, in contrast, starts suddenly and often improves with treatment.', wrong = '{"0": "Acute kidney failure, also called acute kidney injury, often resolves with treatment, so it is not always irreversible.", "2": "NSAIDs, a group of painkillers, are listed as a cause of acute failure. Chronic failure usually follows diabetes or high blood pressure.", "3": "Acute kidney failure occurs suddenly. Developing over many years describes chronic failure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0085' AND answer = 1;
UPDATE questions SET why = 'Acute kidney failure starts suddenly. Its causes include kidney infection, blockage of the urinary tract by kidney stones, bladder cancer or an enlarged prostate, some medicines such as NSAIDs, and blood clots in renal vessels. A blocked tract stops urine flow and quickly harms the kidneys.', wrong = '{"0": "Long-standing diabetes slowly damages the kidneys over years. It is a cause of chronic, not acute, failure.", "1": "Long-term high blood pressure damages kidney vessels gradually. It is a cause of chronic failure.", "2": "Changes over decades are slow by definition. Acute failure is a sudden event."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0086' AND answer = 3;
UPDATE questions SET why = 'A dialyzer is a filter that contains a semipermeable membrane made of cellulose. Blood flows on one side and a fluid called dialysate on the other. Wastes, extra water and salts pass from the blood through the membrane into the dialysate.', wrong = '{"0": "Plasma proteins are large molecules in the blood. They are not used to build the dialyzer membrane.", "1": "The peritoneum is the body''s own membrane used in peritoneal dialysis, not the membrane inside a dialyzer.", "3": "Keratin is a tough protein of skin, hair and nails. It is not used in a dialyzer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0087' AND answer = 2;
UPDATE questions SET why = 'In peritoneal dialysis, 1.5 to 2 L of dialysate is placed in the abdomen through a catheter and left for 4 to 6 hours. Wastes and extra fluid pass into it from the blood capillaries of the peritoneum. It is then drained, and the cycle is repeated several times a day.', wrong = '{"0": "10 to 15 minutes is too short for enough waste to pass from the peritoneal capillaries into the dialysate.", "2": "Leaving dialysate for 2 to 3 days would not clear wastes well enough. The exchange is repeated several times each day.", "3": "One week is far too long. Wastes would build up, and the fluid is changed several times a day."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0088' AND answer = 1;
UPDATE questions SET why = 'Hypotension, or low blood pressure, is a common complication of haemodialysis, especially when fluid is removed from the blood too quickly. Other problems include infection at the access site, muscle cramps from changes in salt levels, anaemia and emotional stress.', wrong = '{"0": "The common blood pressure problem during haemodialysis is a fall in pressure, not hypertension.", "1": "Dialysis is linked with anaemia, too few red cells, not polycythaemia, which is too many red cells.", "2": "Kidney stones are not a complication of dialysis. The listed problems are infection, hypotension, cramps and anaemia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0089' AND answer = 3;
UPDATE questions SET why = 'A genetically related person such as a parent, sibling or child is usually the best kidney donor. Relatives are more likely to share blood group and tissue type with the recipient, so the risk of the immune system rejecting the new kidney is lower.', wrong = '{"1": "A donor''s blood group must match the recipient''s. A different blood group would lead to rejection.", "2": "Unrelated donors can succeed only if blood group and tissue type are matched. Skipping matching is not acceptable.", "3": "Every donor needs careful evaluation and matching. Donating without testing would put both people at risk."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0090' AND answer = 0;
UPDATE questions SET why = 'Pakistan''s first kidney transplant centre was set up in 1985 at the Sindh Institute of Urology and Transplantation (SIUT) in Karachi. It has become one of the largest transplant centres in the world.', wrong = '{"0": "The Pakistan Kidney and Liver Institute (PKLI) in Lahore was established much later, in 2017.", "1": "Mayo Hospital, Lahore, is a large general hospital. It is not the site of Pakistan''s first kidney transplant centre.", "2": "PIMS, Islamabad, is a major hospital, but Pakistan''s first kidney transplant centre was SIUT in Karachi."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0091' AND answer = 3;
UPDATE questions SET why = 'The recipient''s immune system may recognise the donor kidney as foreign and attack it, which is organ rejection. Immunosuppressant drugs weaken this immune response so the new kidney can survive. The cost is a higher risk of infections and some cancers.', wrong = '{"1": "Kidney stones are broken by lithotripsy. Immunosuppressants act on the immune system, not on stones.", "2": "Immunosuppressants are not diuretics. They do not increase urine production.", "3": "By weakening the immune system, immunosuppressants increase the risk of infections rather than preventing them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0092' AND answer = 0;
UPDATE questions SET why = 'The nervous system coordinates body activities using electrical signals called nerve impulses, which travel quickly along neurons. Coordination by hormones carried in the blood is chemical coordination, the job of the endocrine system.', wrong = '{"0": "Hormones carried in blood are the basis of chemical coordination by the endocrine system, not nervous coordination.", "1": "Digestive enzymes break down food in the gut. They do not carry messages between parts of the body.", "2": "Skin pigments such as melanin protect against UV light. They have no role in coordination."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0093' AND answer = 3;
UPDATE questions SET why = 'A transducer is something that changes one form of energy into another. Receptors do this: rod and cone cells of the retina convert light energy into the electrochemical energy of a nerve impulse. The impulse then travels in a sensory neuron.', wrong = '{"0": "Carrying impulses from the CNS to muscles is the job of motor neurons, not receptors.", "1": "Neurotransmitters are stored in synaptic vesicles at axon terminals. This is not what makes receptors transducers.", "3": "Inter-neurons in the brain and spinal cord link sensory neurons to motor neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0094' AND answer = 2;
UPDATE questions SET why = 'A receptor detects the stimulus and starts an impulse in a sensory neuron. The sensory neuron carries it to the CNS, where inter-neurons process it. The CNS then sends impulses along a motor neuron to an effector, a muscle or gland, which responds.', wrong = '{"0": "Motor neurons carry impulses away from the CNS to effectors, so they must come after the inter-neurons, not before them.", "2": "This runs backwards. The pathway begins at a receptor and ends at an effector.", "3": "The sensory neuron must come straight after the receptor, and the motor neuron must come before the effector."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0095' AND answer = 1;
UPDATE questions SET why = 'The cell body of a neuron contains the nucleus and most organelles. Its cytoplasm has Nissl''s granules, which are groups of ribosomes and rough endoplasmic reticulum. They make the large amounts of protein a neuron needs.', wrong = '{"1": "Mitochondria are present in neurons and supply ATP, but they are not what Nissl''s granules are made of.", "2": "Synaptic vesicles store neurotransmitter in the synaptic knobs at the axon terminals, not in the cell body.", "3": "Myelin layers are wrapped around axons by Schwann cells and oligodendrocytes. They are not in the cell body."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0096' AND answer = 0;
UPDATE questions SET why = 'Dendrites are branched extensions of the cell body. They receive information from other neurons or cells, turn it into nerve impulses and carry these impulses toward the cell body. From the cell body, the axon then carries impulses away.', wrong = '{"1": "The axon carries impulses away from the cell body toward the axon terminal.", "2": "The axon terminal is the end of the axon. It passes the signal on to a muscle, gland or another neuron.", "3": "The myelin sheath is an insulating covering around the axon. It speeds conduction but does not carry impulses itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0097' AND answer = 0;
UPDATE questions SET why = 'Motor neurons and inter-neurons receive impulses from many different sources at the same time. To make contact with all these other neurons, they need many receiving branches, so their dendrites are highly branched.', wrong = '{"0": "Conducting impulses over long distances depends on a long axon, not on branched dendrites.", "1": "Myelin sheaths cover axons, not dendrites. They have nothing to do with how branched the dendrites are.", "3": "Only motor neurons carry impulses away from the CNS, and that is the job of the axon. It does not explain dendrite branching."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0098' AND answer = 2;
UPDATE questions SET why = 'Myelin sheaths are made by glial cells that wrap layers of membrane around axons. In the central nervous system this is done by oligodendrocytes. In the peripheral nervous system the same job is done by Schwann cells.', wrong = '{"0": "Schwann cells make the myelin sheaths around axons in the peripheral nervous system, not in the CNS.", "2": "Nissl''s granules are ribosomes and rough ER in the neuron''s cell body. They do not form myelin.", "3": "Basal cells are stem cells, for example in taste buds and the nasal lining. They do not make myelin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0099' AND answer = 1;
UPDATE questions SET why = 'Neuroglia, or glial cells, are supporting cells of the nervous system. They supply nutrients to neurons, remove wastes and provide immunity. Some of them, Schwann cells and oligodendrocytes, also form myelin sheaths around axons.', wrong = '{"0": "Conducting nerve impulses to effectors is done by motor neurons. Glial cells support neurons but do not carry impulses.", "1": "Detecting stimuli is the job of receptors such as rods, cones and taste cells, not glial cells.", "2": "Acetylcholine is a neurotransmitter released from the axon terminals of neurons, not from glial cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0100' AND answer = 3;
UPDATE questions SET why = 'In the CNS, white matter is made mainly of myelinated axons. Myelin is rich in lipid and looks white, which gives this tissue its colour. Grey matter is made of cell bodies and non-myelinated dendrites.', wrong = '{"0": "Cell bodies and non-myelinated dendrites make up grey matter, not white matter.", "1": "Blood capillaries supply nervous tissue with oxygen and nutrients but are not what forms white matter.", "2": "Cerebrospinal fluid fills the ventricles of the brain and the central canal of the spinal cord. It is a fluid, not white matter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0101' AND answer = 3;
UPDATE questions SET why = 'In a myelinated neuron the myelin sheath is not continuous. It is interrupted every 1 to 2 mm by small uncovered gaps called nodes of Ranvier. Action potentials form only at these nodes and jump from one to the next, which speeds up conduction.', wrong = '{"1": "Clusters of sensory neuron cell bodies outside the CNS are called ganglia.", "2": "Swellings at the end of the axon that store neurotransmitter are synaptic knobs.", "3": "The narrow fluid-filled gap between two neurons at a synapse is the synaptic cleft."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0102' AND answer = 0;
UPDATE questions SET why = 'Sensory neurons carry impulses from receptors to the CNS. Their cell bodies lie outside the CNS in clusters called ganglia. For spinal nerves, these are the dorsal root ganglia beside the spinal cord.', wrong = '{"0": "The grey matter of the spinal cord holds the cell bodies of motor neurons and inter-neurons, not sensory neurons.", "2": "White matter is made of myelinated axons. It does not hold the cell bodies of sensory neurons.", "3": "Effectors are muscles and glands that respond to motor neurons. They do not contain sensory cell bodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0103' AND answer = 1;
UPDATE questions SET why = 'Motor neurons carry impulses away from the CNS to effectors. Each has a cell body, a long axon and many branched dendrites, so they are multipolar. Their cell bodies lie inside the brain or spinal cord, and their axons run out to muscles and glands.', wrong = '{"0": "Carrying impulses from receptors to the CNS is the job of sensory neurons.", "1": "The dorsal root ganglia contain the cell bodies of sensory neurons, not motor neurons.", "3": "Only inter-neurons lie entirely within the CNS. Motor neuron axons leave the CNS to reach effectors."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0104' AND answer = 2;
UPDATE questions SET why = 'Inter-neurons, also called associative neurons, lie entirely within the brain and spinal cord. They receive impulses from sensory neurons or other inter-neurons and pass them on to motor neurons or other inter-neurons, so they process information.', wrong = '{"0": "Motor neurons have their cell bodies in the CNS, but their axons extend out of it to reach effectors.", "1": "Sensory neurons bring impulses from receptors into the CNS. Their cell bodies lie outside it in ganglia.", "2": "Schwann cells are glial cells of the peripheral nervous system that make myelin. They are not neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0105' AND answer = 3;
UPDATE questions SET why = 'The reflex arc is the simplest neural pathway, made of only a few neurons. It controls reflex actions, which are immediate, automatic and involuntary responses to a stimulus, such as the knee-jerk. Many reflexes are handled by the spinal cord.', wrong = '{"0": "Many reflexes, such as the knee-jerk, are processed in the spinal cord without involving the cerebrum.", "1": "Reflex actions are involuntary. They happen automatically, without conscious decision.", "3": "A reflex arc is made of neurons and works by nerve impulses. Pathways through the pituitary are hormonal."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0106' AND answer = 2;
UPDATE questions SET why = 'Tapping the patellar tendon below the knee stretches the quadriceps muscle at the front of the thigh. A receptor in the quadriceps senses this and starts an impulse in a sensory neuron, which carries it to the spinal cord.', wrong = '{"0": "The hamstrings at the back of the thigh are made to relax during the reflex. They do not hold the receptor that senses the tap.", "2": "The receptor for this reflex is in the quadriceps muscle, which is stretched by the tap, not in the skin.", "3": "The spinal cord is where the impulse passes to the motor neuron. It is not where the stimulus is first detected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0107' AND answer = 1;
UPDATE questions SET why = 'In the knee-jerk reflex, the sensory neuron enters the spinal cord and passes the impulse straight to the motor neuron of the quadriceps, without an inter-neuron in between. This very short pathway makes the reflex fast.', wrong = '{"1": "The knee-jerk does not need the brain. The impulse is passed on within the spinal cord.", "2": "The cerebellum controls balance and coordination of movement. It is not part of the knee-jerk reflex arc.", "3": "The hamstrings relax, not contract, during the knee-jerk. Their relaxation is not a condition for the motor neuron to fire."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0108' AND answer = 0;
UPDATE questions SET why = 'While the quadriceps contracts, the sensory neuron also activates an inter-neuron in the spinal cord. This inter-neuron releases inhibitory chemicals onto the motor neurons of the hamstrings, so the hamstrings relax and do not resist the forward kick of the leg.', wrong = '{"1": "The quadriceps motor neuron goes only to the quadriceps. If the hamstrings were stimulated they would oppose the kick.", "2": "The knee-jerk is involuntary. No conscious command from the brain is needed.", "3": "The tendon remains intact. The tap stretches the quadriceps, which is what starts the reflex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0109' AND answer = 0;
UPDATE questions SET why = 'A resting neuron is polarized: the inside of its membrane is negative and the outside positive. This resting membrane potential is about –70 mV. It is set up by fixed negative anions inside, the sodium-potassium pump and the leak of K⁺ out of the cell.', wrong = '{"0": "The inside of a resting neuron is negative, not positive. A positive inside is seen briefly during an action potential.", "2": "–7 mV is ten times too small. The resting potential is about –70 mV.", "3": "0 mV would mean no charge difference across the membrane. A resting neuron is polarized."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0110' AND answer = 1;
UPDATE questions SET why = 'Proteins and nucleic acids inside the neuron carry negative charges and are too large to diffuse out through the membrane. They are called fixed anions. Because they stay inside, they are one of the main reasons the inside of a resting neuron is negative.', wrong = '{"0": "Neurotransmitters are chemicals released from synaptic vesicles at a synapse. They are not the trapped negative molecules inside the cell.", "1": "Cations are positively charged ions such as Na⁺ and K⁺. Proteins and nucleic acids here are negatively charged.", "3": "Cytokines are proteins released by immune cells during inflammation. They are not the fixed anions of neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0111' AND answer = 2;
UPDATE questions SET why = 'In a resting neuron the sodium-potassium pump keeps the two ions unevenly spread. K⁺ is about 30 times more concentrated inside the cell than outside, while Na⁺ is about 10 times more concentrated outside than inside.', wrong = '{"0": "This reverses both gradients. K⁺ is concentrated inside the neuron and Na⁺ is concentrated outside.", "1": "The sodium-potassium pump uses ATP to keep these ions unequal. Equal concentrations would remove the resting potential.", "2": "K⁺ is higher inside, but Na⁺ is about 10 times higher outside the cell, not inside."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0112' AND answer = 3;
UPDATE questions SET why = 'In each cycle the sodium-potassium pump uses one ATP to move 3 Na⁺ out of the cell and 2 K⁺ in, both against their concentration gradients. Three positive charges leave for every two that enter, so the inside loses positive charge and becomes more negative.', wrong = '{"0": "The numbers are reversed. Moving 2 out and 3 in would add positive charge to the inside.", "1": "The directions are reversed, and the pump works against concentration gradients, so it must use ATP.", "2": "An equal exchange would not change the balance of charge. The pump moves 3 Na⁺ out for every 2 K⁺ in."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0113' AND answer = 3;
UPDATE questions SET why = 'When a neuron is stimulated, Na⁺ gates in the membrane open and Na⁺ rushes into the cell. This sudden inflow of positive charge cancels the negative charge inside, so the potential rises from –70 mV, past zero, to a positive value. This reversal is depolarization.', wrong = '{"1": "Opening K⁺ gates and letting K⁺ flow out makes the inside negative again. That is repolarization.", "2": "If all gates closed, no ions would move and the potential could not change. Depolarization needs Na⁺ gates to open.", "3": "Cl⁻ entering the cell makes the inside more negative. That is how inhibitory transmitters work, not depolarization."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0114' AND answer = 0;
UPDATE questions SET why = 'After a brief depolarization, the Na⁺ gates close and the K⁺ gates open. K⁺ ions diffuse out of the cell, taking positive charge with them, so the inside becomes negative again. This return toward the resting state is repolarization.', wrong = '{"0": "Na⁺ gates opening and Na⁺ entering is depolarization, the first phase of the action potential.", "1": "Ca²⁺ gates open in the synaptic knob when an impulse reaches a synapse. They do not cause repolarization of the axon.", "3": "The myelin sheath is not removed during an impulse. It stays in place as insulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0115' AND answer = 2;
UPDATE questions SET why = 'During repolarization the K⁺ gates open, but they do not all close at the same moment. While some are still open, extra K⁺ leaks out, so the potential briefly becomes more negative than –70 mV. This short phase is hyperpolarization.', wrong = '{"0": "Extra Na⁺ entering would make the inside less negative. Hyperpolarization needs the inside to become more negative.", "2": "Ca²⁺ movement is important at synapses, not in hyperpolarization of the axon membrane.", "3": "The sodium-potassium pump keeps working. It restores the original ion distribution after hyperpolarization."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0116' AND answer = 1;
UPDATE questions SET why = 'During hyperpolarization the membrane is more negative than at rest, and the neuron cannot produce another action potential. This short period is the refractory period. It ensures the impulse moves forward along the axon and not backward.', wrong = '{"0": "In the resting state the neuron is polarized at –70 mV and can respond to a stimulus.", "2": "Synaptic delay is the short time needed for a signal to cross a synapse by neurotransmitter release.", "3": "The depolarization phase is part of the action potential itself, when Na⁺ rushes in."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0117' AND answer = 1;
UPDATE questions SET why = 'An action potential does not really travel along the axon. The active region acts as a depolarizing stimulus for the region next to it, which then produces its own action potential. Meanwhile the previous region repolarizes, so the impulse is passed on step by step.', wrong = '{"0": "Ions only cross the membrane at each point. They do not flow along the whole length of the axon.", "1": "The strength of an action potential stays constant. The one at the end of the axon is as strong as the first.", "2": "Neurotransmitters are released only at the synaptic knobs of the axon terminal, not along the axon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0118' AND answer = 3;
UPDATE questions SET why = 'The amplitude of an action potential stays the same along the whole axon, so the last one is as strong as the first. Its speed varies: impulses travel faster in axons of larger diameter and in myelinated axons.', wrong = '{"1": "The action potential does not weaken. Each region makes a new, full-sized action potential.", "2": "Speed is not the same in all neurons. It ranges from 1 to 3 m/s in non-myelinated neurons to about 120 m/s in myelinated ones.", "3": "Thin non-myelinated axons are the slowest. Thick and myelinated axons conduct faster."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0119' AND answer = 0;
UPDATE questions SET why = 'Myelination greatly speeds up conduction. In humans, non-myelinated neurons conduct impulses at only 1 to 3 m/s, while myelinated neurons conduct at speeds of up to 120 m/s.', wrong = '{"0": "3 m/s is the upper speed of non-myelinated neurons, not myelinated ones.", "1": "12 m/s is ten times too low for the fastest myelinated neurons.", "3": "1200 m/s is ten times faster than the true maximum of about 120 m/s."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0120' AND answer = 2;
UPDATE questions SET why = 'Myelin insulates the axon, so action potentials can form only at the nodes of Ranvier. The impulse jumps from one node to the next, skipping the myelinated parts. This saltatory conduction can be up to 50 times faster than in the fastest non-myelinated axons.', wrong = '{"0": "Myelin is an insulator, not a conductor. It stops ions crossing the membrane between the nodes.", "2": "Action potentials are produced only at the nodes of Ranvier, so Na⁺ gates under the myelin do not take part.", "3": "Neurotransmitters work only at synapses between cells. They do not carry the impulse along one axon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0121' AND answer = 1;
UPDATE questions SET why = 'At a synapse the two cells do not touch. A narrow, fluid-filled gap separates the presynaptic neuron from the postsynaptic cell, and this gap is the synaptic cleft. Neurotransmitters diffuse across it to carry the signal.', wrong = '{"1": "A node of Ranvier is a small gap in the myelin sheath along one axon, not a gap between two cells.", "2": "A synaptic knob is the swollen end of the axon terminal that holds the synaptic vesicles.", "3": "The dorsal root is the branch of a spinal nerve that carries sensory fibres into the spinal cord."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0122' AND answer = 0;
UPDATE questions SET why = 'A synapse can link a neuron with another neuron or with an effector cell. The synapse between a motor neuron and a skeletal muscle fibre is called the neuromuscular junction. Here acetylcholine is released to make the muscle fibre contract.', wrong = '{"0": "A node of Ranvier is a gap in the myelin sheath of an axon, not a junction with a muscle.", "1": "A ganglion is a cluster of nerve cell bodies outside the CNS, such as a dorsal root ganglion.", "3": "A gyrus is a ridge on the folded surface of the cerebrum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0123' AND answer = 2;
UPDATE questions SET why = 'When an action potential reaches the synaptic knob, the first step is the opening of calcium gates in the presynaptic membrane. Ca²⁺ diffuses into the knob, which makes the synaptic vesicles fuse with the membrane and release their neurotransmitter.', wrong = '{"0": "Neurotransmitter can bind to postsynaptic receptors only after it has been released, which needs Ca²⁺ entry first.", "1": "Postsynaptic Na⁺ gates open only after neurotransmitter binds to the receptors, a later step.", "2": "Acetylcholinesterase breaks down acetylcholine after it has acted. This is the last step, not the first."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0124' AND answer = 3;
UPDATE questions SET why = 'Neurotransmitters are stored in synaptic vesicles. When Ca²⁺ enters the synaptic knob, the vesicles fuse with the presynaptic membrane and empty their contents into the synaptic cleft. Releasing material from a cell by vesicle fusion is exocytosis.', wrong = '{"0": "Osmosis is the movement of water across a membrane. It does not release neurotransmitter.", "1": "Endocytosis takes material into a cell in vesicles, the opposite of releasing it.", "2": "Neurotransmitters are released in packets when whole vesicles fuse with the membrane, not pumped out one molecule at a time."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0125' AND answer = 3;
UPDATE questions SET why = 'All action potentials are the same size, so a stronger signal is coded by a higher frequency of impulses. The more often action potentials arrive at the presynaptic axon, the more neurotransmitter is released into the synaptic cleft.', wrong = '{"0": "The size of an action potential is constant. Only the frequency of impulses changes.", "1": "Calcium gates open each time an action potential arrives. More impulses mean more Ca²⁺ entry, not closed gates.", "3": "Whether a synapse excites or inhibits depends on the type of neurotransmitter, not on how often impulses arrive."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0126' AND answer = 2;
UPDATE questions SET why = 'Neurotransmitters do not stay in the synaptic cleft for ever, or they would keep stimulating the next cell. At many synapses the used transmitter is taken back up by the presynaptic neuron. At others it is broken down by enzymes, such as acetylcholinesterase for acetylcholine.', wrong = '{"0": "Myelin sheaths cover axons, not the synaptic cleft. They do not absorb neurotransmitters.", "2": "If transmitters stayed permanently, the postsynaptic cell would be stimulated non-stop. They are removed quickly.", "3": "Neurotransmitters are organic molecules. They cannot be converted into calcium ions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0127' AND answer = 1;
UPDATE questions SET why = 'Excitatory neurotransmitters bind to receptors on the postsynaptic membrane and make it more permeable to Na⁺. Na⁺ flows in and depolarizes the membrane, which can generate an action potential in the postsynaptic neuron.', wrong = '{"1": "Opening chloride channels is how inhibitory neurotransmitters work. Cl⁻ entry makes the cell harder to excite.", "2": "Making the inside more negative is hyperpolarization, which inhibits rather than excites the neuron.", "3": "If all ion channels were blocked, no Na⁺ could enter and no action potential could form."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0128' AND answer = 0;
UPDATE questions SET why = 'Glutamate is an excitatory neurotransmitter that acts in the central nervous system. Like other excitatory transmitters, it increases the permeability of the postsynaptic membrane to Na⁺, helping to generate an action potential.', wrong = '{"1": "GABA is the chief inhibitory neurotransmitter of the CNS. It reduces excitability rather than increasing it.", "2": "Glycine is an inhibitory neurotransmitter, especially in the spinal cord, brainstem and retina.", "3": "Endorphins are inhibitory neurotransmitters in the brain that reduce the transmission of pain signals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0129' AND answer = 0;
UPDATE questions SET why = 'Too little activity of serotonin-releasing neurons can cause depression. Many antidepressant drugs block the removal of serotonin from the synaptic cleft. Serotonin then stays in the cleft longer and keeps acting on the postsynaptic cell, which reduces depression.', wrong = '{"0": "Destroying serotonin-releasing neurons would lower serotonin activity and make depression worse.", "2": "Reduced dopamine activity is linked with movement problems such as Parkinson''s disease, not with treating depression.", "3": "Faster breakdown of serotonin would shorten its action and lower its activity, the opposite of what is needed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0130' AND answer = 1;
UPDATE questions SET why = 'Dopamine is a brain neurotransmitter that helps control body movements. When dopamine-releasing neurons degenerate, movement control is lost, causing the muscle tremors and stiffness of Parkinson''s disease.', wrong = '{"0": "Multiple sclerosis is caused by damage to the myelin sheaths of neurons in the CNS, not by loss of dopamine neurons.", "1": "Meningitis is inflammation of the meninges, usually caused by infection, not degeneration of dopamine neurons.", "2": "Diabetes insipidus results from too little ADH and causes large volumes of dilute urine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0131' AND answer = 3;
UPDATE questions SET why = 'Serotonin is an excitatory neurotransmitter that regulates appetite, sleep, mood, memory and other functions. Surprisingly, about 90% of it is made by neurons in the intestine, and only about 10% is made in the CNS.', wrong = '{"0": "The brain is part of the CNS, which produces only about 10% of the body''s serotonin.", "1": "The spinal cord is also part of the CNS, which together makes only about 10% of serotonin.", "3": "The adrenal glands release epinephrine (adrenaline), not most of the body''s serotonin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0132' AND answer = 2;
UPDATE questions SET why = 'Inhibitory neurotransmitters open chloride channels instead of sodium channels. Cl⁻ diffuses into the neuron and makes the inside even more negative than the resting potential. This hyperpolarization makes it harder for the neuron to fire an impulse.', wrong = '{"0": "Opening sodium channels lets Na⁺ in and depolarizes the cell. That is how excitatory neurotransmitters work.", "1": "Calcium channels open in the presynaptic knob to release transmitter. They are not how inhibition of the postsynaptic cell works.", "2": "Synapses do not involve the myelin sheath, and transmitters do not remove it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0133' AND answer = 3;
UPDATE questions SET why = 'GABA, gamma-aminobutyric acid, is the chief inhibitory neurotransmitter of the CNS. It lowers the excitability of neurons, reduces anxiety, stress and fear, and promotes relaxation and sleep. Many sedative drugs work by strengthening its binding to its receptors.', wrong = '{"1": "Acetylcholine is an excitatory neurotransmitter, for example at neuromuscular junctions where it makes muscle contract.", "2": "Glutamate is an excitatory neurotransmitter in the CNS, not an inhibitory one.", "3": "Norepinephrine is an excitatory biogenic amine that promotes alertness and focus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0134' AND answer = 0;
UPDATE questions SET why = 'Endorphins are inhibitory neurotransmitters that reduce the release of excitatory transmitters carrying pain messages. Morphine and heroin, derived from opium, are chemically similar to endorphins. They bind easily to endorphin receptors and so block pain signals.', wrong = '{"0": "Blocking GABA would make neurons more excitable. The pain-relieving effect of opiates comes from acting like endorphins.", "2": "Nociceptors are pain receptors. Stimulating them would increase pain, not relieve it.", "3": "Inhibiting acetylcholinesterase is how nerve gases act. It causes muscle overstimulation, not pain relief."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0135' AND answer = 1;
UPDATE questions SET why = 'Acetylcholine makes skeletal muscles contract and is then broken down by the enzyme acetylcholinesterase. Nerve gases such as sarin inhibit this enzyme, so acetylcholine builds up and muscles stay contracted. A diaphragm that stays contracted cannot move air, so breathing stops.', wrong = '{"0": "Nerve gases cause too much acetylcholine at the synapse, not too little. The muscles are overstimulated.", "1": "Nerve gases act on an enzyme at the neuromuscular junction. They do not destroy myelin.", "3": "Nerve gases block acetylcholinesterase, so acetylcholine is broken down more slowly, not faster."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0136' AND answer = 2;
UPDATE questions SET why = 'The human nervous system has two parts. The central nervous system is the brain and spinal cord. The peripheral nervous system is made of the cranial nerves, which arise from the brain, and the spinal nerves, which arise from the spinal cord, along with their ganglia.', wrong = '{"0": "The brain and spinal cord together form the central nervous system, not the peripheral nervous system.", "2": "The brain belongs to the CNS. Cranial nerves are only half of the PNS; spinal nerves are also included.", "3": "The spinal cord belongs to the CNS. The PNS includes cranial nerves as well as spinal nerves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0137' AND answer = 1;
UPDATE questions SET why = 'The brain and spinal cord are covered by three membranes, the meninges. From outside in they are the dura mater, the arachnoid and the pia mater. The dura mater is the thick outermost layer just below the skull and vertebrae, and it contains the larger blood vessels.', wrong = '{"0": "The arachnoid is the thin middle layer. It separates the cerebrospinal fluid below it from the blood in the dura mater.", "1": "The pia mater is the innermost, very delicate layer. It sticks to the brain surface and has capillaries that nourish it.", "3": "The corpus callosum is a band of axons joining the two cerebral hemispheres. It is not a meningeal layer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0138' AND answer = 2;
UPDATE questions SET why = 'The average adult human brain weighs about 1.4 kg, roughly 2% of total body weight. Even so, it contains about 100 billion inter-neurons, each of which forms synapses with several thousand other neurons.', wrong = '{"1": "4 kg is almost three times too heavy. An adult brain weighs about 1.4 kg, about 2% of body weight.", "2": "0.4 kg is far too light for an adult brain. The true figure is about 1.4 kg.", "3": "14 kg is ten times too heavy and would be about a fifth of the whole body."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0139' AND answer = 0;
UPDATE questions SET why = 'A deep groove, or fissure, divides the cerebrum into left and right cerebral hemispheres. At the base of this groove the two hemispheres are joined by the corpus callosum, a thick band of axons that lets the two sides exchange information.', wrong = '{"0": "The pons is part of the brainstem. It carries impulses between the cerebral hemispheres and the cerebellum, but it does not join the two hemispheres.", "1": "The thalamus lies in the diencephalon and relays sensory information to the cerebrum.", "2": "The pia mater is the innermost meningeal layer covering the brain surface. It is not a band of axons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0140' AND answer = 3;
UPDATE questions SET why = 'Each cerebral hemisphere receives sensory information from the opposite side of the body and sends motor commands to that side. Damage to the left hemisphere therefore causes loss of sensation and paralysis on the right side of the body.', wrong = '{"0": "Control is crossed. The left hemisphere controls the right side, so the left side would not be the one paralysed.", "2": "Damage to one hemisphere affects one side of the body. It does not selectively paralyse both legs.", "3": "Effects appear on the side opposite the damage, so the left face would not be the part affected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0141' AND answer = 1;
UPDATE questions SET why = 'Each cerebral hemisphere has four lobes. The frontal lobes carry out executive functions, such as self-control, planning, reasoning and abstract thought. These are the higher functions involved in making decisions.', wrong = '{"0": "The occipital lobes, at the back of the brain, control vision.", "1": "The temporal lobes deal with hearing, visual memory, language comprehension and emotions.", "3": "The parietal lobes process sensory information and give awareness of body position and surroundings."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0142' AND answer = 2;
UPDATE questions SET why = 'Sensory areas of the cerebral cortex receive information from different parts of the body. The auditory cortex, which deals with different sound frequencies, lies in the temporal lobe, at the side of the head near the ears.', wrong = '{"0": "The occipital lobe holds the visual cortex, which deals with information from the eyes.", "1": "The frontal lobe deals with executive functions such as planning and reasoning, not hearing.", "2": "The cerebellum coordinates muscle actions and posture. It is not part of the cerebral cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0143' AND answer = 3;
UPDATE questions SET why = 'The surface of the cerebrum is folded. The ridges are called gyri, the shallow grooves between them are sulci, and the deep grooves are fissures. The deep groove that separates the two cerebral hemispheres is an example of a fissure.', wrong = '{"1": "A sulcus is a shallow groove between gyri, not a deep one.", "2": "A gyrus is a ridge on the cerebral surface, not a groove.", "3": "A ganglion is a cluster of nerve cell bodies outside the CNS. It is not a feature of the cerebral surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0144' AND answer = 0;
UPDATE questions SET why = 'Association areas of the cerebral cortex are the sites of higher mental activities, such as thinking and interpreting information. Some of these functions are mainly on one side, for example language in the left hemisphere and visual-spatial ability in the right.', wrong = '{"0": "Motor areas send impulses to voluntary skeletal muscles. They do not handle higher mental activities.", "1": "The medulla oblongata is a brainstem centre for heart rate, breathing and other vital activities.", "3": "The cerebellum coordinates muscle actions and posture. It is not where language or reasoning are processed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0145' AND answer = 2;
UPDATE questions SET why = 'The brainstem has three parts: the midbrain, pons and medulla oblongata. The medulla oblongata is both a relay centre and a control centre for heart rate, breathing rate and other homeostatic activities.', wrong = '{"1": "The pons transmits impulses between the cerebral hemispheres and the cerebellum. It is not the main centre for heart rate.", "2": "The midbrain relays visual and auditory information and contains the reticular formation.", "3": "The thalamus is part of the diencephalon, not the brainstem. It relays sensory information to the cerebrum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0146' AND answer = 0;
UPDATE questions SET why = 'The pons is the middle part of the brainstem, between the midbrain and the medulla. It transmits impulses between the cerebral hemispheres and the cerebellum, linking the thinking brain with the centre that coordinates movement.', wrong = '{"0": "Relaying visual information is a role of the midbrain. Signals from the eyes reach the occipital lobe by other routes.", "2": "The hypothalamus controls the pituitary gland directly through nerves and hormones. The pons is not involved.", "3": "The pons is in the brain and has no link with the kidneys."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0147' AND answer = 1;
UPDATE questions SET why = 'The thalamus lies in the diencephalon, in the centre of the brain. It acts as a relay centre: sensory information arriving from the body passes through the thalamus, which sends it on to the correct areas of the cerebrum.', wrong = '{"0": "Hunger, satiety and thirst are regulated by the hypothalamus, which lies just below the thalamus.", "1": "Posture and coordination of movements are controlled by the cerebellum.", "2": "Moving information from short-term to long-term memory involves the hippocampus of the limbic system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0148' AND answer = 3;
UPDATE questions SET why = 'The hypothalamus integrates the activities of the internal organs. It regulates body temperature, hunger and satiety, thirst and various emotional states. It also controls the pituitary gland, which in turn regulates many other endocrine glands.', wrong = '{"0": "The thalamus is a relay centre that passes sensory information to the cerebrum. It does not regulate temperature or hunger.", "2": "The amygdala is part of the limbic system that controls emotions such as fear, anger and love.", "3": "The pons carries impulses between the cerebrum and cerebellum. It does not regulate hunger or the pituitary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0149' AND answer = 1;
UPDATE questions SET why = 'The pineal gland is a small gland located where the two halves of the thalamus join. It produces the hormone melatonin, which controls sleep patterns. Melatonin release rises in darkness, helping the body prepare for sleep.', wrong = '{"0": "The hippocampus is part of the limbic system and helps convert short-term memories into long-term ones.", "1": "The pituitary gland produces many hormones, such as growth hormone and TSH, but not melatonin.", "3": "The medulla oblongata controls heart rate and breathing. It does not secrete melatonin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0150' AND answer = 2;
UPDATE questions SET why = 'The limbic system is a group of linked structures around the thalamus. Its two almond-shaped amygdalae lie deep in the temporal lobes and control feelings and emotions such as love, hate, anger, fear and rage.', wrong = '{"0": "The hippocampi help consolidate short-term memory into long-term memory. They are not the main centres of emotion.", "1": "The thalami relay sensory information to the cerebrum. They are not almond-shaped emotional centres.", "2": "The olfactory bulbs receive impulses from smell receptors through cranial nerve I."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0151' AND answer = 3;
UPDATE questions SET why = 'The hippocampus is part of the limbic system, made of two horn-shaped structures that curve back from the amygdala. It plays a key role in consolidation, the process of turning short-term memories into long-term memories.', wrong = '{"1": "The amygdala controls emotions such as fear and anger. It is not the main site of memory consolidation.", "2": "The cerebellum coordinates muscle actions and posture, not the storage of memories.", "3": "The medulla oblongata controls heart rate, breathing and other vital activities."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0152' AND answer = 0;
UPDATE questions SET why = 'The cerebellum lies below and behind the cerebral hemispheres. It receives sensory impulses from muscles, tendons, joints, eyes and ears, processes information about body position, controls posture and coordinates rapid and ongoing movements of skeletal muscles.', wrong = '{"0": "The occipital lobe of the cerebrum contains the visual cortex and controls vision, not posture.", "1": "The thalamus relays sensory information to the cerebrum. It does not coordinate movements.", "3": "The hypothalamus regulates internal conditions such as temperature, hunger and thirst."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0153' AND answer = 2;
UPDATE questions SET why = 'The brain has four fluid-filled ventricles. There are two lateral ventricles in the cerebrum and a third ventricle between the right and left thalamus. The fourth ventricle lies between the cerebellum and the brainstem and continues into the central canal of the spinal cord.', wrong = '{"0": "The space between the two halves of the thalamus is the third ventricle, not the fourth.", "1": "The two large ventricles inside the cerebral hemispheres are the lateral ventricles.", "2": "No ventricle is limited to the occipital lobe. The fourth ventricle lies in the hindbrain region."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0154' AND answer = 3;
UPDATE questions SET why = 'In the brain, grey matter forms the outer cortex and white matter lies beneath it. The spinal cord has the opposite arrangement: an inner H-shaped or butterfly-shaped zone of grey matter, surrounded by an outer zone of white matter made of myelinated axons.', wrong = '{"1": "The arrangement is not the same. In the spinal cord the grey matter is inside and the white matter is outside.", "2": "The spinal cord has grey matter too. Its H-shaped core holds cell bodies of inter-neurons and motor neurons.", "3": "The spinal cord also has white matter. Its outer zone is made of myelinated axons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0155' AND answer = 0;
UPDATE questions SET why = 'There are 12 pairs of cranial nerves arising from the brain. The first two pairs, the olfactory and optic nerves, arise from the cerebrum, and the other 10 pairs arise from the brainstem. Some are sensory, some motor and some mixed.', wrong = '{"0": "31 is the number of pairs of spinal nerves, which arise from the spinal cord.", "2": "10 pairs arise from the brainstem, but two more arise from the cerebrum, making 12 in all.", "3": "8 is the number of pairs of cervical spinal nerves, not cranial nerves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0156' AND answer = 1;
UPDATE questions SET why = 'Cranial nerve X, the vagus nerve, is a mixed nerve that controls many organs, including the heart, lungs and digestive system. Many of the parasympathetic motor neurons travel in the vagus, which is why it slows the heart and increases digestive activity.', wrong = '{"0": "Cranial nerve I, the olfactory nerve, is sensory and carries the sense of smell.", "1": "Cranial nerve VIII is sensory and carries hearing and balance from the inner ear.", "3": "Cranial nerve XII is a motor nerve that controls the muscles of the tongue."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0157' AND answer = 2;
UPDATE questions SET why = 'Cranial nerve VIII is a purely sensory nerve that carries impulses for hearing and balance from the inner ear to the brain. The other purely sensory cranial nerves are I for smell and II for vision.', wrong = '{"0": "Cranial nerve V is mixed. It carries sensation from the face and controls the muscles used in chewing.", "1": "Cranial nerve VII is mixed. It controls facial expression and carries taste from the front of the tongue.", "2": "Cranial nerve XI is a motor nerve that controls muscles of the neck and shoulders."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0158' AND answer = 3;
UPDATE questions SET why = 'Humans have 31 pairs of spinal nerves, named after the region of the backbone they leave: 8 cervical, 12 thoracic, 5 lumbar, 5 sacral and 1 coccygeal pair. Check: 8 + 12 + 5 + 5 + 1 = 31.', wrong = '{"1": "This mixes up the counts. There are 7 cervical vertebrae but 8 pairs of cervical nerves, and only 1 coccygeal pair.", "2": "There are 12 thoracic pairs, not 10, and 5 each of lumbar and sacral pairs, not 6.", "3": "The cervical and thoracic numbers are swapped. There are 8 cervical and 12 thoracic pairs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0159' AND answer = 0;
UPDATE questions SET why = 'Each spinal nerve joins the spinal cord by two roots. The ventral root contains the axons of motor neurons, which carry impulses out to effectors. The dorsal root carries sensory fibres, whose cell bodies lie in the dorsal root ganglion.', wrong = '{"0": "Cell bodies of sensory neurons lie in the dorsal root ganglion, not in the ventral root.", "2": "Inter-neurons lie entirely inside the CNS. They are not found in the roots of spinal nerves.", "3": "The dorsal root ganglion is a swelling on the dorsal root, not part of the ventral root."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0160' AND answer = 1;
UPDATE questions SET why = 'The motor pathways of the PNS have two systems. The somatic nervous system is made of motor neurons that control skeletal muscles, which can be moved at will. In reflexes it acts without conscious control. Smooth muscle, heart muscle and glands are under autonomic control.', wrong = '{"1": "Smooth muscles of the gut are controlled by the autonomic nervous system, which is involuntary.", "2": "The rate and strength of the heartbeat are regulated by the autonomic nervous system.", "3": "Glands are controlled by the autonomic nervous system, for example the salivary and gastric glands."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0161' AND answer = 0;
UPDATE questions SET why = 'The motor neurons of the sympathetic nervous system originate from the thoracic and lumbar regions of the spinal cord. Their axons reach smooth muscles and glands of visceral organs and prepare the body for fight or flight.', wrong = '{"0": "The brain and sacral region of the spinal cord are the origin of the parasympathetic system.", "1": "Sympathetic neurons do not arise from the cervical region alone. They come from the thoracic and lumbar regions.", "3": "The cerebellum coordinates movement and posture. Autonomic motor neurons do not arise there."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0162' AND answer = 2;
UPDATE questions SET why = 'The sympathetic nervous system prepares the body for fight or flight. It dilates the pupils to let in more light and dilates the bronchioles so more air reaches the lungs. It also speeds up the heart and raises blood glucose.', wrong = '{"0": "Increased secretion of saliva is a parasympathetic effect. The sympathetic system decreases salivary secretion.", "1": "Increased movement of the digestive tract is parasympathetic. The sympathetic system decreases gut motility.", "2": "Contraction of the urinary bladder is parasympathetic. The sympathetic system relaxes the bladder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0163' AND answer = 3;
UPDATE questions SET why = 'During stress, the sympathetic system constricts the blood vessels in the skin, which diverts blood to the muscles and heart. It dilates the vessels in skeletal muscles. The parasympathetic system has no effect on either set of vessels.', wrong = '{"0": "The sympathetic system constricts, not dilates, skin vessels, and the parasympathetic system has no effect on them.", "2": "Constriction by the sympathetic system is correct, but the parasympathetic system does not dilate these vessels.", "3": "Dilation by the sympathetic system applies to blood vessels in skeletal muscles, not in the skin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0164' AND answer = 1;
UPDATE questions SET why = 'Parasympathetic motor neurons arise from the brain and the sacral region of the spinal cord. Many of them travel in the vagus nerve, cranial nerve X, which reaches the heart, lungs and digestive organs and returns them to their normal resting state.', wrong = '{"1": "The optic nerve, cranial nerve II, is purely sensory and carries vision. It has no parasympathetic motor neurons.", "2": "Thoracic spinal nerves carry the sympathetic outflow, not parasympathetic neurons.", "3": "Lumbar spinal nerves carry the sympathetic outflow, not parasympathetic neurons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0165' AND answer = 0;
UPDATE questions SET why = 'Taste buds are bulb-shaped chemoreceptors that open into the mouth through a taste pore. Each contains receptor cells with hair-like structures that detect chemicals, and basal cells, which act as stem cells and make new receptor cells to replace old ones.', wrong = '{"0": "Schwann cells are glial cells that make myelin around axons in the PNS. They are not part of a taste bud.", "2": "Merkel cells are touch receptors in the deepest layer of the epidermis, not in taste buds.", "3": "Rods are light-sensitive cells in the retina of the eye."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0166' AND answer = 1;
UPDATE questions SET why = 'When taste receptor cells are stimulated by chemicals in food, they produce impulses in sensory neurons. These impulses travel along cranial nerves VII, IX and X to the brainstem, and then to the taste areas of the cerebral cortex.', wrong = '{"0": "Cranial nerve I carries smell, II carries vision and III moves the eye. None of them carries taste.", "1": "Cranial nerve V carries face sensation and chewing, VIII hearing and balance, and XI neck and shoulder muscles.", "3": "Cranial nerves III, IV and VI are motor nerves that move the eyeball."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0167' AND answer = 2;
UPDATE questions SET why = 'Smell receptors are the ends of sensory neurons in the nasal epithelium. Their dendrites have cilia that project into the moist mucus. Airborne chemicals dissolve in this mucus and bind to receptor sites on the cilia, which starts impulses in the olfactory nerve, cranial nerve I.', wrong = '{"0": "The olfactory bulb receives nerve impulses from the nose. Odour molecules never reach it directly.", "1": "Odour molecules are detected in the nasal cavity, not after travelling through the blood to the brain.", "2": "Taste pores are openings of taste buds in the mouth. They detect chemicals in food, not airborne odours."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0168' AND answer = 3;
UPDATE questions SET why = 'Meissner''s corpuscles are sensory nerve endings enclosed in a capsule, found in the upper layer of the skin. They are especially common in the lips, fingertips, palms and soles, and they detect light touch and vibration.', wrong = '{"1": "Ruffini endings lie in the dermis and detect sustained pressure and stretching of the skin.", "2": "Pacinian corpuscles lie deeper in the skin and detect deep pressure and vibration.", "3": "Nociceptors are free nerve endings that detect pain, not light touch."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0169' AND answer = 0;
UPDATE questions SET why = 'Ruffini endings are sensory nerve endings enclosed in a capsule and located in the dermis. They detect sustained pressure and the stretching of the skin, for example when a joint bends.', wrong = '{"0": "Light touch on the fingertips is detected by Meissner''s corpuscles and Merkel cells.", "1": "Pain from injured cells is detected by nociceptors, which are free nerve endings.", "2": "Movement of hairs is detected by hair follicle receptors around the base of each hair."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0170' AND answer = 3;
UPDATE questions SET why = 'Thermoreceptors in the skin are naked dendrite endings of sensory neurons. Cold receptors lie immediately below the epidermis, while warm receptors lie slightly deeper, in the dermis. Other thermoreceptors in the hypothalamus monitor the temperature of the blood.', wrong = '{"0": "The hypothalamus does have thermoreceptors, but cold receptors are also found in the skin, just under the epidermis.", "1": "This reverses the positions. Cold receptors are the shallower ones; warm receptors lie deeper in the dermis.", "3": "Temperature receptors are spread throughout the skin of the body, not limited to the tongue."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0171' AND answer = 2;
UPDATE questions SET why = 'A psychoactive drug is any drug that alters brain function, mood or behaviour, such as alcohol, caffeine and nicotine. Narcotics are a smaller group: opioid painkillers such as morphine, codeine and oxycodone. So every narcotic is psychoactive, but not every psychoactive drug is a narcotic.', wrong = '{"0": "Alcohol, caffeine and nicotine are psychoactive but are not opioid narcotics, so not all psychoactive drugs are narcotics.", "2": "Caffeine is a stimulant found in coffee and tea that blocks adenosine. It is not an opioid.", "3": "Narcotics have a high potential for addiction and abuse, which is part of their definition."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0172' AND answer = 1;
UPDATE questions SET why = 'With continued use of a drug, the body adapts and becomes less sensitive to it. This is drug tolerance. The person then needs higher doses to get the same effect as before, which tends to deepen addiction.', wrong = '{"0": "Stopping a drug after dependence usually causes withdrawal symptoms such as headache, insomnia and anxiety.", "1": "Tolerance is the opposite. Each dose gives a smaller effect, so the drug seems less effective over time.", "2": "The drug still acts on the brain. The brain has simply become less responsive to the same dose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0173' AND answer = 3;
UPDATE questions SET why = 'Addictive drugs cause dopamine release and block its reabsorption into the presynaptic neuron, so dopamine builds up in the synaptic cleft. The brain adapts by reducing the number of dopamine receptors on the postsynaptic neuron. With fewer receptors, a higher dose is needed for the same pleasure.', wrong = '{"0": "Dopamine release continues. Tolerance comes from fewer receptors on the postsynaptic neuron, not from release stopping.", "2": "The drug blocks dopamine reabsorption, which is why dopamine accumulates in the cleft.", "3": "The number of postsynaptic dopamine receptors falls. Adding receptors would make the drug more effective, not less."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0174' AND answer = 1;
UPDATE questions SET why = 'Caffeine blocks adenosine, a neurotransmitter that promotes sleep and relaxation, so it raises alertness. Regular use leads to tolerance. If a regular user stops suddenly, withdrawal symptoms such as headaches and fatigue can occur.', wrong = '{"0": "Without caffeine, adenosine acts freely again, so the person feels more tired, not more alert.", "1": "Hallucinations of light are not a withdrawal symptom of caffeine. Headache and fatigue are typical.", "3": "Stopping caffeine suddenly after regular use does cause symptoms. They are not avoided at once."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0175' AND answer = 2;
UPDATE questions SET why = 'Cannabis is a psychoactive drug made from the dried flowering tops, leaves and stem of the Indian hemp plant, Cannabis sativa. Marijuana and hashish are cannabis drugs. They cause relaxation and altered perception, and long-term use impairs thinking and harms the lungs.', wrong = '{"1": "The opium poppy is the source of opium and its products, such as morphine and heroin.", "2": "Tobacco leaves are the source of nicotine, the addictive stimulant in cigarettes.", "3": "Coffee seeds (beans) are a source of caffeine, a mild stimulant."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0176' AND answer = 0;
UPDATE questions SET why = 'A stroke is damage to brain cells caused by interruption of the blood supply to part of the brain, due to a blocked or ruptured blood vessel. Because it arises from the blood vessels of the brain, it is classed as a vascular disorder.', wrong = '{"0": "Degenerative disorders involve gradual loss of nerve cells, such as Parkinson''s and Alzheimer''s diseases.", "1": "Functional disorders, such as headache, affect how the nervous system works without an obvious structural cause.", "2": "Infectious disorders, such as meningitis, are caused by viruses, bacteria, fungi or other pathogens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0177' AND answer = 3;
UPDATE questions SET why = 'There are two main types of stroke. A haemorrhagic stroke happens when a blood vessel in the brain leaks or ruptures, so blood escapes into brain tissue. An ischemic stroke happens when a vessel becomes narrowed or blocked.', wrong = '{"0": "Narrowing or blockage of a brain blood vessel causes an ischemic stroke, not a haemorrhagic one.", "1": "Infection and inflammation of the meninges is meningitis, an infectious disorder.", "3": "Death of dopamine-releasing neurons causes Parkinson''s disease, a degenerative disorder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0178' AND answer = 2;
UPDATE questions SET why = 'Meningitis is inflammation of the meninges due to infection. Bacterial meningitis is the most severe and life-threatening form, and it needs immediate antibiotic treatment. Vaccines can prevent some types.', wrong = '{"1": "Viral meningitis is usually less severe and often clears up on its own.", "2": "Fungal meningitis is rare and mostly affects people with weak immune systems. It is not the most severe type.", "3": "Parasitic infections are another possible cause, but they are not described as the most severe form."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0179' AND answer = 0;
UPDATE questions SET why = 'Headaches are divided into primary and secondary types. A primary headache, such as migraine or tension headache, is not caused by another condition. A secondary headache results from an underlying problem in the head or neck, such as bleeding in the brain, a tumour or meningitis.', wrong = '{"0": "A headache that is a problem in itself, such as migraine, is a primary headache.", "2": "Stress is linked with primary tension headaches. Secondary headaches have an underlying structural cause.", "3": "A secondary headache can signal a serious problem such as a tumour or meningitis, so it needs medical attention."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0180' AND answer = 1;
UPDATE questions SET why = 'Multiple sclerosis is an autoimmune disease of the CNS, meaning the immune system attacks the body''s own tissue. It damages the myelin sheath around axons, which slows or blocks impulses and leads to vision loss, pain, fatigue and poor coordination.', wrong = '{"0": "Bacterial infection of the meninges is bacterial meningitis, not multiple sclerosis.", "2": "Rupture of brain blood vessels causes a haemorrhagic stroke.", "3": "Multiple sclerosis affects myelin across the CNS. It is not caused by cutting a single cranial nerve."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0181' AND answer = 1;
UPDATE questions SET why = 'Degenerative disorders involve progressive deterioration of nerve cells in the brain, spinal cord or nerves. Huntington''s disease damages brain neurons and affects movement and thinking, and Alzheimer''s disease destroys memory and thinking ability, so both are degenerative.', wrong = '{"1": "Vascular disorders, such as stroke, arise from problems in the blood vessels of the brain.", "2": "Infectious disorders, such as meningitis, are caused by pathogens like bacteria and viruses.", "3": "Functional disorders, such as headache, have no clear structural cause and do not involve progressive nerve cell loss."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0182' AND answer = 0;
UPDATE questions SET why = 'Electroencephalography (EEG) measures the electrical activity of the brain. Metal electrodes on the scalp pick up the impulses passing between neurons, an amplifier magnifies them, and they are recorded as waveforms. It is painless and is used to study seizures, epilepsy and tumours.', wrong = '{"0": "Passing X-rays through the body and building cross-sectional images is how a CT scan works.", "1": "A strong magnetic field and radio waves are used in MRI, not EEG.", "2": "Injecting dye into the spinal cord is not part of an EEG, which only records signals from the scalp."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0183' AND answer = 3;
UPDATE questions SET why = 'Different EEG waves match different states of brain activity. Alpha waves show a physically and mentally relaxed state. Beta waves show normal alertness, gamma waves high perception and problem-solving, and theta and delta waves sleep.', wrong = '{"0": "Gamma waves are linked with high perception, learning and problem-solving, not alpha waves.", "1": "Beta waves are linked with the normal alert state and active thinking.", "3": "EEG can detect seizure activity, but alpha waves themselves show a relaxed brain, not a seizure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0184' AND answer = 2;
UPDATE questions SET why = 'A CT scan uses X-rays and a computer. Different tissues absorb X-rays to different degrees. An X-ray tube rotates around the patient, detectors record how much X-ray passes through, and a computer uses this to build cross-sectional images.', wrong = '{"0": "Differences in the number of hydrogen atoms in tissues are the basis of MRI, not CT.", "1": "Recording the electrical waves produced by neurons is the principle of EEG.", "3": "Using echoes of sound waves from organs is the principle of ultrasound scanning."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0185' AND answer = 2;
UPDATE questions SET why = 'MRI is based on the fact that tissues contain different amounts of hydrogen atoms, which behave like tiny magnets. The patient lies in a strong magnetic field, radio waves make the hydrogen atoms give out signals, and a computer turns these signals into detailed 3-D images.', wrong = '{"1": "An X-ray tube rotating around the patient is how a CT scan works.", "2": "Electrodes attached to the scalp are used in EEG to record brain electrical activity.", "3": "MRI does not depend on radioactive dyes. Its signals come from hydrogen atoms in the tissues."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0186' AND answer = 0;
UPDATE questions SET why = 'The nervous system uses electrical impulses for fast, short-term responses. The endocrine system uses hormones carried in the blood, which act more slowly but for longer. It therefore mainly controls long-term processes such as growth, metabolism and reproduction.', wrong = '{"1": "High-speed reflex actions are carried out by the nervous system through reflex arcs.", "2": "Voluntary movements of skeletal muscles are controlled by the somatic nervous system.", "3": "Conducting impulses along axons is a function of neurons in the nervous system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0187' AND answer = 0;
UPDATE questions SET why = 'Glands are of two types. Exocrine glands release their secretions into ducts, such as salivary glands. Endocrine glands have no ducts: they release their secretions, the hormones, directly into the blood or tissue fluid, which carries them around the body.', wrong = '{"0": "Releasing secretions into ducts is the feature of exocrine glands such as salivary and sweat glands.", "2": "Digestive enzymes are made by exocrine glands, such as the salivary glands and the exocrine part of the pancreas.", "3": "Endocrine glands are found throughout the body, for example the thyroid, adrenals, pancreas and gonads."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0188' AND answer = 1;
UPDATE questions SET why = 'Blood carries a hormone to every cell in the body, but only target cells respond. Target cells have receptors that bind that specific hormone. Binding to the receptor triggers changes inside the cell, while cells without the receptor are not affected.', wrong = '{"0": "The hormone is carried to all cells. Other cells ignore it because they lack the matching receptor.", "1": "Almost all body cells have a nucleus. Having a nucleus is not what decides whether a cell responds.", "2": "Endocrine glands release hormones into the general blood circulation, not only near the target."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0189' AND answer = 3;
UPDATE questions SET why = 'Peptide and protein hormones, such as insulin, glucagon and growth hormone, are chains of amino acids. They dissolve easily in blood, but they cannot pass through the lipid bilayer of the cell membrane. Their receptors are therefore on the cell surface.', wrong = '{"0": "Being lipid-soluble and entering the cell to act on the nucleus describes steroid hormones, not peptides.", "1": "Steroid hormones such as cortisol and testosterone are made from cholesterol. Peptides are made of amino acids.", "3": "Size alone is not the reason. Peptide hormones stay outside because they are water-soluble and cannot cross the membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0190' AND answer = 2;
UPDATE questions SET why = 'Glycoproteins are conjugated proteins: a protein joined to a carbohydrate group. Thyroid-stimulating hormone (TSH), follicle-stimulating hormone (FSH) and luteinizing hormone (LH) from the anterior pituitary are glycoprotein hormones. They are large and polar, so they cannot enter cells.', wrong = '{"0": "Insulin is a peptide hormone, a chain of amino acids without a carbohydrate group.", "2": "Thyroxine is an amino acid derivative made from tyrosine, not a glycoprotein.", "3": "Cortisol is a steroid hormone made from cholesterol by the adrenal cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0191' AND answer = 1;
UPDATE questions SET why = 'Amino acid derivative hormones are small molecules made from a single amino acid, usually tyrosine or tryptophan. Epinephrine, norepinephrine, thyroxine (T4) and tri-iodothyronine (T3) are made from tyrosine.', wrong = '{"1": "Cholesterol is the source of steroid hormones such as cortisol, aldosterone and testosterone.", "2": "Glucose is used for energy. It is not the starting material for these hormones.", "3": "Fatty acids are not the source of amino acid derivative hormones, which come from tyrosine or tryptophan."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0192' AND answer = 0;
UPDATE questions SET why = 'Amino acid derivative hormones can cross the cell membrane only if they behave more like lipids than proteins. Thyroxine (T4) and tri-iodothyronine (T3) can cross the membrane, while epinephrine and norepinephrine cannot and act on surface receptors.', wrong = '{"0": "Epinephrine and norepinephrine are amino acid derivatives that behave like proteins and cannot cross the membrane.", "1": "Insulin and glucagon are peptide hormones, not amino acid derivatives, and they cannot cross the membrane.", "2": "FSH and LH are glycoprotein hormones. They are large and polar and cannot cross the membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0193' AND answer = 3;
UPDATE questions SET why = 'Steroid hormones are made from cholesterol, a lipid, so they are lipid-soluble. They can pass through the lipid bilayer of the cell membrane and act directly on the nucleus. Examples are cortisol, aldosterone, testosterone, estrogen and progesterone.', wrong = '{"0": "Glycoproteins are large, polar molecules that cannot cross the membrane. Steroids are small lipids.", "1": "Water-soluble chains of amino acids are peptide hormones, which bind to receptors on the cell surface.", "3": "Hormones derived from tyrosine, such as thyroxine and epinephrine, are amino acid derivatives, not steroids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0194' AND answer = 2;
UPDATE questions SET why = 'Steroid hormones are derived from cholesterol. Aldosterone, made by the adrenal cortex, is a steroid that helps the kidneys manage salt and water balance. Cortisol, testosterone, estrogen and progesterone are other steroid hormones.', wrong = '{"0": "Glucagon from the pancreas is a peptide hormone that raises blood glucose.", "1": "Oxytocin is a peptide hormone made by the hypothalamus and released by the posterior pituitary.", "2": "Epinephrine from the adrenal medulla is an amino acid derivative made from tyrosine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0195' AND answer = 3;
UPDATE questions SET why = 'In 1902 Bayliss and Starling found that when acidic gastric juice enters the small intestine, a substance is released into the blood. They called it secretin. It travels to the pancreas and stimulates it to secrete pancreatic juice, which helps neutralise the acid.', wrong = '{"0": "Salivation is controlled by nerves when food is in the mouth. Secretin is released from the small intestine.", "1": "Making the liver store glycogen when blood glucose rises is the action of insulin.", "3": "Raising blood calcium by releasing calcium from bones is the action of parathormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0196' AND answer = 2;
UPDATE questions SET why = 'Hormones and neurotransmitters are both chemical messengers. Neurotransmitters act across a tiny synaptic cleft, so their effects are fast and brief. Hormones travel through the blood, so they are generally slower to act but their effects last longer.', wrong = '{"0": "This is the reverse. Neurotransmitters act quickly and briefly, while hormones act more slowly and for longer.", "2": "Neurotransmitters, not hormones, are released into synaptic clefts. Hormones are released into blood or tissue fluid.", "3": "Hormones are chemical messengers, as are neurotransmitters."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0197' AND answer = 1;
UPDATE questions SET why = 'The hypothalamus contains special neurosecretory cells. These cells conduct nerve impulses like normal neurons but also secrete hormones. This lets the hypothalamus link the nervous system with the endocrine system and control the pituitary gland.', wrong = '{"1": "Neurosecretory cells make hormones themselves, such as ADH and oxytocin. They do not just store pituitary hormones.", "2": "Myelin in the CNS is made by oligodendrocytes, which are glial cells, not neurosecretory cells.", "3": "Digestive enzymes are made by exocrine glands of the gut, not by cells of the hypothalamus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0198' AND answer = 0;
UPDATE questions SET why = 'Oxytocin and ADH are made by neurosecretory cells in the hypothalamus. These hormones travel down the axons of the same cells into the posterior pituitary. There they are stored until they are released into the blood.', wrong = '{"0": "Blood vessels link the hypothalamus with the anterior pituitary. The posterior pituitary receives hormones through axons.", "1": "Oxytocin and ADH are made in the hypothalamus, not in the anterior pituitary.", "2": "Cerebrospinal fluid fills the ventricles and central canal. It is not the route for these hormones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0199' AND answer = 3;
UPDATE questions SET why = 'Blood vessels connect the hypothalamus with the anterior pituitary. Neurosecretory cells of the hypothalamus release two kinds of hormones into these vessels: releasing hormones, which stimulate the anterior pituitary to secrete, and inhibiting hormones, which suppress its secretion.', wrong = '{"0": "Axons from the hypothalamus run into the posterior pituitary, not the anterior lobe.", "1": "Oxytocin and ADH are posterior pituitary hormones. They do not control the anterior pituitary.", "3": "The vagus nerve carries parasympathetic fibres to organs such as the heart and gut, not to the pituitary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0200' AND answer = 2;
UPDATE questions SET why = 'The hypothalamus controls growth hormone secretion with a pair of opposing hormones. Growth hormone releasing hormone stimulates the anterior pituitary to secrete GH, while somatostatin inhibits GH secretion.', wrong = '{"0": "Stimulating growth hormone secretion is the job of growth hormone releasing hormone (GHRH), the partner of somatostatin.", "2": "TSH secretion is stimulated by thyrotropin releasing hormone (TRH) from the hypothalamus.", "3": "Prolactin secretion is inhibited by prolactin inhibiting factor, which is actually dopamine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0201' AND answer = 1;
UPDATE questions SET why = 'Most hypothalamic hormones that act on the anterior pituitary are releasing hormones, but prolactin is mainly held in check. The hormone that inhibits prolactin secretion, prolactin inhibiting factor, is actually dopamine, a substance also known as a brain neurotransmitter.', wrong = '{"1": "Oxytocin is made in the hypothalamus but released from the posterior pituitary. It causes uterine contraction and milk ejection.", "2": "Somatostatin from the hypothalamus inhibits the secretion of growth hormone, not prolactin.", "3": "Serotonin is a neurotransmitter mostly made in the intestine. It is not prolactin inhibiting factor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0202' AND answer = 0;
UPDATE questions SET why = 'Gonadotropin releasing hormone travels from the hypothalamus to the anterior pituitary in blood vessels. It stimulates secretion of the two gonadotropins, FSH and LH, which act on the testes and ovaries.', wrong = '{"0": "TSH secretion is triggered by thyrotropin releasing hormone (TRH), not GnRH.", "2": "ACTH secretion is triggered by adrenocorticotropin releasing hormone.", "3": "Growth hormone secretion is triggered by growth hormone releasing hormone (GHRH)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0203' AND answer = 1;
UPDATE questions SET why = 'The pituitary gland hangs below the hypothalamus, attached to it by a stalk called the infundibulum. The stalk carries both the axons that run to the posterior pituitary and the blood vessels that reach the anterior pituitary.', wrong = '{"1": "The corpus callosum is a band of axons that joins the left and right cerebral hemispheres.", "2": "The hilum is the depressed area on the concave side of the kidney where vessels and the ureter enter or leave.", "3": "The pons is part of the brainstem that relays impulses between the cerebrum and cerebellum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0204' AND answer = 0;
UPDATE questions SET why = 'Adrenocorticotropic hormone (ACTH) from the anterior pituitary stimulates the adrenal cortex to secrete corticosteroids, such as cortisol and aldosterone. These help regulate glucose and salt balance. The adrenal medulla, by contrast, is controlled by nerves.', wrong = '{"0": "Secretion of epinephrine from the adrenal medulla is controlled by the nervous system, not by ACTH.", "1": "Stimulating the thyroid to make thyroxine is the role of thyroid-stimulating hormone (TSH).", "3": "Stimulating the mammary glands to produce milk is the role of prolactin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0205' AND answer = 2;
UPDATE questions SET why = 'Luteinizing hormone acts on the gonads in both sexes. In females it stimulates the ovaries to make estrogen and progesterone and triggers ovulation. In males it stimulates the testes to produce testosterone.', wrong = '{"0": "Development of ovarian follicles in females is stimulated by FSH.", "1": "Milk production by the mammary glands is stimulated by prolactin.", "2": "Water retention by the kidneys is caused by antidiuretic hormone (ADH)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0206' AND answer = 3;
UPDATE questions SET why = 'FSH (follicle-stimulating hormone) and LH (luteinizing hormone) both act on the gonads, the testes and ovaries. For this reason they are together called gonadotropins. Both are glycoprotein hormones made by the anterior pituitary.', wrong = '{"0": "Corticosteroids, such as cortisol and aldosterone, are steroid hormones of the adrenal cortex.", "2": "Catecholamines are hormones such as epinephrine from the adrenal medulla, not FSH and LH.", "3": "FSH and LH are made by the anterior pituitary, not by the neurosecretory cells of the hypothalamus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0207' AND answer = 1;
UPDATE questions SET why = 'The posterior pituitary contains the axons of neurosecretory cells whose cell bodies are in the hypothalamus. It does not make any hormone itself. It only stores ADH and oxytocin, which are made in the hypothalamus, and releases them into the blood.', wrong = '{"0": "ADH and oxytocin are made in the hypothalamus. The posterior pituitary only stores and releases them.", "1": "The posterior pituitary is linked to the hypothalamus by a tract of axons. Blood vessels link the hypothalamus with the anterior lobe.", "3": "Growth hormone is made by the anterior pituitary, not the posterior pituitary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0208' AND answer = 2;
UPDATE questions SET why = 'Two hormones work together in breast-feeding. Prolactin makes the mammary glands produce milk. Oxytocin then causes milk ejection by making the smooth muscles around the milk glands contract, squeezing the milk out.', wrong = '{"1": "Milk production is stimulated by prolactin. Oxytocin only ejects milk that is already made.", "2": "Oxytocin contracts the uterus, as in childbirth. It does not relax it.", "3": "Water retention by the kidneys is the action of ADH, not oxytocin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0209' AND answer = 0;
UPDATE questions SET why = 'Oxytocin makes the uterus contract during childbirth. In a breast-feeding mother, oxytocin release continues each time she nurses. These repeated uterine contractions help the uterus shrink back to its normal size faster than in mothers who do not breast-feed.', wrong = '{"0": "Prolactin acts on the mammary glands to make milk. It does not act on the uterus.", "1": "A rise in progesterone after delivery is not the reason. The uterus shrinks because oxytocin keeps causing contractions.", "2": "ADH controls water reabsorption in the kidneys. It has no role in the size of the uterus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0210' AND answer = 3;
UPDATE questions SET why = 'In humans the intermediate pituitary is a thin layer of cells between the anterior and posterior lobes. It produces melanocyte stimulating hormone (MSH), which stimulates melanocytes in skin and hair to produce and release melanin.', wrong = '{"1": "The posterior pituitary stores and releases ADH and oxytocin. It does not produce MSH.", "2": "The adrenal medulla secretes epinephrine and norepinephrine in stress.", "3": "The pineal gland produces melatonin, which controls sleep patterns. Despite the similar name, it is not MSH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0211' AND answer = 0;
UPDATE questions SET why = 'In an adult the growth plates of long bones have closed, so bones can no longer grow in length. Excess growth hormone then makes bones grow in thickness instead. This is acromegaly, with enlarged hands, feet, skull, nose and jaw.', wrong = '{"0": "Gigantism, with great height, results from excess GH in a growing child whose long bones can still lengthen.", "1": "Dwarfism with normal IQ results from too little growth hormone, not too much.", "2": "Cretinism results from a lack of thyroid hormones during foetal life and childhood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0212' AND answer = 3;
UPDATE questions SET why = 'In pituitary dwarfism, a lack of growth hormone slows development, so the person is short. However, the body parts stay in proportion, and brain development and IQ are not affected, which distinguishes it from cretinism.', wrong = '{"0": "Short stature with mental retardation describes cretinism, caused by a lack of thyroid hormones in childhood.", "2": "Enlarged hands and jaw are signs of acromegaly, caused by excess growth hormone in adults.", "3": "Producing large volumes of dilute urine is diabetes insipidus, caused by a lack of ADH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0213' AND answer = 1;
UPDATE questions SET why = 'Oxytocin stimulates the contractions of the uterus during childbirth. If too little oxytocin is secreted, contractions are weak and the normal process of labour is inhibited. Too much oxytocin, in contrast, can cause the uterine wall to rupture.', wrong = '{"0": "Rupture of the uterine wall is linked with over-secretion of oxytocin, not under-secretion.", "1": "Diabetes insipidus is caused by under-secretion of ADH, the other posterior pituitary hormone.", "3": "Gigantism is caused by too much growth hormone in childhood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0214' AND answer = 2;
UPDATE questions SET why = 'The thyroid gland produces much more T4 (thyroxine) than T3 (tri-iodothyronine). T4 is later converted into T3, which is the more active and powerful form. Both raise heart rate and breathing rate and set the basal metabolic rate.', wrong = '{"1": "This reverses the amounts. The thyroid makes mostly T4, which is then converted into the more active T3.", "2": "Thyroid hormones stimulate cellular respiration and raise the basal metabolic rate rather than lower it.", "3": "T3 and T4 increase heart rate. A low heart rate is a sign of hypothyroidism, a lack of these hormones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0215' AND answer = 0;
UPDATE questions SET why = 'Calcitonin is a thyroid hormone that helps keep blood calcium at the proper level. When blood calcium rises too high, calcitonin stimulates the uptake of calcium into bones, which lowers the calcium level in the blood.', wrong = '{"0": "Releasing calcium from bones into blood is the action of parathormone, which raises blood calcium.", "1": "Activation of vitamin D, needed to absorb calcium from food, is caused by parathormone.", "2": "Making the kidneys reabsorb calcium is an action of parathormone, which raises blood calcium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0216' AND answer = 3;
UPDATE questions SET why = 'Thyroid hormones promote growth of the skeleton and development of the brain in children. If thyroid hormones are lacking during foetal life and childhood, the child develops cretinism, a condition of stunted growth and mental retardation.', wrong = '{"0": "Acromegaly results from excess growth hormone in adults, not from a lack of thyroid hormones.", "2": "Graves'' disease is an autoimmune disease that causes hyperthyroidism, too much thyroid hormone.", "3": "Cushing disease is caused by excess cortisol from the adrenal cortex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0217' AND answer = 1;
UPDATE questions SET why = 'Iodine is needed to make thyroid hormones. If hypothyroidism is caused by iodine deficiency, the thyroid gland enlarges and forms a visible swelling in the neck. This swelling is called goitre.', wrong = '{"0": "Excess growth hormone causes gigantism or acromegaly, not swelling of the thyroid.", "1": "Excess calcium in the blood is linked with over-secretion of parathormone, not with goitre.", "3": "A lack of insulin causes diabetes mellitus, which does not swell the thyroid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0218' AND answer = 2;
UPDATE questions SET why = 'Myxoedema is a rare, life-threatening complication of severe hypothyroidism. Mucopolysaccharides, which are large carbohydrate molecules, build up in the connective tissues. This causes swelling and thickening of the skin and other tissues.', wrong = '{"0": "Protrusion of the eyeballs (exophthalmia) is linked with Graves'' disease, which causes hyperthyroidism.", "1": "Weight loss is a feature of hyperthyroidism. Hypothyroidism usually causes weight gain.", "2": "Muscles staying contracted due to low calcium is tetany, caused by under-secretion of parathormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0219' AND answer = 3;
UPDATE questions SET why = 'Graves'' disease is an autoimmune disease that causes hyperthyroidism, too much thyroid hormone. It often enlarges the thyroid. Its signs include fast heartbeat, poor tolerance of heat, weight loss and irritability, and it may cause protruding eyeballs (exophthalmia).', wrong = '{"1": "Graves'' disease raises thyroid hormone levels. Hypothyroidism in childhood is what causes cretinism.", "2": "Diabetes insipidus is caused by a lack of ADH from the posterior pituitary.", "3": "Addison''s disease is caused by under-secretion of hormones of the adrenal cortex, such as cortisol."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0220' AND answer = 0;
UPDATE questions SET why = 'The parathyroid glands are four small glands attached to the posterior surface of the thyroid gland in the neck. They secrete parathormone, which raises the calcium level of the blood when it falls too low.', wrong = '{"0": "Two glands on top of the kidneys are the adrenal glands.", "2": "A single gland at the base of the brain describes the pituitary gland.", "3": "Patches of endocrine cells in the pancreas are the islets of Langerhans."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0221' AND answer = 1;
UPDATE questions SET why = 'When blood calcium falls, parathormone raises it in three ways. It stimulates osteoclasts to dissolve calcium from the bone matrix, it makes the kidneys reabsorb calcium from urine, and it activates vitamin D so more calcium is absorbed from food.', wrong = '{"0": "Moving calcium into bones lowers blood calcium. That is the action of calcitonin.", "1": "Parathormone makes the kidneys reabsorb calcium, so it reduces calcium loss in urine.", "3": "Parathormone activates vitamin D, which is needed to absorb calcium from the intestine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0222' AND answer = 2;
UPDATE questions SET why = 'Too little parathormone leads to hypocalcaemia, a low blood calcium level. Low calcium makes neurons more excitable, so they fire too easily. This can cause tetany, a condition in which muscles stay contracted.', wrong = '{"0": "Soft, deformed bones result from too much parathormone, which removes excess calcium from bone.", "1": "Depression of the nervous system and muscle weakness are caused by high blood calcium, from too much parathormone.", "2": "Gigantism is caused by excess growth hormone in childhood, not by parathormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0223' AND answer = 3;
UPDATE questions SET why = 'The islets of Langerhans are patches of endocrine cells in the pancreas. They have two cell types. Beta (β) cells are more numerous and secrete insulin, while alpha (α) cells secrete glucagon.', wrong = '{"1": "Alpha cells secrete glucagon, not insulin, and they are the smaller group.", "2": "Beta cells do secrete insulin, but they are the larger group, not fewer than alpha cells.", "3": "Exocrine cells of the pancreas make pancreatic juice, which drains into the pancreatic duct. They do not secrete insulin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0224' AND answer = 0;
UPDATE questions SET why = 'Insulin lowers blood glucose. One way it does this is by promoting glycogenesis, the conversion of glucose into glycogen for storage in the liver. It also increases glucose uptake by cells, raises glucose use in respiration and promotes fat formation.', wrong = '{"0": "Breaking down liver glycogen releases glucose into blood. This is promoted by glucagon, not insulin.", "2": "Insulin inhibits gluconeogenesis, the making of new glucose. It does not stimulate it.", "3": "Insulin lowers the blood glucose level. Glucagon is the hormone that raises it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0225' AND answer = 1;
UPDATE questions SET why = 'Glucagon is secreted by alpha cells when blood glucose falls below normal. It mainly promotes the hydrolysis, or breakdown, of glycogen stored in the liver. The glucose released enters the blood and can be used by cells for energy.', wrong = '{"0": "Increasing glucose uptake by fat cells removes glucose from blood. This is an action of insulin.", "1": "Converting excess glucose into fat lowers blood glucose. This is an action of insulin.", "3": "Glycogenesis stores glucose as glycogen and lowers blood glucose. Insulin promotes it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0226' AND answer = 2;
UPDATE questions SET why = 'In diabetes mellitus, too little insulin means cells cannot take up glucose, so blood glucose rises above normal. This excess glucose in the blood inhibits water reabsorption by the kidneys, so large volumes of urine are produced. The result is dehydration and, over time, kidney damage.', wrong = '{"0": "A complete lack of ADH causes diabetes insipidus, a different disease from diabetes mellitus.", "2": "Glomerular filtration continues in diabetes mellitus. The problem is reduced water reabsorption.", "3": "Glucagon raises blood glucose but does not block the collecting ducts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0227' AND answer = 1;
UPDATE questions SET why = 'Insulin is a peptide hormone, a chain of amino acids. If it were swallowed, digestive enzymes in the stomach and intestine would break it down like any other protein. It must therefore be injected so it enters the blood intact.', wrong = '{"0": "Insulin is a peptide hormone, not a steroid. Steroids are lipid-soluble and made from cholesterol.", "1": "Sensitivity to light is not the reason. Insulin is injected because it would be digested if taken by mouth.", "3": "Insulin for injection is made by genetically engineered bacteria, but that is not why it must be injected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0228' AND answer = 2;
UPDATE questions SET why = 'In Type II diabetes, also called non-insulin-dependent diabetes, the blood usually contains normal levels of insulin. The problem is that the body''s cells have a reduced sensitivity to insulin. It is mainly controlled with medicines, diet and exercise.', wrong = '{"1": "Lacking insulin-secreting beta cells describes Type I diabetes, which needs daily insulin injections.", "2": "Too much ADH is not a feature of diabetes mellitus. ADH controls water reabsorption.", "3": "Type II diabetes is a problem of cells responding poorly to insulin, not of glucagon from tumours."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0229' AND answer = 0;
UPDATE questions SET why = 'Too much insulin removes glucose from the blood faster than it is supplied, so blood glucose falls below normal. This is hypoglycaemia. Brain cells depend on glucose, so the person feels lethargic, dizzy and nervous, and in extreme cases becomes unconscious.', wrong = '{"0": "Excessive urination and thirst are signs of high blood glucose in diabetes mellitus, the opposite condition.", "1": "Enlarged hands and jaw are signs of acromegaly, caused by excess growth hormone in adults.", "2": "Protruding eyeballs are a sign of Graves'' disease, a form of hyperthyroidism."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0230' AND answer = 3;
UPDATE questions SET why = 'The adrenal gland has two parts with different control. The inner adrenal medulla releases epinephrine and norepinephrine when it receives nerve signals during stress, so it is controlled by the nervous system. The outer adrenal cortex is controlled by hormones of the anterior pituitary.', wrong = '{"1": "ACTH from the anterior pituitary controls the adrenal cortex, not the medulla.", "2": "Renin from the kidneys controls aldosterone production by the adrenal cortex, not secretion from the medulla.", "3": "TSH from the anterior pituitary stimulates the thyroid gland, not the adrenal gland."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0231' AND answer = 0;
UPDATE questions SET why = 'Epinephrine and norepinephrine prepare the body for fight or flight. Heart rate, blood pressure and blood glucose rise and the bronchioles dilate. At the same time blood flow to the skin and digestive organs is reduced, so more blood is sent to the muscles and heart.', wrong = '{"0": "In fight or flight the heart beats faster and stronger. A slower heart rate is a parasympathetic, resting effect.", "1": "The bronchioles dilate so more air reaches the lungs. Constriction happens at rest.", "3": "Blood glucose rises to provide extra fuel for the muscles, rather than falling."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0232' AND answer = 2;
UPDATE questions SET why = 'Glucocorticoids such as cortisol maintain glucose homeostasis. They stimulate the breakdown of muscle protein into amino acids, which the blood carries to the liver. The liver then converts these amino acids into glucose, a process called gluconeogenesis.', wrong = '{"0": "Increasing sodium reabsorption by the kidneys is the action of aldosterone, a mineralocorticoid.", "1": "Cortisol breaks down muscle protein rather than building glycogen in muscle. Glycogenesis is promoted by insulin.", "2": "Stimulating milk production is the action of prolactin from the anterior pituitary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0233' AND answer = 3;
UPDATE questions SET why = 'Cushing disease occurs when the pituitary gland makes too much ACTH, so the adrenal cortex secretes excess cortisol. The extra cortisol causes heavy protein breakdown, leading to high blood sugar, high blood pressure, thin bones, muscle loss and thin, fragile skin.', wrong = '{"0": "Too little cortisol from the adrenal cortex causes Addison''s disease, not Cushing disease.", "2": "Too much thyroxine from the thyroid causes hyperthyroidism, with weight loss and fast heartbeat.", "3": "Too little insulin from the pancreas causes diabetes mellitus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0234' AND answer = 1;
UPDATE questions SET why = 'Addison''s disease results from under-secretion of cortisol by the adrenal cortex. It causes a general disturbance of metabolism, weakness of muscles and loss of salts, and its symptoms usually develop slowly.', wrong = '{"0": "Over-secretion of cortisol causes Cushing disease, the opposite condition.", "1": "Over-secretion of epinephrine and other adrenal medulla hormones may cause hypertension and aggressive behaviour.", "2": "Under-secretion of thyroxine causes hypothyroidism, with lethargy, weight gain and low heart rate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0235' AND answer = 3;
UPDATE questions SET why = 'FSH from the anterior pituitary makes ovarian follicles develop. The developing Graafian follicle secretes estrogen in response to FSH. Estrogen then builds up the uterine lining and controls female secondary sexual characteristics.', wrong = '{"1": "LH triggers ovulation and makes the corpus luteum secrete progesterone. Estrogen release from the follicle is the response to FSH.", "2": "ADH acts on the collecting ducts of the kidney to conserve water. It does not act on the ovary.", "3": "Prolactin acts on the mammary glands to make milk. It does not cause estrogen secretion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0236' AND answer = 0;
UPDATE questions SET why = 'After ovulation, LH makes the corpus luteum secrete progesterone. Progesterone thickens the uterine wall and increases its blood supply to maintain pregnancy. It also inhibits further FSH secretion from the pituitary, so no more follicles ripen.', wrong = '{"0": "Ovulation is triggered by a surge of LH. Progesterone suppresses ovulation instead.", "2": "Milk ejection is caused by oxytocin, which contracts the smooth muscle of the mammary glands.", "3": "Progesterone maintains the uterine lining. The lining breaks down when progesterone levels fall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0237' AND answer = 1;
UPDATE questions SET why = 'LH stimulates the testes to secrete androgens, the male sex hormones. Testosterone, the main androgen, is secreted by the interstitial cells that lie between the seminiferous tubules. These cells are also called Leydig cells.', wrong = '{"0": "Sertoli cells inside the seminiferous tubules nourish developing sperms. They are not the source of testosterone.", "1": "The adrenal medulla secretes epinephrine and norepinephrine, not testosterone.", "3": "The corpus luteum is in the ovary and secretes progesterone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0238' AND answer = 2;
UPDATE questions SET why = 'Progesterone keeps the uterine wall thick and well supplied with blood, which is needed to maintain a pregnancy. If too little progesterone is secreted during pregnancy, the uterine lining cannot be maintained and miscarriage may result.', wrong = '{"1": "Gigantism is caused by too much growth hormone in childhood.", "2": "Goitre is a swelling of the thyroid caused by iodine deficiency.", "3": "Tetany, in which muscles stay contracted, is caused by low blood calcium from too little parathormone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0239' AND answer = 0;
UPDATE questions SET why = 'Anabolic steroids are man-made versions of testosterone. Athletes have misused them because they increase muscle mass, strength and endurance. Their use in sport is illegal, and they can damage the liver, raise the risk of heart disease and disturb natural hormone balance.', wrong = '{"0": "Insulin is a peptide hormone from the pancreas that lowers blood glucose. It is not a steroid.", "1": "Thyroxine is an amino acid derivative from the thyroid. It is not what anabolic steroids copy.", "2": "Cortisol is a steroid, but it breaks down muscle protein. Anabolic steroids copy testosterone, which builds muscle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0240' AND answer = 3;
UPDATE questions SET why = 'The thymus gland lies beneath the sternum, between the lungs. It secretes the hormone thymosin, which stimulates the maturation of T cells. T cells are white blood cells that help defend the body against pathogens.', wrong = '{"0": "Sleep patterns are regulated by melatonin from the pineal gland.", "2": "Bile release from the gallbladder is stimulated by cholecystokinin from the small intestine wall.", "3": "Blood calcium is raised by parathormone from the parathyroid glands."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0241' AND answer = 1;
UPDATE questions SET why = 'Endocrine cells in the walls of digestive organs control digestion. When food arrives, the small intestine wall releases cholecystokinin, which makes the gallbladder release bile. The same wall also releases secretin, which acts on the pancreas.', wrong = '{"0": "Gastrin comes from the stomach wall and stimulates gastric glands to release gastric juice.", "1": "Secretin from the small intestine stimulates the pancreas to release pancreatic juice, not bile.", "3": "Erythropoietin is made by the kidneys and stimulates red blood cell production."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0242' AND answer = 2;
UPDATE questions SET why = 'The kidneys produce erythropoietin, a hormone that acts on the bone marrow and stimulates it to produce red blood cells (RBCs). The kidneys also make renin, which controls aldosterone, and calcitriol, which raises blood calcium.', wrong = '{"0": "Stimulating the stomach to release gastric juice is the action of gastrin from the stomach wall.", "2": "Lowering blood calcium is the action of calcitonin from the thyroid gland.", "3": "Sleep is controlled by melatonin from the pineal gland."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0243' AND answer = 1;
UPDATE questions SET why = 'Prostaglandins are hormone-like substances made by almost all cells of the body. Unlike true hormones, they act locally, near where they are made. They are powerful vasodilators, meaning they widen blood vessels, and they are involved in inflammation.', wrong = '{"0": "Prostaglandins are made by almost all body cells, not only by the pituitary, and they act locally rather than on distant glands.", "1": "Prostaglandins are not described as steroid hormones acting on gonad cells. They are local, hormone-like substances.", "3": "Milk production is stimulated by prolactin from the anterior pituitary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0244' AND answer = 2;
UPDATE questions SET why = 'In positive feedback, the response speeds up the controlling system. During childbirth, uterine contractions signal the hypothalamus, which causes oxytocin release. Oxytocin makes the contractions stronger, which causes more oxytocin release, and the loop continues until the baby is born.', wrong = '{"1": "In negative feedback the product switches the process off, as when normal glucose stops insulin release. Oxytocin release keeps building instead.", "2": "Oxytocin is a hormone, so this loop is not purely nervous. It involves both nerves and a hormone.", "3": "Antagonism means two hormones with opposite effects, like insulin and glucagon. Only oxytocin drives this loop."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0245' AND answer = 0;
UPDATE questions SET why = 'In negative feedback the end product stops the process. A rise in blood glucose makes beta cells release insulin, and insulin lowers the glucose level. Once blood glucose is back to normal, this normal level signals the beta cells to stop releasing insulin.', wrong = '{"0": "A rise in blood glucose above normal is what starts insulin release, not what stops it.", "1": "Glucagon is released by alpha cells, not beta cells, when blood glucose is low.", "2": "Oxytocin controls uterine contraction and milk ejection. It plays no part in glucose regulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0246' AND answer = 3;
UPDATE questions SET why = 'Most organ systems, such as the digestive or urinary system, are nearly the same in males and females and work from birth. The reproductive system is different in two ways: it is quite different in the two sexes, and it becomes functional only at puberty.', wrong = '{"1": "The reproductive system does not work from birth. It matures and starts working at puberty.", "2": "The male and female reproductive systems are very different in structure and function.", "3": "The reproductive system is controlled largely by hormones such as FSH, LH, testosterone and estrogen, not only by nerves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0247' AND answer = 0;
UPDATE questions SET why = 'The testes form inside the abdomen and descend into the scrotum shortly before birth. The scrotum keeps them at about 34 °C, slightly below the core body temperature of 37 °C. This lower temperature is needed for the development of sperms.', wrong = '{"0": "37 °C, the core body temperature, is too warm for normal sperm development. That is why the testes lie outside the abdomen.", "2": "40 °C is above body temperature and would harm sperm development.", "3": "25 °C is far below the temperature the scrotum maintains, which is about 34 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0248' AND answer = 1;
UPDATE questions SET why = 'The wall of each seminiferous tubule, the germinal epithelium, has two kinds of cells. Germline cells divide to make sperms, while Sertoli cells nourish the developing sperms. Sertoli cells also release inhibin and secrete fluid that carries sperms to the epididymis.', wrong = '{"0": "Sperms are produced by the germline cells, which divide by mitosis and then meiosis. Sertoli cells support them.", "1": "Testosterone is secreted by Leydig cells, the interstitial cells between the seminiferous tubules.", "3": "Fructose-rich fluid that gives sperms energy is produced by the seminal vesicles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0249' AND answer = 2;
UPDATE questions SET why = 'Sperms leave the seminiferous tubules and enter a network of small tubules called the rete testis. From there they pass into the long, coiled epididymis, where they mature. They then move into the vas deferens.', wrong = '{"0": "The vas deferens comes after the epididymis, and the rete testis comes first, so this order is reversed.", "1": "The rete testis comes before the epididymis, not after it.", "2": "The ejaculatory duct is near the end of the route, formed after the vas deferens joins a seminal vesicle duct."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0250' AND answer = 3;
UPDATE questions SET why = 'Sperms that enter the epididymis are still non-motile, meaning they cannot swim. They must remain in the epididymis for at least 18 hours. After this they become motile and move on into the vas deferens.', wrong = '{"0": "18 minutes is far too short. Sperms need at least 18 hours in the epididymis to become motile.", "1": "18 days is longer than the minimum stated. Sperms become motile after at least 18 hours.", "3": "18 weeks is far too long. The minimum time is about 18 hours."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0251' AND answer = 2;
UPDATE questions SET why = 'On each side, the vas deferens joins a duct coming from a seminal vesicle. After this junction the tube is called the ejaculatory duct. The two ejaculatory ducts pass through the prostate gland and open into the urethra.', wrong = '{"0": "The two vasa deferentia do not join each other. Each joins its own seminal vesicle duct, giving two ejaculatory ducts.", "1": "The ejaculatory ducts open into the urethra inside the prostate. The urethra and prostate do not form the duct.", "2": "The rete testis and epididymis are earlier parts of the route, inside and beside the testis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0252' AND answer = 3;
UPDATE questions SET why = 'The testes lie outside the abdomen in the scrotum. The vas deferens carries sperms from the epididymis upward and passes into the abdominal cavity through an opening in the abdominal wall called the inguinal canal.', wrong = '{"1": "The urethra carries urine and semen out of the body through the penis. It is not the route into the abdomen.", "2": "The cervix is the lower narrow part of the female uterus.", "3": "The ureter carries urine from the kidney to the urinary bladder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0253' AND answer = 0;
UPDATE questions SET why = 'Semen is a mixture of sperms and fluids from accessory glands. The prostate gland, a soft and spongy gland just below the urinary bladder, produces about 60% of the fluid of semen.', wrong = '{"0": "The seminal vesicles add a fructose-rich fluid that gives sperms energy, but the prostate is the gland that makes about 60% of the fluid.", "2": "The bulbourethral glands add only a small amount of clear fluid that lubricates the urethra.", "3": "The testes produce the sperms themselves, not most of the fluid of semen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0254' AND answer = 1;
UPDATE questions SET why = 'The two small bulbourethral glands secrete a clear fluid. It lubricates the urethra for the passage of sperms and provides a protective, neutral environment in which sperms can survive.', wrong = '{"0": "Fructose, which supplies energy to sperms, comes from the seminal vesicles.", "1": "Most of the fluid of semen, about 60%, comes from the prostate gland.", "2": "Enzymes that help the sperm enter the ovum are stored in the acrosome on the sperm''s head."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0255' AND answer = 3;
UPDATE questions SET why = 'Germline cells, spermatogonia and primary spermatocytes are all diploid (2n). Each primary spermatocyte divides by meiosis I, which halves the chromosome number, to give two secondary spermatocytes. These are the first haploid (1n) cells formed.', wrong = '{"0": "Primary spermatocytes are still diploid (2n). They become haploid only after meiosis I.", "2": "Spermatogonia are diploid (2n). They are formed by mitosis and later become primary spermatocytes.", "3": "Germline cells are diploid (2n) and divide by mitosis to give spermatogonia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0256' AND answer = 1;
UPDATE questions SET why = 'Each spermatogonium becomes a primary spermatocyte that undergoes meiosis. Meiosis I gives two secondary spermatocytes, and meiosis II divides each again, giving four spermatids in total. Each spermatid matures into a sperm.', wrong = '{"1": "One functional cell per meiosis is the result of oogenesis, which gives one ovum and polar bodies.", "2": "Two cells are present only after meiosis I. Meiosis II doubles this to four.", "3": "Meiosis has two divisions, giving four cells, not eight."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0257' AND answer = 0;
UPDATE questions SET why = 'A sperm has a head, midpiece and tail. The acrosome is a thick cap covering about two-thirds of the head. It is formed mainly from the Golgi body and contains enzymes that help the sperm penetrate and fertilize the ovum.', wrong = '{"0": "Mitochondria are found in the midpiece, where they supply energy for swimming. They do not form the acrosome.", "1": "The centriole is in the midpiece and gives rise to the microtubules of the tail, not the acrosome.", "3": "The nucleus in the head carries the genetic material. The acrosome is a separate cap over it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0258' AND answer = 2;
UPDATE questions SET why = 'The midpiece of a sperm contains mitochondria and a centriole. The mitochondria supply ATP for swimming, and the microtubules of the tail, called the axial filament, arise from the centriole.', wrong = '{"0": "The acrosome is the cap on the head, not part of the midpiece.", "1": "The nucleus with the genetic material is in the head of the sperm.", "2": "The midpiece is not just a store of Golgi enzymes. Its key contents are mitochondria and a centriole."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0259' AND answer = 3;
UPDATE questions SET why = 'GnRH from the hypothalamus makes the anterior pituitary release FSH and LH. In males, LH acts on the Leydig cells in the interstitial tissue between the seminiferous tubules and stimulates them to secrete testosterone.', wrong = '{"0": "Starting spermatogenesis in the seminiferous tubules is the action of FSH, not LH.", "2": "Inhibin is released by Sertoli cells in response to FSH, and it inhibits further FSH secretion.", "3": "GnRH comes from the hypothalamus and causes LH release. LH does not stimulate GnRH; testosterone actually inhibits it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0260' AND answer = 1;
UPDATE questions SET why = 'When FSH from the anterior pituitary acts on the testes, it makes Sertoli cells release a peptide hormone called inhibin. Inhibin travels back to the pituitary and inhibits further FSH secretion. This negative feedback keeps sperm production steady.', wrong = '{"1": "Testosterone secretion is stimulated by LH acting on Leydig cells. Inhibin does not stimulate it.", "2": "Inhibin does not stimulate LH. LH release is held in check by testosterone, through negative feedback.", "3": "Sperms become motile while they stay in the epididymis, not because of inhibin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0261' AND answer = 0;
UPDATE questions SET why = 'LH stimulates Leydig cells to secrete testosterone. When blood testosterone rises, it inhibits the release of LH from the anterior pituitary and GnRH from the hypothalamus. This negative feedback stops testosterone from rising too high.', wrong = '{"0": "Testosterone exerts negative feedback, so a high level reduces LH release rather than increasing it.", "1": "Inhibin is released by Sertoli cells in response to FSH, not in response to testosterone.", "3": "Testosterone does act on the hypothalamus, where it inhibits the release of GnRH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0262' AND answer = 2;
UPDATE questions SET why = 'Each ovary contains many tiny sac-like structures called ovarian follicles. They are the functional units of the ovary, because each follicle nurtures an immature egg. Each month one ripening follicle releases its egg at ovulation.', wrong = '{"1": "Seminiferous tubules are found in the testes, where sperms are made.", "2": "Nephrons are the functional units of the kidney, not the ovary.", "3": "The endometrium is the inner lining of the uterus. It does not hold immature eggs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0263' AND answer = 0;
UPDATE questions SET why = 'At ovulation the mature follicle releases its egg. LH then turns the ruptured follicle into a yellow glandular structure called the corpus luteum. It secretes progesterone and estrogen, which prepare the uterine lining for pregnancy.', wrong = '{"0": "The Graafian follicle is the mature follicle before ovulation. It becomes the corpus luteum only after it ruptures.", "2": "A polar body is a small haploid cell formed during the unequal divisions of oogenesis.", "3": "The placenta forms from the endometrium during pregnancy, not from the ruptured follicle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0264' AND answer = 1;
UPDATE questions SET why = 'The ovum cannot swim by itself. Its movement along the oviduct toward the uterus is helped by the beating of cilia on the inner lining of the oviduct. Fertilization also takes place in the oviduct.', wrong = '{"0": "The ovum has no flagellum. Only sperms have a tail for swimming.", "1": "The oviduct is not made of skeletal muscle. The ovum is moved mainly by cilia.", "3": "Menstrual blood flows out through the vagina. It does not carry the ovum toward the uterus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0265' AND answer = 2;
UPDATE questions SET why = 'The uterus has three parts. The fundus is the uppermost rounded portion, above the openings of the oviducts. The body is the main middle portion, and the cervix is the narrow lower part that opens into the vagina.', wrong = '{"0": "The cervix is the narrow lower part of the uterus that leads into the vagina.", "1": "The body is the main portion of the uterus, below the fundus.", "2": "The vagina is a separate tube from the cervix to the outside, not part of the uterus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0266' AND answer = 3;
UPDATE questions SET why = 'The uterine wall has three layers. The outer perimetrium is thin, the middle myometrium is thick and made of smooth muscle, and the inner endometrium is the spongy lining. The myometrium contracts strongly during childbirth.', wrong = '{"1": "The perimetrium is the thin outermost layer of the uterine wall, not the thick muscular one.", "2": "The endometrium is the inner spongy lining, which thickens and is shed in the menstrual cycle.", "3": "Germinal epithelium is the wall of the seminiferous tubules in the testes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0267' AND answer = 0;
UPDATE questions SET why = 'The endometrium has a basal layer and a functional layer. The functional layer thickens each cycle and is shed during menstruation. The basal layer stays in place and contains stem cells that regenerate a new functional layer.', wrong = '{"0": "The roles are reversed. The functional layer is shed, and the basal layer rebuilds it.", "2": "The myometrium and perimetrium are not shed. Only the functional layer of the endometrium is lost.", "3": "If the basal layer were shed too, no stem cells would remain to rebuild the lining."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0268' AND answer = 1;
UPDATE questions SET why = 'The vagina is a thin-walled tube about 8 to 10 cm long. It leads from the outside to the cervix of the uterus and is the passage for menstrual flow and for delivery of the baby.', wrong = '{"0": "25 cm is about the length of a ureter, far longer than the vagina.", "1": "2 to 3 cm is about the width of an ovary or testis, too short for the vagina.", "3": "30 to 40 cm is far too long. The vagina is about 8 to 10 cm long."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0269' AND answer = 2;
UPDATE questions SET why = 'Oogenesis begins before birth. Oogonia divide by mitosis to give primary oocytes, which begin meiosis I but stop in prophase I. They stay arrested in prophase I through childhood, for at least 10 to 14 years, until puberty.', wrong = '{"0": "Arrest at metaphase II applies to the secondary oocyte, which forms later, at puberty.", "1": "Primary oocytes stop in prophase I, the first stage of meiosis I, not in anaphase I.", "2": "Meiosis II is completed only after a sperm fuses with the secondary oocyte, not at ovulation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0270' AND answer = 3;
UPDATE questions SET why = 'When a primary oocyte completes meiosis I, the cytoplasm divides unequally. The result is a large secondary oocyte and a small first polar body. Both are haploid (1n) because meiosis I halves the chromosome number.', wrong = '{"1": "The two cells are not equal. Most of the cytoplasm goes to the secondary oocyte, and the polar body is tiny.", "2": "Oogenesis does not produce four ova. It produces one ovum and small polar bodies.", "3": "Meiosis I gives only two cells. The ovum and second polar body form later, after fertilization."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0271' AND answer = 0;
UPDATE questions SET why = 'The secondary oocyte stops at metaphase II and is released from the ovary in that state. If a sperm fuses with it in the oviduct, it quickly completes meiosis II, producing one large ovum and a small second polar body. Without fertilization it dies.', wrong = '{"0": "At ovulation the secondary oocyte is still arrested at metaphase II, so meiosis II is not yet complete.", "2": "Only meiosis I begins during embryonic life, and it stops in prophase I.", "3": "Oocytes do not all complete meiosis together. Meiosis II is finished only if a sperm fuses with the oocyte."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0272' AND answer = 1;
UPDATE questions SET why = 'Oogonia divide during embryonic development to form a large stock of primary oocytes, each inside a follicle. At birth a female''s ovaries contain some 2 million follicles. Only a few hundred of these will ever be ovulated.', wrong = '{"0": "About 400 is roughly the number of eggs ovulated in a lifetime, not the number of follicles present at birth.", "1": "20 thousand is about a hundred times too few. The ovaries hold some 2 million follicles at birth.", "2": "200 million is about a hundred times too many. The figure is some 2 million."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0273' AND answer = 3;
UPDATE questions SET why = 'At the end of a cycle without pregnancy, estrogen and progesterone levels are low. Without these hormones the functional layer of the endometrium cannot be maintained, so it is shed with blood. This is the menstrual phase, days 1 to 5.', wrong = '{"0": "A sudden surge of LH causes ovulation around day 14, not menstruation.", "1": "High progesterone keeps the uterine lining thick. Menstruation happens when it falls.", "3": "hCG from an embryo keeps the corpus luteum working and prevents menstruation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0274' AND answer = 2;
UPDATE questions SET why = 'In the proliferative phase, rising FSH makes a follicle grow into the Graafian follicle. FSH also stimulates this follicle to secrete estrogen. Estrogen rebuilds the endometrium, making it thick, velvety and well supplied with blood again.', wrong = '{"0": "The corpus luteum forms only after ovulation, in the secretory phase, so its progesterone is not present yet.", "1": "Oxytocin from the posterior pituitary causes uterine contraction and milk ejection, not rebuilding of the lining.", "3": "Testosterone does not rebuild the endometrium. Estrogen from the follicle does."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0275' AND answer = 2;
UPDATE questions SET why = 'At the start of each cycle a rise in FSH makes a few ovarian follicles begin to grow. Usually only one keeps growing to become the mature Graafian follicle, which releases the egg. The other follicles degenerate.', wrong = '{"0": "Usually only one follicle releases an ovum at ovulation. The others stop growing and degenerate.", "1": "Two follicles do not always mature. Usually only one does, so twins are not the normal result.", "2": "A follicle matures in every cycle, whether or not pregnancy follows."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0276' AND answer = 3;
UPDATE questions SET why = 'During the proliferative phase, FSH makes the Graafian follicle secrete estrogen. As estrogen rises, it acts back on the anterior pituitary and the FSH level falls. This is negative feedback, because the product lowers the hormone that caused it.', wrong = '{"0": "FSH falls, not rises, as estrogen increases in this phase, because of negative feedback.", "2": "FSH does not stay constant. It falls as estrogen builds up.", "3": "Ovulation is caused by a sudden release of LH, not a sharp rise in FSH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0277' AND answer = 1;
UPDATE questions SET why = 'After ovulation, LH turns the ruptured follicle into the corpus luteum. In the secretory phase it secretes estrogen and progesterone, which make the endometrium more vascular and glandular, ready to receive an embryo.', wrong = '{"1": "FSH and LH are secreted by the anterior pituitary, not by the corpus luteum.", "2": "Oxytocin is made by the hypothalamus and released by the posterior pituitary.", "3": "hCG is made by the chorion of an embryo, and only after fertilization."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0278' AND answer = 0;
UPDATE questions SET why = 'If no fertilization occurs, the corpus luteum degenerates and LH secretion stops. Without the corpus luteum, the levels of estrogen and progesterone fall sharply. The thickened endometrium can no longer be maintained and is shed with bleeding around day 28.', wrong = '{"1": "Without pregnancy the corpus luteum shrinks and breaks down. It does not grow or secrete more progesterone.", "2": "hCG is made only by an embryo. Its absence, not a rise, is why the corpus luteum degenerates.", "3": "FSH rises again at the start of the next cycle. It does not stop for the rest of life."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0279' AND answer = 0;
UPDATE questions SET why = 'After fertilization, the tiny embryo secretes human chorionic gonadotropin (hCG) from its chorion. hCG keeps the corpus luteum working, so estrogen and progesterone stay high and menstruation is prevented. Because hCG comes from the embryo, its presence shows pregnancy.', wrong = '{"0": "hCG is not made by the mother''s pituitary. It comes from the chorion of the embryo.", "1": "hCG is a separate hormone made by the embryo. FSH is made by the anterior pituitary.", "3": "hCG is not released at ovulation. It appears only after fertilization, when an embryo is present."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0280' AND answer = 2;
UPDATE questions SET why = 'In human females the menstrual cycle stops at around 50 years of age. This permanent end of menstrual cycles is called menopause. After menopause, ovulation and menstruation no longer occur.', wrong = '{"0": "Puberty is the stage when the menstrual cycle begins, not when it ends.", "2": "Ovulation is the release of an egg from the ovary in each cycle.", "3": "Menstruation is the monthly shedding of the functional layer of the endometrium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0281' AND answer = 1;
UPDATE questions SET why = 'A true-breeding, or pure-breeding, plant is homozygous for the trait. When it is self-fertilized, all its offspring show the same trait as the parent, generation after generation. Mendel started his experiments with true-breeding pea varieties.', wrong = '{"1": "A true-breeding plant can show either the dominant trait (for example RR) or the recessive one (rr).", "2": "A 3:1 ratio on selfing comes from a heterozygous plant, which is not true-breeding.", "3": "Pea plants normally self-fertilize, and true-breeding plants are tested by self-fertilizing them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0282' AND answer = 0;
UPDATE questions SET why = 'Mendel self-fertilized his F2 plants. Of the dominant-looking plants, one-third bred true and two-thirds did not. So the F2 was really 1/4 pure-breeding dominant, 2/4 non-pure-breeding dominant and 1/4 pure-breeding recessive, a 1:2:1 ratio hidden inside 3:1.', wrong = '{"0": "9:3:3:1 is the F2 ratio of a dihybrid cross, involving two genes, not a monohybrid cross.", "2": "A 1:1 ratio results from a testcross of a heterozygote with a recessive plant.", "3": "A 2:1 ratio is not what Mendel found. His 3:1 ratio split into 1:2:1 genotypes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0283' AND answer = 1;
UPDATE questions SET why = 'Each gene occupies a particular position on a particular chromosome. This position is called the gene''s locus. The alleles of a gene are found at the same locus on the two homologous chromosomes.', wrong = '{"0": "An allele is one of the alternative forms of a gene, such as R or r, not its position.", "1": "A genotype is the combination of alleles an individual has, such as Rr.", "3": "A karyotype is the complete set of chromosomes of a cell, arranged by size and shape."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0284' AND answer = 2;
UPDATE questions SET why = 'An individual carries two alleles of each gene, one from each parent. If the two alleles are different, such as Rr, the individual is heterozygous for that gene. If they are the same, such as RR or rr, it is homozygous.', wrong = '{"0": "Homozygous means the two alleles of the gene are identical, such as RR or rr.", "1": "Hemizygous describes a gene present in only one copy, such as an X-linked gene in a male.", "2": "True-breeding individuals are homozygous, so they have two identical alleles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0285' AND answer = 3;
UPDATE questions SET why = 'Mendel''s law of segregation states that the two alleles of a gene separate during gamete formation. Each gamete receives only one allele of each gene, and which allele it gets is a matter of chance. At fertilization the pair is restored.', wrong = '{"0": "Alleles of different genes staying together would be complete linkage, which is not Mendel''s law of segregation.", "2": "Gametes are haploid, so each carries only one allele of each gene, not both.", "3": "Each allele, dominant or recessive, has an equal chance of entering a gamete."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0286' AND answer = 1;
UPDATE questions SET why = 'A testcross crosses a dominant-looking plant with a homozygous recessive (rr) plant. If the round parent were Rr, about half the offspring would be wrinkled. Since all offspring are round, the round parent must be RR, giving only Rr offspring.', wrong = '{"0": "Rr × rr gives round (Rr) and wrinkled (rr) offspring in a 1:1 ratio, so some wrinkled seeds would appear.", "1": "An rr plant has wrinkled seeds, but this parent was round.", "2": "The result is not ambiguous. All-round offspring point clearly to RR, since Rr would give wrinkled seeds too."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0287' AND answer = 3;
UPDATE questions SET why = 'The RRYY parent can only make RY gametes and the rryy parent only ry gametes. Every F1 offspring is therefore RrYy. Round and yellow are dominant, so all F1 seeds are round and yellow, and they are dihybrids, heterozygous for both genes.', wrong = '{"0": "Wrinkled and green are both recessive traits. They appear only in rryy plants, which the F1 cannot be.", "1": "Yellow (Y) is dominant over green, and every F1 seed receives one Y allele, so none is green.", "3": "The 9:3:3:1 ratio appears in the F2, after the F1 dihybrids are crossed together."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0288' AND answer = 2;
UPDATE questions SET why = 'During gamete formation the R/r alleles separate independently of the Y/y alleles. Each gamete gets one allele of each gene, giving 2 × 2 = 4 kinds: RY, Ry, rY and ry, in equal proportions.', wrong = '{"1": "R and r are alleles of one gene. Each gamete must also carry one allele of the Y gene.", "2": "RY and ry are only the parental combinations. Independent assortment also gives Ry and rY.", "3": "Sixteen is the number of boxes in the Punnett square (4 × 4) when two dihybrids are crossed, not the kinds of gametes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0289' AND answer = 0;
UPDATE questions SET why = 'Crossing two RrYy plants gives an F2 ratio of 9 round yellow : 3 round green : 3 wrinkled yellow : 1 wrinkled green, out of 16. Wrinkled yellow seeds are rrY_, so their fraction is 3/16, which equals 1/4 × 3/4.', wrong = '{"0": "9/16 is the fraction of round yellow seeds, which show both dominant traits.", "2": "1/16 is the fraction of wrinkled green seeds (rryy), which show both recessive traits.", "3": "1/4 (4/16) is the fraction of all wrinkled seeds, both yellow and green, not wrinkled yellow alone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0290' AND answer = 1;
UPDATE questions SET why = 'Independent assortment does not change how each gene pair segregates on its own. Round seeds are the round yellow plus round green classes, 9 + 3 = 12, and wrinkled seeds are 3 + 1 = 4. So round : wrinkled = 12 : 4 = 3 : 1, the usual monohybrid ratio.', wrong = '{"0": "9:7 is a modified ratio seen in some cases of gene interaction. It cannot be made from these four classes.", "1": "Round is dominant, so round seeds must outnumber wrinkled ones. A 1:1 ratio would come from a testcross.", "2": "9:3 compares only two of the four classes and leaves out the round green and wrinkled green seeds."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0291' AND answer = 3;
UPDATE questions SET why = 'During meiosis I, each pair of homologous chromosomes lines up at the equator independently of the other pairs. Which member of a pair, maternal or paternal, goes to which pole is random. Genes on different chromosomes therefore end up in gametes in all possible combinations.', wrong = '{"1": "Maternal and paternal chromosomes do not all go to the same gamete. Each pair separates independently, mixing them.", "2": "Chromosomes are copied only once, before meiosis I. This copying is not what causes independent assortment.", "3": "Genes on the same chromosome tend to be inherited together. This is linkage, the opposite of independent assortment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0292' AND answer = 0;
UPDATE questions SET why = 'Humans have 23 pairs of chromosomes, and each pair lines up randomly in meiosis, giving 2 choices per pair. The number of possible combinations in one gamete is 2²³, which is about 8.4 million.', wrong = '{"0": "46 is simply the total chromosome number in a body cell. It is not the number of possible combinations.", "1": "23² equals 529, far too few. Each of the 23 pairs doubles the combinations, so the answer is 2²³.", "3": "About 20,000 is roughly the number of human genes, not the number of chromosome combinations in gametes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0293' AND answer = 2;
UPDATE questions SET why = 'The law of independent assortment assumes genes are inherited separately. Genes that lie close together on the same chromosome are often inherited together, a situation called gene linkage. Linkage, crossing over, epistasis, pleiotropy and environment all limit the law.', wrong = '{"0": "Genes on different chromosomes assorting independently is exactly what the law predicts, so it is not a limitation.", "2": "Alleles of one gene going into different gametes is the law of segregation, which holds true.", "3": "Random fusion of gametes at fertilization is assumed in Mendel''s predictions. It does not limit the law."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0294' AND answer = 1;
UPDATE questions SET why = 'Pleiotropy is the situation in which one gene controls several different characters. Because these characters are all governed by the same gene, they are inherited together, which can distort the phenotypic ratios expected from independent assortment.', wrong = '{"0": "Epistasis is when one gene masks or modifies the effect of another, unrelated gene.", "1": "Polygenic inheritance is the reverse of pleiotropy: many genes together control one character, such as skin colour.", "3": "Codominance is when both alleles of one gene are fully expressed in the heterozygote, as in the MN blood group."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0295' AND answer = 2;
UPDATE questions SET why = 'The product rule states that the chance of two or more independent events happening together is found by multiplying their separate probabilities. For example, the chance of two sixes on two dice is 1/6 × 1/6 = 1/36, and the chance of aa from Aa × Aa is 1/2 × 1/2 = 1/4.', wrong = '{"1": "The chance that either of two mutually exclusive events happens is found by adding them, which is the sum rule.", "2": "The chance an event does not happen is 1 minus its probability. That is not the product rule.", "3": "Probability rules predict outcomes of crosses. They do not decide whether an allele is dominant."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0296' AND answer = 0;
UPDATE questions SET why = 'On one throw the dice can show 2 or 5 but not both, so the events are mutually exclusive and the sum rule applies. Each has a probability of 1/6, so P(2 or 5) = 1/6 + 1/6 = 2/6 = 1/3.', wrong = '{"0": "1/36 comes from multiplying 1/6 × 1/6, the product rule. That is the chance of two sixes on two dice, not 2 or 5 on one.", "1": "1/6 is the chance of just one face. Two faces are allowed here, so the chance doubles.", "2": "2/36 comes from wrongly using 36 outcomes. One dice has only 6 outcomes, so the answer is 2/6."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0297' AND answer = 3;
UPDATE questions SET why = 'The two disorders assort independently, so each is treated separately. From Aa × Aa, P(aa) = 1/4, and from Bb × Bb, P(bb) = 1/4. By the product rule, the chance of a child with both disorders, aabb, is 1/4 × 1/4 = 1/16.', wrong = '{"0": "1/4 is the chance of a child with one particular disorder, such as aa, ignoring the second gene.", "2": "1/8 would come from multiplying 1/2 × 1/4, but each recessive homozygote has a chance of 1/4, not 1/2.", "3": "3/16 is the chance of one disorder without the other, for example A_bb = 3/4 × 1/4."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0298' AND answer = 1;
UPDATE questions SET why = 'Each gene is considered separately. From Aa × Aa the chance of aa is 1/4, and the same holds for bb and cc. By the product rule, P(aabbcc) = 1/4 × 1/4 × 1/4 = 1/64.', wrong = '{"1": "1/16 = (1/4)² is the answer for only two genes, such as aabb. A third gene adds another factor of 1/4.", "2": "1/8 = (1/2)³ is the chance of a single gamete being abc, not of an offspring that is aabbcc.", "3": "3/64 = 3/4 × 1/4 × 1/4 is the chance of a dominant phenotype for one gene and recessive for the other two, such as A_bbcc."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0299' AND answer = 0;
UPDATE questions SET why = 'In incomplete dominance neither allele is fully dominant, so the heterozygote shows a blend between the two parents. In the four o''clock plant, red (RR) × white (WW) gives all pink (RW) offspring, which is intermediate between red and white.', wrong = '{"0": "With complete dominance the heterozygote would look like one parent, red or white, not pink.", "1": "In codominance both parental traits appear side by side, as in the AB blood group. Pink is a blend, not both colours together.", "3": "Epistasis involves interaction between two different genes. Here only one gene with two alleles is involved."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0300' AND answer = 2;
UPDATE questions SET why = 'RW × RW gives 1/4 RR, 2/4 RW and 1/4 WW. With incomplete dominance each genotype has its own phenotype, so the offspring are 1 red : 2 pink : 1 white. The phenotypic ratio is the same as the genotypic ratio.', wrong = '{"0": "3:1 is seen with complete dominance, where RR and RW would look the same. Here RW is pink, so it is a separate class.", "1": "A 1:1 ratio comes from a cross such as RW × RR, giving red and pink in equal numbers.", "2": "9:3:4 is a modified dihybrid ratio from epistasis between two genes, not a one-gene cross."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0301' AND answer = 3;
UPDATE questions SET why = 'In the MN blood group the alleles Lᴹ and Lᴺ are codominant. Lᴹ produces M antigen and Lᴺ produces N antigen, and both work fully in the heterozygote. So a person with genotype LᴹLᴺ has both M and N antigens on the red cells and has blood group MN.', wrong = '{"1": "Codominance involves no blending. The heterozygote makes both M and N antigens, not a new intermediate one.", "2": "Only M antigen is found in LᴹLᴹ individuals. Here the Lᴺ allele is also expressed.", "3": "Both alleles produce an antigen, so the heterozygote cannot lack antigens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0302' AND answer = 0;
UPDATE questions SET why = 'In codominance both alleles are fully expressed, so the heterozygote shows both parental phenotypes at the same time, as in the MN and AB blood groups. In incomplete dominance the effects blend, giving an intermediate phenotype such as pink four o''clock flowers.', wrong = '{"0": "A blend intermediate between the parents is the feature of incomplete dominance.", "1": "Showing only the dominant phenotype is complete dominance, as in Mendel''s peas.", "2": "Death of heterozygotes is not a feature of codominance. MN and AB individuals are healthy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0303' AND answer = 3;
UPDATE questions SET why = 'The ABO gene has three alleles: Iᴬ, Iᴮ and i. Allele i makes no antigen and is recessive to both Iᴬ and Iᴮ. A person with Iᴬi therefore makes antigen A only and belongs to blood group A, just like a person with IᴬIᴬ.', wrong = '{"0": "Blood group O needs two recessive alleles, ii. One Iᴬ allele is enough to make antigen A.", "1": "Blood group AB needs both Iᴬ and Iᴮ, which are codominant. This person has no Iᴮ allele.", "3": "Blood group B needs at least one Iᴮ allele, which this person does not have."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0304' AND answer = 2;
UPDATE questions SET why = 'A blood group system classifies blood by particular antigens on red cells. The International Society of Blood Transfusion recognises 43 blood group systems in humans. ABO is the most important and Rh the second most important.', wrong = '{"0": "4 is the number of blood groups (A, B, AB and O) within the ABO system, not the number of systems.", "2": "Two systems, ABO and Rh, are the most important for transfusion, but many more systems are recognised.", "3": "23 is the number of chromosomes in a human gamete. It is not the number of blood group systems."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0305' AND answer = 1;
UPDATE questions SET why = 'Of the many blood group systems, only ABO and Rh must be matched between donor and recipient for a transfusion. Mismatches in these systems cause the recipient''s antibodies to attack donor red cells. Other systems usually do not cause matching problems.', wrong = '{"0": "MN and Kell are recognised blood group systems, but they usually do not cause problems in transfusions.", "1": "Lewis and Duffy are blood group systems that usually do not cause transfusion problems.", "2": "Lutheran and MNS are blood group systems that usually do not need to be matched for transfusion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0306' AND answer = 3;
UPDATE questions SET why = 'Karl Landsteiner discovered the ABO system in 1901. He found antigen A and antigen B on red blood cells and noticed that some people have one, some the other and some neither. His students later found people with both.', wrong = '{"0": "1865 is about when Mendel reported his pea plant experiments, long before blood groups were known.", "2": "1927 is the year Landsteiner and Levine discovered the MN blood group system.", "3": "1952 is the year the Bombay phenotype was discovered, in Bombay."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0307' AND answer = 1;
UPDATE questions SET why = 'Landsteiner''s rule says a person''s plasma contains antibodies against the ABO antigen that the person lacks. A person with blood group B has antigen B but not antigen A on the red cells, so the plasma contains anti-A antibodies.', wrong = '{"0": "Anti-B antibodies would attack the person''s own red cells, which carry antigen B. They are found in group A.", "1": "Both anti-A and anti-B antibodies are found in group O, which has neither antigen.", "3": "Having neither antibody is the feature of group AB, which has both antigens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0308' AND answer = 2;
UPDATE questions SET why = 'The ABO blood groups are controlled by gene I, which stands for iso-haemagglutinogen. It has three alleles, Iᴬ, Iᴮ and i, and is located on chromosome 9, an autosome.', wrong = '{"1": "Chromosome 19 carries the dominant secretor gene Se, which lets A and B antigens appear in saliva and tears.", "2": "The ABO gene is autosomal. If it were on the X chromosome, males and females would inherit blood groups differently.", "3": "Chromosome 7 carries the gene for the blue opsin of cone cells, not the ABO gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0309' AND answer = 0;
UPDATE questions SET why = 'In the ABO system, anti-A and anti-B antibodies form naturally, starting in embryonic life and continuing throughout life, with no exposure to the foreign antigen. In the Rh system, an Rh-negative person makes anti-Rh antibodies only after being exposed to Rh-positive blood.', wrong = '{"1": "Forming only after exposure to a mismatched transfusion describes anti-Rh antibodies, not ABO antibodies.", "2": "ABO antibodies are present in everyone who lacks the matching antigen, not only in pregnant women.", "3": "Group AB has both antigens, so its plasma contains neither anti-A nor anti-B antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0310' AND answer = 0;
UPDATE questions SET why = 'A child with blood group O must be ii, receiving one i allele from each parent. The mother has blood group B, so she has at least one Iᴮ, and to pass on i she must be Iᴮi. So the mother is Iᴮi and the child is ii.', wrong = '{"0": "An IᴮIᴮ mother can only pass on Iᴮ, so she could not have a group O child.", "1": "Iᴮi is group B. A child with blood group O must be ii.", "2": "An IᴮIᴮ mother cannot give an i allele, and an Iᴮi child would be group B, not O."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0311' AND answer = 3;
UPDATE questions SET why = 'In a transfusion between incompatible ABO groups, the recipient''s plasma antibodies attack the matching antigens on the donor''s red cells. The antibodies bind the donor cells together into clumps, which is called agglutination.', wrong = '{"0": "The main problem is the recipient''s antibodies attacking donor red cells, not donor antibodies attacking the recipient''s plasma.", "1": "Red cells without A or B antigens, as in group O, are not attacked. That is why group O is a universal donor.", "3": "Platelets help blood clot. Agglutination in a mismatch is caused by antibodies binding to red cell antigens."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0312' AND answer = 2;
UPDATE questions SET why = 'Allele i is carried silently by many people of groups A and B. Crosses such as Iᴬi × Iᴬi, Iᴮi × Iᴮi or Iᴬi × Iᴮi each give about 25% ii (group O) children, and ii × ii gives all ii. So the i allele keeps being passed on and stays common in the population.', wrong = '{"0": "Allele i is recessive to both Iᴬ and Iᴮ, not dominant. It is expressed only in ii individuals.", "2": "There is no evidence that group O people have more children. This is not the reason given.", "3": "The ABO gene, including allele i, is on chromosome 9, an autosome, not on the X chromosome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0313' AND answer = 1;
UPDATE questions SET why = 'The Rh system takes its name from the Rhesus monkey. Landsteiner first discovered its antigen, the Rh factor or antigen D, in this monkey in the 1930s. People with the antigen are Rh-positive and those without it are Rh-negative.', wrong = '{"0": "The name does not come from a scientist called Rhodes. It comes from the Rhesus monkey.", "2": "The red colour of blood comes from haemoglobin, but it has nothing to do with the name Rh.", "3": "The name has no link with the Rhine river. It comes from the Rhesus monkey."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0314' AND answer = 1;
UPDATE questions SET why = 'The Rh system is controlled by gene D with two alleles. The dominant allele D forms the Rh antigen, while d does not. One D allele is enough, so both DD and Dd people have the antigen and are Rh-positive. Only dd people are Rh-negative.', wrong = '{"0": "Rh-negative needs two recessive alleles, dd. A person with one D allele makes the antigen.", "1": "The universal donor is O-negative, which needs dd. Rh genotype alone also says nothing about the ABO group.", "2": "The D allele produces the Rh antigen, so a Dd person does have it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0315' AND answer = 3;
UPDATE questions SET why = 'A universal donor''s red cells must carry no antigen that a recipient could attack. O-negative cells have no A, B or Rh antigen. A universal recipient''s plasma must have no antibody against donor cells. AB-positive plasma has no anti-A, anti-B or anti-Rh antibodies.', wrong = '{"1": "The two are reversed. AB-positive cells carry A, B and Rh antigens, so they cannot be given to everyone.", "2": "O-positive cells carry the Rh antigen, and an AB-negative person can make anti-Rh antibodies after exposure.", "3": "A-negative cells carry antigen A, and B-positive plasma has anti-A, so neither fits the definitions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0316' AND answer = 0;
UPDATE questions SET why = 'Rh-negative people do not naturally have anti-Rh antibodies. If an Rh-negative person receives Rh-positive blood, the immune system starts making anti-Rh antibodies, which destroy the donated red cells. These antibodies stay in the body for life, so a later Rh-positive transfusion is dangerous.', wrong = '{"0": "After the first exposure, anti-Rh antibodies remain for life, so later Rh-positive transfusions can be attacked.", "1": "A transfusion cannot change the person''s genotype. The person stays dd and Rh-negative.", "3": "Anti-A antibodies depend on the ABO group and are present from early life. Rh exposure produces anti-Rh antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0317' AND answer = 2;
UPDATE questions SET why = 'Erythroblastosis foetalis occurs when an Rh-negative mother (dd) carries an Rh-positive foetus (DD or Dd). Foetal blood entering her circulation makes her produce anti-Rh antibodies. These cross the placenta and destroy the foetus''s red blood cells.', wrong = '{"0": "An Rh-positive mother already has the Rh antigen, so she does not make anti-Rh antibodies against her baby.", "1": "If both are Rh-negative, the foetal cells carry no Rh antigen, so there is no Rh incompatibility.", "2": "This is an ABO difference, not Rh incompatibility. Erythroblastosis foetalis as described is caused by the Rh antigen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0318' AND answer = 3;
UPDATE questions SET why = 'In erythroblastosis foetalis, the mother''s anti-Rh antibodies destroy the foetus''s red blood cells. Breakdown of red cells produces bilirubin, a yellow pigment. As it builds up, it turns the skin and eyes yellow (jaundice), and very high levels can damage brain cells.', wrong = '{"0": "Oxygen does not cause jaundice. The baby actually has fewer red cells to carry oxygen.", "1": "Fibrin forms blood clots. Jaundice is caused by bilirubin, not by clots in the liver.", "3": "Uric acid crystals in joints cause gout, not jaundice in a newborn."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0319' AND answer = 2;
UPDATE questions SET why = 'Rh-antiserum is serum containing anti-Rh antibodies. Given during early pregnancy and just after birth, it destroys any of the baby''s Rh-positive red cells that have entered the mother''s blood. They are removed before her own immune system is sensitised to make lasting anti-Rh antibodies.', wrong = '{"0": "The foetus''s genotype is set at fertilization and cannot be changed by an injection.", "2": "The antiserum contains antibodies, not antigens. It does not add Rh antigen to the mother''s red cells.", "3": "The aim is to stop the mother from making her own anti-Rh antibodies, not to increase them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0320' AND answer = 1;
UPDATE questions SET why = 'An O-negative mother already has anti-A and anti-B antibodies in her plasma. If her baby is A-positive, any foetal red cells that enter her blood are quickly destroyed by her anti-A antibodies. They are removed before her immune system can respond to their Rh antigen, so she does not form anti-Rh antibodies.', wrong = '{"1": "Group O mothers do make antibodies. They naturally have both anti-A and anti-B in their plasma.", "2": "A-positive means the baby''s red cells do carry the Rh antigen.", "3": "The protection happens in the mother''s blood, where foetal cells are destroyed before Rh sensitisation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0321' AND answer = 0;
UPDATE questions SET why = 'Polygenic traits are controlled by many gene pairs, and each allele adds a small effect to the same trait. Because many small effects add up, the phenotypes form a smooth range from one extreme to the other. This is continuous variation, as seen in human height and skin colour.', wrong = '{"1": "Two sharp classes are typical of a trait controlled by a single gene, or of epistasis. Polygenic traits give many in-between forms instead.", "2": "A 3:1 ratio comes from a monohybrid cross with complete dominance at one gene. Many additive genes give a whole range of classes, not two.", "3": "Expression in only one sex describes sex-limited traits, such as horns in sheep. Height and skin colour are expressed in both sexes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0322' AND answer = 0;
UPDATE questions SET why = 'In the three-gene model each dominant allele (A, B, C) adds melanin, so a child can carry 6, 5, 4, 3, 2, 1 or 0 dominant alleles. That gives seven colour classes from very dark to very light in the ratio 1:6:15:20:15:6:1, out of 64. The middle class, with three dominant alleles, is the most common.', wrong = '{"0": "9:3:3:1 is the dihybrid ratio when two genes show complete dominance. Additive genes do not give four classes.", "1": "1:2:1 is the ratio for a single gene with incomplete dominance. Three additive genes give seven classes, not three.", "3": "27:9:9:9:3:3:3:1 is the trihybrid ratio with complete dominance at each gene. In polygenic inheritance alleles add up, so classes depend only on how many dominant alleles are present."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0323' AND answer = 2;
UPDATE questions SET why = 'Skin colour depends on how much melanin pigment the skin makes. This trait is controlled by many genes, about 60 of them. Only three genes (A, B and C) are used as a simple teaching model to explain how additive genes give a range of skin colours.', wrong = '{"0": "Three genes are used only as a teaching model to make the idea easy to follow. The real number is much larger, about 60.", "2": "One gene with three alleles describes the ABO blood group system (Iᴬ, Iᴮ, i), not skin colour.", "3": "23 is the number of chromosome pairs in a human cell. It is not the number of genes for skin colour."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0324' AND answer = 1;
UPDATE questions SET why = 'Grain colour is controlled by three additive genes, and only the genotype aabbcc makes no red pigment. In the F2 of AaBbCc × AaBbCc, the chance of aabbcc is ¼ × ¼ × ¼ = 1/64. So 1 plant in 64 has white grains, 1 has the darkest red (AABBCC), and the other 62 show shades of red.', wrong = '{"0": "62 is the number of plants showing in-between shades of red. These plants have at least one, but fewer than six, dominant alleles.", "1": "16 out of 64 is one quarter, the fraction of recessive homozygotes for a single gene. With three genes all must be homozygous recessive, giving 1/64.", "2": "4 out of 64 equals 1/16, the share of white grains expected if only two genes (aabb) controlled colour. Three genes reduce it to 1/64."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0325' AND answer = 3;
UPDATE questions SET why = 'Gene interactions are of two kinds. In allelic interactions, alleles of the same gene interact with each other, as in incomplete dominance, codominance and multiple alleles. In non-allelic interactions, alleles of different genes at different loci interact.', wrong = '{"0": "Non-allelic interactions involve alleles of different genes at different loci, such as epistasis. The three examples in the stem involve one gene each.", "1": "Epistasis is a non-allelic interaction, where an allele of one gene masks the effect of another gene. It is an example of the other category.", "3": "Polygenic inheritance involves many genes adding their effects to one trait. Incomplete dominance and codominance concern alleles of a single gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0326' AND answer = 2;
UPDATE questions SET why = 'Epistasis is an interaction in which an allele of one gene masks or modifies the effect of alleles of another gene. The allele that does the masking is called epistatic. The allele whose effect is masked or modified is called hypostatic.', wrong = '{"0": "The epistatic allele is the one that does the masking. The stem asks for the allele that is masked, which is the hypostatic allele.", "1": "Codominant alleles belong to the same gene and are both fully expressed together, as in blood group AB. Nothing is masked.", "2": "Pleiotropy means a single gene affects several different traits. It does not describe one gene being masked by another."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0327' AND answer = 3;
UPDATE questions SET why = 'In polygenic inheritance many genes each add a small effect, which gives continuous variation. In epistasis one allele masks or changes the effect of another gene, so offspring fall into a few clear-cut groups. This is discontinuous variation, such as black, brown and yellow Labradors.', wrong = '{"0": "Continuous variation is typical of polygenic traits, where many small additive effects blend into a smooth range.", "2": "Only intermediate phenotypes are typical of incomplete dominance, where the heterozygote is in between the two parents.", "3": "Epistasis changes the expected 9:3:3:1 ratio, for example into 9:3:4 in Labradors or 12:3:1 in foxglove."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0328' AND answer = 1;
UPDATE questions SET why = 'In Labradors the B gene sets pigment colour (B black, b brown) and the E gene controls whether pigment is laid down in the fur. The recessive ee genotype is epistatic to B and b and blocks pigment deposition. So a BBee dog has a yellow coat, even though it carries B.', wrong = '{"1": "A black coat needs at least one B and at least one E (B_E_). This dog is ee, so no pigment is deposited in its fur.", "2": "A brown coat needs bb together with at least one E (bbE_). This dog is BB and ee, so it is neither.", "3": "Labradors are black, brown or yellow. A white coat is not one of the three colours in this example."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0329' AND answer = 0;
UPDATE questions SET why = 'From BbEe × BbEe, 9/16 are B_E_ (black) and 3/16 are bbE_ (brown). Any dog with ee is yellow whatever its B alleles, so B_ee (3/16) and bbee (1/16) join into one class of 4/16. The ratio is 9 black : 3 brown : 4 yellow.', wrong = '{"0": "9:3:3:1 would appear only if the two genes acted independently. Because ee masks the B/b difference, the last two classes merge into 4.", "1": "12:3:1 is the ratio for foxglove flower colour, where a dominant allele (W) is epistatic. In Labradors the masking allele is recessive (ee).", "3": "9:7 is the ratio when two genes are both needed for one phenotype (complementary genes). Labradors show three colours, not two."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0330' AND answer = 2;
UPDATE questions SET why = 'The H gene makes H substance, the precursor that Iᴬ and Iᴮ enzymes change into A and B antigens. A person with genotype hh makes no H substance, so the Iᴬ and Iᴮ alleles have nothing to work on. No A or B antigens form, and the blood types as group O.', wrong = '{"0": "Iᴬ and Iᴮ are dominant to i, not recessive. The O phenotype here comes from missing H substance, not from i.", "1": "The ABO gene lies on chromosome 9, and losing a whole chromosome 9 is not the cause. The person still carries Iᴬ and Iᴮ but cannot use them.", "2": "The A and B antigens are never made in the first place. Nothing is destroying antigens after they form."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0331' AND answer = 3;
UPDATE questions SET why = 'Allele W is epistatic: it limits the pigment to small spots, so any plant with W looks white. From DdWw selfed, all __W_ plants (12/16) are white, D_ww (3/16) are dark red and ddww (1/16) is light red. The ratio is 12:3:1.', wrong = '{"0": "9:3:4 is the Labrador coat colour ratio, where a recessive allele (ee) is epistatic. In foxglove the masking allele W is dominant.", "2": "9:3:3:1 needs the two genes to act independently. Because W hides the D/d difference, three classes merge into one white class.", "3": "15:1 is the ratio when either of two dominant genes gives the same phenotype (duplicate genes). Foxglove shows three colours."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0332' AND answer = 1;
UPDATE questions SET why = 'In 1902 the American scientist Walter Sutton proposed the chromosomal theory of inheritance. It states that genes lie at specific places on chromosomes, and that the way chromosomes behave in meiosis explains Mendel''s laws.', wrong = '{"1": "Karl Correns rediscovered Mendel''s work in 1900 and suggested a role for chromosomes, but he did not propose the 1902 theory.", "2": "Thomas Hunt Morgan later supported the theory with his work on linkage and sex linkage in Drosophila (from 1910).", "3": "Gregor Mendel described inherited \"factors\" in the 1860s, before chromosomes were linked to heredity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0333' AND answer = 0;
UPDATE questions SET why = 'When parental combinations are more common than new (recombinant) combinations, the genes are on the same chromosome but are sometimes separated. This is incomplete linkage. The few new combinations are produced by crossing over between homologous chromosomes.', wrong = '{"0": "Complete linkage gives only parental combinations and no new ones, because the genes are so close they never separate.", "1": "Independent assortment gives parental and new combinations in equal numbers, a 1:1:1:1 ratio in a test cross.", "3": "Codominance is about two alleles of one gene both being expressed. It says nothing about how two genes are inherited together."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0334' AND answer = 2;
UPDATE questions SET why = 'Linkage is detected by counting how often parental and new combinations appear among the offspring. These frequencies are only reliable when there are many offspring. The larger the progeny, the closer the result is to the true linkage frequency.', wrong = '{"0": "A small number of offspring can give misleading ratios by chance, so linkage cannot be measured reliably.", "1": "Genes on different chromosomes are not linked at all; they assort independently.", "2": "Asexual reproduction involves no meiosis or crossing of parents, so linkage cannot be studied through crosses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0335' AND answer = 3;
UPDATE questions SET why = 'With independent assortment, the F2 of this cross should show a 9:3:3:1 ratio, including new combinations. Morgan saw only the two parental combinations, in a 3:1 ratio. So he concluded that the genes for wing length and abdomen width lie on the same chromosome and are inherited together.', wrong = '{"1": "Genes on different chromosomes assort independently and would give new combinations in a 9:3:3:1 ratio.", "2": "Crossing over between the genes would produce new (recombinant) combinations, and none were seen.", "3": "The result showed no difference between males and females, so it gives no evidence of sex linkage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0336' AND answer = 0;
UPDATE questions SET why = 'Crossing over happens during meiosis I, when homologous chromosomes pair up. Chromatids of the two homologues break at matching points and exchange segments of DNA. This recombines linked genes and is a major source of genetic variation.', wrong = '{"0": "Sister chromatids are identical copies, so swapping between them would not recombine alleles. Crossing over is described in meiosis I.", "2": "Fertilization is the fusion of sperm and egg nuclei. It brings chromosomes together but does not exchange DNA segments.", "3": "Meiosis II separates sister chromatids. Exchange occurs between homologous, not non-homologous, chromosomes in meiosis I."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0337' AND answer = 1;
UPDATE questions SET why = 'Drosophila has 4 pairs of chromosomes in all (8 chromosomes). Three pairs are autosomes, which are the same in males and females. The fourth pair is the sex chromosomes, XX in females and XY in males.', wrong = '{"0": "22 pairs of autosomes is the human number. Humans have 23 pairs in total, including one pair of sex chromosomes.", "1": "4 is the total number of chromosome pairs in Drosophila. One of these pairs is the sex chromosomes, so autosomes are 3 pairs.", "2": "11 pairs of autosomes (22 autosomes) are found in the grasshopper, which uses the XX–XO system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0338' AND answer = 3;
UPDATE questions SET why = 'Heterogametic means producing two kinds of gametes for sex chromosomes. A male (XY) makes sperm of which half carry X and half carry Y. A female (XX) makes only X-carrying eggs, so the type of sperm decides the sex of the child.', wrong = '{"0": "Males make both X-carrying and Y-carrying sperm, in equal numbers. Making only one type would make them homogametic.", "1": "Having two X chromosomes describes females, who are homogametic and make only X-carrying eggs.", "3": "Z and W eggs are made by female birds in the ZW–ZZ system. In XX–XY animals males produce sperm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0339' AND answer = 2;
UPDATE questions SET why = 'Grasshoppers use the XX–XO system. Both sexes have 22 autosomes (11 pairs). The female is XX with 24 chromosomes, but the male has a single X and no Y, so he has 22 + 1 = 23 chromosomes.', wrong = '{"1": "XY would add two sex chromosomes, giving 24. Male grasshoppers have no Y chromosome.", "2": "Grasshoppers have 22 autosomes, not 21. XX with 22 autosomes describes the female, who has 24 chromosomes.", "3": "Male grasshoppers are diploid for autosomes. Their odd number comes from having one X with no partner."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0340' AND answer = 0;
UPDATE questions SET why = 'In birds the female is ZW and the male is ZZ. The female is heterogametic and makes two kinds of eggs, Z and W, while all sperm carry Z. So the egg decides the sex: Z egg + Z sperm gives a male, W egg + Z sperm gives a female.', wrong = '{"0": "Male birds are ZZ, not ZW. They make only Z-carrying sperm, so sperm cannot decide the sex.", "2": "Temperature decides sex in some reptiles. In birds sex is set by the ZW–ZZ chromosomes.", "3": "Autosome number differs between bird species and does not decide sex. The sex chromosome pair does."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0341' AND answer = 1;
UPDATE questions SET why = 'Most sex-linked genes are on the X chromosome only. A few traits have alleles on both the X and the Y, so males and females carry two copies each. Such traits appear equally in both sexes and are called X–Y-linked or pseudo-autosomal traits.', wrong = '{"0": "Holandric genes are found only on the non-homologous part of the Y. They appear only in males and pass from father to son.", "1": "Sex-limited genes are on autosomes but are expressed in only one sex, such as horns in male sheep.", "3": "X-linked recessive traits have no allele on the Y, so they are much more common in males than in females."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0342' AND answer = 2;
UPDATE questions SET why = 'Morgan crossed the red-eyed F1 flies with each other. Out of 4252 F2 flies, 782 (about 18%) had white eyes, and every one of them was male. This pointed to the white-eye gene being on the X chromosome.', wrong = '{"0": "No white-eyed females appeared in this F2. Morgan later obtained white-eyed females only through a test cross.", "1": "The white eyes were not shared between the sexes in this F2; all 782 white-eyed flies were males.", "2": "No sterility was reported. The striking finding was that white eyes appeared only in males."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0343' AND answer = 3;
UPDATE questions SET why = 'A white-eyed female has the white allele on both X chromosomes. Each son gets his only X from his mother, so all sons have white eyes. Each daughter also gets the father''s X with the dominant red allele, so all daughters have red eyes.', wrong = '{"1": "The sons received only their mother''s X, which carries the white allele, and they have no second X to mask it.", "2": "The daughters received their father''s X with the dominant red allele, so they could not be white-eyed.", "3": "This reverses the real result. Daughters get the father''s red allele and sons get only the mother''s white allele."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0344' AND answer = 0;
UPDATE questions SET why = 'Amniocentesis is an embryonic screening method usually done between the 15th and 20th weeks of pregnancy. Guided by ultrasound, a needle removes some amniotic fluid containing foetal cells. The cells are cultured and checked for an abnormal number of chromosomes.', wrong = '{"0": "In the first three weeks there is too little amniotic fluid and the embryo has barely implanted, so the test is not done.", "2": "Weeks 36 to 40 are near full term, too late for the result to guide decisions during pregnancy.", "3": "Two to four days after fertilization the embryo has not even implanted, and no amniotic sac exists yet."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0345' AND answer = 1;
UPDATE questions SET why = 'A father passes his X chromosome to every daughter and his Y chromosome to every son. So every daughter gets his X with the recessive allele and also a normal X from the mother, making her a carrier. Sons get his Y, so no son is affected.', wrong = '{"0": "Sons receive their father''s Y, not his X, so they cannot inherit an X-linked trait from him.", "1": "Half of the sons being affected happens when the mother is a carrier. Here the mother is not a carrier.", "2": "Daughters also get a normal X from the mother, so they are carriers, not affected. Sons are unaffected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0346' AND answer = 3;
UPDATE questions SET why = 'In X-linked dominant disorders, a single copy of the allele on the X is enough to cause the condition. Vitamin D-resistant rickets is one, where vitamin D is not properly used and bones become soft and weak. Rett syndrome and Aicardi syndrome are other examples.', wrong = '{"0": "Haemophilia A, caused by a faulty clotting factor VIII, is X-linked recessive.", "1": "Duchenne muscular dystrophy, where dystrophin is not made, is X-linked recessive, so it is much more common in boys.", "3": "Red-green colour blindness is caused by recessive alleles of the opsin genes on the X, so it is X-linked recessive."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0347' AND answer = 2;
UPDATE questions SET why = 'A father gives his X chromosome to every daughter and his Y to every son. With an X-linked dominant trait, one copy of the allele is enough. So all his daughters inherit the trait and none of his sons do.', wrong = '{"1": "Sons get their father''s Y, not his X, so they cannot inherit an X-linked trait from him.", "2": "Half of the children being affected, regardless of sex, is expected when the mother is heterozygous for the trait.", "3": "Every daughter receives the father''s X with the dominant allele, so all daughters are affected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0348' AND answer = 0;
UPDATE questions SET why = 'Hypertrichosis of the pinna is a Y-linked trait. Its gene lies on the non-homologous part of the Y and has no allele on the X; such genes are called holandric. Only males have a Y, and a son always gets his Y from his father, so it passes from father to son only.', wrong = '{"0": "Passing from mother to son is the pattern of X-linked traits, since sons get their X from their mother.", "2": "Equal inheritance by sons and daughters fits autosomal or pseudo-autosomal traits, not a gene found only on the Y.", "3": "Daughters never receive a Y chromosome, so they cannot inherit a Y-linked trait."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0349' AND answer = 1;
UPDATE questions SET why = 'Haemophilia is a group of disorders where blood fails to clot properly. Haemophilia A is due to faulty clotting factor VIII and haemophilia B to factor IX; both are X-linked recessive. Haemophilia C is due to factor XI and is autosomal recessive.', wrong = '{"0": "A defect in factor VIII causes haemophilia A, the commonest type, which is also X-linked recessive.", "2": "A defect in factor XI causes haemophilia C, which is autosomal recessive.", "3": "Factor I is fibrinogen, the protein converted to fibrin. It is not the cause of any of the three named types of haemophilia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0350' AND answer = 1;
UPDATE questions SET why = 'Haemophilia C is caused by a faulty clotting factor XI, and its gene is on an autosome, not on a sex chromosome. Both sexes carry two copies of every autosome. So an autosomal recessive trait appears equally often in males and females.', wrong = '{"1": "X-linked recessive traits, like haemophilia A and B, are more common in males, who have only one X.", "2": "Y-linked traits appear only in males, because only males have a Y chromosome.", "3": "Sex-limited traits are expressed in only one sex, so they could not occur equally in both."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0351' AND answer = 0;
UPDATE questions SET why = 'When a vessel is injured, platelets and damaged tissue release clotting factors. These factors work in a chain of reactions (the clotting cascade) that converts the soluble plasma protein fibrinogen into insoluble fibrin. Fibrin threads form a mesh that traps blood cells into a solid clot.', wrong = '{"0": "This reverses the change. Clotting turns dissolved fibrinogen into solid fibrin threads, not the other way.", "1": "Platelets are cell fragments that form the first plug at the wound. They are never turned into red blood cells.", "2": "Haemoglobin is broken down to bilirubin when old red cells are destroyed in the liver and spleen. This is not part of clotting."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0352' AND answer = 3;
UPDATE questions SET why = 'Each type of cone cell has its own light-sensitive protein called an opsin. The genes for the red and green opsins are on the X chromosome, which is why red-green colour blindness is X-linked and common in males. The blue opsin gene is on autosome 7.', wrong = '{"0": "Chromosome 7 carries the gene for the blue opsin, not the red and green ones.", "1": "The Y chromosome carries very few genes and none for opsins. Colour blindness is X-linked, not Y-linked.", "3": "Chromosome 9 carries the ABO blood group gene. It does not hold the opsin genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0353' AND answer = 2;
UPDATE questions SET why = 'Dichromacy is seeing only two of the three primary colours because one opsin is missing. If the red opsin is missing the condition is protanopia (red blindness). Missing green is deuteranopia, and missing blue is tritanopia.', wrong = '{"0": "Deuteranopia is green blindness, caused by a missing green opsin.", "1": "Tritanopia is blue blindness, caused by a missing blue opsin, whose gene is on autosome 7.", "3": "Monochromacy is total colour blindness, where two of the three opsins are missing and only one colour is seen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0354' AND answer = 2;
UPDATE questions SET why = 'Duchenne muscular dystrophy is X-linked recessive, so it mainly affects boys. An affected boy cannot make the muscle protein dystrophin. Without it, muscle fibres die, and weakness spreads from the hip and thigh muscles to other muscles.', wrong = '{"1": "Myosin is a contractile protein of muscle filaments. Its production is not the defect in Duchenne muscular dystrophy.", "2": "Fibrinogen is a plasma protein that forms fibrin during blood clotting. It is linked to clotting, not muscle disease.", "3": "Opsins are light-sensitive proteins in cone cells of the retina. Missing opsins cause colour blindness."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0355' AND answer = 0;
UPDATE questions SET why = 'Muscular dystrophy has no cure, but its symptoms can be managed. Corticosteroid medicines can give a short-term improvement in muscle strength and function. Physical therapy, painkillers and surgery for joint contractures are also used.', wrong = '{"0": "Rh-antiserum (anti-D) is given to an Rh-negative mother to prevent Rh sensitization. It has no effect on muscle.", "1": "Insulin injections treat type 1 diabetes by lowering blood glucose. They do not improve muscle strength in this disorder.", "2": "Colour-blind glasses help colour-blind people tell colours apart. They do nothing for muscle weakness."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0356' AND answer = 3;
UPDATE questions SET why = 'Sex-limited traits have genes on autosomes, so both sexes carry them, but they are expressed in only one sex because of anatomical or hormonal differences. Both male and female sheep carry the horn genes, but only males grow horns. Milk production in female mammals is another example.', wrong = '{"0": "Sex-linked genes are located on sex chromosomes. Horn genes are present on autosomes in both sexes.", "2": "Sex-influenced alleles are expressed in both sexes but are dominant in one and recessive in the other, as in baldness.", "3": "Y-linked genes are carried only by males. Here females also carry the horn genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0357' AND answer = 1;
UPDATE questions SET why = 'In sex-influenced traits the same allele shows different dominance in the two sexes because of hormonal differences. The baldness allele is dominant in men but recessive in women. So one copy can make a man bald, but a woman needs two, and baldness is more common in men.', wrong = '{"0": "A gene found only on the Y would never appear in women. Baldness genes are not Y-linked.", "2": "Baldness is seen in both sexes, and it is more common in men. It is not expressed only in women.", "3": "Baldness is not an X-linked trait. Its uneven frequency comes from hormones changing dominance, not from the X."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0358' AND answer = 1;
UPDATE questions SET why = 'Chromosomes were discovered in 1882 by the German embryologist Walther Flemming. He saw them in rapidly dividing cells of salamander larvae. The name "chromosome", meaning coloured body, was given later by Waldeyer-Hartz in 1888.', wrong = '{"0": "Waldeyer-Hartz proposed the name \"chromosome\" in 1888. He did not discover chromosomes.", "1": "Wilhelm Johannsen, a Danish botanist, introduced the term \"gene\" in 1909.", "3": "Walter Sutton proposed the chromosomal theory of inheritance in 1902."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0359' AND answer = 2;
UPDATE questions SET why = 'In a non-dividing (interphase) cell, chromosomes are not seen as separate bodies. Their DNA and proteins stay uncoiled as a fine network called chromatin. When the cell prepares to divide, chromatin coils and condenses into visible chromosomes.', wrong = '{"0": "The kinetochore is a disc-shaped protein structure on the centromere where spindle fibres attach. It is not a network.", "1": "The spindle is a structure of microtubules that forms during cell division to move chromosomes.", "2": "A karyotype is the complete set of chromosomes of a species, described by their number, size and shape."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0360' AND answer = 3;
UPDATE questions SET why = 'Sister chromatids are held together at the centromere. A disc-shaped protein structure called the kinetochore sits on the centromere. During division, spindle fibres attach to the kinetochore and pull the chromatids apart.', wrong = '{"0": "Telomeres are the end regions of a chromosome. They stop chromosomes from joining at their ends.", "2": "The satellite is the knob-like end of a chromosome beyond a secondary constriction.", "3": "A nucleosome is a stretch of DNA wrapped around a set of eight histones. It is a packing unit, not a spindle attachment point."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0361' AND answer = 1;
UPDATE questions SET why = 'Some chromosomes have a second narrow region besides the centromere, called the secondary constriction. It is also called the nucleolar organizer region (NOR), because it makes the nucleoli during interphase. The knob-like end beyond it is the satellite.', wrong = '{"1": "Attachment to the spindle happens at the kinetochore on the primary constriction (centromere).", "2": "Telomeres, at the chromosome ends, stop chromosomes from sticking together by their ends.", "3": "Sister chromatids are joined at the centromere, the primary constriction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0362' AND answer = 0;
UPDATE questions SET why = 'Telomeres are the end regions of a chromosome. They act like protective caps and prevent two chromosomes from joining with each other at their ends. This keeps each chromosome separate and intact.', wrong = '{"0": "Spindle fibres attach at the kinetochore, which sits on the centromere, not at the ends.", "1": "Nucleoli are made at the secondary constriction, the nucleolar organizer region (NOR).", "3": "Sister chromatids are held together at the centromere."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0363' AND answer = 2;
UPDATE questions SET why = 'Chromosomes are named by where the centromere lies. Metacentric has it at the centre, sub-metacentric slightly off centre, acrocentric near one end, and telocentric at the very end. So near, but not at, one end means acrocentric.', wrong = '{"0": "In a metacentric chromosome the centromere is in the middle, giving two arms of equal length.", "2": "In a sub-metacentric chromosome the centromere is only slightly away from the centre, so one arm is a little longer.", "3": "In a telocentric chromosome the centromere is right at the end, so there is only one arm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0364' AND answer = 1;
UPDATE questions SET why = 'A chromosome is made of about 40% DNA and 60% protein, mainly histones. Histones are basic proteins around which the DNA is wound to pack it. Both chromatids carry identical DNA molecules.', wrong = '{"0": "This reverses the proportions. Proteins make up the larger part, about 60%, and DNA about 40%.", "1": "Chromosomes are made mainly of DNA and protein. RNA is only a minor component, not 10%.", "2": "Lipids are not a main part of chromosomes. The main parts are DNA and histone proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0365' AND answer = 3;
UPDATE questions SET why = 'The phosphate groups in the DNA backbone carry negative charges, so DNA is negatively charged. Histones are rich in the basic amino acids arginine and lysine, which make them positively charged. Opposite charges attract, so DNA binds tightly to histones.', wrong = '{"1": "If both were negative they would repel each other, so DNA could not wrap tightly around histones.", "2": "Histones are rich in basic amino acids (arginine and lysine), not acidic ones. That is why they are positive.", "3": "Every DNA nucleotide has a phosphate group. These phosphates give DNA its negative charge."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0366' AND answer = 0;
UPDATE questions SET why = 'In a nucleosome, about 146 nucleotides of DNA wrap twice around a core of eight histone molecules, the histone octamer. The octamer has two copies each of H2A, H2B, H3 and H4. A fifth histone, H1, is the linker histone that sits outside the core where DNA enters and leaves.', wrong = '{"1": "H1 is the linker histone outside the core, so it is not part of the octamer. This list also leaves out H2B, which is in the core.", "2": "H1 is the linker histone outside the core, so it is not part of the octamer. This list also leaves out H2A, which is in the core.", "3": "H1 is the linker histone and is not part of the octamer. This list also leaves out H4, which is one of the four core histones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0367' AND answer = 0;
UPDATE questions SET why = 'DNA (2 nm) wraps around histones to form the nucleosome string (11 nm). This coils into the chromatin fibre (30 nm), which folds into a supercoil (300 nm). The supercoil condenses further into a chromatid (700 nm), so the order is 11 → 30 → 300 → 700 nm.', wrong = '{"0": "The chromatin fibre (30 nm) is thicker than the nucleosome string (11 nm), so it cannot come first. The last two are also swapped.", "1": "This starts with a 300 nm supercoil and drops back to 11 nm, so it is not in order of increasing thickness.", "3": "The supercoil (300 nm) is put before the chromatin fibre (30 nm). The chromatin fibre is thinner and forms first."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0368' AND answer = 2;
UPDATE questions SET why = 'Chromatin has two kinds of regions. Heterochromatin is tightly packed and genetically inactive, and it stains dark, producing dark bands. Euchromatin is loosely packed and active, so its genes can be transcribed.', wrong = '{"0": "Euchromatin is the active, loosely packed part of chromatin. It does not form the dark inactive bands.", "1": "Telomeres are the end regions of chromosomes that stop chromosomes from joining at their ends.", "2": "Exons are the coding parts of a gene that remain in mature mRNA. They are not a type of chromatin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0369' AND answer = 3;
UPDATE questions SET why = 'The Danish botanist Wilhelm Johannsen introduced the word "gene" in 1909 for the basic unit of heredity. A gene was later defined as a short segment of DNA that codes for the amino acid sequence of a polypeptide.', wrong = '{"0": "Mendel described inherited units as \"factors\" in the 1860s. He did not use the word gene.", "2": "Walther Flemming discovered chromosomes in 1882 in dividing cells of salamander larvae.", "3": "Francis Crick co-discovered the DNA double helix and used the term \"central dogma\" for the flow of genetic information."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0370' AND answer = 1;
UPDATE questions SET why = 'Genetic material must be copied and passed to daughter cells, so it must be able to replicate itself before cell division. It must also code for amino acid sequences, be found in the nucleus of eukaryotic cells, and be able to change over time to allow evolution. DNA meets all these needs.', wrong = '{"1": "Genetic material must be able to change over time, through mutation, to account for evolution. Never changing is not a requirement.", "2": "In eukaryotic cells the genetic material must be found in the nucleus, not only in the cytoplasm.", "3": "Molecules made of amino acids are proteins. The genetic material, DNA, is made of nucleotides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0371' AND answer = 0;
UPDATE questions SET why = 'Live R-type bacteria alone and heat-killed S-type alone were both harmless. But a mixture of heat-killed S-type and living R-type killed the mice, and live S-type bacteria were found in their blood. Material from the dead S-type had transformed the R-type into virulent S-type.', wrong = '{"0": "Living R-type bacteria lack the polysaccharide coat and are not virulent. Mice injected with them alone showed no effect.", "1": "Heat-killed S-type bacteria cannot multiply, so on their own they did not cause disease, and the mice stayed healthy.", "3": "R-type bacteria are not virulent even when alive. Killing them by heat makes them harmless too."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0372' AND answer = 2;
UPDATE questions SET why = 'The S-type strain has a polysaccharide coat that gives smooth colonies. Griffith suggested the coat protects the bacteria from the host''s immune system, so they survive and cause pneumonia. The R-type strain lacks this coat, forms rough colonies and is harmless.', wrong = '{"0": "Both strains have a normal cell wall. The difference between them is the outer polysaccharide coat.", "2": "A protein coat around injected DNA describes bacteriophages, the viruses used by Hershey and Chase, not these bacteria.", "3": "Rough colonies are formed by the R-type strain, which has no coat and is not virulent."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0373' AND answer = 1;
UPDATE questions SET why = 'Griffith called this change transformation. It is the transfer of genetic material from one organism to another, which changes the genetic makeup of the receiver. Here, material from dead S-type cells changed living R-type cells into virulent S-type cells.', wrong = '{"0": "Transduction is the transfer of bacterial DNA by a virus (bacteriophage). Griffith''s change involved no virus.", "1": "Translation is protein synthesis on ribosomes using the code in mRNA.", "2": "Transcription is the making of RNA from a DNA template, the first step of gene expression."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0374' AND answer = 3;
UPDATE questions SET why = 'Avery, MacLeod and McCarty treated dead S-type cells in two ways. When they removed the proteins, transformation still happened. When they removed all the DNA, no transformation occurred and the mice stayed healthy, so DNA is the transforming principle.', wrong = '{"0": "With proteins removed, transformation still took place and the mice became ill. This showed protein is not the transforming principle.", "1": "Heating the R-type bacteria was not part of their test. They removed proteins or DNA from the dead S-type cells.", "3": "They did not add polysaccharide. Their test was to remove either proteins or DNA from the dead S-type extract."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0375' AND answer = 2;
UPDATE questions SET why = 'Hershey and Chase used isotopes that label only one kind of molecule. Sulphur is found in some amino acids of proteins but not in DNA, so ³⁵S labelled the protein coats. Phosphorus is found in DNA phosphate groups but not in protein, so ³²P labelled the DNA.', wrong = '{"1": "³²P was used to label the DNA, because phosphorus is in the phosphate groups of DNA and not in proteins.", "2": "¹⁵N, a heavy isotope, was used by Meselson and Stahl to study DNA replication.", "3": "¹⁴C is present in both DNA and protein, so it could not tell them apart and was not used."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0376' AND answer = 0;
UPDATE questions SET why = 'When phages with ³²P-labelled DNA infected bacteria, the DNA was injected into the cells. After centrifugation the bacterial cells held the radioactivity and the medium did not. This showed DNA enters the cell and directs the making of new phages.', wrong = '{"0": "Radioactivity in the medium was the result with ³⁵S-labelled protein, because protein coats stay outside the cell.", "1": "The labelled DNA went into the bacteria, so radioactivity was in the cells, not shared equally with the medium.", "2": "Radioactivity from ³²P was detected clearly in the bacterial cells. It does not decay away at once."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0377' AND answer = 3;
UPDATE questions SET why = 'In the semi-conservative model, the two parent strands separate and each acts as a template for a new strand. So each daughter DNA has one old parental strand and one newly made strand. Meselson and Stahl showed that DNA replicates this way.', wrong = '{"0": "A daughter with both parental strands is predicted by the conservative model, where the parent helix stays intact.", "2": "A daughter with two new strands is also part of the conservative model, alongside one fully parental molecule.", "3": "Strands made of mixed old and new nucleotides describe the dispersive model."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0378' AND answer = 1;
UPDATE questions SET why = 'Meselson and Stahl dissolved the DNA in caesium chloride solution and spun it at very high speed (ultracentrifugation). This builds a density gradient, densest at the bottom. Each DNA settles where its density matches the solution, so heavy ¹⁵N DNA settles lower than light ¹⁴N DNA.', wrong = '{"0": "Sodium chloride was not used. A caesium chloride solution was used because it forms a steep density gradient.", "1": "Sucrose was not used. The density gradient was made with caesium chloride.", "2": "Glucose was not used. The density gradient was made with caesium chloride."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0379' AND answer = 3;
UPDATE questions SET why = 'The conservative model predicts that after one round there would be one fully heavy and one fully light molecule, giving two bands. Meselson and Stahl saw a single band of intermediate density instead. This ruled out the conservative model.', wrong = '{"1": "A single intermediate band is exactly what the semi-conservative model predicts, since each DNA is a ¹⁵N/¹⁴N hybrid.", "2": "The dispersive model also predicts one intermediate band after one round. It was ruled out only after the second round.", "3": "The law of segregation is one of Mendel''s laws of inheritance, not a model of DNA replication."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0380' AND answer = 0;
UPDATE questions SET why = 'After the first round every DNA molecule is a hybrid, with one ¹⁵N and one ¹⁴N strand. In the second round each hybrid separates: the ¹⁵N strand forms another hybrid and the ¹⁴N strand forms a fully light molecule. So two bands appear, one intermediate and one light.', wrong = '{"0": "A single intermediate band was seen after the first round, not the second.", "2": "No fully heavy DNA remains after replication in ¹⁴N medium, because every new strand uses ¹⁴N.", "3": "A single heavy band was seen only at 0 minutes, before any replication in ¹⁴N medium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0381' AND answer = 1;
UPDATE questions SET why = 'A prokaryote has a small circular DNA with a single origin site and a single termination site. Eukaryotic DNA is very long, so replication starts at many origins along each chromosome at the same time. Each eukaryotic chromosome therefore has several replicons.', wrong = '{"0": "This is reversed. Prokaryotes have one origin, and eukaryotes have many.", "1": "Eukaryotes have many origins on each chromosome. A single origin would make copying their long DNA far too slow.", "3": "Replication always begins at origin sites, where an initiator protein binds and starts the process."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0382' AND answer = 2;
UPDATE questions SET why = 'At the replication origin, helicase enzymes break the hydrogen bonds between base pairs. The two strands separate and form Y-shaped replication forks. Each separated strand can then act as a template.', wrong = '{"1": "Primase lays down short RNA primers on the separated strands. It does not open the helix.", "2": "DNA ligase joins Okazaki fragments of the lagging strand at the end of replication.", "3": "Peptidyl transferase forms peptide bonds between amino acids during translation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0383' AND answer = 0;
UPDATE questions SET why = 'Once helicase separates the two strands, they tend to pair up again. Single-strand binding proteins attach to the separated strands and stop them from re-joining and rewinding. This keeps both templates exposed so they can be copied.', wrong = '{"0": "Unwinding the double helix is done by helicase, which breaks the hydrogen bonds between base pairs.", "1": "RNA primers are made by the enzyme primase, which lays down 5 to 10 RNA nucleotides at the origin.", "3": "Okazaki fragments are joined by DNA ligase, after DNA polymerase I fills the gaps."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0384' AND answer = 2;
UPDATE questions SET why = 'DNA polymerase cannot start a new strand on a bare template. So the enzyme primase lays down a short primer of about 5 to 10 RNA nucleotides. DNA polymerase III then adds DNA nucleotides to the 3′ end of this primer.', wrong = '{"0": "DNA polymerase I removes primers later and fills the gap with DNA. 100 to 200 nucleotides is the length of eukaryotic Okazaki fragments.", "1": "A chain of about 250 adenine nucleotides is the poly-A tail added to the 3′ end of eukaryotic mRNA.", "2": "Helicase unwinds DNA and does not make primers. 1000 to 2000 nucleotides is the length of prokaryotic Okazaki fragments."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0385' AND answer = 3;
UPDATE questions SET why = 'DNA polymerase III builds new strands from deoxyribonucleoside triphosphates: dATP, dCTP, dGTP and dTTP. Each has three phosphate groups. When one is added, two phosphates break off, releasing the energy used to join the nucleotide to the chain.', wrong = '{"0": "Ribonucleoside triphosphates (ATP, CTP, GTP, UTP) are the raw materials of RNA, used in transcription.", "2": "Amino acids are the building blocks of proteins, joined during translation.", "3": "Monophosphates have no extra phosphates to break off, so they cannot supply the energy needed. The triphosphate form is used."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0386' AND answer = 1;
UPDATE questions SET why = 'Prokaryotes have three DNA polymerases. Polymerase III is the main builder of new strands. Polymerase I supports it by removing the RNA primers at the end and filling the gaps with DNA, while polymerase II repairs DNA damage.', wrong = '{"1": "The main enzyme that adds nucleotides to the new strands is DNA polymerase III.", "2": "Unwinding the double helix is done by helicase.", "3": "DNA polymerases work on DNA, not mRNA. Polymerase I replaces primers and fills gaps."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0387' AND answer = 0;
UPDATE questions SET why = 'Starting a new chain on an exposed template tends to introduce many errors. Making this first stretch out of RNA marks it as temporary. DNA polymerase I can then easily remove the error-prone primer and replace it with accurate DNA.', wrong = '{"0": "RNA is actually less stable than DNA, and stability is not the reason given for using an RNA primer.", "2": "DNA polymerase III copies DNA templates. It only needs the primer as a starting 3′ end.", "3": "Primers do not stay. DNA polymerase I removes them and fills the gaps with DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0388' AND answer = 1;
UPDATE questions SET why = 'DNA polymerase can only add nucleotides to a 3′ end, so it builds strands 5′ to 3′. The two template strands run in opposite directions, so on one strand the enzyme must work away from the fork. It jumps back to new primers and makes short pieces, the Okazaki fragments, later joined by ligase.', wrong = '{"0": "Both parental strands act as templates. The lagging strand has a template but it runs in the awkward direction.", "1": "Helicase separates the strands by breaking hydrogen bonds. It does not cut either strand into pieces.", "3": "RNA polymerase makes RNA in transcription. Both new DNA strands are made by DNA polymerase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0389' AND answer = 2;
UPDATE questions SET why = 'Replication starts at a specific sequence called the origin site and ends at a termination site. The stretch of DNA between them is one replication unit, called a replicon. Prokaryotic DNA is a single replicon, while each eukaryotic chromosome has several.', wrong = '{"0": "A codon is a group of three nucleotides in mRNA that codes for one amino acid.", "1": "An operon is a group of bacterial genes controlled together by one promoter and operator. It is not a unit of replication.", "2": "A promoter is the DNA sequence where RNA polymerase binds to start transcription."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0390' AND answer = 3;
UPDATE questions SET why = 'Okazaki fragments form on the lagging strand in both groups, but their length differs. In prokaryotes they are long, about 1000 to 2000 nucleotides. In eukaryotes they are shorter, about 100 to 200 nucleotides.', wrong = '{"0": "1000 to 2000 nucleotides is the length of prokaryotic Okazaki fragments. Eukaryotic ones are shorter.", "1": "The fragments are not the same length; prokaryotic ones are about ten times longer.", "3": "Eukaryotes also have a lagging strand, so they also make Okazaki fragments."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0391' AND answer = 2;
UPDATE questions SET why = 'Prokaryotes use three DNA polymerases (I, II and III). Eukaryotes have many more, at least 14, such as alpha, delta and epsilon. They need these to copy their huge amounts of linear DNA.', wrong = '{"0": "Three DNA polymerases (I, II and III) are named for prokaryotes. Eukaryotes have many more.", "2": "Even prokaryotes use more than one DNA polymerase, and eukaryotes have at least 14.", "3": "20 is the number of standard amino acids. Eukaryotes have at least 14 DNA polymerases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0392' AND answer = 1;
UPDATE questions SET why = 'Stability means DNA is copied accurately. DNA polymerases have a proofreading ability: they check each newly added nucleotide and correct mistakes. This keeps the base sequence the same, so the organism''s traits are maintained.', wrong = '{"0": "Mutations caused by radiation change the DNA sequence. They are a source of variability, not stability.", "1": "Crossing over in meiosis reshuffles alleles and creates variation, not stability.", "2": "Transposons (jumping genes) move within DNA and can cause mutations, which reduces stability."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0393' AND answer = 3;
UPDATE questions SET why = 'Francis Crick used the term central dogma for the one-way flow of genetic information. DNA is copied into RNA by transcription, and RNA directs the making of protein by translation. Once information is in protein, it never flows back.', wrong = '{"1": "Information never flows back from protein to RNA or DNA. This sequence is the exact reverse of the dogma.", "2": "The flow starts from DNA, which is transcribed into RNA. RNA is not the starting point in the dogma.", "3": "Protein cannot be made directly from DNA. An RNA copy is made first and then used to build protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0394' AND answer = 0;
UPDATE questions SET why = 'There are only four nucleotides. A one-nucleotide code gives 4 combinations and a two-nucleotide code gives 4 × 4 = 16, both fewer than 20 amino acids. A triplet code gives 4 × 4 × 4 = 64 combinations, more than enough, so codons must be three nucleotides long.', wrong = '{"0": "Four nucleotides can be arranged in triplets in 64 ways. That is the reason triplets work.", "1": "There are 20 amino acids, not 64. 64 is the number of possible triplet codons.", "2": "Single nucleotides give only 4 combinations, not 20. That is why single-base codons were rejected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0395' AND answer = 3;
UPDATE questions SET why = 'mRNA is made complementary to the DNA template. T pairs with A, A pairs with U (RNA has U, not T), and C pairs with G. So DNA TAC gives mRNA AUG, which is the start codon for methionine.', wrong = '{"1": "ATG has the right pairing but uses T. RNA contains uracil (U) instead of thymine (T).", "2": "UAC simply copies the DNA codon with U for T. Transcription makes the complementary sequence, not a copy.", "3": "TUG is not complementary to TAC and wrongly puts T into RNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0396' AND answer = 0;
UPDATE questions SET why = 'In 1961 Nirenberg made an mRNA of only uracil nucleotides (poly-U) and added it to bacterial cytoplasm. The bacteria made a polypeptide made only of phenylalanine. So the codon UUU specifies phenylalanine.', wrong = '{"0": "Methionine is specified by AUG, the start codon, not by UUU.", "1": "Glycine is specified by codons beginning with GG, such as GGC. A poly-U mRNA contains only UUU.", "3": "Valine is specified by codons beginning with GU. A poly-U mRNA contains only UUU."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0397' AND answer = 2;
UPDATE questions SET why = 'Of the 64 codons, three (UAA, UAG and UGA) are stop or nonsense codons. They do not specify any amino acid. When one reaches the A site of the ribosome, no tRNA matches it, a release factor frees the chain and protein synthesis stops.', wrong = '{"0": "AUG is the start codon, found at the beginning of genes. It specifies methionine.", "2": "UUU specifies phenylalanine, as Nirenberg showed with poly-U mRNA.", "3": "GGC specifies the amino acid glycine. It is not a stop codon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0398' AND answer = 1;
UPDATE questions SET why = 'Nirenberg and Philip Leder tested triplet codons and worked out the amino acids for 47 of them. Har Gobind Khorana, who studied at Government College Lahore, determined the amino acids for the remaining 17 codons. Together this completed the 64-codon code.', wrong = '{"1": "The work on all 64 codons was shared. Nirenberg and Leder decoded 47 and Khorana the remaining 17.", "2": "Khorana''s work covered 17 codons, not only the three stop codons.", "3": "The 47 codons were decoded by Nirenberg and Leder, not by Khorana."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0399' AND answer = 0;
UPDATE questions SET why = 'The genetic code is called universal because the same codons mean the same amino acids in almost all organisms. Mitochondria use a slightly different code, reflecting their separate evolutionary history. So this is an exception to universality, as are some ciliates and viruses.', wrong = '{"0": "Mitochondria still read their code in three-nucleotide codons. The triplet nature is not affected.", "1": "Mitochondrial codons are still read one after another without sharing bases. Only some codon meanings differ.", "3": "Mitochondrial codons are still read continuously, without gaps. Only some codon meanings differ."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0400' AND answer = 2;
UPDATE questions SET why = 'A non-overlapping code means each triplet is read on its own and no base is shared between neighbouring codons. So AUGAGCGCA is read only as AUG / AGC / GCA. It is never read as overlapping triplets like AUG / UGA / GAG.', wrong = '{"0": "Degeneracy means more than one codon can code for the same amino acid. It is not about how codons are divided.", "2": "Universality means the same code is used in almost all organisms. It is not about how the sequence is read.", "3": "Ambiguous would mean one codon codes for more than one amino acid. The genetic code is not ambiguous."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0401' AND answer = 1;
UPDATE questions SET why = 'Because the code is universal, a codon has the same meaning in almost every organism. For example, AGA specifies arginine in bacteria and in humans. So a gene moved from one organism into another is still read correctly, which makes genetic engineering possible.', wrong = '{"0": "Organisms share the same code, not the same genes. Different species have very different genes.", "1": "Each codon codes for only one amino acid. Universality is about the same meanings across organisms.", "2": "Mitochondria do have their own DNA, and it uses a slightly different code. That is an exception, not a result."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0402' AND answer = 3;
UPDATE questions SET why = 'Only one strand of DNA, the template (antisense) strand, is transcribed, and the mRNA is complementary to it. The other strand, the coding (sense) strand, is not transcribed. Its sequence matches the mRNA, except that DNA has T where RNA has U.', wrong = '{"0": "The strand that is transcribed into mRNA is the template (antisense) strand.", "1": "The strand complementary to the mRNA is the template strand. The coding strand has the same sequence as the mRNA.", "3": "Splicing removes introns from immature mRNA. It does not remove a DNA strand."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0403' AND answer = 2;
UPDATE questions SET why = 'DNA polymerase needs a primer, but RNA polymerase does not. In transcription, RNA polymerase binds to the promoter and starts the RNA chain on its own. This is a key difference from DNA replication.', wrong = '{"1": "An RNA primer is needed by DNA polymerase in replication. RNA polymerase starts a chain without one.", "2": "DNA polymerase III makes DNA during replication. Transcription is carried out by RNA polymerase.", "3": "Only the template strand is transcribed. Replication copies both strands."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0404' AND answer = 0;
UPDATE questions SET why = 'A promoter is a DNA sequence where RNA polymerase binds; it is not itself transcribed. In prokaryotes, TATAAT lies about 10 nucleotides before the start point, so it is the –10 sequence. TTGACA lies about 35 nucleotides before, so it is the –35 sequence.', wrong = '{"0": "The TATA box (TATAAA) is a eukaryotic promoter about 25 nucleotides before the start point.", "1": "The CAAT box is a eukaryotic promoter about 70 nucleotides before the start point.", "2": "The prokaryotic –35 sequence is TTGACA, not TATAAT."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0405' AND answer = 3;
UPDATE questions SET why = 'Prokaryotes have only one RNA polymerase, which makes all three kinds of RNA. Eukaryotes have three. RNA polymerase I makes rRNA in the nucleolus, RNA polymerase II makes mRNA, and RNA polymerase III makes tRNA.', wrong = '{"0": "RNA polymerase I makes rRNA in the nucleolus.", "2": "RNA polymerase III makes tRNA, the adaptor molecules that carry amino acids to the ribosome.", "3": "DNA polymerase III builds new DNA strands during replication in prokaryotes. It does not make RNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0406' AND answer = 1;
UPDATE questions SET why = 'In elongation, RNA polymerase builds the RNA chain in the 5′ to 3′ direction, adding to the 3′ end. The units used are ribonucleoside triphosphates (rNTPs). As each one is added, two phosphates break off and release energy.', wrong = '{"0": "RNA grows 5′ to 3′, not 3′ to 5′. It uses ribonucleotides, not deoxyribonucleotides, which build DNA.", "1": "The direction is right, but amino acids are joined in translation, not transcription.", "2": "RNA grows 5′ to 3′, and transcription needs no primer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0407' AND answer = 3;
UPDATE questions SET why = 'At the end of a gene, GC base pairs in the new RNA pair with each other and form a GC hairpin, followed by a tail of U nucleotides. The hairpin makes RNA polymerase pause. U–A pairing is the weakest and cannot hold the RNA to the DNA during the pause, so the RNA comes away and transcription stops.', wrong = '{"0": "A release factor binding to a stop codon ends translation on the ribosome, not transcription.", "2": "The sigma (σ) subunit recognizes the promoter and starts transcription. It does not cut RNA.", "3": "DNA ligase joins Okazaki fragments during replication. It plays no part in ending transcription."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0408' AND answer = 1;
UPDATE questions SET why = 'In eukaryotes, mRNA must travel from the nucleus to the cytoplasm. To protect it, a methylated GTP is attached at its 5′ end, forming the 5′ cap. The cap protects the mRNA from nucleases and phosphatases on this journey.', wrong = '{"0": "A chain of about 250 A nucleotides is the poly-A tail, added at the 3′ end.", "1": "A stop codon is part of the coding sequence and signals the end of translation. It is not added as a cap.", "3": "Introns are non-coding pieces removed by splicing. They are not attached to the 5′ end."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0409' AND answer = 2;
UPDATE questions SET why = 'Newly made eukaryotic mRNA is immature because it contains introns, non-coding regions, between the exons. Splicing cuts out the introns and joins the exons. So the mature mRNA is shorter and carries only coding sequences.', wrong = '{"1": "The 5′ cap is added, not removed, and it does not shorten the mRNA.", "2": "This reverses splicing. Exons are kept and joined; introns are removed.", "3": "A poly-A tail is added at the 3′ end, which makes the mRNA longer. It is not doubled."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0410' AND answer = 0;
UPDATE questions SET why = 'Before translation, each amino acid is joined to its own tRNA, forming aminoacyl-tRNA. This is done by the enzyme aminoacyl-tRNA synthetase. There are 20 kinds of it, each recognizing one amino acid and the tRNAs with the matching anticodons.', wrong = '{"0": "Peptidyl transferase forms peptide bonds between amino acids on the ribosome. It does not load amino acids onto tRNA.", "1": "RNA polymerase makes RNA from a DNA template during transcription.", "2": "A release factor recognizes a stop codon and frees the finished polypeptide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0411' AND answer = 3;
UPDATE questions SET why = 'Translation starts at the codon AUG, which codes for methionine. In prokaryotes the first amino acid is a modified form, N-formyl methionine. In eukaryotes it is ordinary, unmodified methionine.', wrong = '{"0": "Unmodified methionine is the first amino acid in eukaryotes. Prokaryotes use the formylated form.", "1": "Phenylalanine is coded by UUU. It is not brought by the start codon AUG.", "3": "Valine is not coded by the start codon AUG, so it is not the first amino acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0412' AND answer = 2;
UPDATE questions SET why = 'A ribosome has three tRNA sites. The P (peptidyl) site holds the tRNA carrying the growing chain. The A (aminoacyl) site is where the next aminoacyl-tRNA binds, and the E (exit) site is where empty tRNAs leave.', wrong = '{"0": "Empty tRNAs leave the ribosome from the E (exit) site.", "2": "Splicing of mRNA happens in the nucleus, before the mRNA reaches the ribosome.", "3": "A release factor frees the polypeptide at a stop codon. The 5′ cap is added in the nucleus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0413' AND answer = 1;
UPDATE questions SET why = 'The ribosome moves along the mRNA toward its 3′ end. New aminoacyl-tRNAs enter at the A site, move to the P site, and empty tRNAs leave from the E site. So from 5′ to 3′ the sites are arranged as E, P, A.', wrong = '{"1": "This is the reverse order. The A site is on the 3′ side, where new codons appear.", "2": "The E site is on the 5′ side, since tRNAs leave from the part of the mRNA already read.", "3": "The P site lies between E and A, because tRNAs move from A to P to E."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0414' AND answer = 0;
UPDATE questions SET why = 'After a peptide bond forms, the ribosome moves three nucleotides (one codon) along the mRNA in the 5′ to 3′ direction. This movement is called translocation. It shifts the tRNA with the chain from the A site to the P site and the empty tRNA to the E site.', wrong = '{"0": "Transformation is the uptake of genetic material that changes an organism, as in Griffith''s bacteria.", "1": "Transposition is the movement of transposons (jumping genes) from one place to another in DNA.", "2": "Transcription is the making of RNA from a DNA template."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0415' AND answer = 3;
UPDATE questions SET why = 'Stop codons (UAA, UAG, UGA) have no matching tRNA anticodon, so no aminoacyl-tRNA enters the A site. Instead a protein called release factor recognizes the stop codon and frees the polypeptide from the tRNA at the P site. The ribosomal subunits then separate from the mRNA.', wrong = '{"0": "No tRNA or amino acid matches a stop codon. That is exactly why the chain stops growing.", "2": "The ribosome does not cut the mRNA. The release factor frees the polypeptide and the subunits separate.", "3": "RNA polymerase works in transcription, not on the ribosome during translation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0416' AND answer = 1;
UPDATE questions SET why = 'In eukaryotes the new mRNA must travel from the nucleus to the cytoplasm, so it is processed first. A 5′ cap and a 3′ poly-A tail are added, and introns are removed by splicing. Eukaryotes also use larger 80S ribosomes and start with unmodified methionine.', wrong = '{"0": "70S ribosomes are found in prokaryotes. Eukaryotic ribosomes in the cytoplasm are larger, 80S.", "1": "N-formyl methionine is the first amino acid in prokaryotes. Eukaryotes start with unmodified methionine.", "3": "Translating mRNA at once, with no modification, is true of prokaryotes, which have no nucleus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0417' AND answer = 2;
UPDATE questions SET why = 'Every cell of an organism carries the same genome. But each cell type switches on only certain genes and keeps others off, under the control of regulator proteins. This regulation of gene expression produces different cell types, which is the basis of cell differentiation.', wrong = '{"1": "All body cells of an organism have the same set of chromosomes. Only the genes in use differ.", "2": "Cells do not lose their DNA as they specialize; the genome stays the same in all cell types.", "3": "Every living cell expresses many genes. Liver cells are only one example of cells using their own set of genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0418' AND answer = 0;
UPDATE questions SET why = 'In negative gene regulation, regulator proteins called repressors bind to DNA sites called operators, which lie near the promoter. A bound repressor blocks RNA polymerase. So transcription of the gene is stopped or reduced.', wrong = '{"0": "Helping RNA polymerase bind to the promoter is positive regulation, carried out by activators.", "1": "Removing introns from mRNA is splicing. It happens after transcription and is not the action of a repressor.", "3": "Adding a poly-A tail is a post-transcriptional change to eukaryotic mRNA, not gene repression."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0419' AND answer = 2;
UPDATE questions SET why = 'Liver cells and brain neurons have the same genes, including those for alcohol dehydrogenase. Liver cells switch these genes on to make the enzyme that breaks down alcohol. Neurons keep the same genes switched off, which shows cell-specific regulation of gene expression.', wrong = '{"1": "No mutation is involved. The genes in neurons are normal; they are simply not expressed.", "2": "Neurons still carry the alcohol dehydrogenase genes. The genes are switched off, not lost.", "3": "Crossing over is the exchange of DNA between homologous chromosomes in meiosis. It does not explain differences between body cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0420' AND answer = 0;
UPDATE questions SET why = 'In alternative splicing, regulatory proteins in different cell types cut the same immature mRNA in different ways. They may remove different introns or even exons, so mRNAs of different lengths are made. As a result, one gene can produce more than one polypeptide.', wrong = '{"0": "Copying a gene into DNA is replication (or reverse transcription). Splicing works on mRNA.", "1": "Sharing one promoter between genes is a feature of bacterial operons, not alternative splicing.", "2": "Information never flows from protein back to mRNA, according to the central dogma."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0421' AND answer = 3;
UPDATE questions SET why = 'A mutagen is any agent that causes a mutation, such as X-rays, UV radiation or chemicals like mustard gas. The organism or cell in which the mutation occurs is called a mutant. So the agent is the mutagen and the result is the mutant.', wrong = '{"0": "A mutant is the organism or cell that carries the mutation, not the agent that caused it.", "2": "A transposon is a jumping gene that moves within the genome. It can cause mutations but is not the general term for such agents.", "3": "A codon is a group of three mRNA nucleotides that codes for one amino acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0422' AND answer = 1;
UPDATE questions SET why = 'X-rays and gamma rays are high-energy ionizing radiation. They change atoms into free radicals, which are very reactive. These free radicals can break the phosphodiester bonds of the DNA backbone, causing mutations.', wrong = '{"1": "Joining two neighbouring pyrimidines (C and T) by covalent bonds is the effect of UV radiation, which DNA absorbs strongly.", "2": "Removing amino groups from adenine or cytosine is done by some mutagen chemicals, causing the bases to mis-pair.", "3": "Transposons move into new places by themselves. Radiation does not insert them into genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0423' AND answer = 0;
UPDATE questions SET why = 'GGC and GGU both code for glycine because the genetic code is degenerate: several codons can specify the same amino acid. So this base change leaves the amino acid sequence unchanged. A mutation that does not change the protein is a silent mutation.', wrong = '{"0": "A missense mutation changes one amino acid into another, as in sickle cell anaemia. Here glycine stays glycine.", "2": "A nonsense mutation creates an early stop codon. GGU is not a stop codon.", "3": "A frameshift deletion removes nucleotides. Here one base is replaced, and no nucleotide is lost."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0424' AND answer = 1;
UPDATE questions SET why = 'A nonsense mutation changes a codon into a stop codon in the middle of a gene. Translation stops early, giving a short protein that cannot work. In some cases of Duchenne muscular dystrophy, this is why the dystrophin protein is not made properly.', wrong = '{"0": "A silent mutation does not change the amino acid sequence, so the protein is normal.", "1": "A missense mutation replaces one amino acid with another. It does not stop the chain early.", "2": "A translocation moves a chromosome segment to another chromosome. A premature stop codon is a point mutation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0425' AND answer = 3;
UPDATE questions SET why = 'The common cause of cystic fibrosis is the deletion of just three nucleotides in a gene. Three nucleotides make one codon, so one amino acid is left out of the protein. The protein then folds wrongly, which leads to lung and digestive problems.', wrong = '{"0": "An extra chromosome 21 (trisomy 21) causes Down syndrome, not cystic fibrosis.", "1": "Glutamic acid being replaced by valine in the β chain of haemoglobin causes sickle cell anaemia.", "3": "Non-disjunction of the X chromosome gives sex chromosome disorders such as Klinefelter (XXY) or Turner (XO) syndrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0426' AND answer = 2;
UPDATE questions SET why = 'Sickle cell anaemia is caused by a recessive allele of the gene for the β chain of haemoglobin. This gene is located on chromosome 11. A child who inherits two mutant alleles makes abnormal β chains.', wrong = '{"0": "Chromosome 12 carries the gene for phenylalanine hydroxylase, which is faulty in phenylketonuria.", "1": "An extra chromosome 21 causes Down syndrome. The β-globin gene is not on chromosome 21.", "3": "Sickle cell anaemia is autosomal recessive, so it affects both sexes equally. Its gene is not on the X."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0427' AND answer = 2;
UPDATE questions SET why = 'In the mutant allele, a single base substitution changes the codon for glutamic acid into one for valine. So the abnormal β chain has valine where glutamic acid should be. This haemoglobin carries less oxygen and makes red blood cells sickle-shaped.', wrong = '{"1": "This reverses the change. Normal haemoglobin has glutamic acid, and the mutant has valine in its place.", "2": "Phenylalanine and tyrosine are linked to phenylketonuria, where phenylalanine is not converted to tyrosine.", "3": "Sickle cell anaemia is a point mutation in one gene, not a change in chromosome number."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0428' AND answer = 0;
UPDATE questions SET why = 'Bone marrow makes red blood cells, so replacing a patient''s marrow with healthy donor marrow lets the body make normal cells. A bone marrow transplant can therefore give a long-term cure. Painkillers, blood transfusions, vaccines and antibiotics only manage the symptoms.', wrong = '{"0": "A low-phenylalanine diet is used to manage phenylketonuria (PKU), not sickle cell anaemia.", "1": "Estrogen replacement therapy is used in Turner syndrome to develop secondary sexual characteristics.", "2": "Growth hormone injections are used in Turner syndrome to improve height."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0429' AND answer = 3;
UPDATE questions SET why = 'A gene on chromosome 12 codes for the liver enzyme phenylalanine hydroxylase (PAH). This enzyme converts the amino acid phenylalanine into tyrosine. In PKU the enzyme does not work properly, so phenylalanine builds up to toxic levels.', wrong = '{"0": "This reverses the reaction. The enzyme changes phenylalanine into tyrosine, not tyrosine into phenylalanine.", "2": "Converting glucose into glycogen is glycogenesis, controlled by other enzymes and by insulin.", "3": "Converting ammonia into urea happens in the urea (ornithine) cycle in the liver, not by this enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0430' AND answer = 1;
UPDATE questions SET why = 'In PKU the body cannot convert phenylalanine to tyrosine, so phenylalanine builds up and can damage the brain. Patients must avoid foods rich in phenylalanine, such as meat, dairy products, eggs and some grains. Blood levels are checked regularly to adjust the diet.', wrong = '{"0": "Vitamin C is not involved in PKU. The problem is the amino acid phenylalanine.", "1": "PKU is a problem with an amino acid, not with carbohydrates. The diet limits phenylalanine-rich protein foods.", "2": "Iodine is needed for thyroid hormones. It has nothing to do with PKU."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0431' AND answer = 3;
UPDATE questions SET why = 'Chromosomal rearrangements happen when DNA breaks and rejoins wrongly. In a translocation, a segment of one chromosome breaks off and becomes part of another chromosome. In an inversion, a segment is reversed within the same chromosome.', wrong = '{"0": "An inversion reverses the orientation of a segment within the same chromosome. Nothing moves to another chromosome.", "1": "A deletion is the loss of a segment of a chromosome. The segment is not joined to another chromosome.", "3": "A substitution is a point mutation in which one nucleotide is replaced by another."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0432' AND answer = 2;
UPDATE questions SET why = 'Transposons, or jumping genes, are small pieces of DNA that move to random new places in the genome. If one inserts into a gene, it can inactivate that gene; this is insertional inactivation. For example, a transposon inside the clotting factor IX gene adds a stop codon and causes haemophilia.', wrong = '{"1": "Failure of chromosomes or chromatids to separate in meiosis is non-disjunction, which changes chromosome number.", "2": "A gene being copied twice is a duplication, a type of chromosomal rearrangement.", "3": "The transposon adds a stop codon in the middle of the gene. Removing a stop codon is not how the gene is inactivated."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0433' AND answer = 0;
UPDATE questions SET why = 'Men make new sperm every day. In a female, all future eggs have already reached prophase I of meiosis before she is born. So her eggs are as old as she is, and errors in separating chromosomes build up with age, which is why the mother''s age matters more.', wrong = '{"0": "Sperm are produced continuously and freshly every day, not just once in life.", "2": "Eggs do undergo meiosis. They pause in prophase I for years before completing it.", "3": "Sperm do carry a sex chromosome, either X or Y."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0434' AND answer = 1;
UPDATE questions SET why = 'Down syndrome is caused by non-disjunction of autosome pair 21, usually during egg formation. An egg with 24 chromosomes is fertilized by a normal sperm with 23. The child has three copies of chromosome 21 (trisomy), giving 2n + 1 = 47 chromosomes.', wrong = '{"0": "An extra chromosome 13 causes a different, severe condition. A trisomy also gives 47 chromosomes, not 45.", "2": "Loss of an X chromosome gives Turner syndrome (XO, 45 chromosomes).", "3": "An extra chromosome 18 causes a different condition, and a trisomy gives 47, not 46."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0435' AND answer = 1;
UPDATE questions SET why = 'Klinefelter syndrome results when an XX egg is fertilized by a Y sperm, or an X egg by an XY sperm. The child has XXY sex chromosomes and 47 chromosomes in total (44 + XXY). Such a person is a sterile male with some female body features, such as less body hair.', wrong = '{"0": "XO with 45 chromosomes is Turner syndrome, which affects females.", "1": "XXX with 47 chromosomes is triple X syndrome. These females are fertile.", "2": "A person with a Y chromosome develops as a male, so XYY could not be a female. It is not Klinefelter syndrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0436' AND answer = 3;
UPDATE questions SET why = 'An OY zygote forms when an egg with no X chromosome is fertilized by a Y sperm. The X chromosome carries many genes needed for life, and the Y cannot replace them. So an OY zygote fails to develop.', wrong = '{"1": "Turner syndrome is XO: one X and no second sex chromosome. That person has the essential X genes.", "2": "Klinefelter syndrome is XXY. It has two X chromosomes as well as a Y.", "3": "A normal male is XY. An OY zygote has no X at all, so it cannot develop."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0437' AND answer = 0;
UPDATE questions SET why = 'Turner syndrome is caused by having only one X chromosome (XO), so the female has 45 chromosomes. Typical features are short stature, a webbed neck, immature sex organs and infertility. Growth hormone and estrogen replacement therapy are used to treat it.', wrong = '{"0": "Klinefelter syndrome (XXY) affects males, who have 47 chromosomes.", "1": "Down syndrome is trisomy 21, giving 47 chromosomes, and it occurs in both sexes.", "3": "Triple X females have 47 chromosomes, are often tall and are fertile."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0438' AND answer = 2;
UPDATE questions SET why = 'Triple X syndrome (XXX) arises when an XX egg is fertilized by an X sperm, giving 47 chromosomes. Affected females may have learning difficulties, tall stature and wide-spaced eyes. Unlike Turner females, they are fertile and enter puberty at the normal age.', wrong = '{"0": "45 chromosomes is the count in Turner syndrome. Triple X females have 47.", "1": "Triple X females are fertile. Sterility is a feature of Turner syndrome.", "3": "A webbed neck is a feature of Turner syndrome, not triple X syndrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0439' AND answer = 2;
UPDATE questions SET why = 'Traditional biotechnology has been used for thousands of years through fermentation. Microorganisms such as yeast and bacteria change food materials, giving bread, cheese and beer. Modern biotechnology began in the 20th century after the structure of DNA was discovered.', wrong = '{"0": "Recombinant DNA technology is modern biotechnology, which began in the 20th century.", "1": "PCR is a modern technique, developed by Kary Mullis in 1983.", "3": "Gene guns are a modern method for shooting DNA into plant cells. They were not used in ancient food making."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0440' AND answer = 2;
UPDATE questions SET why = 'Genetic engineering is the alteration of an organism''s DNA to change its traits or capabilities. It involves inserting, deleting or modifying genes, and sometimes moving genes between different species. It relies on recombinant DNA technology and PCR.', wrong = '{"0": "Cross-pollination is traditional plant breeding. It mixes whole genomes and does not directly change DNA.", "2": "Using microbes to ferment food is traditional biotechnology, not direct alteration of DNA.", "3": "Selecting the best animals for breeding is selective breeding. It does not directly alter genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0441' AND answer = 1;
UPDATE questions SET why = 'A gene of interest can be made in three ways: direct synthesis in the lab, reverse transcription of its mRNA, or cutting it out of a chromosome. Copying mRNA into DNA is reverse transcription. It is done by the enzyme reverse transcriptase.', wrong = '{"0": "Restriction endonucleases cut a gene out of chromosomal DNA. They do not copy mRNA into DNA.", "1": "DNA ligase joins DNA fragments together, such as a gene and a plasmid.", "2": "RNA polymerase makes RNA from a DNA template, the opposite direction to what is needed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0442' AND answer = 3;
UPDATE questions SET why = 'Restriction endonucleases are enzymes that cut DNA. Each kind recognizes a specific short nucleotide sequence called a restriction site and cuts the DNA there. Because they cut DNA at exact places, they are called molecular scissors.', wrong = '{"1": "Joining two DNA fragments is done by DNA ligase, which is called molecular glue.", "2": "Copying DNA many times is done by DNA polymerase, for example in PCR.", "3": "Carrying genes into host cells is the job of vectors, such as plasmids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0443' AND answer = 0;
UPDATE questions SET why = 'A restriction site is a palindromic sequence of 4 to 8 nucleotides. Palindromic means both strands have the same sequence when each is read in its own 5′ to 3′ direction, so they read the same in opposite directions. The enzyme then cuts both strands at this site.', wrong = '{"0": "Restriction sites are 4 to 8 nucleotides long. A single nucleotide could not be palindromic.", "2": "Restriction sites can contain all four bases. Being palindromic does not depend on having only A and T.", "3": "Restriction sites occur in DNA from any source, including chromosomes, not only in plasmids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0444' AND answer = 1;
UPDATE questions SET why = 'A restriction endonuclease cuts both strands of DNA at slightly different points within the site. This leaves each fragment with a short single-stranded overhang a few nucleotides long. These overhangs are complementary to each other, so they can pair up again and are called sticky ends.', wrong = '{"1": "Blunt ends have no overhang. Sticky ends have short single-stranded overhangs.", "2": "Sticky ends are bare single-stranded DNA, free to pair with complementary ends. They are not covered with proteins.", "3": "Sticky ends can pair with complementary ends and be joined by DNA ligase. That is why they are useful."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0445' AND answer = 0;
UPDATE questions SET why = 'A given restriction enzyme always leaves the same sticky ends. So any two DNA fragments cut by the same enzyme have complementary ends and can be joined, for example a human gene and a bacterial plasmid. This is what makes recombinant DNA possible.', wrong = '{"0": "Restriction enzymes cut DNA from any source, wherever their recognition site occurs.", "1": "Restriction enzymes cut DNA. Copying DNA is done by DNA polymerase, which needs a template.", "3": "Antibiotic resistance comes from a resistance gene on the plasmid, not from the restriction enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0446' AND answer = 2;
UPDATE questions SET why = 'A vector is a carrier molecule that takes the gene of interest into host cells. Bacterial plasmids, small circular DNA molecules, are the most commonly used vectors. Bacteriophages, cosmids, BACs and YACs are also used.', wrong = '{"0": "Restriction enzymes are tools for cutting DNA, not carriers of genes.", "1": "Ribosomes make proteins by translation. They do not carry genes into cells.", "2": "Okazaki fragments are short DNA pieces made on the lagging strand during replication."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0447' AND answer = 3;
UPDATE questions SET why = 'A cosmid is a type of vector. It is a plasmid that also contains a small region of bacteriophage DNA called the cos sequence. So it combines features of plasmids and phages.', wrong = '{"0": "An artificial chromosome made from yeast is a YAC (yeast artificial chromosome), a different vector.", "1": "Animal viruses such as the human cold virus are a separate type of vector used for monkey and human cells.", "2": "A heat-stable DNA polymerase is Taq polymerase, used in PCR. It is an enzyme, not a vector."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0448' AND answer = 3;
UPDATE questions SET why = 'DNA ligase joins two DNA fragments by forming phosphodiester linkages between adjacent nucleotides. In recombinant DNA work it seals the gene of interest into the cut vector. Because it sticks DNA pieces together, it is called molecular glue.', wrong = '{"0": "Cutting DNA at palindromic sites is done by restriction endonucleases, the molecular scissors.", "2": "Heating to about 98 °C separates DNA strands in PCR. No enzyme is needed for that step.", "3": "A radioactive probe detects colonies in DNA hybridization screening. Ligase plays no part in that."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0449' AND answer = 1;
UPDATE questions SET why = 'The expression system is a suitable host organism that takes up the recombinant DNA and expresses the gene of interest, making its protein. Bacteria are ideal expression systems because they have a short generation time and a simple genetic system.', wrong = '{"1": "The restriction enzyme is a tool for cutting DNA. It does not express the gene.", "2": "The antibiotic is used in screening to select bacteria that took up the plasmid.", "3": "A gel separates DNA fragments by size. It is not a living host that expresses genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0450' AND answer = 0;
UPDATE questions SET why = 'Each restriction enzyme leaves its own type of sticky ends. If the source DNA and the plasmid are cut with the same restriction endonuclease, their sticky ends are complementary. DNA ligase can then join the gene into the plasmid.', wrong = '{"0": "Ligase joins DNA; it does not cut. Cutting is done by restriction endonucleases.", "1": "Heating to 98 °C separates the two strands of DNA, as in PCR. It does not make sticky ends.", "3": "The gene of interest must also be cut out with the same enzyme so that it has matching sticky ends."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0451' AND answer = 2;
UPDATE questions SET why = 'The plasmid used as a vector carries a gene for resistance to an antibiotic such as ampicillin. When the bacteria are grown on an ampicillin medium, cells without the plasmid are killed. Only bacteria that took up a plasmid survive and form colonies.', wrong = '{"1": "Bacteria without plasmids have no resistance gene, so ampicillin kills them.", "2": "Blue colour comes from the lacZ′ gene in blue-white screening, not from ampicillin.", "3": "Bacteria that took up the plasmid carry the resistance gene and survive."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0452' AND answer = 0;
UPDATE questions SET why = 'The plasmid''s lacZ′ gene makes an enzyme that acts on a special sugar and turns the colony blue. If the gene of interest is inserted into the plasmid, it breaks the lacZ′ gene, so no blue colour is made. White colonies therefore contain the recombinant plasmid.', wrong = '{"0": "A plasmid without an insert keeps lacZ′ working, so its colony turns blue.", "1": "Bacteria without any plasmid lack the resistance gene and die on the antibiotic medium, so they form no colony.", "2": "Colony colour reflects whether lacZ′ works. It does not measure resistance to antibiotics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0453' AND answer = 3;
UPDATE questions SET why = 'In DNA hybridization, a radioactive probe, a DNA strand complementary to the gene of interest, is used. It sticks (hybridizes) only to colonies that contain that gene. Autoradiography on photographic film then shows where these colonies are on the master plate.', wrong = '{"0": "The blue colour from lacZ′ only tells plain plasmids from recombinant ones. It does not identify the specific gene.", "2": "Taq polymerase copies DNA in PCR. It is not used to locate colonies.", "3": "Using an electrical current to make pores is electroporation, a method of gene transfer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0454' AND answer = 1;
UPDATE questions SET why = 'Kary Mullis developed the polymerase chain reaction (PCR) in 1983. PCR uses DNA polymerase to copy a piece of DNA again and again, making millions of copies. He won the Nobel Prize in Chemistry in 1993 for this work.', wrong = '{"0": "Har Gobind Khorana worked out the meanings of 17 codons of the genetic code.", "1": "Marshall Nirenberg worked on the genetic code, starting with poly-U mRNA and the codon UUU.", "3": "Thomas Hunt Morgan worked on linkage and sex linkage in Drosophila."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0455' AND answer = 2;
UPDATE questions SET why = 'The first step of PCR is denaturation. Heating the DNA to about 98 °C breaks the hydrogen bonds between the strands, so the double-stranded DNA separates into single strands. Each single strand then acts as a template for making new DNA.', wrong = '{"0": "Primers are not activated by heat. They bind (anneal) when the mixture cools to about 60 °C.", "1": "Heating separates strands; nothing is joined at this step.", "2": "Taq polymerase is heat-stable and is not destroyed by heating, so it does not need to be replaced."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0456' AND answer = 3;
UPDATE questions SET why = 'After denaturation the mixture is cooled to about 60 °C. At this lower temperature, the forward and backward primers bind (anneal) to their complementary regions on the single-stranded DNA. These primers give Taq polymerase a starting point.', wrong = '{"1": "The DNA strands separate during denaturation at about 98 °C, before annealing.", "2": "Taq polymerase adds nucleotides during extension, at about 72 °C.", "3": "No cutting takes place in PCR. Cutting DNA is done by restriction enzymes in recombinant DNA work."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0457' AND answer = 0;
UPDATE questions SET why = 'A primer is a short single-stranded piece of nucleic acid that binds to the DNA template and gives the polymerase a starting point. In PCR an excess of primers about 20 to 30 nucleotides long is mixed with the DNA. This length is long enough to bind only at the target site.', wrong = '{"0": "Primers of 2 to 3 nucleotides would match many places in the DNA, so they could not bind specifically.", "2": "200 to 300 nucleotides is much longer than PCR primers, which are about 20 to 30 nucleotides.", "3": "2000 to 3000 nucleotides is far too long for a primer; that is the size of a whole gene fragment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0458' AND answer = 1;
UPDATE questions SET why = 'Taq polymerase comes from Thermus aquaticus, a bacterium that lives in hot springs. It is heat-stable and stays active at near-boiling temperatures. So it survives the 98 °C step of each cycle, and fresh enzyme does not need to be added.', wrong = '{"0": "Taq polymerase works best at high temperature, about 72 °C for extension, not only at 37 °C.", "1": "Taq polymerase copies DNA; it does not cut it. Cutting is done by restriction enzymes.", "3": "Because it is heat-stable, Taq polymerase survives heating and does not need to be added again."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0459' AND answer = 2;
UPDATE questions SET why = 'Each PCR cycle doubles the number of DNA molecules, so after n cycles one fragment gives 2ⁿ copies. After 20 cycles that is 2²⁰ = 1,048,576 copies. So one fragment gives more than one million copies.', wrong = '{"0": "20 copies would mean adding one copy per cycle. In PCR the number doubles every cycle.", "2": "400 is 20², the number of cycles squared. The correct calculation is 2 raised to the power 20.", "3": "About one thousand copies (2¹⁰ = 1024) come after only 10 cycles, not 20."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0460' AND answer = 1;
UPDATE questions SET why = 'PCR can make millions of copies from a very tiny amount of DNA. In criminal investigations, DNA from a speck of dried blood or the root of a single hair is amplified this way. The copies are then used to prepare a DNA fingerprint to identify a person.', wrong = '{"0": "Insulin for diabetics is produced by transgenic bacteria carrying the human insulin genes.", "1": "Shooting DNA into plant cells with a gene gun is biolistic transformation, a gene transfer method.", "3": "Ampicillin resistance comes from a gene carried on a plasmid used as a vector, not from PCR."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0461' AND answer = 2;
UPDATE questions SET why = 'A GMO is any plant, animal or microbe whose genome has been changed. Transgenic organisms are a particular group of GMOs that have received DNA from a different, unrelated species. An example is cotton carrying genes from the bacterium Bacillus thuringiensis.', wrong = '{"1": "Every GMO, including a transgenic one, has a changed genome. An unchanged genome is not a GMO at all.", "2": "Transgenic organisms are made by gene transfer methods in the lab, such as microinjection or gene guns, not by natural mating.", "3": "Moving an organism''s own genes to new places would not make it transgenic. Transgenics carry foreign DNA from another species."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0462' AND answer = 0;
UPDATE questions SET why = 'In electroporation, a short pulse of electric current creates temporary pores in the cell wall or cell membrane of the target cell. The gene of interest enters through these pores. Once the current stops, the pores close again.', wrong = '{"0": "Injecting the gene into the nucleus with a fine needle is microinjection.", "1": "Firing metal-coated DNA into cells with a gene gun is biolistic transformation.", "2": "Using a virus such as an adenovirus to carry the gene into cells is virus-mediated gene transfer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0463' AND answer = 3;
UPDATE questions SET why = 'In biolistic transformation, the gene of interest is coated with heavy metal particles. A gene gun then fires these particles into the target cells by mechanical force. This method is widely used for plant cells, which have tough cell walls.', wrong = '{"0": "Electroporation uses an electric current to open temporary pores in the membrane. No particles are fired.", "1": "Microinjection uses a fine needle to inject the gene directly into the nucleus.", "3": "In protoplast-mediated transfer, the cell wall is removed first and the protoplast is mixed with the gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0464' AND answer = 2;
UPDATE questions SET why = 'Transgenic bacteria are used to make many medicines from human genes. Tissue plasminogen activator (tPA) is one of them; it dissolves blood clots. Others include insulin, clotting factors, growth hormone, interferon and erythropoietin.', wrong = '{"0": "Erythropoietin made by transgenic bacteria is used to treat anaemia, by stimulating red blood cell production.", "2": "Interferon made by transgenic bacteria is used to treat some cancers.", "3": "Chymosin made by transgenic bacteria clots milk protein for cheese making."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0465' AND answer = 1;
UPDATE questions SET why = 'Transgenic bacteria also make enzymes for the food industry. Chymosin clots the protein in milk, which is the first step in making cheese. Other examples are alpha-amylase and pectin-esterase.', wrong = '{"1": "Clarifying fruit juice is done by pectin-esterase, another enzyme made by transgenic bacteria.", "2": "Converting starch into simple sugars is done by alpha-amylase.", "3": "Haemophilia is treated with clotting factors made by transgenic bacteria, not with chymosin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0466' AND answer = 0;
UPDATE questions SET why = 'Transgenic bacteria are also used to help the environment and mining. They can make enzymes that break down toxins into less harmful forms. They can also leach copper from ore, clean up mercury pollution and detect arsenic in drinking water.', wrong = '{"0": "Spider-silk proteins in milk are produced by transgenic goats, not bacteria.", "1": "Bt genes from a bacterium are put into plants such as cotton, so the plant itself makes the pest-killing protein.", "2": "Milk like human breast milk is produced by transgenic dairy cows carrying human genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0467' AND answer = 3;
UPDATE questions SET why = 'A transgenic animal carries a foreign gene that makes a useful protein. Transgenic goats have been made to produce strong, spider-web-like silk proteins in their milk. Other transgenic goats produce the human enzyme lysozyme in milk to fight diarrhoea-causing bacteria.', wrong = '{"0": "Human insulin is produced in transgenic E. coli bacteria, not in the blood of goats.", "2": "Bt toxin genes are inserted into crop plants such as cotton and maize, not goats.", "3": "Chymosin for cheese making is produced by transgenic bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0468' AND answer = 1;
UPDATE questions SET why = 'Germline cells give rise to eggs and sperm, so a gene inserted into them would be passed to future generations. Such inheritable changes carry risks and raise ethical issues. Somatic (body) cells are not passed on, so most research has focused on them.', wrong = '{"0": "Somatic cells contain the full set of DNA. Gene therapy works on them because they do have genes.", "1": "In theory genes can be inserted into germline cells too. They are avoided because of risk and ethics.", "3": "Changes in somatic cells stay in the treated person and are not passed to offspring."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0469' AND answer = 2;
UPDATE questions SET why = 'Malaria is caused by Plasmodium, which develops inside mosquitoes before it is passed to humans. Scientists inserted a gene into mosquitoes that reduces the development of Plasmodium in them. Such transgenic mosquitoes are less able to spread malaria.', wrong = '{"0": "The mosquitoes were not changed by removing feeding genes. A new gene was added to block Plasmodium.", "1": "Bt toxin genes are put into crop plants to kill insect pests, not used to stop malaria in mosquitoes.", "2": "Human lysozyme is produced in the milk of transgenic goats to fight diarrhoea-causing bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0470' AND answer = 3;
UPDATE questions SET why = 'Many plant cells are totipotent, meaning a single cell can divide and develop into a whole new plant. So a plant cell that has received a foreign gene can be grown into a complete transgenic plant. Every cell of that plant then carries the new gene.', wrong = '{"1": "Haploid means having one set of chromosomes. That is not what allows a single cell to grow into a full plant.", "2": "Plant cells do have cell walls. Totipotency, not lack of a wall, lets one cell form a plant.", "3": "A single cell must divide many times to form a plant. Cells that could not divide would be useless."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0471' AND answer = 0;
UPDATE questions SET why = 'Bacillus thuringiensis (Bt) is a soil bacterium whose genes code for insect-killing proteins. These genes have been put into crops such as cotton, rice, maize and brinjal. The plants then make proteins that kill insect pests but do not harm other useful insects.', wrong = '{"0": "Iron content was raised in transgenic rice using genes from beans, Aspergillus fungus and wild rice.", "1": "Resistance to the herbicide glyphosate is a separate genetic modification, not the job of Bt genes.", "3": "Human insulin is produced by transgenic bacteria carrying insulin genes, not by Bt crops."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0472' AND answer = 2;
UPDATE questions SET why = 'Transgenic (golden) rice was made to fight vitamin A and iron deficiency. The genes for making beta-carotene, which the body turns into vitamin A, were taken from daffodil. Genes to raise iron content were taken from beans, Aspergillus fungus and wild rice.', wrong = '{"1": "Beans supplied genes to increase the iron content of the rice, not beta-carotene.", "2": "Aspergillus fungus supplied genes for higher iron content, not beta-carotene.", "3": "Bacillus thuringiensis genes give crops resistance to insect pests."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0473' AND answer = 0;
UPDATE questions SET why = 'Insulin has two chains, A and B. Scientists put the DNA for chain A into one set of plasmids and the DNA for chain B into another, then into two separate E. coli cultures. The purified chains are mixed and joined by disulphide bonds to form working insulin.', wrong = '{"0": "The two chains are made separately in E. coli bacteria. There is no single whole gene put into one yeast cell.", "2": "Transgenic goats are used for products like spider-silk proteins and lysozyme, not human insulin.", "3": "PCR only copies DNA. Making a protein such as insulin needs living cells to read the gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0474' AND answer = 1;
UPDATE questions SET why = 'Bacteria may not read a foreign human gene well on its own. So each insulin gene is attached next to a bacterial gene, such as lacZ, in the plasmid. This helps the bacteria recognize and express the foreign DNA, making large amounts of the insulin chain.', wrong = '{"0": "Blue colour from lacZ′ is used in blue-white screening of colonies. It is not the reason here, and the insulin is not coloured.", "1": "Chains A and B are made in separate cultures and joined chemically in the lab after extraction.", "2": "Killing bacteria without plasmids is done with an antibiotic and a plasmid resistance gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0475' AND answer = 3;
UPDATE questions SET why = 'Chains A and B are made separately, then extracted and purified. In the laboratory they are mixed and linked by disulphide (S–S) bonds between sulphur-containing amino acids. This gives the working three-dimensional insulin molecule, identical to human insulin.', wrong = '{"0": "The two chains are not joined end to end by peptide bonds. They lie side by side, held by disulphide bridges.", "1": "Hydrogen bonds alone are too weak to hold the chains together. The chains are linked by covalent disulphide bonds.", "3": "Phosphodiester bonds link nucleotides in DNA and RNA, not amino acids in proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0476' AND answer = 2;
UPDATE questions SET why = 'The first line of defence stops microbes from entering the body in the first place. It consists of the skin, the digestive tract and the respiratory tract. These act as barriers and also release chemicals such as acid and lysozyme.', wrong = '{"0": "Macrophages, neutrophils and natural killer cells are germ-killer cells of the second line of defence.", "1": "Complement proteins and interferons are protective proteins of the second line of defence.", "2": "T cells and B cells are lymphocytes of the third line of defence, the specific immune system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0477' AND answer = 3;
UPDATE questions SET why = 'The outer layer of the epidermis is the stratum corneum. Its cells are constantly damaged and shed. New cells formed deep in the epidermis move upward to replace them, making keratin as they go.', wrong = '{"1": "The dermis is the layer of skin below the epidermis. It is not the outer layer.", "2": "The hypodermis is the layer beneath the dermis, containing fat.", "3": "The basement membrane lies under the epithelium, at the base of the epidermis, not on the surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0478' AND answer = 0;
UPDATE questions SET why = 'New epidermal cells form in the deep epidermis and move up toward the surface. As they move, they make the tough protein keratin. Keratin makes the skin tough and impenetrable to microbes.', wrong = '{"0": "Collagen is a fibre protein of connective tissue, such as the dermis. It is not the barrier protein of the epidermis.", "1": "Lysozyme is an enzyme in sweat that digests bacterial cell walls. It is not a structural protein.", "3": "Perforins are proteins released by natural killer cells to make pores in infected cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0479' AND answer = 2;
UPDATE questions SET why = 'The epidermis is the outer layer of the skin and is about 10 to 30 cells thick. Its outermost layer, the stratum corneum, is shed and replaced continuously. This thickness forms a strong barrier against microbes.', wrong = '{"0": "1 to 3 cells would be a very thin lining, like simple epithelium. The skin''s epidermis is much thicker.", "2": "100 to 300 cells is far thicker than the epidermis, which is about 10 to 30 cells.", "3": "500 to 1000 cells is far too thick. The epidermis is about 10 to 30 cells thick."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0480' AND answer = 1;
UPDATE questions SET why = 'Oil and sweat glands secrete chemicals that make the skin surface acidic. They lower the pH to about 3 to 5. This acidity is enough to inhibit the growth of many microbes.', wrong = '{"1": "A pH of 7 to 8 is neutral to slightly alkaline, which would not stop microbes from growing.", "2": "A pH of 8 to 10 is alkaline. Skin secretions make the surface acidic, not alkaline.", "3": "A pH of 1 to 2 is the strength of stomach acid, much more acidic than the skin surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0481' AND answer = 0;
UPDATE questions SET why = 'Lysozyme is an enzyme that attacks and digests the cell walls of many bacteria. It is found in sweat on the skin and in saliva in the mouth. So it helps the first line of defence kill bacteria on the body surface and in food.', wrong = '{"0": "Salivary amylase digests starch into sugars. It does not attack bacterial cell walls.", "2": "Pepsin is a protein-digesting enzyme of the stomach. It is not found in sweat.", "3": "Lipase digests fats into fatty acids and glycerol. It does not attack bacterial cell walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0482' AND answer = 1;
UPDATE questions SET why = 'Cells lining the smaller bronchi and bronchioles secrete a layer of sticky mucus that traps microbes. Cilia on these cells keep sweeping the mucus upward, away from the warm, moist lungs. The mucus reaches the throat and is swallowed.', wrong = '{"0": "The aim is to keep microbes out of the lungs. Mucus is moved upward, not carried down into them.", "1": "Mucus is not absorbed into the blood. It is moved up and swallowed.", "2": "Alveoli do not secrete acid. Trapped microbes are removed by cilia moving the mucus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0483' AND answer = 3;
UPDATE questions SET why = 'Food carries many bacteria. Saliva with lysozyme kills some in the mouth. Most of the rest are killed by the strong digestive acid in the stomach, and protein-digesting enzymes in the intestine kill more.', wrong = '{"0": "Bile salts are released into the small intestine to emulsify fats. They are not the stomach''s defence.", "1": "Interferons are released by virus-infected cells to protect nearby cells. They do not act in the stomach.", "3": "Antibodies from plasma cells are part of the third line of defence, not the stomach''s barrier."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0484' AND answer = 2;
UPDATE questions SET why = 'When microbes get past the first line and reach deep tissues, the second line of defence acts. Like the first line, it is non-specific, meaning it acts against any invader in the same way. Specific defence belongs only to the third line, the immune system.', wrong = '{"1": "Targeting one particular microbe is specific defence, which is the work of the third line.", "2": "B cells are lymphocytes of the third line. The second line uses germ-killer cells, proteins, inflammation and fever.", "3": "The non-specific defences are present from birth (innate). They do not need vaccination."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0485' AND answer = 0;
UPDATE questions SET why = 'The four main parts of the second line of defence are germ-killer cells of blood, antimicrobial proteins, the inflammatory response and the temperature response. Plasma cells secreting antibodies belong to the third line of defence. So they are not part of the second line.', wrong = '{"0": "Germ-killer cells of blood (macrophages, neutrophils, natural killer cells) are one of the four components.", "2": "The inflammatory response, with redness, swelling and warmth, is one of the four components.", "3": "The temperature response, or fever, is one of the four components."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0486' AND answer = 1;
UPDATE questions SET why = 'Macrophages develop from monocytes, a type of white blood cell. Monocytes leave the blood and enlarge into macrophages. These large phagocytes engulf and digest bacteria and clean up debris.', wrong = '{"0": "Neutrophils are a separate type of phagocytic white blood cell. They do not turn into macrophages.", "1": "Platelets are cell fragments that help blood clot. They do not become macrophages.", "3": "Plasma cells develop from B cells and secrete antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0487' AND answer = 2;
UPDATE questions SET why = 'A macrophage takes in a bacterium by endocytosis, enclosing it in a vesicle. It then kills and digests the bacterium with its lysozyme enzymes. Macrophages are found patrolling the blood, lymph and interstitial fluid.', wrong = '{"0": "Perforins are used by natural killer cells and cytotoxic T cells to punch pores in infected cells.", "1": "Releasing a network of DNA fibres is a killing method of neutrophils.", "2": "Membrane-attack complexes are formed by complement proteins on the microbe''s membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0488' AND answer = 3;
UPDATE questions SET why = 'Most macrophages move about, patrolling the blood, lymph and interstitial fluid. Some, however, stay fixed within certain organs. Fixed macrophages are found in the lungs, liver, spleen and brain.', wrong = '{"0": "The kidneys, bladder and ureters are not the organs named for fixed macrophages.", "2": "The stomach, oesophagus and colon are not the organs named for fixed macrophages.", "3": "Hair and nails are dead keratin structures. They are not sites of fixed macrophages."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0489' AND answer = 1;
UPDATE questions SET why = 'Neutrophils kill pathogens in three ways: phagocytosis, releasing soluble antimicrobial chemicals, and releasing a network of DNA fibres. The DNA fibres bind to bacteria and kill them. This third method is described for neutrophils, not for macrophages.', wrong = '{"0": "Both neutrophils and macrophages ingest bacteria by phagocytosis, so this is shared.", "1": "Being derived from monocytes is true of macrophages, not neutrophils.", "2": "Both neutrophils and macrophages patrol the blood, so this does not separate them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0490' AND answer = 3;
UPDATE questions SET why = 'Natural killer cells attack body cells infected with viruses. They release proteins called perforins, which insert into the target cell''s membrane and form a pore. Water rushes in through the pore, so the cell swells and bursts.', wrong = '{"1": "Natural killer cells do not engulf their targets. Phagocytosis is used by macrophages and neutrophils.", "2": "Antibodies are secreted by plasma cells, which come from B cells.", "3": "Histamine is released by injured cells and mast cells during inflammation and allergy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0491' AND answer = 0;
UPDATE questions SET why = 'Natural killer cells do not kill free microbes. They detect and kill body cells that have gone wrong. Besides virus-infected cells, they recognize cancer cells and kill them before they can develop into a tumour.', wrong = '{"0": "Old red blood cells are removed by the spleen and liver, not by natural killer cells.", "1": "Natural killer cells do not kill invading microbes directly. They attack infected or cancerous body cells.", "3": "Pollen grains are allergens, handled by antibodies and mast cells, not natural killer cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0492' AND answer = 2;
UPDATE questions SET why = 'All normal body cells carry a surface protein marker that identifies them as "self", called a self-protein. Macrophages, neutrophils and natural killer cells recognize it and leave such cells alone. They attack only cells that lack self-proteins.', wrong = '{"0": "Keratin is a tough protein made by skin cells. It is not present on all body cells as a self marker.", "1": "Interferon receptors let cells respond to interferons. They do not mark a cell as self.", "3": "Human cells have no cell wall. Cell walls are found in bacteria, fungi and plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0493' AND answer = 2;
UPDATE questions SET why = 'The complement system is a group of more than a dozen proteins that circulate in the blood in an inactive form. These proteins are produced in the liver. When they meet a microbe, they activate one another in sequence.', wrong = '{"1": "The thymus is where T cells mature. It does not make complement proteins.", "2": "Bone marrow makes blood cells, including white blood cells, not complement proteins.", "3": "Lymph nodes house lymphocytes and filter lymph. They do not make complement proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0494' AND answer = 0;
UPDATE questions SET why = 'Complement proteins activate one another in sequence: the first activates the second, and so on. The final five proteins of this sequence come together to form the membrane-attack complex (MAC). The MAC inserts into the microbe''s plasma membrane and punctures it.', wrong = '{"0": "The first protein only starts the chain of activation. It does not form the attack complex.", "2": "IgE antibodies are involved in allergic reactions. They do not form the membrane-attack complex.", "3": "Interferons are a separate group of protective proteins that warn nearby cells against viruses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0495' AND answer = 1;
UPDATE questions SET why = 'The membrane-attack complex punctures the plasma membrane of the microbe. Fluids and salts then flow into the microbe through the hole. The microbe swells and bursts.', wrong = '{"0": "The attack complex acts on the plasma membrane. It does not cut the microbe''s DNA.", "1": "Complement proteins do not engulf microbes. Engulfing is done by phagocytes such as macrophages.", "2": "The attack complex does not act on ribosomes. It kills by puncturing the membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0496' AND answer = 3;
UPDATE questions SET why = 'Interferons are protective proteins released by cells that have been infected by a virus. They signal nearby cells to strengthen their antiviral defences. They also activate other immune cells such as natural killer cells and macrophages.', wrong = '{"0": "Mast cells release histamine, which causes inflammation and allergic symptoms.", "2": "Liver cells release complement proteins into the blood, not interferons.", "3": "Plasma cells secrete antibodies, which are specific to one antigen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0497' AND answer = 1;
UPDATE questions SET why = 'Cytokines are proteins that carry signals between cells to trigger the immune system''s defences. Interferons belong to this large class. They warn nearby cells about viruses and activate natural killer cells and macrophages.', wrong = '{"1": "Immunoglobulins are antibodies made by plasma cells. Interferons are not antibodies.", "2": "Perforins are pore-forming proteins released by natural killer cells to burst infected cells.", "3": "Pyrogens are chemicals released by macrophages that cause fever by acting on the hypothalamus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0498' AND answer = 0;
UPDATE questions SET why = 'During inflammation, more blood flows to the injured site, making it warm. This heat makes the site unfavourable for microbes to grow. It also promotes healing and raises the mobility of white blood cells, so they reach the microbes faster.', wrong = '{"0": "Inflammation increases blood flow to the injured area because local blood vessels widen.", "1": "The heat of inflammation does not destroy self-proteins. Self-proteins protect normal cells from attack.", "3": "Neutrophils do not turn into plasma cells. Plasma cells develop from B cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0499' AND answer = 2;
UPDATE questions SET why = 'Injured or infected cells release histamines and prostaglandins. These make local blood vessels widen, increasing capillary blood flow, and make capillaries more permeable so fluid leaks out. This gives redness, swelling and warmth.', wrong = '{"0": "Constriction of arterioles would reduce blood flow, making the area paler and cooler, not red and warm.", "1": "Clotting that blocks capillaries would stop blood reaching the area. It is not what causes the signs.", "2": "Shedding of the stratum corneum is a normal first-line skin process, not part of inflammation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0500' AND answer = 3;
UPDATE questions SET why = 'During inflammation, neutrophils and macrophages move to the infected site and engulf microbes, and many of them die. Pus is a mixture of dead or dying neutrophils, broken-down tissue cells and dead pathogens. It forms at some infection sites.', wrong = '{"0": "Pus is mostly dead cells and debris. Antibodies and complement proteins are not its main content.", "2": "Red blood cells and platelets are not the main parts of pus. It is mainly dead white cells and debris.", "3": "Mucus from the bronchioles is a first-line secretion that traps microbes in the airways. It is not pus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0501' AND answer = 1;
UPDATE questions SET why = 'Normally inflammation is a response to infection or injury. In some cases, such as arthritis, inflammation occurs without any infection or injury. This is an example of a misdirected immune response, which damages the body''s own joints.', wrong = '{"1": "Arthritis is a disorder where inflammation harms the joints. It is not a successful barrier like the skin.", "2": "Passive acquired immunity means receiving ready-made antibodies, as from mother to baby. Arthritis is not immunity.", "3": "Fever is a rise in body temperature caused by pyrogens. Arthritis is inflammation of the joints, not a fever."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0502' AND answer = 0;
UPDATE questions SET why = 'When macrophages attack microbes, they release chemicals called pyrogens. Pyrogens travel in the blood to the hypothalamus, the body''s thermostat. They make it raise the core temperature above the normal 37 °C, which is fever.', wrong = '{"0": "The medulla oblongata controls breathing and heart rate, not body temperature set points.", "1": "The cerebellum coordinates movement and balance. It does not set body temperature.", "2": "The thymus is where T cells mature. It does not control body temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0503' AND answer = 3;
UPDATE questions SET why = 'Normal body temperature is 37 °C (98.6 °F). In general, temperatures above 39.4 °C (103 °F) are considered dangerous. Temperatures above 40.5 °C (105 °F) are often fatal.', wrong = '{"0": "37 °C (98.6 °F) is the normal body temperature, not a dangerous one.", "1": "38 °C (100.4 °F) is a mild fever, which helps fight infection.", "3": "39.4 °C (103 °F) is the level considered dangerous. The often-fatal level is higher, above 40.5 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0504' AND answer = 2;
UPDATE questions SET why = 'Fever is a defence mechanism. It makes it harder for bacteria and viruses to reproduce and kills some temperature-sensitive microbes. It also speeds up the actions of neutrophils and macrophages, and more interferons are released.', wrong = '{"1": "Fever slows the reproduction of bacteria and viruses. It does not make them multiply faster.", "2": "During fever the body releases more cytokines, including interferons, not fewer.", "3": "Fever does not stop antibody production. It supports the body''s defences."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0505' AND answer = 0;
UPDATE questions SET why = 'The third line of defence is the immune system. It is specific: it targets particular microbes and acts especially against them. It also remembers previous invaders, so it responds faster if they enter the body again.', wrong = '{"0": "Defence present in full at birth is innate (non-specific) immunity. Specific immunity is acquired during life.", "1": "Skin and mucus belong to the first line of defence.", "2": "Acting the same way against all microbes is non-specific defence, the first and second lines."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0506' AND answer = 3;
UPDATE questions SET why = 'In natural active immunity, the body makes its own antibodies after natural exposure to an antigen, here the measles virus. Memory cells formed during the illness protect against later infection. It is regarded as the most effective form of immunity.', wrong = '{"0": "Artificial active immunity comes from vaccination with weakened or killed antigens, not from catching the disease.", "1": "Passive immunity means receiving ready-made antibodies, for example from the mother. Here the person made the antibodies.", "3": "Innate immunity is the non-specific defence present at birth. Immunity to measles is specific and acquired."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0507' AND answer = 2;
UPDATE questions SET why = 'In passive immunity, a person is given ready-made antibodies, for example by injection or from the mother. The body does not make them itself and forms no memory cells. When the supplied antibodies break down, the protection is lost, so it is short-lived.', wrong = '{"0": "Memory B cells are formed in active immunity. Passive immunity lacks them, which is why it does not last.", "2": "Vaccination makes the body produce its own antibodies and memory cells, which is active immunity.", "3": "Passive immunity relies on antibodies from outside, not on the person''s own T cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0508' AND answer = 1;
UPDATE questions SET why = 'T cells develop from stem cells in the bone marrow, like other white blood cells. They then migrate to the thymus, a small grey gland just above the heart. There they mature and gain the ability to recognize specific antigens.', wrong = '{"0": "B cells, not T cells, stay and complete their maturation in the bone marrow.", "1": "The spleen holds many lymphocytes, but T cells do not mature there.", "2": "The liver makes complement proteins. It is not the site of T cell maturation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0509' AND answer = 3;
UPDATE questions SET why = 'There are four main kinds of T cells. Helper T cells start the immune response, cytotoxic T cells destroy infected cells, and suppressor T cells end the response. Inducer T cells supervise the development of T cells in the thymus.', wrong = '{"1": "Helper T cells start (initiate) the immune response after being activated by macrophages.", "2": "Cytotoxic T cells recognize and destroy body cells infected by microbes.", "3": "Suppressor T cells end (terminate) the immune response once the infection is controlled."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0510' AND answer = 0;
UPDATE questions SET why = 'B cells mature in the bone marrow, and each is specialized to recognize a particular antigen. When a B cell meets its antigen, it divides into many plasma cells. Each plasma cell secretes antibodies that stick to the antigen and mark it for destruction.', wrong = '{"0": "Macrophages develop from monocytes, not from B cells.", "2": "Inducer T cells are a kind of T cell that matures in the thymus. B cells do not turn into T cells.", "3": "Mast cells are found in connective tissue and release histamine. They are not made from B cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0511' AND answer = 1;
UPDATE questions SET why = 'When a macrophage engulfs a microbe, it makes special proteins that are recognized by helper T cells. This activates the helper T cells. Activated helper T cells then start both cell-mediated immunity and antibody-mediated immunity.', wrong = '{"0": "Suppressor T cells end the immune response after the infection is controlled. They do not start it.", "1": "Memory B cells give a fast response on a later exposure to the same antigen. They do not start the first response.", "3": "Natural killer cells are part of the non-specific second line of defence. They do not start specific responses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0512' AND answer = 2;
UPDATE questions SET why = 'An activated helper T cell releases soluble chemicals such as T cell growth factor. This factor makes all types of T cells divide rapidly. As a result, large clones of T cells that recognize the antigen are formed; this is the proliferation step.', wrong = '{"1": "Attracting macrophages to the infection site is done by a second factor from helper T cells (the activation step).", "2": "Shutting down the cytotoxic response is the work of suppressor T cells in the suppression step.", "3": "Antibodies are secreted by plasma cells in antibody-mediated immunity, not by T cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0513' AND answer = 0;
UPDATE questions SET why = 'Suppressor T cells block the cytotoxic T cell response. But they multiply more slowly than cytotoxic T cells and start in low numbers, so at first they cannot stop the attack. After 1 to 2 weeks their numbers rise enough to shut the response down.', wrong = '{"0": "T cells develop from bone marrow stem cells and mature in the thymus, not the liver.", "1": "Suppressor T cells do work in the specific immune response. Their delay is due to low numbers and slow growth.", "3": "Perforins are used against infected or cancer cells. They do not destroy suppressor T cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0514' AND answer = 2;
UPDATE questions SET why = 'Antibodies are proteins secreted by plasma cells into the blood. They make up about 20% by weight of the total protein in blood plasma. The rest is mostly other plasma proteins such as albumin and clotting proteins.', wrong = '{"0": "2% is far too low. Antibodies are a major part of plasma protein, about 20%.", "1": "50% is too high. Albumin, not antibodies, is the most abundant plasma protein.", "2": "80% is far too high. Antibodies are only about one fifth of plasma protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0515' AND answer = 3;
UPDATE questions SET why = 'Antibodies do not destroy an antigen directly. They only mark it for destruction, in one of three ways: by activating complement proteins, by being recognized by macrophages, or by being recognized by killer cells. Digesting the antigen with enzymes is not one of them.', wrong = '{"0": "Some antibodies activate complement proteins, which make holes in the antigen''s membrane so it bursts. This is one of the three ways.", "2": "Antibody-coated antigens are recognized and ingested by macrophages. This is one of the three ways.", "3": "Killer cells have receptors for antibody-coated antigens and kill them. This is one of the three ways."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0516' AND answer = 1;
UPDATE questions SET why = 'Some members of the clone of plasma cells do not make antibodies. Instead they persist as memory B cells. If the same antigen enters again, these memory cells give a rapid and strong secondary response.', wrong = '{"1": "Complement proteins from the liver are non-specific and have no memory of earlier infections.", "2": "Interferons are released by virus-infected cells and act non-specifically. They give no memory.", "3": "Histamine from mast cells causes inflammation and allergic symptoms. It plays no part in immune memory."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0517' AND answer = 0;
UPDATE questions SET why = 'An antibody is a Y-shaped protein made of four polypeptide chains. It has two identical long (heavy) chains and two identical short (light) chains. The four chains are held together by disulphide bridges.', wrong = '{"0": "An antibody has two heavy and two light chains, not one and three. The chains are held by disulphide bridges, not hydrogen bonds.", "1": "The four chains are not all identical: two are heavy and two are light. They are held by disulphide bridges.", "3": "An antibody has two light chains as well as two heavy chains."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0518' AND answer = 2;
UPDATE questions SET why = 'Each antibody chain has a constant region and a variable region. On each arm of the Y, the variable regions of one heavy and one light chain together form the antigen-binding site. Variable regions differ between antibodies, which makes each antibody specific.', wrong = '{"0": "Constant regions are similar in all antibodies of the same class, so they cannot give specific binding.", "2": "Disulphide bridges hold the four chains together. They do not form the binding site.", "3": "The stem of the Y is made of the constant regions of the heavy chains. The binding sites are at the tips of the arms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0519' AND answer = 1;
UPDATE questions SET why = 'Only a small part of an antigen molecule fits into an antibody''s binding site. This part is called the determinant. Monoclonal antibodies attach to just one determinant, while polyclonal antibodies bind to different determinants.', wrong = '{"0": "A hybridoma is a cell made by fusing a plasma cell with a myeloma cancer cell to make monoclonal antibodies.", "1": "A self-protein is a surface marker that identifies the body''s own normal cells.", "2": "The constant region is part of the antibody molecule itself, not part of the antigen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0520' AND answer = 3;
UPDATE questions SET why = 'Milstein and Köhler mixed antibody-producing plasma cells with myeloma cancer cells. The fused cells, called hybridomas, use plasma-cell genes to make one antibody and myeloma genes to keep dividing. So they produce large amounts of a single monoclonal antibody.', wrong = '{"0": "T cells and macrophages do not make antibodies, so fusing them could not produce monoclonal antibodies.", "2": "Neither neutrophils nor red blood cells make antibodies. Mature red cells have no nucleus at all.", "3": "Mast cells release histamine and are not used. The fusion partner for the plasma cell is a myeloma cell."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0521' AND answer = 1;
UPDATE questions SET why = 'Monoclonal antibodies bind to just one determinant on one kind of molecule. So they can be used to pick out and purify a specific molecule from a complex mixture. Interferon was purified this way.', wrong = '{"0": "Replacing skin in burn patients is not a listed use of monoclonal antibodies; they are used to purify molecules and deliver targeted therapy.", "1": "Insulin is made by recombinant DNA technology in bacteria, not by monoclonal antibodies.", "3": "Raising body temperature during infection is the effect of pyrogens on the hypothalamus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0522' AND answer = 2;
UPDATE questions SET why = 'Tumour-infiltrating lymphocytes (TILs) attack tumours but are not strong enough to control malignant melanoma. Genetic engineers are trying to insert a gene into TILs so they make tumour necrosis factor (TNF). Returned to the blood, these TILs would enter the tumour and release TNF to kill it.', wrong = '{"1": "Interferon is released by virus-infected cells to warn nearby cells. It is not the protein named in this therapy.", "2": "Insulin is a hormone that lowers blood glucose. It has no role in killing tumour cells.", "3": "Lysozyme is an enzyme that digests bacterial cell walls. It does not kill tumour cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0523' AND answer = 0;
UPDATE questions SET why = 'In an allergy, some people make E-antibodies (IgE) against a harmless allergen. These antibodies bind to mast cells in connective tissue around blood vessels. Mast cells then release histamines, causing inflammation with sneezing, runny nose and itching.', wrong = '{"0": "Perforins are released by natural killer and cytotoxic T cells to burst infected cells.", "1": "Pyrogens are released by macrophages and cause fever by acting on the hypothalamus.", "2": "Complement proteins are made in the liver and circulate in the blood. Mast cells do not release them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0524' AND answer = 3;
UPDATE questions SET why = 'In desensitization, small amounts of allergen extract are injected into the patient. This makes the body produce G-antibodies (IgG) in the blood. When the allergen enters, the G-antibodies remove it before it can reach E-antibodies on mast cells, so less histamine is released.', wrong = '{"0": "More E-antibodies on mast cells would make the allergy worse, since they trigger histamine release.", "1": "Antihistamines are drugs given from outside to block histamine. The body does not make them.", "3": "More mast cells would release more histamine and worsen the allergy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0525' AND answer = 2;
UPDATE questions SET why = 'Anaphylactic shock is a severe allergic reaction caused by a large release of histamines. Histamines dilate vessels and make them leak fluid, causing swelling. When the airways swell, breathing becomes difficult, which can be life-threatening.', wrong = '{"1": "Anaphylactic shock is not described as a fall in body temperature. Its danger is swelling that blocks breathing.", "2": "Antibodies are not destroyed in anaphylaxis. The reaction is caused by IgE antibodies triggering mast cells.", "3": "Keratin production in the skin has nothing to do with allergic reactions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0526' AND answer = 0;
UPDATE questions SET why = 'Myasthenia gravis is an autoimmune disease. Patients make antibodies against the acetylcholine receptors on their own skeletal muscle cells. The bound antibodies block the receptors, so muscles cannot respond to acetylcholine and become weak.', wrong = '{"0": "Antibodies against insulin-producing cells of the pancreas cause type I (juvenile) diabetes.", "1": "Antibodies against the cartilage of joints cause rheumatoid arthritis.", "2": "Antibodies against connective tissue and major organs cause systemic lupus erythematosus (SLE)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0527' AND answer = 3;
UPDATE questions SET why = 'An autoimmune disease occurs when the immune system cannot tell the body''s own cells from foreign material and attacks them. In type I diabetes, antibodies destroy the insulin-producing cells of the pancreas. So too little insulin is made and blood glucose rises.', wrong = '{"0": "In type I diabetes the body makes too little insulin, because the cells that make it are destroyed.", "2": "The cause is destruction of insulin-producing pancreatic cells, not the liver failing to make glucose.", "3": "Mast cells releasing histamine describes an allergic reaction, not autoimmune destruction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0528' AND answer = 1;
UPDATE questions SET why = 'Rejection is least likely when the donor''s self-proteins match the recipient''s. Identical twins have a 100% match of self-proteins. The order of preference is identical twin, then sibling, then parent, then unrelated donor.', wrong = '{"0": "A parent comes after an identical twin and a sibling, because a parent shares only half of a child''s genes.", "1": "An unrelated donor is the last choice; the chance of a match is only about 1 in 100,000 to 200,000.", "2": "A grandparent is not in the listed order and shares fewer genes than an identical twin, so the match is poorer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0529' AND answer = 3;
UPDATE questions SET why = 'Transplant rejection happens when the recipient''s T cells attack the donated organ. One approach uses monoclonal antibodies to destroy the T cells that attack the transplant. Another uses stem cells to build a new immune system that sees the organ as self.', wrong = '{"0": "Injecting allergen extracts to make G-antibodies is desensitization, a treatment for allergies.", "2": "Raising body temperature with pyrogens causes fever. It does not stop the immune system attacking the organ.", "3": "Antihistamine drugs block histamine and relieve allergy symptoms. They do not prevent transplant rejection."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0530' AND answer = 1;
UPDATE questions SET why = 'Testing every member of a population is often impractical or too costly. Biostatistical analysis lets researchers study a representative sample and use that data to make decisions about the whole population. For example, a subset of workers can show how common a health condition is among all workers.', wrong = '{"1": "The main point of biostatistics is to avoid testing everyone, by studying a sample instead.", "2": "Statistics always needs data to analyse. It cannot draw conclusions without any data.", "3": "Biostatistics helps people make informed decisions. It does not cure diseases directly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0531' AND answer = 0;
UPDATE questions SET why = 'Study design and experimental planning comes before any data are collected. It includes forming the research question, setting objectives, selecting the population and defining variables. It also covers randomization, controlling confounding factors and calculating an adequate sample size.', wrong = '{"0": "Data management and processing means organizing, cleaning, coding and storing data after it is collected.", "1": "Presentation and communication means sharing results using charts, graphs and clear language.", "3": "Interpretation of results means turning statistical findings into meaningful biological or health conclusions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0532' AND answer = 2;
UPDATE questions SET why = 'After data are collected, they must be organized and checked for accuracy before analysis. This component is data management and processing. It includes data cleaning, coding and storage, while keeping the data confidential and intact.', wrong = '{"0": "Data collection is gathering primary data (experiments, surveys) or secondary data (records, reports).", "1": "Study design is the planning stage before any data exist, such as choosing the sample and variables.", "2": "Data analysis applies statistical techniques to cleaned data to summarize it and draw inferences."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0533' AND answer = 3;
UPDATE questions SET why = 'Descriptive statistics only describe the data, using measures such as the mean, median, mode and standard deviation. Inferential statistics use sample data to draw conclusions about a whole population. Hypothesis testing, regression and modelling are inferential.', wrong = '{"0": "The mean summarizes the centre of the data, so it is a descriptive statistic.", "2": "The mode gives the most frequent value in the data, so it is a descriptive statistic.", "3": "The standard deviation describes how spread out the data are, so it is a descriptive statistic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0534' AND answer = 1;
UPDATE questions SET why = 'Genetics and genomics uses biostatistics to analyse complex genetic data. It links genes with diseases and studies inheritance and genetic variation. Personalized medicine, where treatment is tailored to a person''s genetic profile, is part of this application.', wrong = '{"0": "Environmental health uses biostatistics to study how pollution and toxins affect human health.", "1": "Healthcare quality control uses biostatistics to check test accuracy and track patient outcomes.", "3": "Identifying barriers to care uses biostatistics to study access to health services and reduce inequality."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0535' AND answer = 2;
UPDATE questions SET why = 'Epidemiology is the study of the distribution and determinants of diseases within populations. It uses biostatistics to understand how diseases spread and to identify risk factors. It also judges how well preventive measures work.', wrong = '{"0": "Bioinformatics uses computers and statistics to analyse large genomic and proteomic datasets.", "1": "Pharmacology is the study of drugs and how they act on the body.", "2": "Demography studies population trends such as births and deaths, not specifically the causes of disease."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0536' AND answer = 3;
UPDATE questions SET why = 'The mean is the sum of the values divided by the number of values: mean = Σx ÷ n. Here Σx = 12 + 15 + 18 + 21 + 24 = 90 and n = 5. So the mean = 90 ÷ 5 = 18 cm. Quick check: the values rise evenly by 3 cm, so the mean equals the middle value, 18.', wrong = '{"0": "15 cm is just the second value in the list. It is not the sum divided by the number of values.", "2": "21 cm is just the fourth value in the list. The mean works out to 90 ÷ 5 = 18 cm.", "3": "90 cm is the sum of the lengths. It still has to be divided by n = 5 to give the mean."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0537' AND answer = 1;
UPDATE questions SET why = 'For grouped data, mean = Σfx ÷ Σf, where x is each class midpoint. The midpoints are 5, 15 and 25, so Σfx = (2 × 5) + (5 × 15) + (3 × 25) = 10 + 75 + 75 = 160. Σf = 2 + 5 + 3 = 10, so the mean = 160 ÷ 10 = 16.', wrong = '{"1": "15 is the midpoint of the middle class. It ignores the different frequencies of the classes.", "2": "20 does not come from Σfx ÷ Σf. The weighted calculation gives 160 ÷ 10 = 16.", "3": "160 is Σfx, the total before dividing by Σf = 10."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0538' AND answer = 0;
UPDATE questions SET why = 'In grouped data, each class is represented by its midpoint, x. The midpoint = (lower limit + upper limit) ÷ 2. For the class 30–40, x = (30 + 40) ÷ 2 = 35, and this value is multiplied by the class frequency f to find Σfx.', wrong = '{"0": "30 is the lower limit of the class, not its midpoint.", "1": "40 is the upper limit of the class, not its midpoint.", "2": "10 is the class width (40 − 30), not the midpoint."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0539' AND answer = 3;
UPDATE questions SET why = 'To find the median, first arrange the values in order: 3, 5, 7, 9, 11. There are n = 5 values, an odd number, so the median is the middle value at position (n + 1) ÷ 2 = 3. The third value is 7.', wrong = '{"0": "9 is the fourth value in the ordered list, not the middle one.", "2": "5 is the second value in the ordered list, not the middle one.", "3": "35 is the sum of the five values. The sum is used for the mean, not the median."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0540' AND answer = 1;
UPDATE questions SET why = 'Arrange the values in order: 12, 16, 18, 20, 24, 30. There are n = 6 values, an even number, so the median is the average of the 3rd and 4th values. Median = (18 + 20) ÷ 2 = 19.', wrong = '{"1": "18 is only the 3rd value. With an even number of values, it must be averaged with the 4th value, 20.", "2": "20 is only the 4th value. With an even number of values, it must be averaged with the 3rd value, 18.", "3": "16 is the 3rd value of the unordered list. The values must first be arranged in order."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0541' AND answer = 0;
UPDATE questions SET why = 'The median is the middle value of ordered data, so a few extreme values do not pull it much. Many biological data, such as population size, disease prevalence and body measurements, are not normally distributed. For such skewed data the median shows the centre better than the mean.', wrong = '{"0": "With only one value there is nothing to compare, so no measure of central tendency is needed.", "1": "For perfectly symmetrical data the mean and median are the same, so the median has no special advantage.", "3": "Whether data are grouped into classes is not the reason the median is preferred. Skewness is."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0542' AND answer = 2;
UPDATE questions SET why = 'The mode is the value that appears most often in a dataset. In 4, 6, 6, 7, 8, 8, 8, 9, the value 8 appears three times. No other value appears that often, so the mode is 8.', wrong = '{"0": "6 appears only twice, while 8 appears three times.", "1": "7 appears only once in the data, so it is not the most frequent value.", "2": "7.5 is the median of these eight values, (7 + 8) ÷ 2. It is not the most frequent value."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0543' AND answer = 3;
UPDATE questions SET why = 'The mode is the value or values that appear most often. In 3, 3, 5, 7, 7, 9, both 3 and 7 appear twice, and every other value appears once. So the data have two modes, 3 and 7 (bimodal).', wrong = '{"0": "5 appears only once, so it cannot be the mode. 3 and 7 each appear twice.", "1": "3 appears just as often as 7, so 7 is not the only mode.", "3": "A mode must be a value that actually occurs in the data. 5.5 does not occur."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0544' AND answer = 2;
UPDATE questions SET why = 'The modal class is 20–30, with the highest frequency. So l = 20, fm = 16, f1 = 10 (class before), f2 = 8 (class after) and h = 10. Mode = 20 + [(16 − 10) ÷ ((16 − 10) + (16 − 8))] × 10 = 20 + (6 ÷ 14) × 10 = 20 + 4.29 = 24.29.', wrong = '{"0": "25 is just the midpoint of the modal class. The formula shifts the mode toward the larger neighbouring frequency.", "2": "20 is only the lower boundary, l. The fraction × h must still be added to it.", "3": "26.67 does not come from the formula with these values. Correct substitution gives 20 + (6 ÷ 14) × 10 = 24.29."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0545' AND answer = 1;
UPDATE questions SET why = 'The deviations from the mean (5) are −3, −1, −1, −1, 0, 0, 2 and 4. Their squares are 9, 1, 1, 1, 0, 0, 4 and 16, which add up to 32. Variance = 32 ÷ 8 = 4, so the standard deviation = √4 = 2.', wrong = '{"1": "4 is the variance. The standard deviation is its square root, √4 = 2.", "2": "32 is the sum of the squared deviations. It must be divided by N = 8 and then square-rooted.", "3": "5 is the mean of the values, not a measure of how spread out they are."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0546' AND answer = 0;
UPDATE questions SET why = 'The standard deviation measures how spread out values are around the mean. A small standard deviation means the values lie close to the mean. Sample X (1 cm) has heights clustered much more tightly around the mean than sample Y (8 cm).', wrong = '{"1": "The two samples have the same mean height, so X is not taller on average.", "2": "The standard deviation shows spread, not the number of plants in a sample.", "3": "Values tightly clustered around the mean usually give a smaller range, not a larger one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0547' AND answer = 0;
UPDATE questions SET why = 'Some deviations from the mean are positive and some negative, and they would cancel out if simply added. Squaring makes every deviation positive and gives more weight to large deviations. At the end the square root is taken to return to the original units.', wrong = '{"0": "Squaring has nothing to do with percentages. It removes negative signs.", "2": "The median is found by ordering the data. Squaring deviations is part of the standard deviation.", "3": "Squaring does not make deviations equal. It makes large deviations count even more."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0548' AND answer = 1;
UPDATE questions SET why = 'The variance is the average of the squared deviations from the mean. Its units are squared, so the standard deviation is found by taking its square root: SD = √variance. For example, a variance of 87.11 gives SD = √87.11 ≈ 9.33.', wrong = '{"0": "Multiplying the variance by N gives back the sum of squared deviations, not the standard deviation.", "1": "Halving the variance has no statistical meaning here. The standard deviation is its square root.", "2": "Squaring the variance goes the wrong way. The standard deviation is the square root of the variance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0549' AND answer = 3;
UPDATE questions SET why = 'The range is the difference between the largest and smallest values: range = maximum − minimum. Here the maximum is 39.1 °C and the minimum is 36.9 °C. So the range = 39.1 − 36.9 = 2.2 °C.', wrong = '{"0": "1.3 °C is 39.1 − 37.8, but 37.8 is not the lowest value. The minimum is 36.9 °C.", "1": "0.6 °C is 37.8 − 37.2, and neither of these is an extreme value.", "3": "37.9 °C is the mean of the five temperatures (189.5 ÷ 5), not the range."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0550' AND answer = 2;
UPDATE questions SET why = 'The range is found as Xmax − Xmin, so it uses only the two extreme values. All the values in between are ignored. A single unusually high or low value can therefore change the range a lot.', wrong = '{"0": "Using every value is a strength of the standard deviation, not the range.", "2": "The range can be found for any dataset with two or more values, however small.", "3": "The range is zero only when all the values are equal, which is rare in biological data."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0551' AND answer = 1;
UPDATE questions SET why = 'A percentile is the value below which a given percentage of the data lies. The 25th percentile is the first quartile (Q1), the 50th is the median, and the 75th is the third quartile (Q3). So the 75th percentile is Q3, with 75% of the data below it.', wrong = '{"0": "The first quartile (Q1) is the 25th percentile, with only 25% of the data below it.", "1": "The median is the 50th percentile, the middle value of the ordered data.", "2": "The mode is the most frequent value. It is not a percentile."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0552' AND answer = 3;
UPDATE questions SET why = 'The rank of a percentile is R = (P ÷ 100) × (n + 1). Here P = 25 and n = 19, so R = 0.25 × (19 + 1) = 0.25 × 20 = 5. Since R is a whole number, the 25th percentile is the 5th value in the ordered data.', wrong = '{"1": "4.75 comes from multiplying 0.25 by n = 19 instead of by n + 1 = 20.", "2": "25 is P, the desired percentile. It has to be put into the formula to find the rank.", "3": "20 is n + 1. It must still be multiplied by P ÷ 100 = 0.25."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0553' AND answer = 0;
UPDATE questions SET why = 'Here n = 8, so R = (30 ÷ 100) × (8 + 1) = 0.3 × 9 = 2.7. This lies between the 2nd value (4) and the 3rd value (6). By interpolation, the percentile = 4 + 0.7 × (6 − 4) = 4 + 1.4 = 5.4.', wrong = '{"0": "4 is the 2nd value. Since the rank 2.7 is not a whole number, interpolation toward the 3rd value is needed.", "1": "6 is the 3rd value. The rank 2.7 lies below it, between the 2nd and 3rd values.", "3": "2.7 is the rank, the position in the data, not the percentile value itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0554' AND answer = 2;
UPDATE questions SET why = 'In a bar chart, the categories being compared go on the horizontal x-axis. The values or counts go on the vertical y-axis. So the insect species are on the x-axis and the number of individuals counted is on the y-axis.', wrong = '{"1": "This reverses the standard layout described. Categories go on the x-axis and counts on the y-axis.", "2": "A bar chart is drawn with axes; a legend only explains colours or patterns.", "3": "Sectors of a circle are used in pie charts, not in bar charts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0555' AND answer = 0;
UPDATE questions SET why = 'In a bar chart, only the height (or length) of each bar shows its value. So all bars must have equal width and be evenly spaced. Otherwise a wider bar would look bigger and mislead the reader.', wrong = '{"0": "Bar width must not carry any information. Making bars wider for larger values would exaggerate differences.", "2": "Bars arranged in a circle are not a bar chart. Bars stand along an axis, separated by equal gaps.", "3": "Random widths would make some bars look more important than others and mislead the reader."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0556' AND answer = 1;
UPDATE questions SET why = 'A legend is a key on a chart, graph or map. It explains what each symbol, colour, pattern or label stands for. For example, in a bar chart with different colours, the legend shows which colour belongs to which category.', wrong = '{"0": "An axis title names what is shown along an axis, such as \"Insect species\". It does not explain colours.", "1": "Error bars show the variability or uncertainty in the data around each bar.", "3": "A class interval is a range used to group data, such as 10–20. It is not a key on a chart."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0557' AND answer = 2;
UPDATE questions SET why = 'A whole pie chart is 360°, and each sector''s angle is proportional to its share. Sector angle = (frequency ÷ total) × 360°. For group B, angle = (60 ÷ 240) × 360° = 0.25 × 360° = 90°.', wrong = '{"0": "60 is the number of students with group B. It must be converted to a share of 360°.", "1": "25 is the percentage of students with group B (60 ÷ 240 × 100). The angle is 25% of 360°, which is 90°.", "2": "144° would be 40% of the circle, which would mean 96 students, not 60."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0558' AND answer = 3;
UPDATE questions SET why = 'The whole circle of a pie chart is 360°, which stands for 100%. Percentage = (angle ÷ 360°) × 100. So a 54° sector represents (54 ÷ 360) × 100 = 15% of the whole. Quick check: 10% of the circle is 36°, so 54° is one and a half times that.', wrong = '{"0": "The angle in degrees is not the same as the percentage, because the circle is 360°, not 100.", "2": "5.4% is ten times too small. The correct value is 54 ÷ 360 × 100 = 15%.", "3": "30% of the circle would need a sector of 0.30 × 360° = 108°, twice 54°."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0559' AND answer = 1;
UPDATE questions SET why = 'A pie chart is a circle divided into sectors, with the whole circle standing for 100%. Each sector shows one category''s share of the whole. So it is the best choice for showing how a cell population is divided among four cell types.', wrong = '{"0": "A line on an x-axis figure shows how something changes with an independent variable such as time or temperature.", "1": "A bar chart with error bars compares group means and their variability. It does not show parts of 100%.", "3": "A scatter of individual measurements shows spread or relationships, not shares of a whole."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0560' AND answer = 2;
UPDATE questions SET why = 'The independent variable is the factor the experimenter changes, and it is usually plotted on the x-axis. Here temperature is chosen and changed by the experimenter. Enzyme activity is the measured result, the dependent variable, so it goes on the y-axis.', wrong = '{"0": "The dependent variable is enzyme activity, the thing being measured. It goes on the y-axis.", "1": "Control variables, such as pH or enzyme concentration, are kept constant and are not plotted.", "2": "A legend is a key explaining colours or symbols. It is not a variable."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0561' AND answer = 3;
UPDATE questions SET why = 'Range error bars use the smallest and largest values in each group. Each bar extends from the minimum to the maximum value. This shows the full spread of the data for that group.', wrong = '{"1": "Extending one standard deviation above and below the mean describes standard deviation (SD) error bars.", "2": "The bar itself runs from zero up to the mean. Error bars are drawn on top of it.", "3": "Error bars do not run between the mode and the median. They show range or standard deviation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0562' AND answer = 0;
UPDATE questions SET why = 'A ±1 SD error bar extends one standard deviation above and below the mean. Here the mean is 15 cm and the SD is 2 cm. So the bar runs from 15 − 2 = 13 cm to 15 + 2 = 17 cm.', wrong = '{"0": "14 to 16 cm uses ±1 cm. The standard deviation is 2 cm, not 1 cm.", "1": "15 to 17 cm extends only upward. An SD error bar extends both above and below the mean.", "2": "11 to 19 cm is the mean ± 4 cm, which is ±2 SD, not ±1 SD."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0563' AND answer = 3;
UPDATE questions SET why = 'The range is the largest value minus the smallest: 12 − 8 = 4 cm. The range error is half of the range, written as ± around the mean. So the range error = 4 ÷ 2 = ±2 cm, and the bar spans 8 to 12 cm around the mean of 10 cm.', wrong = '{"0": "4 cm is the whole range. The range error is half of it, ±2 cm.", "1": "10 cm is the mean of the three heights, (8 + 12 + 10) ÷ 3. It is not the range error.", "3": "±1 cm would be a quarter of the range. Half of the range of 4 cm is 2 cm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0564' AND answer = 2;
UPDATE questions SET why = 'The independent variable is what the experimenter changes, here the fertilizer concentration. The dependent variable is what is measured and changes in response. So the number of leaves on the bean plants is the dependent variable.', wrong = '{"0": "Fertilizer concentration is changed by the students, so it is the independent variable.", "2": "The type of pot is kept the same for all plants, so it is a control variable.", "3": "Plants given no fertilizer form the control group, a baseline for comparison, not a variable."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0565' AND answer = 1;
UPDATE questions SET why = 'Control variables are all the other factors that must be kept the same in every group, so the test is fair. In the high-fat diet experiment these include the age, strain and sex of the mice, the cage, light, temperature and feeding schedule. So the age of the mice is a control variable.', wrong = '{"1": "The type of diet is the factor being changed, so it is the independent variable.", "2": "Weight gain is what is measured, so it is the dependent variable.", "3": "The mice fed the high-fat diet are the experimental group. A group is not a variable."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0566' AND answer = 0;
UPDATE questions SET why = 'Random assignment means each mouse has an equal chance of going into either group. This avoids putting, for example, heavier or more active mice in one group by choice. So the groups are comparable and bias is reduced, and any difference can be linked to the diet.', wrong = '{"1": "Randomization does not decide the result. It only makes the comparison between groups fair.", "2": "A control group (normal diet) is still needed as a baseline for comparison.", "3": "The dependent variable, weight gain, is what is measured and is expected to change."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0567' AND answer = 0;
UPDATE questions SET why = 'The steps of experimental design are: state the question, formulate a hypothesis, identify the variables, set up control and experimental groups, plan the procedure, analyse results and draw conclusions. So formulating a hypothesis comes right after stating the question.', wrong = '{"0": "Drawing conclusions is the last step, done after the results are analysed.", "1": "Analysing results comes near the end, after the experiment has been carried out.", "2": "Setting up groups comes after the hypothesis and after the variables are identified."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0568' AND answer = 3;
UPDATE questions SET why = 'A hypothesis is accepted or rejected on the basis of the results. The hypothesis predicted that high-fat mice would gain more weight. If there is no significant difference between the groups, the prediction is not met, so the hypothesis is rejected.', wrong = '{"0": "The hypothesis would be supported only if the high-fat group showed a significant increase in weight gain.", "1": "A result showing no significant difference cannot prove the hypothesis true.", "3": "The results are exactly what decide whether a hypothesis is accepted or rejected."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0569' AND answer = 2;
UPDATE questions SET why = 'Drugs can come from plants, animals and microorganisms, or be made in laboratories. Medicines prepared from plants and used in traditional systems of treatment are called herbal medicines. This form of treatment is also known as phytotherapy.', wrong = '{"1": "Antibiotics are drugs that kill bacteria or stop their growth. They are defined by their action, not by coming from plants.", "2": "Monoclonal antibodies are produced artificially in laboratories from hybridoma cells, not from plants.", "3": "Antiretrovirals are drugs that treat infections by retroviruses such as HIV."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0570' AND answer = 0;
UPDATE questions SET why = 'Drug discovery has four stages: target identification, target validation, lead compound identification and lead optimization. In target validation, researchers confirm that the chosen target is important in the disease. Experiments check that acting on it produces a therapeutic effect.', wrong = '{"0": "Target identification only picks a molecule, such as a protein or enzyme, involved in the disease.", "2": "Lead optimization modifies promising compounds to improve them. It comes after validation.", "3": "Post-marketing surveillance is the monitoring of a drug after it is sold to the public."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0571' AND answer = 1;
UPDATE questions SET why = 'In lead compound identification, scientists screen thousands of natural or synthetic compounds. The promising substances that interact effectively with the target molecule are called lead compounds. They are later modified in lead optimization.', wrong = '{"0": "The target molecule is the disease-related protein or enzyme itself, not the compounds tested against it.", "1": "A placebo is an inactive substance given to compare with a real treatment.", "3": "Hybridomas are fused cells that produce monoclonal antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0572' AND answer = 2;
UPDATE questions SET why = 'Lead optimization is the last stage of drug discovery. The lead compounds are chemically modified to make them more effective and less toxic. Their drug-like properties are also improved before testing begins.', wrong = '{"0": "Testing in thousands of patients is a Phase 3 clinical trial, part of drug development.", "1": "Monitoring rare side effects after sale is post-marketing surveillance.", "2": "Choosing a disease-causing protein to target is target identification, the first stage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0573' AND answer = 3;
UPDATE questions SET why = 'Preclinical research is the first stage of drug development. Compounds are tested in vitro on cell cultures and in vivo in animals. This measures safety, toxicity and efficacy before any human trial.', wrong = '{"0": "A Phase 1 clinical trial is the first test in humans, carried out after preclinical research.", "1": "FDA drug review is when regulators examine all the trial data to approve or reject a drug.", "3": "Lead compound identification is a drug discovery step that screens compounds against a target."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0574' AND answer = 2;
UPDATE questions SET why = 'Phase 1 is the first test of a new drug in humans. It uses a small group of 20 to 100 healthy volunteers. Its main aim is to find out whether the drug is safe and what dose to use.', wrong = '{"0": "1,000 to 3,000 patients take part in Phase 3 trials, which confirm efficacy on a large scale.", "2": "Testing in laboratory animals is preclinical research, done before human trials.", "3": "Monitoring the general public after the drug is sold is post-marketing surveillance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0575' AND answer = 1;
UPDATE questions SET why = 'Clinical trials have three phases. Phase 1 uses 20 to 100 healthy volunteers, and Phase 2 uses 100 to 300 patients. Phase 3 is large-scale, with about 1,000 to 3,000 patients, and confirms efficacy while monitoring adverse reactions.', wrong = '{"1": "Phase 1 trials are small, with 20 to 100 healthy volunteers, and mainly test safety and dosage.", "2": "Preclinical trials are done on cell cultures and animals, not on patients.", "3": "Lead optimization is a drug discovery step that improves compounds before any testing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0576' AND answer = 0;
UPDATE questions SET why = 'Clinical trials involve at most a few thousand people, so very rare or long-term side effects may not appear. After a drug is released, it is monitored continuously in the whole population. This post-marketing surveillance detects such effects.', wrong = '{"0": "Target validation happens before any drug compound has even been found.", "1": "Phase 1 trials use only 20 to 100 people, too few to reveal rare side effects.", "2": "Preclinical research is done on cells and animals before the drug is ever used in humans."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0577' AND answer = 3;
UPDATE questions SET why = 'Penicillin is a group of bactericidal antibiotics obtained from Penicillium fungi. It was discovered by Alexander Fleming in 1928. It is highly effective against Gram-positive bacteria such as streptococci and staphylococci.', wrong = '{"0": "Gerhard Domagk discovered sulfanilamide, the parent of the sulfonamides, in 1932.", "1": "George Lesher discovered the fluoroquinolones in 1962.", "2": "Cesar Milstein shared the 1984 Nobel Prize for producing monoclonal antibodies."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0578' AND answer = 3;
UPDATE questions SET why = 'The bacterial cell wall is made of peptidoglycan (murein) chains joined by cross-links. Penicillin blocks this cross-linking, so new cell wall cannot be built. The weakened wall cannot hold the cell together, and the bacterium bursts (lysis).', wrong = '{"0": "Binding to the 30S ribosomal subunit is how tetracycline blocks bacterial protein synthesis.", "2": "Inhibiting DNA gyrase is how fluoroquinolones stop bacterial DNA replication.", "3": "Blocking folate synthesis is how sulfonamides stop bacterial growth."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0579' AND answer = 1;
UPDATE questions SET why = 'Penicillin works by stopping the cross-linking of peptidoglycan in bacterial cell walls. Animal cells, including human cells, have no cell walls. So penicillin has nothing to act on in human cells and harms only bacteria.', wrong = '{"1": "Beta-lactamases are enzymes made by some resistant bacteria to destroy penicillin. Human cells do not make them.", "2": "Human cytoplasmic ribosomes are 80S, and penicillin does not act on ribosomes anyway.", "3": "Human cells do take up penicillin. It is harmless because they have no cell wall to attack."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0580' AND answer = 0;
UPDATE questions SET why = 'Some bacteria resist penicillin by producing enzymes called beta-lactamases. These enzymes break down the penicillin molecule before it can block cell-wall synthesis. So the antibiotic no longer works against those bacteria.', wrong = '{"0": "Reverse transcriptase is an enzyme of retroviruses such as HIV, used to copy RNA into DNA.", "1": "DNA gyrase is a bacterial enzyme in DNA replication and is the target of fluoroquinolones.", "3": "Lysozyme is an enzyme in tears and sweat that digests bacterial cell walls. It does not protect bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0581' AND answer = 2;
UPDATE questions SET why = 'Tetracycline enters bacterial cells and binds reversibly to the 30S subunit of the ribosome. This stops aminoacyl-tRNA from binding to the acceptor (A) site. So translation is blocked and the bacteria cannot make proteins.', wrong = '{"1": "Breaking bacterial DNA strands is the action of fluoroquinolones.", "2": "Blocking cell-wall cross-links is the action of penicillin.", "3": "Inhibiting folic acid synthesis is the action of sulfonamides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0582' AND answer = 0;
UPDATE questions SET why = 'Tetracycline is bacteriostatic: it stops bacteria from growing and multiplying rather than killing them outright. It acts on both Gram-positive and Gram-negative bacteria. It comes from soil bacteria of the genus Streptomyces.', wrong = '{"0": "Tetracycline is bacteriostatic, not bactericidal, and it acts on both Gram-positive and Gram-negative bacteria.", "1": "Tetracycline should not be taken with dairy products or iron supplements, which reduce its absorption.", "2": "Tetracycline comes from Streptomyces bacteria. The bark of the Cinchona tree gives quinine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0583' AND answer = 3;
UPDATE questions SET why = 'Common side effects of tetracycline are nausea, vomiting, diarrhoea and sensitivity to sunlight. Penicillin''s common side effects include nausea, vomiting, diarrhoea, abdominal pain and skin rashes. So sun sensitivity is listed for tetracycline but not for penicillin.', wrong = '{"0": "Nausea is listed as a side effect of both penicillin and tetracycline.", "2": "Diarrhoea is listed as a side effect of both penicillin and tetracycline.", "3": "Vomiting is listed as a side effect of both penicillin and tetracycline."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0584' AND answer = 1;
UPDATE questions SET why = 'Fluoroquinolones enter bacteria and inhibit their type II topoisomerases, enzymes that manage DNA coiling during replication. The drug traps these enzymes on the DNA, forming a complex that causes double-strand breaks. The bacteria cannot multiply and die, so fluoroquinolones are bactericidal.', wrong = '{"0": "Blocking peptidoglycan cross-links is how penicillin kills bacteria.", "1": "Binding the 30S ribosomal subunit is how tetracycline stops protein synthesis.", "3": "Competing with PABA (para-aminobenzoic acid) in folate synthesis is how sulfonamides act."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0585' AND answer = 2;
UPDATE questions SET why = 'Fluoroquinolones inhibit two type II topoisomerases. In Gram-negative bacteria the main target is DNA gyrase, which uncoils DNA during replication. In Gram-positive bacteria the main target is topoisomerase IV, which separates replicated DNA.', wrong = '{"1": "Topoisomerase IV is the main target in Gram-positive bacteria, not Gram-negative ones.", "2": "Fluoroquinolones do not act on ribosomes. They target DNA replication enzymes.", "3": "Fluoroquinolones do not target outer membrane lipids. They act on topoisomerases inside the cell."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0586' AND answer = 0;
UPDATE questions SET why = 'Fluoroquinolones are useful bactericidal drugs, but they have some rare and serious adverse effects. These include tendon rupture, peripheral neuropathy (nerve damage) and heart problems. Drug resistance is also a concern.', wrong = '{"0": "Hair loss is not listed as an adverse effect of fluoroquinolones.", "1": "Night blindness is linked to vitamin A deficiency, not to fluoroquinolones.", "3": "Tooth decay is not listed as an adverse effect of fluoroquinolones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0587' AND answer = 2;
UPDATE questions SET why = 'Folate (folic acid) is needed to make DNA. Bacteria must build folate themselves, but humans simply absorb it from food. Sulfonamides block the bacterial folate pathway, so they starve bacteria while leaving human cells unharmed.', wrong = '{"0": "Human cells do have ribosomes. Sulfonamides act on folate synthesis, not ribosomes.", "2": "Human cells also have DNA. The difference is that humans take in folate from food.", "3": "Human cells have no cell walls, and sulfonamides do not act on walls anyway."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0588' AND answer = 1;
UPDATE questions SET why = 'On their own, sulfonamides are bacteriostatic: they stop bacterial growth and let the immune system clear the infection. When combined with another drug such as trimethoprim, which also blocks the folate pathway, the effect becomes stronger. The combination is bactericidal and kills the bacteria.', wrong = '{"0": "Neither sulfonamides nor trimethoprim act on viruses; both are antibacterial.", "1": "Sulfonamides are broad-spectrum, acting on both Gram-positive and Gram-negative bacteria. The combination does not narrow this.", "2": "Combining the drugs does not turn them into penicillin. They remain separate drugs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0589' AND answer = 3;
UPDATE questions SET why = 'Bactericidal drugs kill bacteria. Penicillin does this by weakening the cell wall so the cell bursts, and fluoroquinolones by causing breaks in bacterial DNA. Tetracycline and sulfonamides on their own are bacteriostatic, stopping growth only.', wrong = '{"0": "Both tetracycline and sulfonamides are bacteriostatic. They stop growth rather than kill.", "1": "Penicillin is bactericidal, but tetracycline is bacteriostatic.", "2": "Fluoroquinolones are bactericidal, but sulfonamides on their own are bacteriostatic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0590' AND answer = 3;
UPDATE questions SET why = 'Antiviral drugs treat many viral infections, such as hepatitis, influenza and herpes. Antiretroviral drugs treat only infections by retroviruses, such as HIV. Since retroviruses are one group of viruses, all antiretrovirals are antivirals, but not all antivirals are antiretrovirals.', wrong = '{"0": "Many antivirals act on viruses that are not retroviruses, such as influenza and herpes viruses.", "2": "Antiretrovirals treat retroviral infections such as HIV, not bacterial infections.", "3": "Viruses have no cell walls, so antivirals cannot work by blocking cell-wall synthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0591' AND answer = 1;
UPDATE questions SET why = 'Retroviruses, such as HIV, have RNA as their genetic material. They use the enzyme reverse transcriptase to copy their RNA into DNA when they replicate. Antiretroviral drugs are designed to act against these viruses.', wrong = '{"0": "A peptidoglycan cell wall is a feature of bacteria. Viruses have no cell wall.", "1": "Needing folate from food is a feature of human cells. Viruses do not take in nutrients.", "3": "Viruses have no ribosomes of their own. 30S subunits are part of bacterial ribosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0592' AND answer = 2;
UPDATE questions SET why = 'Monoclonal antibodies are highly specific and bind to a single target. In cancer treatment they can be aimed at cancer cells, so healthy tissues suffer less damage. As a result they have lower toxicity and fewer side effects than conventional chemotherapy.', wrong = '{"1": "Killing all dividing cells is a drawback of conventional chemotherapy, not an advantage of monoclonals.", "2": "Each monoclonal antibody binds to one specific target, not to every antigen.", "3": "Monoclonal antibodies are not general drugs against all bacterial infections."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0593' AND answer = 0;
UPDATE questions SET why = 'Creationism, also called the theory of intelligent design, holds that all organisms were created as they exist today. Creationists claim each type of organism was created individually and has not changed through history. This is the opposite of evolution.', wrong = '{"0": "Spontaneous generation is the old idea that living things can arise from non-living matter.", "1": "Lamarckism is a theory of evolution, so it accepts that organisms change over time.", "2": "Neo-Darwinism combines Darwin''s natural selection with genetics. It describes change, not fixed forms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0594' AND answer = 3;
UPDATE questions SET why = 'Careful experiments showed that life does not arise from non-living matter, which disproved spontaneous generation. However, they said nothing about whether organisms were created in their present form. So they could not disprove creationism.', wrong = '{"0": "These experiments did show that new life comes only from existing life.", "1": "Rejecting the idea that life arises from non-living matter is exactly what these experiments did.", "3": "Disproving spontaneous generation was an important step in the progress of science."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0595' AND answer = 2;
UPDATE questions SET why = 'Evolution is the gradual change in the genetic makeup of a population over successive generations. In modern terms this is a change in allele frequencies. Over a long time it can lead to the formation of new species.', wrong = '{"0": "Growth during one organism''s lifetime is development. Individuals do not evolve; populations do.", "2": "Separate creation of each species is the idea of creationism, the opposite of evolution.", "3": "Life arising from non-living matter is the idea of spontaneous generation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0596' AND answer = 1;
UPDATE questions SET why = 'In 1831 Charles Darwin set out as a naturalist on a scientific expedition aboard HMS Beagle. The five-year voyage took him around the world, to tropical rainforests, fossil sites and the Galápagos Islands. His observations on this voyage shaped his theory of evolution.', wrong = '{"1": "Galápagos is the name of the group of islands Darwin visited, not the name of his ship.", "2": "HMS Endeavour was a different ship, linked with Captain Cook''s voyages. Darwin sailed on HMS Beagle.", "3": "HMS Victoria was not Darwin''s ship. His voyage was aboard HMS Beagle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0597' AND answer = 0;
UPDATE questions SET why = 'On the Galápagos Islands, Darwin noticed that plants and animals differed from island to island. Giant tortoises on one island had saddle-shaped shells, while those on another had dome-shaped shells. Such differences made him think about adaptation to local conditions.', wrong = '{"0": "All the tortoises had four legs. The difference Darwin noted was in shell shape.", "2": "Tortoises do not have wings on any island. The difference was in shell shape.", "3": "Tortoises are reptiles that breathe with lungs; none have gills. The difference was in shell shape."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0598' AND answer = 1;
UPDATE questions SET why = 'Darwin found different species of finches with different beak sizes and shapes on different islands. He concluded these were adaptations for feeding on different kinds of food. He linked such gradual adaptations to the origin of new species.', wrong = '{"1": "Beaks stretching during life and being passed on is a Lamarckian idea, not Darwin''s conclusion.", "2": "The beaks were not identical; they differed between islands and species.", "3": "Darwin related the beak shapes directly to the food available, so they were linked to the environment."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0599' AND answer = 0;
UPDATE questions SET why = 'Darwin noticed that many Galápagos plants and animals looked more like those of South America, the nearest mainland, than like those of other islands. This suggested they came from South American ancestors that later changed on the islands.', wrong = '{"0": "Galápagos species did not mainly resemble African ones. Africa is far away across the Atlantic.", "1": "Galápagos species did not mainly resemble Australian ones. The nearest mainland is South America.", "2": "Galápagos species did not mainly resemble European ones. The nearest mainland is South America."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0600' AND answer = 3;
UPDATE questions SET why = 'Charles Darwin (1809–1882) published his book "On the Origin of Species" in 1859. In it he proposed that evolution happens through natural selection acting on variations. This is the basis of the modern theory of evolution.', wrong = '{"0": "1831 is when Darwin began his voyage on HMS Beagle, 28 years before the book appeared.", "1": "1809 is the year Darwin was born, and also the year Lamarck published his book.", "3": "1908 is the year the Hardy-Weinberg theorem was presented."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0601' AND answer = 2;
UPDATE questions SET why = 'Darwin''s first point is overproduction: organisms can produce far more offspring than ever survive. A female sea star releases about a million eggs each season. If all survived and reproduced, sea stars would soon fill the oceans.', wrong = '{"1": "Inheritance of acquired characters is Lamarck''s idea, not a point of Darwin''s theory.", "2": "Gene flow is the movement of alleles when individuals migrate between populations.", "3": "Mutational equilibrium is when forward and back mutations balance. It has nothing to do with egg numbers."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0602' AND answer = 0;
UPDATE questions SET why = 'Because more offspring are produced than resources can support, individuals struggle to survive. Those with helpful variations survive and reproduce more successfully. Darwin called such helpful variations adaptive traits, and they are passed to the next generation.', wrong = '{"0": "Acquired characters are changes gained by use or disuse during life, in Lamarck''s theory.", "2": "Vestigial structures are remnants that have lost their use, such as the human appendix.", "3": "Analogous organs have the same function but different structure, such as bird and insect wings."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0603' AND answer = 1;
UPDATE questions SET why = 'Under natural selection, individuals with disadvantageous traits are less likely to survive and reproduce. So they pass these traits to fewer offspring. Over generations the traits become less frequent and are eventually eliminated.', wrong = '{"0": "Losing traits through disuse of organs is a Lamarckian idea, not natural selection.", "1": "Mutations keep happening. Harmful traits fall because their carriers reproduce less.", "3": "The environment does not edit DNA. It only affects which individuals survive and reproduce."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0604' AND answer = 2;
UPDATE questions SET why = 'In the early 20th century, Darwin''s theory was combined with modern genetics to form Neo-Darwinism. It defines evolution more precisely as a change in allele frequencies in a population''s gene pool. It is based on the Hardy-Weinberg theorem.', wrong = '{"0": "The endosymbiotic theory explains how eukaryotic cells arose from prokaryotes. It is not part of Neo-Darwinism.", "1": "Creationism holds that organisms were created in their present form, which rejects evolution.", "2": "Spontaneous generation, life arising from non-living matter, had already been disproved."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0605' AND answer = 3;
UPDATE questions SET why = 'The Hardy-Weinberg theorem was presented in 1908 by Godfrey Hardy, an English mathematician, and Wilhelm Weinberg, a German physician. It describes when allele and genotype frequencies stay constant in a population.', wrong = '{"0": "Darwin was the naturalist on the Beagle. The theorem was presented by a mathematician and a physician.", "1": "A French naturalist suggests Lamarck, who proposed use and disuse, not this theorem.", "2": "An American biologist who studied cells suggests Lynn Margulis, who proposed the endosymbiotic theory."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0606' AND answer = 3;
UPDATE questions SET why = 'The Hardy-Weinberg theorem says allele and genotype frequencies stay constant from generation to generation in a large, randomly mating population with no evolutionary forces. This means no migration, no net mutation and equal survival of all genotypes. If any condition fails, evolution occurs.', wrong = '{"1": "A small, isolated population is affected by genetic drift, so its frequencies change by chance.", "2": "Choosing mates of the same colour is non-random mating, which breaks the equilibrium.", "3": "New mutations each generation change allele frequencies, so the equilibrium is not kept."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0607' AND answer = 0;
UPDATE questions SET why = 'Allele frequency is the proportion of a specific allele among all the genes for that trait. Here 300 of the 1200 flower-colour genes are for white. So the frequency of the white allele = 300 ÷ 1200 = 0.25, or 25%.', wrong = '{"0": "0.30 comes from dividing 300 by 1000 instead of by the actual total of 1200.", "2": "0.75 is the frequency of the other allele (900 ÷ 1200), not of white.", "3": "0.40 does not follow from these numbers; it would need 480 white genes out of 1200."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0608' AND answer = 1;
UPDATE questions SET why = 'Genotype frequency is the proportion of individuals in a population with a particular genotype. Here 50 of the 250 plants are rr. So the genotype frequency of rr = 50 ÷ 250 = 0.2, or 20%.', wrong = '{"0": "0.5 would mean half the plants are rr, which is 125 plants, not 50.", "1": "0.25 comes from dividing 50 by the 200 plants that are not rr, instead of by all 250 plants.", "3": "0.05 is a quarter of the correct value. It would mean only about 12 or 13 rr plants out of 250."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0609' AND answer = 2;
UPDATE questions SET why = 'The gene pool is the total of all the genes for a trait in a population. For example, if a population has 1000 genes for flower colour, that is its gene pool for that trait. Evolution is a change in allele frequencies within the gene pool.', wrong = '{"0": "Genotype frequency is the proportion of individuals with a particular genotype, such as RR.", "1": "Allele frequency is the proportion of one particular allele in the gene pool, such as 0.6 for red.", "3": "A genome is all the DNA of a single organism, not the total genes for a trait in a population."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0610' AND answer = 2;
UPDATE questions SET why = 'Genetic drift is a change in allele frequencies caused by chance events, not by fitness. It is most obvious in small populations; for example, a fire may leave mostly brown rabbits just by luck. Drift is often called neutral selection and usually lowers genetic diversity.', wrong = '{"1": "Genetic drift usually reduces genetic diversity, because some alleles are lost by chance.", "2": "Genetic drift is most obvious in small populations, where chance events have a bigger effect.", "3": "Changes caused by migration of individuals are gene flow, not genetic drift."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0611' AND answer = 0;
UPDATE questions SET why = 'Gene flow is the change in gene frequencies caused by individuals moving into or out of a population. Immigrants can bring alleles that the population did not have before. As soon as they breed there, the gene frequencies change almost instantly.', wrong = '{"0": "Gene flow moves existing alleles between populations. It does not cause new mutations in the residents.", "1": "Gene flow is about migration, not about whether mating is random.", "2": "A sharp fall in population size leads to genetic drift, not gene flow."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0612' AND answer = 3;
UPDATE questions SET why = 'Mutational equilibrium exists when mutation from the wild-type allele to the mutant form is balanced by mutation from the mutant back to the wild type. The two changes cancel out. So allele frequencies stay the same as if no mutation occurred, though this rarely happens.', wrong = '{"0": "Equilibrium does not mean no mutations at all. It means forward and back mutations balance.", "2": "Mutations may be harmful, neutral or helpful. Mutational equilibrium is about balance, not harm.", "3": "Mutation pressure measures the tendency of gene frequencies to change by mutation. High pressure is not equilibrium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0613' AND answer = 1;
UPDATE questions SET why = 'Mutations are the origin of all new genes and alleles, so they are a source of variation. Most mutations are harmful, but some may help in a particular environment. Natural selection then acts on these variations, so mutations provide the raw material for evolution.', wrong = '{"0": "Most mutations are harmful. Only a few are neutral or helpful.", "1": "Mutations add new alleles, so they increase variation rather than reduce it.", "3": "Mutations occur in all populations, large or small."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0614' AND answer = 2;
UPDATE questions SET why = 'Biogeography shows that similar organisms can live in places separated by vast barriers. The African lion and the American mountain lion are alike, which suggests a common ancestor. Their clear differences come from millions of years of independent evolution on different continents.', wrong = '{"0": "Convergent evolution is when unrelated organisms come to look alike. These lions are explained by a shared ancestor.", "2": "Lamarckian use and disuse has been rejected. It is not how biogeography explains these lions.", "3": "The two lions are separated by oceans, so they are not the result of recent migration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0615' AND answer = 1;
UPDATE questions SET why = 'Islands are colonized by only a few organisms that manage to cross the sea. These colonists then evolve separately, cut off from the mainland. So islands often have relatively few species, but many of them are unique.', wrong = '{"1": "Separate creation of species on islands is not a scientific explanation. Biogeography explains it by colonization and evolution.", "2": "Constant gene flow from the mainland would make island species more like mainland ones, not unique.", "3": "Mutations occur everywhere, including on islands. Island species are unique because of isolation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0616' AND answer = 0;
UPDATE questions SET why = 'Homologous structures share a similar structure but are used for different functions. Vertebrate forelimbs have the same basic bone plan but are used for flying, swimming, running or climbing. This shows divergent evolution from a common ancestor.', wrong = '{"0": "Convergent evolution from different ancestors produces analogous structures, which share function but not structure.", "1": "Inheritance of acquired characters is Lamarck''s rejected idea. It does not explain homology.", "2": "Spontaneous generation is the old idea of life from non-living matter. It is unrelated to homology."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0617' AND answer = 3;
UPDATE questions SET why = 'Analogous organs have the same function but a different structure. Bird wings and insect wings are both used for flight, but they evolved from different ancestors. Their similarity simply reflects that flight needs a broad, flat surface; this is convergent evolution.', wrong = '{"1": "Having the same bones arranged differently describes homologous structures. Insect wings have no bones.", "2": "Both bird and insect wings are fully working organs used for flight, so they are not vestigial.", "3": "Birds and insects do not share a winged ancestor. Their wings evolved separately."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0618' AND answer = 0;
UPDATE questions SET why = 'Vestigial structures are remnants of organs that were useful in ancestors but have lost their function. Boa constrictors and pythons have tiny pelvic (hindlimb) bones left from their limbed reptilian ancestors. Such remnants are clear evidence of evolutionary change.', wrong = '{"0": "Analogous structures do the same job in unrelated organisms. These pelvic bones do no job.", "1": "Acquired characters are Lamarck''s idea of changes gained during life. These bones are inherited remnants.", "3": "Homologous biochemicals are similar molecules, such as DNA and proteins, in related organisms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0619' AND answer = 2;
UPDATE questions SET why = 'Humans have many vestigial structures that were useful in ancestors. The vermiform appendix is a vestige of the caecum, a pouch used by plant-eating ancestors. Other examples are the coccyx, wisdom teeth and ear muscles.', wrong = '{"0": "The coccyx (tailbone) is the vestige of the tail, not the appendix.", "2": "The third molars are themselves vestigial, as the wisdom teeth. They are not linked to the appendix.", "3": "Ear muscles are themselves vestigial structures. The appendix is not derived from them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0620' AND answer = 1;
UPDATE questions SET why = 'Related organisms have similar DNA and proteins, inherited from a common ancestor. Scientists compare the differences in these molecules. Assuming mutations build up at a fairly constant rate, the number of differences shows how long ago the two species shared an ancestor.', wrong = '{"0": "Vestigial organs show that change has occurred, but counting them cannot measure the time since divergence.", "1": "Body size varies for many reasons and cannot be used to estimate time since a common ancestor.", "2": "Measuring how much organs are used is linked to Lamarck''s idea and gives no timing information."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0621' AND answer = 3;
UPDATE questions SET why = 'A gene for antibiotic resistance can arise in bacteria by mutation. When the antibiotic is used, bacteria with this gene survive and reproduce while others die. Through natural selection the resistance gene is passed on, so later generations are resistant.', wrong = '{"0": "Bacteria cannot learn to avoid a drug and pass that on. This is a Lamarckian explanation.", "2": "The antibiotic does not create resistance genes. It only selects bacteria that already carry them.", "3": "Antibiotics do not stop mutations. Mutations keep occurring, and some give resistance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0622' AND answer = 1;
UPDATE questions SET why = 'The endosymbiotic theory was proposed by Lynn Margulis. It says large prokaryotes engulfed small ones, which were not digested but lived inside them. Over time the small prokaryotes became organelles such as mitochondria and chloroplasts.', wrong = '{"0": "Charles Darwin proposed evolution by natural selection, not the origin of eukaryotic cells.", "1": "Jean-Baptiste Lamarck proposed use and disuse and inheritance of acquired characters.", "3": "Alfred Wallace developed a theory of natural selection very similar to Darwin''s."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0623' AND answer = 2;
UPDATE questions SET why = 'The earliest organisms on Earth were prokaryotes, which arose about 3.5 billion years ago. Eukaryotes evolved from prokaryotes much later, about 2 billion years ago. So prokaryotes existed alone for about 1.5 billion years.', wrong = '{"0": "This reverses the order. Prokaryotes came first, about 3.5 billion years ago.", "1": "These figures are in millions of years. Both events happened billions of years ago.", "2": "1 billion and 500 million years ago are much too recent for these events."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0624' AND answer = 3;
UPDATE questions SET why = 'In the endosymbiotic theory, some small engulfed prokaryotes could carry out aerobic respiration. They supplied energy to themselves and to the large host cell. These became the mitochondria of eukaryotic cells.', wrong = '{"1": "Chloroplasts came from engulfed prokaryotes that could use sunlight to make food.", "2": "The nucleus is explained by the membrane invagination theory, where the cell membrane folded inward.", "3": "The endoplasmic reticulum is explained by the membrane invagination theory."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0625' AND answer = 0;
UPDATE questions SET why = 'Mitochondria reproduce by binary fission, the same way prokaryotes do. Eukaryotic cells divide by mitosis instead. Mitochondria are also about the size of prokaryotes and have their own circular DNA, all of which support the endosymbiotic theory.', wrong = '{"0": "Mitosis is how eukaryotic cells divide. Mitochondria divide by binary fission, like bacteria.", "1": "Mitochondria are about the same size as prokaryotic cells, not much larger.", "3": "Mitochondrial membranes are more like prokaryotic membranes than the eukaryotic plasma membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0626' AND answer = 2;
UPDATE questions SET why = 'The membrane invagination theory says the cell membrane of a prokaryote folded inward into the cytoplasm. These infoldings formed internal membranous structures. This explains the origin of the nucleus and the endoplasmic reticulum.', wrong = '{"0": "Mitochondria arising from engulfed aerobic bacteria is the endosymbiotic theory.", "2": "Chloroplasts arising from engulfed photosynthetic bacteria is the endosymbiotic theory.", "3": "Flagella from engulfed spirochete-like bacteria is also an endosymbiotic idea, not membrane invagination."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0627' AND answer = 1;
UPDATE questions SET why = 'Jean-Baptiste Lamarck (1744–1829) was a French naturalist and an early supporter of evolution. In 1809 he published "Philosophie Zoologique" (Zoological Philosophy). In it he proposed use and disuse of organs and inheritance of acquired characters.', wrong = '{"0": "\"On the Origin of Species\" was published by Charles Darwin in 1859.", "1": "\"Principles of Geology\" was written by the geologist Charles Lyell, not Lamarck.", "2": "\"Systema Naturae\" was written by Carolus Linnaeus and is about classification."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0628' AND answer = 3;
UPDATE questions SET why = 'Lamarck believed that organs used often become stronger and more developed, while unused organs become weak. He called such changes, gained through long-term use or disuse during life, acquired characters. He thought they were passed on to offspring.', wrong = '{"1": "Adaptive traits are Darwin''s idea: inherited genetic variations favoured by natural selection.", "2": "A homologous structure is one with the same basic structure in different species, not something gained by use.", "3": "Gene flow is the movement of alleles between populations by migration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0629' AND answer = 0;
UPDATE questions SET why = 'Lamarck explained the giraffe''s neck as follows. Ancestors stretched their necks to reach tall leaves, so their necks became longer during life, an acquired character. The key step is that this longer neck was passed on, so offspring were born with slightly longer necks.', wrong = '{"0": "Giraffes born with longer necks by mutation surviving better is the Darwinian explanation.", "1": "Migration of short-necked giraffes is not part of Lamarck''s account.", "2": "Changes by chance alone describe genetic drift, not Lamarck''s idea of inherited use."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0630' AND answer = 3;
UPDATE questions SET why = 'When the mechanism of inheritance was discovered, scientists found that acquired characters have no genetic basis. Changes in the body during life do not change the genes in gametes, so they cannot be inherited. Also, organs are not modified by an organism''s wish or need.', wrong = '{"0": "Lamarck supported the idea that evolution happens. His proposed mechanism was what proved wrong.", "2": "Genetic drift was not part of Lamarck''s theory; he relied on use and disuse.", "3": "Lamarckism was not based on molecular evidence, which came much later."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0631' AND answer = 1;
UPDATE questions SET why = 'In Lamarck''s time there was no evidence to explain how evolution could happen. So most scientists did not accept that species change at all. Lamarck was therefore criticized more for supporting the idea of evolutionary change than for the mechanism he proposed.', wrong = '{"1": "This reverses the point. In his own day, the idea of change itself drew more criticism than the mechanism.", "2": "The endosymbiotic theory was proposed much later by Lynn Margulis, not by Lamarck.", "3": "Mathematical errors are not mentioned as a reason for criticism of Lamarck."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0632' AND answer = 0;
UPDATE questions SET why = 'A species is a group of organisms with similar physical and genetic features that can interbreed to produce fertile offspring. It is the basic unit of biological classification. For example, Indus River dolphins can breed with each other but not with other dolphins.', wrong = '{"0": "A community is made of many different species living and interacting in one area.", "1": "A biome is a large geographical region with its own climate and typical plants and animals.", "2": "An ecosystem includes the community together with abiotic factors such as soil, water and sunlight."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0633' AND answer = 3;
UPDATE questions SET why = 'A population is a group of individuals of the same species living in the same area at the same time. So all the markhors in Chitral Gol National Park form one population. Markhors across all of Pakistan and beyond would be the species.', wrong = '{"0": "The species includes markhors everywhere. Those in one park are only one population of it.", "1": "A community would include all the other species living in the park, not only markhors.", "3": "A biome is a large climatic region, such as the coniferous forest biome, not one group of animals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0634' AND answer = 2;
UPDATE questions SET why = 'An ecosystem is made of the living (biotic) community together with the non-living (abiotic) factors. The Thar Desert includes snakes, blackbucks and shrubs, plus heat, shifting sand dunes and rare rainfall. Taken together, they form an ecosystem.', wrong = '{"1": "A population is a group of a single species, such as only the blackbucks.", "2": "A community is only the living part, the snakes, blackbucks and shrubs, without the abiotic factors.", "3": "A species is a single type of organism, not a whole desert with its living and non-living parts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0635' AND answer = 0;
UPDATE questions SET why = 'Energy enters an ecosystem as sunlight, passes along food chains, and is lost as heat. It is not reused, so energy flows in one direction. Nutrients such as carbon and nitrogen are recycled between living and non-living parts, so they cycle.', wrong = '{"0": "This reverses the two. Nutrients are recycled, while energy flows one way and is lost as heat.", "2": "Energy cannot be recycled; it is lost as heat at each step. Only nutrients cycle.", "3": "Both energy and nutrients move through an ecosystem, along food chains and through cycles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0636' AND answer = 1;
UPDATE questions SET why = 'The biosphere is the highest and most inclusive level of ecological organization. It is the sum of all the biomes on Earth. It includes every place where life exists, from deep sea trenches to high mountains and into the air.', wrong = '{"0": "A biome is one large region with a particular climate, such as a desert. The biosphere includes all biomes.", "1": "A community is all the populations living in one area, a much smaller level.", "3": "An ecosystem is a community and its abiotic surroundings in one area, not the whole Earth."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0637' AND answer = 2;
UPDATE questions SET why = 'A biome is a large region with its own climate and typical plants and animals. Murree and Swat are high-altitude areas with cold winters, dominated by pine trees. So they are examples of the coniferous forest biome in Pakistan.', wrong = '{"1": "The desert biome in Pakistan is found in the Thal and Thar regions, with low rainfall.", "2": "The freshwater biome in Pakistan includes the Indus River system.", "3": "Mangroves grow on the coast, such as near Karachi, not in cold hill areas."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0638' AND answer = 0;
UPDATE questions SET why = 'A primary reservoir is the large part of the biosphere where an element is stored for a long time. Biogeochemical cycles are classified by this reservoir. In gaseous cycles it is the air or the oceans, and in sedimentary cycles it is the Earth''s crust.', wrong = '{"0": "The speed of cycling is not the basis for this classification. The type of reservoir is.", "1": "The number of organisms involved is not used to classify these cycles.", "2": "Trophic levels describe feeding positions in energy flow, not the reservoirs of nutrient cycles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0639' AND answer = 3;
UPDATE questions SET why = 'Sedimentary cycles are those whose main reservoir is the Earth''s crust, in rocks and soil. The phosphorus cycle is one, along with the sulphur and calcium cycles. Phosphorus has no important gaseous form, so it moves slowly through rocks, soil and organisms.', wrong = '{"0": "The nitrogen cycle is a gaseous cycle, with the atmosphere as its main reservoir.", "2": "The water cycle is a gaseous cycle, with the oceans and air as its reservoir.", "3": "The carbon cycle is a gaseous cycle, with air and oceans as its main reservoir."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0640' AND answer = 1;
UPDATE questions SET why = 'The sun powers the whole water cycle. Solar radiation heats water in oceans and lakes, giving the molecules enough energy to evaporate. The vapour then rises, condenses into clouds and falls as precipitation.', wrong = '{"1": "Heat from the Earth''s core does not drive the water cycle. Sunlight does.", "2": "Lightning helps fix nitrogen in the nitrogen cycle. It does not power evaporation.", "3": "Decomposers release only small amounts of water from dead bodies. They do not drive the cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0641' AND answer = 0;
UPDATE questions SET why = 'Oceans cover most of the Earth''s surface and are heated by the sun. About 86% of global evaporation takes place from the oceans. For Pakistan, the Arabian Sea is the main source of water vapour that moves inland.', wrong = '{"0": "14% is the remaining share, roughly what evaporates from land and fresh water, not from the oceans.", "1": "50% is too low. The oceans supply most of the world''s evaporation, about 86%.", "3": "99% is too high. Some evaporation also happens from lakes, rivers, soil and plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0642' AND answer = 2;
UPDATE questions SET why = 'Infiltration, also called percolation, is the seeping of rain water into the soil. The water moves downward until it reaches the water table and is stored underground as groundwater, which refills aquifers used for drinking water.', wrong = '{"0": "Surface runoff is the flow of water over the land surface when the soil can take in no more. It feeds streams and rivers, not groundwater.", "1": "Transpiration is the loss of water vapour from leaves through stomata. It sends water up into the air, not down into the soil.", "2": "Condensation is cooling of water vapour into droplets or ice crystals that form clouds. It happens in the air, not in the soil."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0643' AND answer = 3;
UPDATE questions SET why = 'Water leaves living things in several ways, but transpiration in plants is the major exit point. Plants lose huge amounts of water vapour into the atmosphere through the stomata of their leaves, which returns water from the biotic part of the cycle to the air.', wrong = '{"0": "Animals do lose water in urine, but this is a minor route, and it returns water to soil or water bodies rather than mainly to the atmosphere.", "2": "Water lost in faeces (egestion) is a small amount and goes to the soil or water bodies, not mainly to the air.", "3": "Decomposition of dead bodies releases some water to soil or air, but it is a minor route compared with transpiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0644' AND answer = 1;
UPDATE questions SET why = 'Cellular respiration breaks down glucose and releases water as a by-product. This water, made inside the body by metabolism in both plants and animals, is called metabolic water, and part of it is exhaled as water vapour.', wrong = '{"0": "Groundwater is water stored underground below the water table after infiltration. It is not made by respiration.", "1": "Surface runoff is water flowing over the land into streams and rivers, not water produced inside cells.", "3": "Brackish water is a mix of fresh river water and salty seawater, as found in mangrove areas."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0645' AND answer = 2;
UPDATE questions SET why = 'Nitrogen makes up about 78% of the air as N₂, but its two atoms are joined by a very strong triple bond that plants cannot break. Nitrogen fixation must first convert N₂ into usable compounds such as ammonia (NH₃) before plants can use it.', wrong = '{"1": "N₂ is not scarce. It is about 78% of the atmosphere, the largest part of the air.", "2": "Nitrogen is a gas at room temperature, not a solid.", "3": "N₂ is not toxic to plant cells. It is simply too unreactive for them to use directly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0646' AND answer = 0;
UPDATE questions SET why = 'Biological fixation by soil microorganisms accounts for more than 90% of all nitrogen fixation. These include free-living fixers such as cyanobacteria, Azotobacter and Clostridium, and symbiotic Rhizobium in legume root nodules, all of which convert N₂ into ammonia.', wrong = '{"0": "Lightning fixes nitrogen by combining N₂ with oxygen, but it accounts for only about 5 to 10% of nitrogen fixation.", "2": "Industrial fixation makes fertilizer by combining N₂ with hydrogen to form ammonia. It is not the source of more than 90% of fixation.", "3": "Animals cannot fix nitrogen. They obtain nitrogen by eating plants or other animals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0647' AND answer = 1;
UPDATE questions SET why = 'Rhizobium is a mutualistic (symbiotic) bacterium that lives in the root nodules of legumes such as chickpea (chana) and mung bean (moong). It fixes N₂ into ammonia for the plant and receives food and shelter in return.', wrong = '{"0": "Azotobacter fixes nitrogen, but it is free-living in the soil, not inside root nodules.", "1": "Clostridium is also a free-living (non-symbiotic) nitrogen fixer, not a root nodule bacterium.", "2": "Nitrobacter is a nitrifying bacterium that converts nitrite to nitrate. It does not fix N₂."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0648' AND answer = 3;
UPDATE questions SET why = 'In atmospheric fixation, lightning during storms supplies the large energy needed to join nitrogen with oxygen. N₂ becomes nitrogen oxides and then nitrates, which reach the soil with rain. This route fixes only about 5 to 10% of nitrogen.', wrong = '{"0": "Bacteria in root nodules making ammonia is biological fixation, carried out by Rhizobium, not atmospheric fixation.", "2": "Combining nitrogen and hydrogen in factories to make ammonia is industrial fixation, used to produce fertilizers.", "3": "Decomposers breaking down proteins into ammonia is ammonification, the recycling step of the cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0649' AND answer = 1;
UPDATE questions SET why = 'Nitrification happens in two steps by soil bacteria. Nitrosomonas first oxidizes ammonia to nitrite (NO₂⁻), then Nitrobacter converts this nitrite to nitrate (NO₃⁻), the form plants absorb most easily.', wrong = '{"1": "Ammonia to nitrite is the first step of nitrification, carried out by Nitrosomonas, not Nitrobacter.", "2": "Nitrate to nitrogen gas is denitrification, done by bacteria such as Pseudomonas in waterlogged soils.", "3": "Nitrogen gas to ammonia is nitrogen fixation, done by microbes such as Rhizobium and Azotobacter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0650' AND answer = 0;
UPDATE questions SET why = 'When plants and animals die or animals release nitrogenous wastes, decomposers (fungi and bacteria) break down the complex proteins. They convert this organic nitrogen back into ammonia, a recycling step called ammonification.', wrong = '{"0": "Assimilation is the uptake of nitrates by plants and microbes to build proteins, DNA and chlorophyll, the opposite direction.", "1": "Nitrification converts ammonia into nitrite and then nitrate. It starts from ammonia rather than producing it.", "2": "Denitrification converts nitrates back into nitrogen gas, which returns to the atmosphere."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0651' AND answer = 3;
UPDATE questions SET why = 'Assimilation is the step in which plants and microbes absorb nitrates from the soil and use them to make proteins, DNA and chlorophyll. Nitrogen enters the living world this way, and animals then assimilate it by eating plants and other animals.', wrong = '{"0": "Ammonification is the breakdown of proteins in dead bodies and wastes into ammonia by decomposers.", "1": "Nitrogen fixation converts atmospheric N₂ into ammonia. It does not involve plants taking up nitrates.", "3": "Denitrification converts nitrates in the soil back into N₂ gas, removing nitrogen from the soil."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0652' AND answer = 2;
UPDATE questions SET why = 'Denitrifying bacteria such as Pseudomonas and Thiobacillus work in waterlogged soils, where oxygen is scarce. They convert nitrates back into nitrogen gas (N₂), which is released into the atmosphere and keeps the cycle balanced.', wrong = '{"0": "Well-aerated soils have plenty of oxygen, which favours nitrification. Denitrification needs oxygen-poor conditions.", "1": "Root nodules of legumes contain Rhizobium, which fixes N₂ into ammonia. That adds nitrogen to the soil rather than returning it to air.", "3": "Lightning during storms fixes nitrogen into nitrogen oxides and nitrates. It removes N₂ from the air rather than returning it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0653' AND answer = 2;
UPDATE questions SET why = 'Organisms are grouped into trophic (feeding) levels. Producers form level 1, and herbivores that feed directly on producers, such as rabbits and insects, are primary consumers at trophic level 2.', wrong = '{"0": "Trophic level 1 is the producers: green plants, algae and photosynthetic bacteria.", "1": "Trophic level 3 is secondary consumers (carnivores) such as frogs and snakes, which eat herbivores.", "2": "Trophic level 4 is tertiary consumers such as wolves and hawks, which eat carnivores."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0654' AND answer = 3;
UPDATE questions SET why = 'Decomposers and detritivores, such as crabs, vultures and jackals, feed on detritus (dead and decaying plant and animal material) and faecal matter. Because this material comes from every trophic level, they are placed in a separate level of their own.', wrong = '{"0": "Photosynthesis is done by producers at trophic level 1, not by decomposers and detritivores.", "2": "Feeding only on herbivores describes secondary consumers at trophic level 3.", "3": "Being eaten by tertiary consumers is not the basis for this grouping. Their separate level comes from feeding on dead matter from all levels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0655' AND answer = 1;
UPDATE questions SET why = 'Producers convert only about 1 to 2% of the solar energy falling on them into the bond energy of organic matter. The rest is reflected, passes through, or is lost as heat. After that, about 10% of energy passes from one trophic level to the next.', wrong = '{"1": "10% is the rough share of energy transferred from one trophic level to the next, not the share of sunlight fixed by producers.", "2": "50% is far too high. Producers capture only a tiny fraction of the sunlight that reaches them.", "3": "90% is far too high. In fact about 90% of energy is lost at each transfer between trophic levels."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0656' AND answer = 0;
UPDATE questions SET why = 'By the 10% rule, each trophic level passes only about one-tenth of its energy to the next. So 50,000 kcal in producers gives 5,000 kcal to primary consumers, 500 kcal to secondary consumers and 50 kcal to tertiary consumers.', wrong = '{"0": "500 kcal is what secondary consumers receive. It stops one step short of the tertiary level.", "2": "5,000 kcal is what primary consumers (herbivores) receive, only one transfer from the producers.", "3": "5 kcal would be reached after four transfers, at a fifth trophic level, one step beyond tertiary consumers."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0657' AND answer = 1;
UPDATE questions SET why = 'At every transfer from one trophic level to the next, most energy is lost as heat and only about 10% is passed on. A short food chain has fewer transfers, so less energy is wasted and a larger share of the producers'' energy reaches the top consumers.', wrong = '{"1": "Energy is never recycled in an ecosystem. Its flow is one-way (unidirectional), unlike the cycling of matter.", "2": "How much energy producers fix depends on sunlight and photosynthesis, not on how long the food chain is.", "3": "Decomposers are present in all ecosystems and feed on every trophic level, whatever the chain length."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0658' AND answer = 0;
UPDATE questions SET why = 'Demography is the statistical study of the characteristics of populations, such as their size, density, growth, births and deaths. Population size is its most important feature because it is directly related to a population''s ability to survive.', wrong = '{"0": "Biogeography studies how organisms are distributed over the Earth, not the statistics of populations.", "1": "Ecology is the broad study of interactions between organisms and their environment. Demography is only one part of it.", "2": "Taxonomy is the science of naming, describing and classifying organisms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0659' AND answer = 3;
UPDATE questions SET why = 'In a type I (convex) survivorship curve, most individuals survive to old age and then die rapidly, because the environment has little effect on early mortality. Humans and many large mammals show this pattern and live most of their potential life span.', wrong = '{"0": "A type II (diagonal) curve shows a constant chance of death at every age, as seen in birds, lizards and rodents.", "1": "A type III (concave) curve shows very high death rates among the young, as in fishes and many invertebrates.", "3": "An exponential curve describes population growth over time, not the pattern of survival with age."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0660' AND answer = 2;
UPDATE questions SET why = 'A type III (concave) survivorship curve drops steeply at the start because juvenile mortality is very high. The few individuals that reach adulthood then have a much lower death rate. Fishes and many invertebrates show this curve.', wrong = '{"0": "A type I (convex) curve has low mortality in early life, with most deaths in old age, as in humans.", "2": "A type II (diagonal) curve has a constant probability of death throughout life, as in birds, lizards and rodents.", "3": "A logistic curve describes population growth levelling off at carrying capacity, not survival with age."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0661' AND answer = 1;
UPDATE questions SET why = 'In the logistic model, a growing population eventually faces a shortage of resources such as space, light, water or nutrients. Growth slows and the population stabilizes at the carrying capacity, so the curve takes a sigmoid (flattened S) shape.', wrong = '{"0": "Growth without limit describes the exponential model, which gives a J-shaped curve, not an S-shape.", "1": "Adding the same number each generation would give a straight line. Neither growth model works this way.", "2": "Survivorship type describes the pattern of deaths with age. It does not explain the shape of a growth curve."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0662' AND answer = 3;
UPDATE questions SET why = 'In the exponential model, the population grows without limits at its maximal rate. Instead of adding a constant number each generation, it increases by the same ratio per unit time, so the numbers rise faster and faster.', wrong = '{"0": "Adding a constant number each generation is the pattern the exponential model is contrasted with. That gives straight-line growth.", "1": "Slowing growth that levels off at carrying capacity describes the logistic model.", "3": "Exponential growth follows a fixed rate of increase. It is not driven by chance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0663' AND answer = 2;
UPDATE questions SET why = 'Population density is the number of individuals per unit area or volume. Counting E. coli cells per millilitre of culture measures individuals per unit volume, so it is a measure of population density.', wrong = '{"1": "Carrying capacity is the maximum number of individuals an environment can support sustainably over a long period, not a count per unit volume.", "2": "Survivorship is the percentage of individuals alive at a given age.", "3": "Dispersion is the pattern of spacing of individuals, such as random, uniform or clumped."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0664' AND answer = 0;
UPDATE questions SET why = 'Animals that defend defined territories, such as nesting penguins, keep a fairly equal distance from their neighbours. This gives uniform spacing, similar to plants that inhibit the growth of nearby individuals.', wrong = '{"0": "Random spacing occurs when individuals do not interact strongly, as with some plants grown from wind-dispersed seeds.", "2": "Clumped spacing comes from uneven resources or group living. Territorial defence pushes individuals apart instead.", "3": "Exponential describes a growth model, not a pattern of spacing."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0665' AND answer = 1;
UPDATE questions SET why = 'Clumped spacing is the most common pattern in nature. Resources are usually unevenly spread, so animals, plants and microorganisms gather in resource-rich places. Animals living in groups and plants dropping seeds straight down also form clumps.', wrong = '{"0": "Random spacing needs individuals that do not interact strongly. It is not common in nature.", "1": "Uniform spacing is limited to special cases such as territorial animals or plants that inhibit their neighbours.", "2": "Linear spacing is not one of the dispersion patterns. The three are random, uniform and clumped."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0666' AND answer = 3;
UPDATE questions SET why = 'Carrying capacity is the maximum number of individuals of a species that an environment can support sustainably over a long period. It is set by limiting factors such as food, water, shelter and nesting sites, along with predators and diseases.', wrong = '{"1": "Survivorship type describes the pattern of deaths with age. It does not fix the number an environment can support.", "2": "Dispersion pattern describes how individuals are spaced, not how many the habitat can hold.", "3": "The number of trophic levels describes energy flow in an ecosystem, not the limit for a single species."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0667' AND answer = 0;
UPDATE questions SET why = 'Below its minimal viable population size, a population such as the few remaining Himalayan brown bears faces inbreeding. This causes genetic weaknesses and lower immunity, and a single disaster such as a flood or forest fire could wipe out all the survivors.', wrong = '{"0": "Carrying capacity is always limited by food, water, shelter and other factors. It never becomes infinite.", "1": "A very small population does not grow exponentially. Its problem is a high risk of extinction.", "3": "Survivorship type does not change because a population is small. The danger comes from inbreeding and chance disasters."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0668' AND answer = 2;
UPDATE questions SET why = 'The Pakistan Bureau of Statistics recorded Pakistan''s population as 241.49 million in the 2023 census, which is about 241 million. The growth rate is officially about 2.55% a year.', wrong = '{"0": "8 billion is the approximate population of the whole world, reached in 2022, not of Pakistan.", "1": "24 million is about ten times smaller than the census figure of 241.49 million.", "2": "2.4 billion is about ten times larger than Pakistan''s census figure of 241.49 million."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0669' AND answer = 3;
UPDATE questions SET why = 'Greenhouse gases such as CO₂ let sunlight pass through to the Earth''s surface. They then trap the heat radiated from the surface and stop it escaping directly into space. This natural greenhouse effect keeps Earth warm enough for life, and extra GHGs make it stronger.', wrong = '{"0": "Greenhouse gases allow sunlight to pass through. If they blocked all sunlight, the surface would cool, not warm.", "2": "Greenhouse gases do not burn or produce heat. They trap heat that the Earth''s surface gives off.", "3": "Ozone depletion is a separate problem. Warming comes from trapping heat, not from destroying ozone."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0670' AND answer = 1;
UPDATE questions SET why = 'Methane (CH₄) is produced by livestock through enteric fermentation, the breakdown of food by microbes in the cattle gut, as well as by farming and the production of coal and gas. It contributes about 11% of global warming.', wrong = '{"1": "Nitrous oxide (N₂O) comes from agricultural and industrial activities and fossil fuel combustion, not cattle digestion. It causes about 6% of warming.", "2": "Chlorofluorocarbons are synthetic gases from industrial processes such as old refrigerators and air conditioners.", "3": "Burning fossil fuels releases CO₂, the main greenhouse gas, but this is not what cattle digestion produces."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0671' AND answer = 0;
UPDATE questions SET why = 'Fluorinated gases such as chlorofluorocarbons (CFCs) are entirely synthetic. They are released from industrial processes such as old refrigerators and air conditioners and contribute about 3% of global warming.', wrong = '{"0": "Methane is not synthetic. It comes from livestock, agriculture and coal and gas production.", "1": "Nitrous oxide is released by farming, industry and fuel combustion. It is not a purely synthetic gas.", "3": "Carbon dioxide is released by burning fossil fuels and deforestation. It also occurs naturally, so it is not synthetic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0672' AND answer = 2;
UPDATE questions SET why = 'A glacial lake outburst flood (GLOF) is a sudden release of water from a glacial lake when its natural dam, often ice, breaks. Rising temperatures melt glaciers such as Baltoro and Batura, and GLOF water can travel over 100 km downstream.', wrong = '{"0": "A cloudburst is a sudden, extremely heavy rainfall over a small area in a short time. It does not involve a lake dam breaking.", "1": "Surface runoff is the normal flow of water over land into streams and rivers when soil cannot absorb more.", "3": "Desertification is fertile land turning into desert as heat dries out soil moisture."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0673' AND answer = 2;
UPDATE questions SET why = 'As polar ice melts and warmed seawater expands, sea levels rise. In coastal areas such as Thatta and Badin, seawater pushes inland and turns fertile farmland into salty marshes, along with coastal erosion.', wrong = '{"1": "GLOFs are sudden floods from glacial lakes in the northern mountains, not seawater entering coastal land.", "2": "Heatwaves in Jacobabad cause heatstroke and drought, but they do not bring seawater inland.", "3": "Denitrification is the bacterial conversion of nitrates to N₂ in waterlogged soils, part of the nitrogen cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0674' AND answer = 0;
UPDATE questions SET why = 'Temperate deciduous forests grow in moist northern mountains such as Shogran, Neelam Valley, Murree and Kaghan, with 750 to 1500 mm of rain a year. Typical plants are yew, blue pine and Himalayan cedar, and animals include rhesus monkeys and black bears.', wrong = '{"0": "Tropical thorn forest covers the dry Indus plains, with plants such as Jhand, Peelu, Karir and Kikar.", "2": "Mangrove forests are coastal, salt-tolerant forests dominated by Avicennia marina (Timmar).", "3": "Alpine meadows are high, cold grasslands with stunted junipers and birch, home to snow leopards and ibex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0675' AND answer = 1;
UPDATE questions SET why = 'Tropical thorn forest is the most widespread land ecosystem of Pakistan''s plains, covering much of the Indus plains with only 200 to 750 mm of rain a year. Its xerophytic (drought-resistant) plants bear thorns to deter herbivores and reduce water loss. Most has been cleared for settlements and canal irrigation.', wrong = '{"0": "Temperate deciduous forest grows in moist northern mountain areas such as Murree and Kaghan, not on the plains.", "1": "Alpine meadows are high-altitude cold grasslands in Gilgit-Baltistan, Chitral and Deosai.", "2": "Mangrove forests are found only along the coast of Sindh and Balochistan."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0676' AND answer = 3;
UPDATE questions SET why = 'Alpine and sub-alpine meadows are high-altitude "cold deserts" where the climate is too harsh for large trees. The mean annual temperature is only 1 to 10 °C and precipitation falls mostly as heavy snow, so only stunted junipers, birch, willow and grasses grow.', wrong = '{"0": "Salty soil is a feature of coastal mangrove areas, not mountain meadows.", "2": "Precipitation here falls mostly as snow. Heavy rainfall is not what keeps large trees away.", "3": "Grazing is not the reason given. The limit on tree growth is the severe cold and harsh climate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0677' AND answer = 1;
UPDATE questions SET why = 'Avicennia marina, locally called Timmar, makes up about 95% of Pakistan''s mangrove forests. These salt-tolerant forests grow in brackish water on oxygen-poor mudflats, and the trees have breathing roots to get air.', wrong = '{"1": "Vachellia nilotica (Kikar) is a drought-resistant tree of the tropical thorn forest of the plains.", "2": "Cedrus deodara (deodar, Himalayan cedar) grows in the temperate forests of the northern mountains.", "3": "Betula utilis (birch) grows in the cold alpine and sub-alpine meadows."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0678' AND answer = 0;
UPDATE questions SET why = 'The American ecologist Robert Whittaker proposed the five-kingdom system in 1969. It divided all organisms into Monera, Protista, Fungi, Plantae and Animalia, with prokaryotes in Monera and eukaryotes in the other four kingdoms.', wrong = '{"1": "Carl Woese proposed the three-domain system (Archaea, Bacteria, Eukarya) in 1990, which came after the five-kingdom system.", "2": "Ernst Mayr is known for the biological species concept, not for the five-kingdom system.", "3": "Carolus Linnaeus founded binomial nomenclature in the 18th century. He did not propose the five kingdoms of 1969."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0679' AND answer = 0;
UPDATE questions SET why = 'In 1990 Carl Woese recognised that prokaryotes are not one group but two separate kinds, Archaea and Bacteria, which differ in membrane lipids, cell walls and genes. Adding the eukaryotes (Eukarya) gave three domains: Archaea, Bacteria and Eukarya.', wrong = '{"0": "Fungi and plants were not merged. They remain separate kingdoms within domain Eukarya.", "1": "Viruses are acellular and are not placed in any of the three domains.", "2": "Protists and animals stay as separate kingdoms within Eukarya. The new domains came from splitting the prokaryotes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0680' AND answer = 3;
UPDATE questions SET why = 'In Whittaker''s five-kingdom system, kingdom Monera held all the prokaryotes, the cells without a true nucleus. The other four kingdoms, Protista, Fungi, Plantae and Animalia, all contained eukaryotes.', wrong = '{"0": "Protista contains eukaryotes, such as Amoeba and algae, which have a true nucleus.", "1": "Fungi are eukaryotes with nuclei and chitin cell walls, not prokaryotes.", "3": "Archaea is a domain of the later three-domain system (1990). It was not a kingdom in Whittaker''s scheme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0681' AND answer = 2;
UPDATE questions SET why = 'The evolutionary relationship among organisms is called phylogeny. A branching diagram that shows these relationships, tracing groups back to common ancestors, is called a phylogenetic or evolutionary tree.', wrong = '{"0": "A taxonomic key is a tool for identifying organisms by their features. It does not show ancestry.", "2": "A food web shows the feeding links between organisms in an ecosystem, not their evolutionary history.", "3": "A karyotype is a picture of an organism''s chromosomes arranged in pairs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0682' AND answer = 1;
UPDATE questions SET why = 'Archaea and Bacteria evolved independently from a common ancestor. Molecular evidence shows that Eukarya branched off from Archaea after Archaea split from Bacteria, so archaea are more closely related to eukaryotes than to bacteria. They share several genetic sequences with eukaryotes.', wrong = '{"0": "This is the reverse of the molecular evidence. Despite both being prokaryotes, archaea are closer to eukaryotes.", "1": "Archaea are not the ancestors of bacteria. The two groups evolved independently from a common ancestor.", "2": "Archaea are prokaryotes that never had a nucleus. They are not eukaryotes that lost one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0683' AND answer = 3;
UPDATE questions SET why = 'The name Archaea comes from the Greek word archaios, meaning "ancient". These prokaryotes diverged from bacteria in very ancient times and were first called archaebacteria.', wrong = '{"1": "Many archaea live in extreme habitats, but \"extreme\" is a description of where they live, not the meaning of the name.", "2": "Archaeans are small, 0.1 to over 15 μm, but the name does not refer to their size.", "3": "\"Hidden\" is not the meaning of archaios. The word means ancient."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0684' AND answer = 0;
UPDATE questions SET why = 'Archaea reproduce only asexually, by binary or multiple fission, fragmentation or budding. Mitosis and meiosis do not occur in archaea, so meiosis is the process that is NOT found in them.', wrong = '{"0": "Binary fission does occur in archaea. It is one of their asexual methods of reproduction.", "2": "Fragmentation does occur in archaea. It is listed among their methods of reproduction.", "3": "Budding does occur in archaea. It is another of their asexual methods."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0685' AND answer = 1;
UPDATE questions SET why = 'Archaeal membrane lipids have branched chains joined to glycerol by ether linkages. These make the membrane more resistant to extreme conditions such as heat and acidity, which helps archaea survive in harsh habitats.', wrong = '{"0": "Unbranched fatty acid chains joined to glycerol by ester linkages describe the membranes of bacteria and eukaryotes.", "1": "Archaeal membrane lipids do contain glycerol. What differs is the ether linkage and the branched chains.", "3": "Cholesterol replacing fatty acids is not the archaeal feature. Their difference is ether linkages and branched chains."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0686' AND answer = 2;
UPDATE questions SET why = 'Archaeal cell walls lack both cellulose and peptidoglycan. Instead they contain distinct polysaccharides and proteins, and some archaea have pseudopeptidoglycan, a polymer that resembles peptidoglycan but is chemically different.', wrong = '{"0": "Peptidoglycan, a polymer of sugars and amino acids, is the cell wall material of bacteria, not archaea.", "1": "Cellulose forms the cell walls of plants and algae among the eukaryotes.", "3": "Chitin forms the cell walls of fungi."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0687' AND answer = 2;
UPDATE questions SET why = 'Methanogenesis, the production of methane, is a metabolic process unique to archaea. It is not found in bacteria or eukaryotes. Methanogens use it in sewage treatment to make biogas, and in the human gut.', wrong = '{"0": "Photosynthesis is carried out by some bacteria (such as cyanobacteria) and by plants and algae, so it is not unique to archaea.", "1": "Nitrogen fixation is carried out by bacteria such as Rhizobium and cyanobacteria.", "2": "Fermentation occurs in many bacteria and in eukaryotes such as yeast."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0688' AND answer = 3;
UPDATE questions SET why = 'Archaeans living in harsh conditions provide enzymes that work under those conditions. DNA replication enzymes taken from such archaeans work best at high temperatures, which allows rapid copying (cloning) of DNA in the laboratory.', wrong = '{"0": "Their value is the opposite: they withstand high temperatures, not work only in the cold.", "2": "Digesting cellulose is not the laboratory use described for archaeal enzymes.", "3": "Destroying plasmids is not their use. Their DNA replication enzymes are used to copy DNA quickly."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0689' AND answer = 1;
UPDATE questions SET why = 'Halobacteria are the group of archaea that live in extremely saline (salty) environments, such as salt lakes and salt pans. The prefix halo- means salt. The other major groups are methanogens, thermococci and Thaumarchaeota.', wrong = '{"1": "Methanogens produce methane as a metabolic by-product and live in places such as sewage and the gut.", "2": "Thermococci are found in hot environments.", "3": "Thaumarchaeota are involved in the nitrogen cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0690' AND answer = 0;
UPDATE questions SET why = 'Acidophilic archaea thrive in highly acidic conditions. In mineral processing they are used to extract metals such as gold, cobalt and copper from their ores.', wrong = '{"0": "Producing methane (biogas) from sewage is the job of methanogen archaea, not acidophiles.", "2": "Penicillin is an antibiotic obtained from the fungus Penicillium.", "3": "Fixing nitrogen in soil is done mainly by bacteria. It is not a mineral-processing use."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0691' AND answer = 1;
UPDATE questions SET why = 'Methanogens are archaea that produce methane as a by-product of their metabolism. In humans, intestinal gas is largely the result of the metabolism of methanogens living in the gut.', wrong = '{"0": "Halobacteria live in extremely salty environments, not in the human intestine.", "1": "Cyanobacteria are photosynthetic bacteria found in water and soil. They do not produce intestinal gas.", "3": "Thermococci are archaea of hot environments, not of the human gut."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0692' AND answer = 2;
UPDATE questions SET why = 'Bacteria come in four main shapes: cocci are spherical, bacilli are rod-shaped, spirilla are spiral-shaped, and vibrios are comma-shaped. So comma-shaped bacteria, such as the cholera bacterium, are vibrios.', wrong = '{"1": "Bacilli are rod-shaped bacteria, such as Bacillus subtilis.", "2": "Cocci are spherical bacteria.", "3": "Spirilla are spiral-shaped bacteria with several turns."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0693' AND answer = 0;
UPDATE questions SET why = 'Cocci are named by how the cells are arranged. Single cells in pairs are diplococci, chains are streptococci, and grape-like clusters are staphylococci, so spherical bacteria in clusters are staphylococci.', wrong = '{"0": "Streptococci are cocci arranged in chains, not clusters.", "1": "Diplococci are cocci arranged in pairs.", "2": "Spirilla are spiral-shaped bacteria. The name describes a shape, not an arrangement of cocci."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0694' AND answer = 3;
UPDATE questions SET why = 'Cyanobacteria are photosynthetic bacteria, and Spirulina and Anabaena are examples of this group. So Spirulina with Cyanobacteria is the correctly matched pair.', wrong = '{"1": "Helicobacter pylori belongs to Proteobacteria, along with E. coli and Rhizobium. Firmicutes include Bacillus and Lactobacillus.", "2": "Treponema pallidum, the cause of syphilis, belongs to Spirochaetes, not Actinobacteria.", "3": "Mycobacterium tuberculosis belongs to Actinobacteria, along with Streptomyces, not Proteobacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0695' AND answer = 0;
UPDATE questions SET why = 'In eukaryotes, DNA is organised into multiple linear chromosomes inside the nucleus. The DNA is wrapped around histone proteins, which help organise it and regulate its genes.', wrong = '{"0": "A single circular chromosome lying in a nucleoid is the arrangement in prokaryotes (bacteria and archaea).", "1": "Plasmids are small extra circular DNA molecules found mainly in bacteria. They are not the main genetic material of eukaryotes.", "3": "Eukaryotic DNA is enclosed in a nucleus and bound to histones. It is not naked circular DNA in the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0696' AND answer = 2;
UPDATE questions SET why = 'According to the endosymbiosis idea, eukaryotes arose when a host cell engulfed certain prokaryotic cells and the two began living together. These engulfed prokaryotes became mitochondria and chloroplasts.', wrong = '{"0": "Binary fission is the way prokaryotes divide into two daughter cells. It does not bring organelles into another cell.", "2": "Conjugation is the transfer of genetic material between bacteria through a pilus.", "3": "Meiosis is cell division that halves the chromosome number to form gametes or spores."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0697' AND answer = 1;
UPDATE questions SET why = 'The taxonomic hierarchy runs domain, kingdom, phylum, class, order, family, genus, species. Domain is the highest and broadest level, and there are three: Archaea, Bacteria and Eukarya.', wrong = '{"0": "Kingdom is one of the highest ranks, but it lies just below domain.", "1": "Phylum lies below kingdom, two levels under domain.", "2": "Species is the lowest and most specific level, not the highest."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0698' AND answer = 3;
UPDATE questions SET why = 'Phylum is the level below kingdom. Organisms in the same phylum share a basic body plan and significant structural features. For example, phylum Chordata includes all animals with a notochord, such as fish, birds and mammals.', wrong = '{"0": "The ability to interbreed and produce fertile offspring defines members of the same species, not a phylum.", "2": "A phylum contains many genera, so its members usually have different genus names.", "3": "Diet is not used to define a phylum. Body plan and structural features are."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0699' AND answer = 1;
UPDATE questions SET why = 'Within the order Primates, the family Hominidae includes the great apes and humans. Below this, the genus Homo contains humans and their closest extinct relatives.', wrong = '{"0": "Primates is the order that includes humans, monkeys and apes. It is broader than the family.", "1": "Mammalia is the class of all mammals, characterised by hair and mammary glands.", "3": "Homo is the genus, which includes humans and close extinct relatives but not the great apes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0700' AND answer = 2;
UPDATE questions SET why = 'The taxonomic hierarchy from broad to specific is domain, kingdom, phylum, class, order, family, genus, species. Class, order, family, genus follows this order exactly.', wrong = '{"1": "This puts order before class and genus before family. Class is broader than order, and family is broader than genus.", "2": "Family is the narrowest of family, order and class. Here the sequence runs the wrong way.", "3": "This swaps order and family. Order is broader, so it must come before family."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0701' AND answer = 0;
UPDATE questions SET why = 'The onion, Allium cepa, is classified as Eukarya, Plantae, Angiosperms (phylum), Monocots (class), Asparagales (order), Amaryllidaceae (family), Allium (genus) and Allium cepa (species). Family names of plants usually end in -aceae.', wrong = '{"0": "Asparagales is the order of the onion, one level above family.", "1": "Monocots is the class of the onion.", "2": "Allium is the genus of the onion, one level below family."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0702' AND answer = 3;
UPDATE questions SET why = 'Protists may be unicellular, colonial, filamentous or simple multicellular. "Simple multicellular" means that, although made of many cells, they do not have multicellular sex organs, unlike plants and animals.', wrong = '{"1": "All protists are eukaryotes with a true nucleus. Having no nucleus describes prokaryotes.", "2": "Only certain protists, such as Plasmodium, are parasitic. Many are free-living.", "3": "Many protists, such as algae, have chlorophyll and make their own food."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0703' AND answer = 0;
UPDATE questions SET why = 'Amoebic dysentery is caused by the parasitic protist Entamoeba histolytica, an animal-like protozoan that infects the human intestine.', wrong = '{"0": "Plasmodium is a parasitic protist that causes malaria.", "1": "Trypanosoma is a parasitic protist that causes sleeping sickness.", "3": "Paramecium is a free-living ciliated protozoan. It is not a cause of dysentery."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0704' AND answer = 2;
UPDATE questions SET why = 'Slime molds (Myxomycota) and water molds (Oomycota) are fungi-like protists. They have hypha-like structures and are saprophytic, absorbing food from dead organic matter as fungi do.', wrong = '{"0": "Animal-like protists are the protozoa, unicellular heterotrophs such as Amoeba and Paramecium.", "1": "Plant-like protists are the algae, which have chlorophyll and cellulose walls.", "2": "All protists, including slime and water molds, are eukaryotes, not prokaryotes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0705' AND answer = 3;
UPDATE questions SET why = 'Fungi are eukaryotic heterotrophs whose cells are covered by a cell wall made of chitin, a nitrogen-containing polysaccharide. They absorb food from their surroundings rather than ingesting it.', wrong = '{"0": "Cellulose forms the cell walls of plants and algae, not fungi.", "2": "Peptidoglycan forms the cell walls of bacteria.", "3": "Silica forms the needle-like skeleton (spicules) of some sponges and the walls of diatoms, not fungal walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0706' AND answer = 1;
UPDATE questions SET why = 'Zygomycota are fungi whose hyphae lack septa (cross-walls), so the cytoplasm and nuclei run continuously along each hypha. Rhizopus, the black bread mould that grows on moist bread and fruit, is an example.', wrong = '{"0": "Septate hyphae, divided by cross-walls, are found in Ascomycota and Basidiomycota.", "1": "Rhizopus does form hyphae. They are simply not divided by septa.", "2": "Fungi have no chlorophyll. They are heterotrophs that absorb food."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0707' AND answer = 3;
UPDATE questions SET why = 'Ascomycota is the largest group of fungi, with septate hyphae. It includes common molds, morels, truffles, cup fungi, Neurospora and yeasts.', wrong = '{"0": "Basidiomycota includes mushrooms, toadstools, puffballs, bracket fungi, rusts and smuts.", "1": "Zygomycota includes fungi without septa, such as Rhizopus (bread mould).", "3": "Oomycota are water molds, which are fungi-like protists, not true fungi."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0708' AND answer = 2;
UPDATE questions SET why = 'Nonvascular plants, called bryophytes, lack conducting tissues (xylem and phloem). Because they cannot transport water far, they stay small and grow in moist places. Mosses, liverworts and hornworts are examples.', wrong = '{"1": "Gymnosperms are vascular seed plants with naked seeds, such as pine and spruce. They have xylem and phloem.", "2": "Angiosperms are vascular flowering plants whose seeds are enclosed in fruits.", "3": "Ferns are seedless vascular plants. They do have xylem and phloem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0709' AND answer = 0;
UPDATE questions SET why = 'A sponge''s body wall has many small pores called ostia through which water enters. The water passes through the central cavity (spongocoel) and leaves through a single larger opening at the top called the osculum.', wrong = '{"0": "Ostia are the numerous small pores through which water enters the sponge, not where it leaves.", "2": "The spongocoel is the central cavity, lined by collar cells. Water passes through it but exits by the osculum.", "3": "A gemmule is a resistant capsule of amoeboid cells used in reproduction, not an opening for water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0710' AND answer = 1;
UPDATE questions SET why = 'A sponge body wall has three layers: outer flat pinacocytes, a jelly-like middle mesohyl with amoeboid cells, and an inner layer of choanocytes (collar cells) lining the spongocoel. Their beating flagella keep water flowing through the sponge.', wrong = '{"1": "Pinacocytes are thin, flat cells that form the outer layer of the sponge body, not the lining of the spongocoel.", "2": "Cnidocytes are stinging cells of cnidarians such as Hydra. Sponges do not have them.", "3": "Flame cells are excretory cells of flatworms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0711' AND answer = 0;
UPDATE questions SET why = 'Some sponges form gemmules, which are resistant capsules containing masses of amoeboid cells. When the parent sponge dies, the gemmules are released, and in a favourable environment the amoeboid cells come out and form a new sponge.', wrong = '{"0": "Stinging organelles are nematocysts, found inside the cnidocytes of cnidarians.", "2": "The skeletal needles of calcium carbonate or silica in sponges are spicules, not gemmules.", "3": "The pores through which water enters a sponge are ostia."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0712' AND answer = 1;
UPDATE questions SET why = 'Cnidarians are diploblastic, with two tissue layers: the outer epidermis and the inner gastrodermis. Between them lies a jelly-like layer called the mesoglea, which contains amoeboid cells.', wrong = '{"0": "Mesohyl (mesohyle) is the jelly-like middle layer of sponges, not cnidarians.", "1": "Mesoderm is the third germ layer of triploblastic animals. Cnidarians are diploblastic and do not have it.", "3": "Parenchyma is the loose connective tissue that fills the space between body wall and organs in flatworms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0713' AND answer = 2;
UPDATE questions SET why = 'Cnidarians have two body forms. The polyp is cylindrical, attached to a surface at its aboral end (the end away from the mouth), and reproduces asexually. The medusa is umbrella-like, free-swimming and reproduces sexually.', wrong = '{"0": "An umbrella-shaped, free-swimming, sexually reproducing form is the medusa, not the polyp.", "1": "Cnidarians have a sac-like digestive system with one opening, the mouth, which also acts as the anus.", "2": "Cnidarians have only a nerve net in the body wall, with no brain or spinal cord."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0714' AND answer = 3;
UPDATE questions SET why = 'Flatworms are acoelomates, meaning they have no body cavity. The space between the body wall and the body organs is filled with a loose connective tissue called parenchyma.', wrong = '{"1": "A fluid-filled false body cavity, the pseudocoelom, is found in roundworms (nematodes), which are pseudocoelomates.", "2": "A true coelom lined by mesoderm is found in coelomates such as molluscs and annelids, not flatworms.", "3": "Mesoglea is the jelly-like layer between the two body layers of cnidarians."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0715' AND answer = 0;
UPDATE questions SET why = 'Flatworms excrete with a network of tubules called protonephridia. Each branch ends in a bulb-like flame cell whose cilia beat, looking like a flickering flame, and draw surrounding fluid into the tubules. Wastes are then removed through a nephridiopore.', wrong = '{"0": "Flame cells are part of the excretory system. They play no role in capturing prey.", "1": "Flatworms have no circulatory system or blood vessels for flame cells to pump through.", "3": "Flatworms have no respiratory system. Gases diffuse through the body surface, and flame cells are excretory."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0716' AND answer = 2;
UPDATE questions SET why = 'In nematodes (roundworms), a nerve ring encircles the pharynx and is attached to four longitudinal nerve cords that run along the body.', wrong = '{"0": "A double ventral nerve cord is found in annelids and arthropods, not nematodes.", "2": "A dorsal tubular nerve cord is one of the key features of chordates.", "3": "Five (or multiples of five) radial nerves around a nerve ring are found in echinoderms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0717' AND answer = 1;
UPDATE questions SET why = 'All molluscs except the bivalves have a radula, a rasping tongue-like organ used to scrape food. A snail, for example, uses its radula to scrape algae or plant tissue.', wrong = '{"0": "The mantle is the epithelial envelope around the visceral mass, which in most molluscs secretes the shell.", "1": "The madreporite is the sieve-like plate through which the water-vascular system of echinoderms opens outside.", "2": "The syrinx is the voice organ of birds, at the lower end of the trachea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0718' AND answer = 3;
UPDATE questions SET why = 'Most molluscs have an open circulatory system, where blood leaves the vessels and bathes the tissues directly. Cephalopods such as octopus and cuttlefish are the exception, since they have a closed system.', wrong = '{"1": "Gastropods such as snails and slugs have an open circulatory system, like most molluscs.", "2": "Bivalves are the exception for the radula, which they lack, but their circulatory system is open.", "3": "Land snails are gastropods, and they have an open circulatory system."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0719' AND answer = 0;
UPDATE questions SET why = 'In annelids the body is divided into similar ring-like segments separated by cross walls (septa). Each segment has its own circulatory, excretory and neural elements, such as a pair of metanephridia and ganglia. This repeated arrangement is metameric segmentation.', wrong = '{"0": "Tagmata (head, thorax, abdomen) are regions formed by fused segments in arthropods, not annelids.", "2": "Body parts arranged in fives around an oral-aboral axis is the radial symmetry of adult echinoderms.", "3": "Annelids are the segmented worms. A soft, unsegmented body describes molluscs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0720' AND answer = 1;
UPDATE questions SET why = 'Setae are chitinous bristles that annelids such as earthworms and Nereis use to grip the ground or swim. Leeches lack setae, and instead move using suckers.', wrong = '{"0": "Earthworms do have setae, which anchor them in the soil while they crawl.", "1": "Nereis, a marine annelid, has many setae on its paddle-like body extensions.", "3": "Marine annelids such as Nereis have setae. They are absent only in leeches."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0721' AND answer = 2;
UPDATE questions SET why = 'Annelids have a closed circulatory system with pulsating vessels called pseudohearts. In most annelids the respiratory pigment haemoglobin is dissolved directly in the blood plasma rather than carried in red blood cells.', wrong = '{"0": "Haemoglobin inside red blood cells is the arrangement in vertebrates. In annelids it is dissolved in plasma.", "1": "Pseudohearts are pulsating blood vessels that pump blood. Haemoglobin is in all the blood, not only there.", "2": "Colourless haemolymph without haemoglobin is the blood of arthropods."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0722' AND answer = 3;
UPDATE questions SET why = 'The hard chitin exoskeleton of arthropods cannot stretch. A young arthropod sheds it from time to time, grows rapidly, and then secretes a new one. This shedding process is called ecdysis or moulting.', wrong = '{"0": "Metamorphosis is a change in body form during development, such as caterpillar to butterfly, not just shedding the exoskeleton.", "2": "Regeneration is regrowth of lost body parts, as in sea stars and flatworms.", "3": "Fission is asexual division of the body into pieces, as in flatworms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0723' AND answer = 1;
UPDATE questions SET why = 'Malpighian tubules are the excretory organs of insects and other arthropods. These narrow tubules project from the alimentary canal at the junction of the midgut and hindgut and excrete nitrogenous waste as solid uric acid crystals.', wrong = '{"0": "The foregut-midgut junction is further forward. Malpighian tubules join at the midgut-hindgut junction.", "1": "The pharynx and oesophagus are at the front of the gut, far from where Malpighian tubules attach.", "2": "The crop and gizzard are parts of the foregut. The tubules attach further back, between midgut and hindgut."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0724' AND answer = 3;
UPDATE questions SET why = 'In echinoderms such as sea stars, a ring canal around the mouth is part of the water-vascular system. It opens to the outside through a sieve-like plate called the madreporite, through which water enters the system.', wrong = '{"1": "The osculum is the large opening through which water leaves a sponge.", "2": "The nephridiopore is the small opening that releases excretory wastes in flatworms.", "3": "Spiracles are the openings of the tracheal air tubes in arthropods."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0725' AND answer = 0;
UPDATE questions SET why = 'Echinoderm larvae are bilaterally symmetrical, with left and right sides. As they become adults they develop radial symmetry, with body parts arranged in fives (or multiples of five) around an oral-aboral axis.', wrong = '{"0": "This reverses the stages. The larvae are bilateral and the adults are radial.", "1": "Neither stage is asymmetrical. The larvae are bilateral and the adults are radial.", "3": "The adults have the calcareous endoskeleton of plates called ossicles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0726' AND answer = 2;
UPDATE questions SET why = 'Urochordates such as sea squirts have a notochord and nerve cord only in their free-swimming larvae. When the larva settles and becomes the attached adult, these structures are lost.', wrong = '{"0": "A notochord that persists throughout life is found in cephalochordates such as Amphioxus.", "2": "Replacement of the notochord by a vertebral column happens in vertebrates.", "3": "Both structures are formed in the larva of urochordates, so they are not absent completely."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0727' AND answer = 1;
UPDATE questions SET why = 'Four features are unique to chordates and appear at some stage of development: a notochord, pharyngeal slits, a dorsal tubular nerve cord and a post-anal tail. Pharyngeal slits are openings in the side walls of the pharynx.', wrong = '{"1": "Bilateral symmetry is shared by many non-chordates, such as flatworms, annelids and arthropods.", "2": "Triploblastic bodies are found in many invertebrates, such as flatworms and molluscs.", "3": "A true coelom is also present in molluscs, annelids, arthropods and echinoderms."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0728' AND answer = 0;
UPDATE questions SET why = 'Fishes have a two-chambered heart with one auricle (atrium) and one ventricle. Blood passes through the heart only once in each round of circulation, which is called single circulation.', wrong = '{"0": "Two atria and one ventricle form the three-chambered heart of amphibians.", "1": "A four-chambered heart with complete separation of atria and ventricles is found in birds and mammals.", "3": "The fish heart has two chambers, not one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0729' AND answer = 2;
UPDATE questions SET why = 'Class Chondrichthyes, the sharks, skates and ratfish, have a skeleton of cartilage instead of bone. Their tail fin has a large upper lobe, and they lack both a swim bladder and lungs.', wrong = '{"0": "A bony skeleton with a swim bladder or lung-like sac describes Osteichthyes, the bony fishes.", "1": "A sucking mouth with seven pairs of pharyngeal slits describes lampreys (class Cephalaspidomorphi).", "2": "A mouth with four pairs of tentacles describes hagfishes (class Myxini)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0730' AND answer = 3;
UPDATE questions SET why = 'Amphibians fall into three groups. Salamanders, newts and mudpuppies are tailed, frogs and toads are tailless, and caecilians are legless amphibians that look rather like worms.', wrong = '{"1": "Tailed amphibians are salamanders, newts and mudpuppies, not caecilians.", "2": "Tailless amphibians are frogs and toads.", "3": "Egg-laying mammals are monotremes such as the platypus. Caecilians are amphibians."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0731' AND answer = 0;
UPDATE questions SET why = 'Reptile amniotic eggs are covered by a leathery calcareous shell. It is partly permeable to gases, so the embryo can breathe, but not to water, so the egg does not dry out. This let reptiles lay eggs on land.', wrong = '{"0": "This reverses the permeability. The shell lets gases pass but keeps water in.", "2": "Reptile eggs do have a shell, which protects the embryo from drying out.", "3": "The shell is calcareous (containing calcium), not made of chitin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0732' AND answer = 1;
UPDATE questions SET why = 'In reptiles the first two cervical (neck) vertebrae are the atlas and the axis. Their joint allows more movement of the head, including turning, than the single neck joint of amphibians.', wrong = '{"0": "Incus and malleus are two of the three small bones of the mammalian middle ear.", "1": "The keel is a large bone on the sternum (chest bone) of birds for attaching flight muscles.", "3": "Ossicles are the skeletal plates of echinoderms, and also the tiny ear bones of mammals. They are not neck vertebrae."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0733' AND answer = 2;
UPDATE questions SET why = 'Birds produce sound with a syrinx, their organ of voice, located at the lower end of the trachea where it divides into the bronchi.', wrong = '{"0": "A larynx with vocal cords is the voice apparatus of mammals.", "1": "The crop is a storage pouch (diverticulum) of the oesophagus for holding food.", "2": "Air sacs connect to the lungs and help in breathing. They do not produce sound."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0734' AND answer = 3;
UPDATE questions SET why = 'Birds have no teeth, so food is crushed in the gizzard, a region of the stomach with thick muscular walls. Small stones swallowed by the bird often help this grinding.', wrong = '{"0": "The crop is a storage pouch of the oesophagus that lets birds take in large amounts of food quickly.", "2": "The keel is a bony ridge of the sternum where flight muscles attach.", "3": "The cloaca is the common chamber at the end of the gut. It does not crush food."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0735' AND answer = 1;
UPDATE questions SET why = 'Some birds have secondarily lost the power of flight and are called running birds. These include the ostrich, kiwi, rhea, cassowary and emu, so the kiwi is the flightless one here.', wrong = '{"1": "The pigeon is a flying bird.", "2": "The crow is a flying bird.", "3": "The robin is a flying bird."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0736' AND answer = 0;
UPDATE questions SET why = 'Mammals have skin glands developed from the epidermis. Sudoriferous (sweat) glands release watery secretions, and evaporation of this sweat cools the body.', wrong = '{"0": "Oily secretion comes from sebaceous glands, not sweat glands.", "1": "Milk is produced by mammary glands, which are functional in females.", "2": "Digestive enzymes come from glands of the digestive system, not from skin glands."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0737' AND answer = 3;
UPDATE questions SET why = 'Monotremes are mammals that lay eggs (they are oviparous), and the whole development of the embryo takes place inside the egg. The duckbill platypus and the spiny anteater (echidna) are examples.', wrong = '{"0": "Marsupials such as the kangaroo and opossum have a pouch and give birth to immature young. They do not lay eggs.", "1": "Placental mammals are viviparous, nourishing the foetus through a placenta.", "3": "The platypus and echidna have hair and feed young on milk, so they are mammals, not reptiles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0738' AND answer = 2;
UPDATE questions SET why = 'Marsupials have a pouch (marsupium) on the female''s abdomen. They give birth to immature young, which complete their development in the mother''s pouch. The kangaroo and opossum are examples.', wrong = '{"0": "The bat is a placental mammal whose young develop in the uterus, nourished by a placenta.", "2": "The dolphin is a placental mammal and gives birth to well-developed young.", "3": "The echidna (spiny anteater) is a monotreme, an egg-laying mammal."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0739' AND answer = 1;
UPDATE questions SET why = 'Prions are acellular infectious particles made of protein only, with no nucleic acid at all. They are not considered living organisms. Viroids, by contrast, are made of circular RNA only.', wrong = '{"0": "Particles made of circular RNA only are viroids, not prions.", "1": "Nucleic acid such as DNA surrounded by a protein coat describes a virus.", "3": "RNA with a lipid envelope describes an enveloped RNA virus such as influenza virus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0740' AND answer = 2;
UPDATE questions SET why = 'Viruses are classified by their genetic material, replication strategy, shape and host range. The guidelines for this classification are set by the International Committee on Taxonomy of Viruses (ICTV).', wrong = '{"1": "The World Health Organization deals with global public health. It does not set the rules for virus classification.", "2": "The IUCN works on nature conservation and threatened species, not virus taxonomy.", "3": "The PMDC is Pakistan''s medical and dental regulatory body. It has no role in classifying viruses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0741' AND answer = 0;
UPDATE questions SET why = 'By host range, viruses are grouped as animal viruses, plant viruses, bacteriophages and archaea viruses. Sulfolobus spindle-shaped virus infects Sulfolobus, an archaeon, so it is an archaea virus.', wrong = '{"0": "Viruses that infect bacteria are bacteriophages, such as T4 phage and lambda phage.", "1": "Plant viruses include tobacco mosaic virus and potato virus X.", "2": "Animal viruses include influenza virus and rabies virus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0742' AND answer = 3;
UPDATE questions SET why = 'In helical viruses the capsid proteins are arranged in a spiral around the nucleic acid, giving a rod- or bullet-shaped particle. Tobacco mosaic virus and rabies virus are examples of helical viruses.', wrong = '{"1": "Adenoviruses have an icosahedral capsid, a symmetrical shape with 20 triangular faces.", "2": "Herpesviruses also have an icosahedral capsid.", "3": "Poliovirus is a non-enveloped (naked) virus with an icosahedral capsid, not a helical one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0743' AND answer = 0;
UPDATE questions SET why = 'Enveloped viruses such as influenza virus and HIV have an outer lipid envelope around their capsid. This envelope is taken from the host cell membrane as the new virus leaves the cell.', wrong = '{"0": "Peptidoglycan is the cell wall polymer of bacteria. Viral envelopes are lipid membranes.", "2": "Viral nucleic acid cannot secrete lipids. The envelope comes from the host cell membrane.", "3": "The capsid is the protein coat that lies beneath the envelope. The envelope itself is lipid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0744' AND answer = 1;
UPDATE questions SET why = 'RNA viruses can have single-stranded or double-stranded RNA. Rotaviruses, which cause gastroenteritis, are double-stranded RNA (dsRNA) viruses.', wrong = '{"0": "Single-stranded DNA viruses include parvoviruses, which also cause gastroenteritis but are a different group.", "1": "Double-stranded DNA viruses include adenoviruses and herpesviruses.", "3": "Single-stranded RNA viruses include coronaviruses and influenza viruses."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0745' AND answer = 2;
UPDATE questions SET why = 'DNA viruses may carry single-stranded or double-stranded DNA. Parvoviruses, which cause gastroenteritis, are single-stranded DNA (ssDNA) viruses.', wrong = '{"0": "Double-stranded DNA viruses include adenoviruses (respiratory infections) and herpesviruses (herpes, chickenpox).", "1": "Double-stranded RNA viruses include rotaviruses.", "2": "Reverse transcribing viruses include HIV and hepatitis B virus, which use reverse transcriptase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0746' AND answer = 3;
UPDATE questions SET why = 'A negative-sense RNA genome is the complement of mRNA, so ribosomes cannot read it directly. A viral RNA polymerase first transcribes it into mRNA, which is then translated. Rabies virus and Ebola virus work this way.', wrong = '{"0": "Direct translation by host ribosomes describes positive-sense RNA viruses such as poliovirus and hepatitis C virus.", "2": "Copying RNA into DNA by reverse transcriptase describes reverse transcribing viruses such as HIV.", "3": "The genome is expressed. It must simply be transcribed into mRNA first."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0747' AND answer = 1;
UPDATE questions SET why = 'Reverse transcribing viruses replicate through a DNA intermediate using reverse transcriptase, and their genome can be RNA or DNA. Hepadnaviruses such as hepatitis B virus have a DNA genome, while retroviruses such as HIV have an RNA genome.', wrong = '{"1": "An RNA genome with reverse transcription describes retroviruses such as HIV, not hepatitis B virus.", "2": "Infectious agents made of protein only are prions, not viruses.", "3": "Naked circular RNA without a coat describes viroids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0748' AND answer = 0;
UPDATE questions SET why = 'In positive-sense RNA viruses, the RNA genome acts directly as mRNA and is translated by the host cell''s ribosomes. Poliovirus and hepatitis C virus are examples.', wrong = '{"0": "Ebola virus is a negative-sense RNA virus, so its genome must first be transcribed into mRNA.", "1": "Rabies virus is a negative-sense RNA virus that needs a viral RNA polymerase to make mRNA first.", "2": "Hepatitis B virus is a reverse transcribing virus with a DNA genome, not an RNA virus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0749' AND answer = 3;
UPDATE questions SET why = 'A niche is the role or function of an organism or species within its ecosystem. It includes its habitat, its interactions with other organisms such as predation, competition and symbiosis, and its role in energy flow.', wrong = '{"0": "A habitat is only the place where an organism lives. It is one part of the niche, not its whole role.", "1": "A population is a group of individuals of one species living in an area, not the role of an organism.", "3": "A biome is a large region with a characteristic climate and community, such as a desert or grassland."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0750' AND answer = 2;
UPDATE questions SET why = 'At the genetic level, biodiversity is the variety of genetic information carried by all the individuals of a species. This variation lets a species adapt to and survive environmental changes.', wrong = '{"0": "The species level counts the different species in an area along with their abundance and distribution.", "2": "The ecosystem level looks at the range of habitats, such as forests, wetlands and deserts.", "3": "Biodiversity is assessed at genetic, species and ecosystem levels. The variety within one species is genetic diversity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0751' AND answer = 1;
UPDATE questions SET why = 'Random sampling gives every part of the study area an equal chance of being sampled, which minimises bias. The sample then represents the whole area fairly, and the data can be analysed statistically to estimate species richness and abundance.', wrong = '{"1": "Choosing the richest spots deliberately would introduce bias, the very thing random sampling is meant to avoid.", "2": "Random sampling does not avoid statistics. Its data are analysed statistically to give reliable estimates.", "3": "Sampling studies only part of the area and then estimates. Counting every organism would not need sampling."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0752' AND answer = 0;
UPDATE questions SET why = 'In quadrat sampling, squares of fixed size are placed at random in the study area and the species inside each are recorded. It is particularly useful for plants and other sessile (non-moving) organisms that stay in place.', wrong = '{"0": "Point counts record animals seen from a fixed point over a set time. They suit birds and other mobile animals.", "1": "Mark-recapture is used to estimate the size of mobile animal populations that are hard to count.", "3": "Aerial surveys use aircraft or drones over large areas, for example to track herds or birds, not plants in one field."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0753' AND answer = 2;
UPDATE questions SET why = 'In mark-recapture, animals are captured, marked and released, then a second sample is caught later. The share of marked animals in the second catch is used to estimate the total population size, which suits animals that are hard to count directly.', wrong = '{"0": "Quadrat sampling suits plants and sessile organisms that stay in one place, not mobile animals.", "1": "Transect sampling records species at intervals along a line to study their distribution across an area.", "2": "Point counts record mobile animals such as birds from a fixed point. They are not used for plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0754' AND answer = 3;
UPDATE questions SET why = 'Cryptic species are organisms that look very similar but are genetically distinct and cannot interbreed. They make it hard to identify species from physical traits alone, which is why Mayr stressed reproductive isolation.', wrong = '{"0": "Hybrids are offspring produced by crossing two different species or varieties.", "2": "Polyploids are organisms with more than two sets of chromosomes, often formed in plants.", "3": "Subspecies are populations of the same species that differ somewhat but can still interbreed, so they are not genetically separate species."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0755' AND answer = 1;
UPDATE questions SET why = 'Ernst Mayr used reproductive isolation as the key test of a species. In his concept, species are groups of interbreeding natural populations, and members of different species do not normally mate or produce fertile offspring.', wrong = '{"0": "Physical similarity can mislead because cryptic species look alike but are distinct, which is why Mayr did not rely on it.", "1": "Geographical location does not define a species. Populations in different places can still be one species.", "3": "Body size varies within species and is not the criterion Mayr used."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0756' AND answer = 2;
UPDATE questions SET why = 'Peripatric speciation happens when a small population becomes isolated at the edge of a larger population. The small group evolves rapidly and diverges, as in island species that arise from a small founding population.', wrong = '{"0": "Allopatric speciation occurs when a population is split into two or more isolated groups by a geographical barrier.", "1": "Parapatric speciation occurs in neighbouring populations living along an environmental gradient with limited gene flow.", "2": "Sympatric speciation occurs within the same area without any physical barrier."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0757' AND answer = 3;
UPDATE questions SET why = 'In parapatric speciation, adjacent populations occupy different environments along a gradient, and gene flow between them is limited. The grass Anthoxanthum odoratum adapted to different soil conditions in neighbouring areas, leading to reproductive isolation.', wrong = '{"1": "Allopatric speciation needs complete geographical separation by a barrier, not neighbouring areas.", "2": "Peripatric speciation involves a small isolated population at the edge of a larger one.", "3": "Polyploidy causes sudden sympatric speciation through extra chromosome sets. This grass example is about adaptation to soil."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0758' AND answer = 0;
UPDATE questions SET why = 'Sympatric speciation produces new species within the same area without any physical barrier. In plants, polyploidy (having multiple chromosome sets) can make offspring unable to breed with the parent population, giving immediate reproductive isolation.', wrong = '{"0": "Allopatric speciation needs a geographical barrier that separates populations.", "1": "Peripatric speciation needs a small population isolated at the edge of a larger one.", "2": "Parapatric speciation involves adjacent populations in different environments along a gradient."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0759' AND answer = 3;
UPDATE questions SET why = 'The rigid bacterial cell wall is built mainly from a unique macromolecule called peptidoglycan, also known as murein. Its amount differs between bacteria, being thick in Gram-positive and thin in Gram-negative cells.', wrong = '{"0": "Cellulose is the main cell wall material of plants and algae.", "1": "Chitin is the cell wall material of fungi.", "2": "Pseudopeptidoglycan is found in the walls of some archaea, not bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0760' AND answer = 3;
UPDATE questions SET why = 'Peptidoglycan is made of long glycan (polysaccharide) chains that are cross-linked by short peptide fragments. This mesh of sugar and amino acid parts gives the bacterial wall its strength and shape.', wrong = '{"1": "Phospholipids with ether linkages are found in archaeal cell membranes, not in peptidoglycan.", "2": "Chitin is the polysaccharide of fungal cell walls. It is not part of peptidoglycan.", "3": "Lipopolysaccharides and porins belong to the outer membrane of Gram-negative bacteria, outside the peptidoglycan."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0761' AND answer = 0;
UPDATE questions SET why = 'The Gram staining technique was devised by Hans Christian Gram. It sorts bacteria into Gram-positive, which retain the violet dye and look purple, and Gram-negative, which lose it.', wrong = '{"0": "Robert Koch is famous for linking specific bacteria to diseases such as tuberculosis, not for the Gram stain.", "1": "Carl Woese proposed the three-domain system of classification in 1990.", "3": "Robert Whittaker proposed the five-kingdom system in 1969."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0762' AND answer = 2;
UPDATE questions SET why = 'Gram-positive bacteria have a thick peptidoglycan layer in their cell walls. This layer holds the crystal violet dye during the Gram stain, so the cells stay purple.', wrong = '{"0": "Bacteria without a cell wall, such as mycoplasmas, are not Gram-positive. The thick wall is what holds the dye.", "2": "An outer lipopolysaccharide membrane is a feature of Gram-negative bacteria, which do not keep the violet dye.", "3": "Gram-positive walls have a thick peptidoglycan layer. A lack of peptidoglycan would not hold the dye."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0763' AND answer = 1;
UPDATE questions SET why = 'The Gram-negative cell wall has only a thin layer of peptidoglycan, covered by an outer membrane made of lipopolysaccharides and lipoproteins. This outer membrane makes these bacteria resistant to many antibiotics.', wrong = '{"0": "A thick peptidoglycan layer with less lipid describes the Gram-positive cell wall.", "2": "Gram-negative bacteria actually have more periplasmic space than Gram-positive bacteria.", "3": "Gram-negative walls are rich in lipid, since the outer membrane contains lipopolysaccharides and lipoproteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0764' AND answer = 1;
UPDATE questions SET why = 'The outer membrane of Gram-negative bacteria contains a protein called porin. Porins form channels that act like pores, letting specific molecules pass through the otherwise less permeable outer membrane.', wrong = '{"0": "The rigidity of the cell wall comes from peptidoglycan, not porin.", "1": "The flagellum is anchored in the membrane and wall by the rings of its basal body.", "2": "Antibiotic-resistance genes are carried on plasmids, not stored in porin proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0765' AND answer = 3;
UPDATE questions SET why = 'Gram-negative bacteria have an outer membrane of lipopolysaccharides and lipoproteins outside their thin peptidoglycan layer. This outer membrane acts as a barrier that keeps many antibiotics out, making these bacteria resistant to them.', wrong = '{"0": "A thick peptidoglycan layer is a feature of Gram-positive bacteria, not Gram-negative ones.", "1": "Having no capsule is not what makes them resistant. The protective barrier is the outer membrane.", "3": "All bacteria have 70S ribosomes, so this cannot explain why Gram-negative bacteria in particular are resistant."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0766' AND answer = 2;
UPDATE questions SET why = 'The periplasmic space is the gap between the peptidoglycan layer of the cell wall and the cell membrane. Gram-negative bacteria have more periplasmic space than Gram-positive bacteria.', wrong = '{"1": "The capsule is a gelatinous layer outside the cell wall. There is no periplasmic space there.", "2": "Ribosomal subunits (50S and 30S) fit together to form a 70S ribosome. No periplasmic space lies between them.", "3": "The nucleoid and mesosomes are inside the cytoplasm, not at the edge of the cell wall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0767' AND answer = 0;
UPDATE questions SET why = 'Some bacteria produce a capsule, a gelatinous layer outside the cell wall. It makes bacterial colonies sticky and helps the cells stick to surfaces and resist drying.', wrong = '{"0": "The periplasm (periplasmic space) lies inside the wall, between the peptidoglycan layer and the cell membrane.", "2": "Mesosomes are infoldings of the cell membrane inside the cytoplasm, not an outer gelatinous layer.", "3": "The nucleoid is the dense region in the cytoplasm that holds the bacterial DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0768' AND answer = 1;
UPDATE questions SET why = 'The cell membrane normally lies just beneath the cell wall. In bacteria that have no cell wall, such as Mycoplasmas and Spiroplasmas, the cell membrane itself becomes the outermost layer of the cell.', wrong = '{"0": "A capsule is an extra gelatinous layer that some bacteria make outside the wall. It is not the outer layer of wall-less Mycoplasmas.", "1": "An outer membrane is part of the Gram-negative cell wall. Mycoplasmas have no wall, so they have no outer membrane.", "3": "A protein S-layer is not what bounds Mycoplasmas. Their outer boundary is the cell membrane."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0769' AND answer = 2;
UPDATE questions SET why = 'The bacterial cell membrane is a phospholipid bilayer with proteins, but unlike the membranes of eukaryotes it does not contain sterols such as cholesterol.', wrong = '{"1": "Phospholipids are the main lipids of the bacterial membrane, forming its bilayer.", "2": "The bacterial membrane contains many proteins, for example for transport and respiration.", "3": "The bacterial membrane is a lipid bilayer, like other cell membranes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0770' AND answer = 0;
UPDATE questions SET why = 'Mesosomes are infoldings of the bacterial cell membrane that form vesicles, tubules or lamellae in the cytoplasm. They take part in DNA replication and cell division and also serve as respiratory centres, since bacteria have no mitochondria.', wrong = '{"0": "Making the capsule is not the role given for mesosomes.", "1": "The flagellum is made of flagellin protein and is anchored by its basal body, not formed by mesosomes.", "2": "Plasmids are free circular DNA molecules in the cytoplasm. They are not stored in mesosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0771' AND answer = 3;
UPDATE questions SET why = 'Bacterial ribosomes are smaller than eukaryotic ones. Each sediments at 70S and is made of a larger 50S subunit and a smaller 30S subunit. S values are not simply added, which is why 50S + 30S gives 70S.', wrong = '{"0": "80S ribosomes with 60S and 40S subunits are found in the cytoplasm of eukaryotes.", "1": "This mixes the two types. A 70S ribosome has 50S and 30S subunits, not 60S and 40S.", "2": "This also mixes the two types. 50S and 30S subunits form a 70S ribosome, not an 80S one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0772' AND answer = 3;
UPDATE questions SET why = 'A bacterium has a single, circular, double-stranded DNA molecule lying in an irregular dense region of the cytoplasm called the nucleoid. This DNA has no histones attached and no nuclear membrane around it, and is sometimes called the bacterial chromosome.', wrong = '{"0": "Several linear DNA molecules wrapped on histones describe eukaryotic chromosomes.", "1": "The genetic material of bacteria is double-stranded DNA, not single-stranded RNA.", "3": "Bacteria are prokaryotes. Their nucleoid has no nuclear membrane around it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0773' AND answer = 2;
UPDATE questions SET why = 'Plasmids are small, circular, double-stranded DNA molecules found outside the bacterial chromosome. They replicate on their own and often carry genes for resistance, for example to antibiotics. They are also used as vectors in genetic engineering.', wrong = '{"1": "Plasmids are made of DNA, and they are circular, not linear RNA.", "2": "In peptidoglycan the glycan chains are cross-linked by short peptides. Plasmids are DNA, not proteins.", "3": "Infoldings of the bacterial cell membrane are mesosomes, not plasmids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0774' AND answer = 0;
UPDATE questions SET why = 'Bacterial cytoplasm contains dissolved substances, the nucleoid, ribosomes and mesosomes. It has no cytoskeleton and no membrane-bounded organelles such as mitochondria or endoplasmic reticulum.', wrong = '{"0": "Ribosomes are present in bacterial cytoplasm, many dispersed freely and some attached to the membrane.", "2": "The nucleoid, which holds the circular DNA, is present in the bacterial cytoplasm.", "3": "The cytoplasm contains many dissolved substances, such as nutrients and enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0775' AND answer = 1;
UPDATE questions SET why = 'Endospores are specialised resting cells formed by some bacteria to survive harsh conditions. They are thick-walled and metabolically inactive (dormant), and germinate into a new vegetative cell when conditions improve.', wrong = '{"0": "Endospores are dormant and do not divide. Active division is a feature of vegetative cells.", "2": "Endospores are not gametes. They do not fuse, and one endospore simply forms one new cell.", "3": "Endospores are dormant and do not swim. They have no working flagella."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0776' AND answer = 1;
UPDATE questions SET why = 'When conditions turn unfavourable, the bacterium first replicates its DNA. The cell membrane then grows inward as a septum, separating the new DNA and a small portion of cytoplasm from the rest of the cell. This is the first step of sporulation.', wrong = '{"1": "The spore coat forms late, around the developing spore, after the peptidoglycan layer.", "2": "A capsule is a gelatinous layer outside some bacterial walls. It plays no part in sporulation.", "3": "The new peptidoglycan layer forms later, between the two membranes around the new DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0777' AND answer = 0;
UPDATE questions SET why = 'During sporulation the membrane grows around the new DNA and cytoplasm, so they are wrapped in two membranes. A new peptidoglycan layer is then laid down between these two membranes, and a spore coat forms around the outside.', wrong = '{"0": "The spore coat is the outermost layer. The peptidoglycan layer forms inside it, between the membranes.", "1": "The nucleoid is the DNA region. No peptidoglycan is formed inside it.", "3": "The new layer forms around the developing spore, not outside the old cell wall, which later breaks to release the spore."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0778' AND answer = 2;
UPDATE questions SET why = 'Swarming is movement of a whole bacterial population together by means of their flagella. It lets the colony spread quickly across a moist surface.', wrong = '{"0": "Twitching is crawling over surfaces using pili that attach and retract, not group movement by flagella.", "1": "Gliding is smooth movement over solid surfaces helped by a slimy secretion.", "2": "Sliding is spreading caused by the pushing force of dividing cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0779' AND answer = 3;
UPDATE questions SET why = 'Twitching, or crawling, is used to move over surfaces. Pili attach to the surrounding solid surface and then retract, which pulls the bacterial cell forward in short jerks.', wrong = '{"0": "Counterclockwise rotation of flagella drives swimming in liquid, not twitching.", "1": "Secretion of slime allows gliding over solid surfaces.", "2": "The axial filament is a modified internal flagellum that moves spirochaetes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0780' AND answer = 3;
UPDATE questions SET why = 'A bacterial flagellum works like a rotating propeller. Counterclockwise rotation pushes the cell forward through liquid with the flagellum trailing behind it.', wrong = '{"1": "Clockwise rotation is not what drives the cell forward. Forward swimming is produced by counterclockwise rotation.", "2": "Bacterial flagella rotate. They do not beat back and forth like a whip, as eukaryotic flagella do.", "3": "Flagella allow swimming in liquid media. They do not need attachment to a surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0781' AND answer = 0;
UPDATE questions SET why = 'Sliding is a passive movement over surfaces. As cells keep dividing, the growing colony expands, and the pushing force of the dividing cells moves the cells outward.', wrong = '{"0": "Retraction of pili produces twitching or crawling movement.", "1": "Rotation of flagella produces swimming and swarming.", "3": "Random movement caused by particles in the fluid is Brownian movement."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0782' AND answer = 2;
UPDATE questions SET why = 'Bacteria such as Streptococcus have neither flagella nor pili, so they cannot swim, swarm or twitch. They move only by Brownian movement, which is random motion caused by the particles of the fluid around them bumping into them.', wrong = '{"0": "Gliding needs the secretion of a slimy substance over a surface. It is not the movement given for Streptococcus.", "2": "Swarming is group movement using flagella, which Streptococcus lacks.", "3": "An axial filament is a modified flagellum found in spirochaetes, not in Streptococcus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0783' AND answer = 1;
UPDATE questions SET why = 'In spirochaetes the flagellum is modified into an axial filament. It runs lengthwise in the periplasmic space, between the cell membrane and the outer membrane, and is made of two sets of fibrils anchored at the two poles. It lets the cell flex, spin and creep.', wrong = '{"0": "The axial filament is internal, inside the outer membrane. It does not stick out like an external whip.", "2": "The nucleoid contains DNA. The axial filament is not part of it.", "3": "The axial filament lies beneath the outer membrane, not in a capsule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0784' AND answer = 1;
UPDATE questions SET why = 'Bacteria are named by the number and position of their flagella. Lophotrichous bacteria have a tuft (group) of flagella at one pole.', wrong = '{"0": "Monotrichous bacteria have a single flagellum at one pole.", "1": "Amphitrichous bacteria have flagella at both poles.", "2": "Peritrichous bacteria have flagella all around the cell surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0785' AND answer = 3;
UPDATE questions SET why = 'Bacteria that have no flagella at all are called atrichous (a- means without). Those with flagella are named by their arrangement, such as monotrichous or peritrichous.', wrong = '{"0": "Peritrichous bacteria have flagella spread all over the cell.", "1": "Monotrichous bacteria have a single flagellum at one pole.", "3": "Lophotrichous bacteria have a tuft of flagella at one pole."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0786' AND answer = 2;
UPDATE questions SET why = 'Pili (singular pilus) are non-helical, filamentous appendages that are smaller and thinner than flagella. They are used mainly for attachment to surfaces, and some help in exchanging genetic material between bacteria.', wrong = '{"1": "Pili are shorter and thinner than flagella. Swimming is the job of flagella.", "2": "The 9+2 microtubule pattern is found only in eukaryotic flagella and cilia, not in bacterial pili.", "3": "Pili are found in many bacteria. They are not limited to archaea."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0787' AND answer = 0;
UPDATE questions SET why = 'Bacterial flagella are entirely different from eukaryotic ones. They are made of a protein called flagellin and are not built on the 9+2 microtubule pattern. Each has a basal body, a hook and a filament.', wrong = '{"0": "The 9+2 arrangement of microtubules belongs to eukaryotic flagella and cilia.", "1": "Tubulin builds the microtubules of eukaryotic flagella. Bacterial flagella are made of flagellin.", "3": "Being covered by the cell membrane is a feature of eukaryotic flagella. Bacterial flagella stick out from the cell surface."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0788' AND answer = 2;
UPDATE questions SET why = 'The basal body anchors the flagellum in the cell membrane and wall with rotating rings. Gram-negative bacteria have two pairs of rings, while Gram-positive bacteria have only one pair.', wrong = '{"1": "One pair of rings is found in Gram-positive bacteria, which have a simpler wall.", "2": "Bacterial flagella have no microtubules. A 9+2 core belongs to eukaryotic flagella.", "3": "The basal body is built of rotating rings, which anchor and turn the flagellum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0789' AND answer = 0;
UPDATE questions SET why = 'A bacterial flagellum has three parts: a basal body anchored in the membrane and wall, a long filament, and a curved hook that connects the basal body to the filament.', wrong = '{"0": "Pili are separate thin appendages used for attachment. They are not part of a flagellum.", "2": "The axial filament is the modified internal flagellum of spirochaetes, not the link in an ordinary flagellum.", "3": "An end plate is part of the tail of the T4 bacteriophage, not of a bacterial flagellum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0790' AND answer = 1;
UPDATE questions SET why = 'Lynn Margulis and Karlene Schwartz proposed a useful classification system for all prokaryotes that divides them into 16 phyla. Important bacterial groups in it include omnibacteria, cyanobacteria, spirochaetes and actinomycetes.', wrong = '{"0": "Five kingdoms is Whittaker''s 1969 system for all living organisms, not only prokaryotes.", "1": "Three domains is Carl Woese''s 1990 system for all living organisms.", "2": "Eight classes is not the scheme proposed by Margulis and Schwartz."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0791' AND answer = 3;
UPDATE questions SET why = 'Omnibacteria are rigid, rod-shaped, heterotrophic, Gram-negative bacteria. Most have flagella, do not form spores and are usually aerobic. Escherichia coli is an example, and the group also includes many pathogens and the vibrios.', wrong = '{"0": "Pseudomonads are Gram-negative rods with polar flagella, such as Pseudomonas aeruginosa.", "1": "Actinomycetes are filamentous bacteria, such as Mycobacterium and Streptomyces.", "3": "Spirochaetes are long spiral bacteria such as Treponema, the cause of syphilis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0792' AND answer = 2;
UPDATE questions SET why = 'Many cyanobacteria fix atmospheric nitrogen in special thick-walled cells called heterocysts. These cells keep out oxygen, which would damage the nitrogen-fixing enzyme.', wrong = '{"0": "Endospores are dormant, thick-walled resting cells formed by some bacteria to survive harsh conditions.", "1": "Mesosomes are infoldings of the bacterial cell membrane linked with respiration and cell division.", "2": "Gemmules are resistant reproductive capsules of sponges."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0793' AND answer = 3;
UPDATE questions SET why = 'Cyanobacteria are photosynthetic bacteria. Along with chlorophyll a, they contain accessory pigments such as carotenoids and blue and red phycobilins, which give their blooms colour.', wrong = '{"1": "Chlorophyll b is found in plants and green algae. Cyanobacteria use chlorophyll a with carotenoids and phycobilins.", "2": "Haemoglobin is an oxygen-carrying pigment of animal blood, not a photosynthetic pigment.", "3": "Melanin is a dark pigment of animal skin and hair, not an accessory pigment of cyanobacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0794' AND answer = 0;
UPDATE questions SET why = 'Penicillin works by blocking the growth of the bacterial cell wall. Mycoplasmas have no cell wall at all, so penicillin and other antibiotics that inhibit wall growth have nothing to act on.', wrong = '{"0": "A capsule is not the reason. Their resistance comes from having no cell wall for penicillin to act on.", "2": "Mycoplasmas are not known for endospores. Their resistance comes from lacking a wall.", "3": "Mycoplasmas have no cell wall, and so no outer membrane with porins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0795' AND answer = 1;
UPDATE questions SET why = 'Spiroplasmas, like mycoplasmas, are bacteria without cell walls. Spiroplasmas are important plant pathogens, and lethal yellowing of coconuts is the example of a plant disease given for this group.', wrong = '{"1": "Mycoplasmas are the wall-less bacteria linked with diseases of mammals, such as certain types of pneumonia in humans.", "2": "Pseudomonads include many plant pathogens, but they are not the group named for lethal yellowing of coconuts.", "3": "Actinomycetes are filamentous bacteria linked with tuberculosis, leprosy and dental plaque, and are sources of antibiotics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0796' AND answer = 0;
UPDATE questions SET why = 'Spirochaetes are long, spiral bacteria with Gram-negative walls, which move using axial filaments. Treponema is an important spirochaete that causes syphilis, a serious sexually transmitted disease.', wrong = '{"0": "Omnibacteria are rigid Gram-negative rods such as E. coli, not spiral bacteria.", "2": "Actinomycetes are filamentous bacteria such as Mycobacterium, which causes tuberculosis.", "3": "Cyanobacteria are photosynthetic bacteria. They do not cause syphilis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0797' AND answer = 1;
UPDATE questions SET why = 'Actinomycetes are filamentous bacteria that form resistant spores. Two members cause serious human diseases: Mycobacterium leprae causes leprosy and Mycobacterium tuberculosis causes tuberculosis.', wrong = '{"0": "Pseudomonads are Gram-negative rods of soil and water, such as Pseudomonas aeruginosa. They do not cause leprosy or TB.", "1": "Spirochaetes are spiral bacteria such as Treponema, which causes syphilis.", "2": "Omnibacteria are Gram-negative rods such as E. coli."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0798' AND answer = 3;
UPDATE questions SET why = 'Some actinomycetes are responsible for dental plaque, in which the enamel of the teeth is destroyed. This group also includes the bacteria of TB and leprosy and is the original source of many antibiotics.', wrong = '{"0": "Lethal yellowing of coconuts is a plant disease linked with spiroplasmas, not actinomycetes.", "1": "Syphilis is caused by Treponema, a spirochaete.", "3": "Pneumonia is linked with some mycoplasmas, and they do not cause lethal pneumonia in all mammals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0799' AND answer = 2;
UPDATE questions SET why = 'Nitrosomonas and Nitrobacter are chemosynthetic bacteria. They get energy by oxidising inorganic nitrogen compounds, ammonia to nitrite and nitrite to nitrate, and use this energy to make their food. This makes them vital in the nitrogen cycle.', wrong = '{"1": "They are not photosynthetic. Their energy comes from chemical reactions, not sunlight.", "2": "Decomposing dead matter is the role of decomposer (heterotrophic) bacteria.", "3": "Heterocysts are special nitrogen-fixing cells of cyanobacteria, not of Nitrosomonas or Nitrobacter."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0800' AND answer = 0;
UPDATE questions SET why = 'Azotobacter is a free-living, nitrogen-fixing aerobic bacterium found in soil and water. Like others in this group, it is Gram-negative and usually flagellated, and it converts atmospheric nitrogen into compounds plants can use.', wrong = '{"0": "Chemosynthetic bacteria oxidise compounds of nitrogen, sulphur or iron for energy, as Nitrosomonas does. Azotobacter fixes N₂ instead.", "2": "Azotobacter is not a cyanobacterium. Cyanobacteria are photosynthetic and fix nitrogen in heterocysts.", "3": "Azotobacter has a normal cell wall. Mycoplasmas are the bacteria without walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0801' AND answer = 1;
UPDATE questions SET why = 'Bacteria such as Lactobacillus, working together with yeasts and moulds, have been used for thousands of years to make fermented foods. Examples include yogurt, cheese, pickles, soy sauce and vinegar.', wrong = '{"0": "Tetracycline and several other antibiotics were first obtained from actinomycetes, not Lactobacillus.", "1": "The main bacterial biopesticide is Bacillus thuringiensis.", "3": "Insulin is made by bacteria into which human genes have been inserted. This is not the traditional use of Lactobacillus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0802' AND answer = 2;
UPDATE questions SET why = 'Bioremediation is the use of living things, such as bacteria, to remove or break down pollutants. Bacteria that digest petroleum hydrocarbons clean up oil spills, and others treat sewage and industrial toxic wastes.', wrong = '{"0": "Biopesticides are organisms such as Bacillus thuringiensis used to control pests, not to clean up pollution.", "1": "Fermentation is used to make foods such as yogurt and cheese.", "2": "Sporulation is the process by which bacteria form endospores."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0803' AND answer = 3;
UPDATE questions SET why = 'Bacillus thuringiensis, a Gram-positive soil bacterium, is the bacterium most commonly used in biological pest control. These biopesticides are environmentally friendly and have little or no effect on humans, wildlife or pollinators.', wrong = '{"0": "E. coli is used widely in research and genetic engineering, not as a biopesticide.", "2": "Treponema pallidum is a spirochaete that causes syphilis.", "3": "Pseudomonas aeruginosa lives in soil and water and can cause serious infections in weak people. It is not used as a biopesticide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0804' AND answer = 1;
UPDATE questions SET why = 'Bacteria grow quickly and are easy to manipulate in the laboratory. Scientists make mutations in bacterial DNA and study the effects to learn what genes and enzymes do, and also insert human genes to make proteins such as insulin.', wrong = '{"0": "Bacteria are prokaryotes, not eukaryotes.", "1": "Bacteria do have DNA, a circular chromosome and often plasmids. Studying this DNA is the main reason they are used.", "3": "Bacteria can mutate. Scientists deliberately make mutations in them to study gene function."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0805' AND answer = 2;
UPDATE questions SET why = 'Surface tissues such as skin and mucous membranes are in constant contact with the environment and are colonised by microbes. The mixture of organisms regularly found at any such anatomical site is called the normal flora.', wrong = '{"0": "Pathogen load refers to disease-causing microbes. Normal flora live with us harmlessly and are mostly mutualistic.", "1": "A biofilm is a slimy layer of microbes stuck to a surface. It is not the term for the usual microbes of a body site.", "2": "Plankton are tiny organisms drifting in water, not microbes living on the body."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0806' AND answer = 3;
UPDATE questions SET why = 'In a healthy animal, internal tissues such as blood, brain and muscle are normally free of microorganisms. Only surface tissues, which touch the environment, are colonised by normal flora.', wrong = '{"1": "Skin is a surface tissue in contact with the environment, so it is colonised by normal flora.", "2": "Mucous membranes of the mouth are exposed to the environment and are colonised by many microbes.", "3": "The large intestine is open to the outside through the gut and holds a very large population of bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0807' AND answer = 0;
UPDATE questions SET why = 'Bacteria in the alimentary canal make vitamins in excess of their own needs. Enteric (gut) bacteria secrete vitamin K and vitamin B12, which are absorbed and distributed in the body. Lactic acid bacteria also produce some B vitamins.', wrong = '{"1": "Vitamin C comes mainly from fruit and vegetables, and vitamin D is made in the skin in sunlight. Neither is a gut bacterial product.", "2": "Insulin is made by the pancreas. Bacteria make it only when human genes are inserted in the laboratory.", "3": "Bile salts are made by the liver, not by intestinal bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0808' AND answer = 0;
UPDATE questions SET why = 'Normal flora occupy attachment sites and use the nutrients available there. Because they compete with pathogens for these sites and nutrients, pathogens have less chance of settling and entering body tissues.', wrong = '{"0": "Normal flora do not destroy antibodies. They actually stimulate low levels of antibodies that cross-react with certain pathogens.", "2": "Normal flora help the body. Their substances inhibit or kill pathogens rather than damaging the gut.", "3": "Normal flora supply vitamins such as K and B12. They do not block vitamin absorption."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0809' AND answer = 1;
UPDATE questions SET why = 'Viruses are extremely small and can be seen only with an electron microscope. They range from about 20 nm (parvovirus) to 250 nm (poxviruses), making them 10 to 1000 times smaller than most bacteria.', wrong = '{"0": "0.1 µm to over 15 µm is the size range of archaeans, which are cells and much larger than viruses.", "1": "2 to 25 µm is the size of cells, far larger than any virus.", "3": "200 to 2,500 nm is too large. Even the largest viruses given, poxviruses, are about 250 nm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0810' AND answer = 2;
UPDATE questions SET why = 'The capsid is the protein coat around the viral nucleic acid. It is built from many protein subunits called capsomeres, and the number and kind of capsomeres is characteristic of each virus.', wrong = '{"0": "A virion is a complete virus particle, not one protein subunit of its coat.", "1": "The nucleocapsid is the nucleic acid core together with the whole capsid.", "2": "Spikes are glycoproteins projecting from the envelope of some viruses, such as HIV."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0811' AND answer = 3;
UPDATE questions SET why = 'A virus has a central core of nucleic acid (DNA or RNA) surrounded by a protein coat called the capsid. The core and capsid together are called the nucleocapsid.', wrong = '{"0": "The envelope is an extra lipid-rich membrane from the host cell that surrounds the nucleocapsid in some animal viruses.", "1": "A capsomere is only one protein subunit of the capsid.", "3": "A prion is an infectious particle made only of protein, not a part of a virus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0812' AND answer = 2;
UPDATE questions SET why = 'Each virus has a characteristic number of capsomeres in its capsid. The adenovirus, which can cause a common cold, has 252 capsomeres in its capsid.', wrong = '{"0": "Six is the number of tail fibres on a T4 bacteriophage, not adenovirus capsomeres.", "1": "Twenty is the number of faces of an icosahedron, the shape of the adenovirus capsid, not its number of capsomeres.", "2": "162 capsomeres is the figure usually given for herpesvirus capsids, not adenovirus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0813' AND answer = 3;
UPDATE questions SET why = 'In some animal viruses the nucleocapsid is covered by a lipid-rich envelope from the host cell. Viruses without this envelope consist only of a capsid around nucleic acid and are called naked viruses, as in poliovirus and adenovirus.', wrong = '{"0": "Prions are infectious particles made only of protein. They are not viruses at all.", "2": "Bacteriophages are viruses that infect bacteria. The name refers to their host, not to the absence of an envelope.", "3": "Retroviruses such as HIV have a lipid envelope, so they are not naked."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0814' AND answer = 1;
UPDATE questions SET why = 'A T4 phage has a head and a tail. At the end of the tail sheath is an end plate with six tail fibres attached, and these fibres help the phage attach to the bacterial cell wall before it injects its DNA.', wrong = '{"1": "Glycoprotein spikes on a lipid envelope are found in HIV. T4 phage has no envelope.", "2": "The hexagonal head holds the phage DNA. It does not attach to the bacterium.", "3": "Reverse transcriptase is the enzyme of retroviruses such as HIV, not of T4 phage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0815' AND answer = 0;
UPDATE questions SET why = 'The head of a T4 phage is an elongated hexagonal, prism-shaped capsid made of proteins. Its core contains a long double-stranded DNA molecule, which is injected into the host bacterium.', wrong = '{"0": "Single-stranded RNA is the genome of retroviruses such as HIV, not T4 phage.", "1": "RNA together with reverse transcriptase is found in HIV.", "3": "Particles made of protein only are prions. A phage head contains DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0816' AND answer = 2;
UPDATE questions SET why = 'In genetic engineering, a gene of interest is inserted into the phage DNA. The phage carries it into the target bacterium, and when the phage DNA joins the bacterial chromosome the gene becomes part of it. These transgenic bacteria then make copies of the gene or the protein.', wrong = '{"0": "Making bacteria resistant to all viruses is not how phages are used. They are used as carriers of genes.", "1": "In this use the phage DNA joins the bacterial chromosome. It does not destroy all the bacterial DNA.", "2": "Phages do not produce antibiotics. Many antibiotics come from actinomycetes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0817' AND answer = 3;
UPDATE questions SET why = 'Human immunodeficiency virus (HIV) belongs to the retroviruses, a special group of animal viruses. Retroviruses have an RNA genome and the enzyme reverse transcriptase, which copies RNA into DNA.', wrong = '{"1": "Bacteriophages are viruses that infect bacteria. HIV infects human cells.", "2": "Parvoviruses are small single-stranded DNA viruses that cause gastroenteritis.", "3": "Adenoviruses are naked double-stranded DNA viruses with an icosahedral capsid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0818' AND answer = 0;
UPDATE questions SET why = 'HIV''s lipid-rich envelope carries glycoprotein spikes. These spikes help the virus identify its target cell and bind to it, which is the first step of infection.', wrong = '{"0": "Copying RNA into DNA is the job of the enzyme reverse transcriptase, inside the capsid.", "2": "The capsid is the protein coat inside the envelope. The spikes are on the outside of the envelope.", "3": "The viral genome is RNA held inside the capsid. Spikes do not store it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0819' AND answer = 1;
UPDATE questions SET why = 'HIV is a spherical retrovirus about 100 nm in diameter, which places it between the smallest viruses (about 20 nm) and the largest (about 250 nm).', wrong = '{"0": "1,000 nm (1 µm) is roughly the size of a bacterium, about ten times larger than HIV.", "1": "20 nm is the size of parvovirus, one of the smallest viruses.", "3": "250 nm is the size of poxviruses, the largest viruses given."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0820' AND answer = 2;
UPDATE questions SET why = 'Reverse transcriptase carries out reverse transcription. It uses a single-stranded RNA template to make a strand of DNA, then uses that DNA strand to complete a DNA double helix. This is the opposite direction to normal transcription.', wrong = '{"0": "Making RNA from a DNA template is ordinary transcription, done by RNA polymerase.", "1": "Making protein from mRNA is translation, which takes place on ribosomes.", "2": "The lipid envelope of HIV comes from the host cell membrane. No enzyme builds it from RNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0821' AND answer = 3;
UPDATE questions SET why = 'AIDS was first reported in 1981. In 1984 scientists found that the cause was a virus, and in 1986 this virus was named human immunodeficiency virus (HIV).', wrong = '{"0": "AIDS was first reported in 1981, not 1990.", "1": "In 1984 the agent of AIDS was found to be a virus, not a bacterium.", "3": "HIV is host-specific. It can multiply in monkeys but does not cause AIDS in them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0822' AND answer = 2;
UPDATE questions SET why = 'HIV attacks the immune system and weakens it. Without a working immune system, the body cannot defend itself against other viral and bacterial infections, and these infections are what make AIDS fatal.', wrong = '{"0": "HIV does not mainly destroy red blood cells. It damages the immune system.", "1": "HIV does not block the airways. Lung infections may occur only because immunity is lost.", "2": "HIV does not directly destroy the kidneys. Death results from infections after immunity is weakened."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0823' AND answer = 3;
UPDATE questions SET why = 'Homeostasis is keeping a stable internal environment. Cells achieve it by controlling which substances enter and leave through their membranes, keeping the right amounts of water, ions and nutrients inside.', wrong = '{"0": "Meiosis is cell division that forms gametes for sexual reproduction. It does not keep the internal environment stable.", "1": "Producing gametes is part of reproduction, a different property of life.", "2": "Flagella are used for movement, as in sperm cells, not for keeping internal conditions stable."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0824' AND answer = 3;
UPDATE questions SET why = 'In 1665 Robert Hooke examined a thin slice of cork under his microscope and saw many little boxes. He found the same in stems and roots, concluded that plant parts are made of compartments, and named them "cellulae", from which the word cell comes.', wrong = '{"0": "\"Animalcules\" was the name Anton van Leeuwenhoek gave to living cells he saw in pond water in 1673.", "1": "The nucleus was discovered later, in 1831, by Robert Brown.", "3": "A protoplast is what remains of a cell after its wall is removed by enzymes, not Hooke''s term."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0825' AND answer = 2;
UPDATE questions SET why = 'In 1831 the British botanist Robert Brown discovered the nucleus in plant cells. This came after Hooke''s cork cells (1665) and before Schleiden and Schwann''s work that led to the cell theory.', wrong = '{"0": "Robert Hooke described the little boxes in cork in 1665. He did not see the nucleus.", "2": "Theodor Schwann concluded in 1839 that animals are made of cells.", "3": "Anton van Leeuwenhoek observed living cells (animalcules) in pond water in 1673."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0826' AND answer = 1;
UPDATE questions SET why = 'In 1838 the German botanist Matthias Schleiden studied many plant parts under the microscope and concluded that all plants are composed of cells. The next year Theodor Schwann reached the same conclusion for animals.', wrong = '{"1": "Theodor Schwann, a zoologist, made the same conclusion for animals in 1839, not for plants.", "2": "Rudolf Virchow observed that all cells come from pre-existing cells.", "3": "Louis Pasteur gave experimental proof in 1862 that cells come only from other cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0827' AND answer = 0;
UPDATE questions SET why = 'Rudolf Virchow observed that all cells come from other cells. In 1862 Louis Pasteur provided the experimental proof of this idea, which became the third point of the cell theory: cells come only from pre-existing cells.', wrong = '{"0": "Virchow made the observation that cells come from cells, but the experimental proof came from Pasteur.", "2": "Robert Brown discovered the nucleus in 1831.", "3": "Lamarck observed cells in plant and animal parts in 1809. He did not prove that cells come from cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0828' AND answer = 1;
UPDATE questions SET why = 'In vertebrates, muscle cells (myocytes) fuse together to form long fibres with many nuclei. This challenges the idea of a single cell as the basic unit of complex tissues. Other exceptions include viruses, prions, organelles with their own DNA and multinucleate fungi and algae.', wrong = '{"0": "Red blood cells carrying oxygen are ordinary cells doing their job. They are not listed as an exception.", "1": "Bacteria dividing by binary fission produce cells from pre-existing cells, which fits the cell theory exactly.", "3": "A cellulose wall is a normal feature of plant cells. It does not conflict with the cell theory."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0829' AND answer = 2;
UPDATE questions SET why = 'Mitochondria and chloroplasts have their own DNA and can replicate independently of the cell''s nucleus. This behaviour, like that of separate cells, suggests they began as free-living prokaryotes, which is why they are counted among the exceptions.', wrong = '{"0": "Both organelles are bounded by a double membrane, so they do have membranes.", "1": "Particles made only of protein are prions. Mitochondria and chloroplasts contain DNA, lipids and proteins.", "2": "Mitochondria and chloroplasts are found inside eukaryotic cells, not outside them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0830' AND answer = 3;
UPDATE questions SET why = 'Resolution is a microscope''s ability to distinguish two points that are close together as separate. Higher resolution shows finer detail. The naked eye resolves about 0.1 mm, while a light microscope resolves about 0.2 µm.', wrong = '{"1": "Magnification is how many times larger the image appears than the object, not the ability to separate close points.", "2": "Focal length is a property of a lens. It is not the term for separating two close points.", "3": "Illumination is the light or electron beam that lights the specimen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0831' AND answer = 0;
UPDATE questions SET why = 'Total magnification is found by multiplying the magnifications of all the lenses. For example, a 10X eyepiece with a 40X objective gives 10 × 40 = 400X.', wrong = '{"0": "Adding is wrong. A 10X eyepiece with a 40X objective gives 400X, not 50X.", "1": "Division is not used. Each lens enlarges the image further, so the values are multiplied.", "2": "Both the objective and the eyepiece enlarge the image, so both must be counted."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0832' AND answer = 3;
UPDATE questions SET why = 'The light microscope has a resolving power of about 0.2 micrometre (0.2 µm, where 1 µm = 1/1000 mm). It cannot distinguish objects smaller than this, and its magnification is about 1500X.', wrong = '{"0": "0.2 nm is the resolving power of the electron microscope, about 1000 times finer.", "1": "About 0.1 mm is the resolution of the naked human eye. 1 mm is coarser still.", "3": "2 µm is ten times coarser than the light microscope''s resolving power of 0.2 µm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0833' AND answer = 2;
UPDATE questions SET why = 'To be viewed in an electron microscope, specimens must be fixed, dried and sliced or coated, and placed in a vacuum. These preparation methods kill the cells, so only dead material can be viewed.', wrong = '{"0": "Electrons can pass through very thin specimens. This is how the transmission electron microscope works.", "2": "Its resolution is very high, about 0.2 nm, much better than a light microscope.", "3": "The electron microscope uses a beam of electrons focused by magnetic lenses, not visible light."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0834' AND answer = 1;
UPDATE questions SET why = 'The scanning electron microscope (SEM) studies surface details. The specimen is coated with metal, and electrons reflected from the surface form a three-dimensional-looking image. It can magnify up to about 100,000 times.', wrong = '{"1": "Viewing internal structure in very thin sections is the job of the transmission electron microscope (TEM).", "2": "No electron microscope can view living cells, because specimen preparation kills them.", "3": "Electron microscope images are not coloured by stains. Stained colours are seen with a light microscope."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0835' AND answer = 0;
UPDATE questions SET why = 'The transmission electron microscope (TEM) passes electrons through a very thin specimen and can magnify objects up to about 250,000 times. By comparison, the SEM reaches about 100,000 times and the light microscope about 1500 times.', wrong = '{"0": "About 1500 times is the magnification of the light microscope.", "1": "Ten million times is far beyond the value given for the TEM.", "2": "100,000 times is the magnification given for the scanning electron microscope (SEM)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0836' AND answer = 3;
UPDATE questions SET why = 'Human eyes cannot see electrons, so the electron beam is made visible on a zinc sulphate fluorescent screen, which glows where electrons strike it. In a light microscope the image is seen directly through the ocular lens.', wrong = '{"0": "The ocular lens (eyepiece) is how the image is viewed in a light microscope.", "1": "A glass slide holds the specimen in a light microscope. It does not display the image.", "2": "The condenser focuses light onto the specimen in a light microscope."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0837' AND answer = 3;
UPDATE questions SET why = 'If cell wall-degrading enzymes remove the wall of a plant, fungal or bacterial cell, what remains is the cell membrane with everything inside it. This wall-less cell is called a protoplast.', wrong = '{"1": "The middle lamella is the pectin-rich layer that holds the walls of neighbouring plant cells together.", "2": "The tonoplast is the membrane around the large vacuole of a plant cell.", "3": "A plasmodesma is a small channel through the cell walls that connects the cytoplasm of neighbouring plant cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0838' AND answer = 0;
UPDATE questions SET why = 'The primary cell wall is made of the polysaccharides cellulose, hemicellulose and pectin, along with many proteins. Its cellulose microfibrils lie at all angles and are held together by hydrogen bonds.', wrong = '{"0": "Lignin with cellulose and hemicellulose makes up the secondary wall, laid down after the cell matures.", "2": "Calcium and magnesium pectates form the middle lamella between neighbouring cells, not the primary wall.", "3": "Chitin is the cell wall material of fungi."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0839' AND answer = 1;
UPDATE questions SET why = 'The middle lamella is a gelatinous layer that holds the primary walls of neighbouring cells together. It forms first, from the cell plate during cytokinesis, and is made mainly of calcium and magnesium pectates (salts of pectic acid).', wrong = '{"0": "Lignin is found in the secondary wall, making it rigid.", "1": "Cellulose microfibrils are the main structural part of the primary wall.", "3": "Peptidoglycan is the cell wall polymer of bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0840' AND answer = 2;
UPDATE questions SET why = 'After some plant cells mature, a secondary wall is laid down between the plasma membrane and the primary wall. It contains lignin along with cellulose and hemicellulose, and the lignin makes it more rigid than the primary wall, as in wood.', wrong = '{"1": "Pectin is found in the primary wall and middle lamella. It does not give the secondary wall its rigidity.", "2": "Chitin is the wall material of fungi, not plants.", "3": "Silica walls are made by diatoms, a group of algae."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0841' AND answer = 0;
UPDATE questions SET why = 'Plasmodesmata are formed during cell division. When the new cell wall is laid down between the two daughter cells, parts of the parent cell''s endoplasmic reticulum get trapped in it. These leave channels that connect the cytoplasm of neighbouring cells.', wrong = '{"0": "The breakdown of the nuclear envelope during division does not create channels through the cell wall.", "2": "Golgi vesicles fusing with the plasma membrane is exocytosis, which releases materials from the cell.", "3": "Lignin deposition forms the rigid secondary wall. It does not create channels between cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0842' AND answer = 1;
UPDATE questions SET why = 'Diatoms, a group of algae, make their cell walls from silicic acid. The acid is polymerised inside the cell into silica and the wall is extruded. Silica walls need less energy to make, which helps diatoms grow fast.', wrong = '{"0": "Algal walls generally contain cellulose and glycoproteins, but diatoms build theirs from silica.", "1": "Chitin is the wall material of fungi.", "3": "Peptidoglycan is the wall material of bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0843' AND answer = 2;
UPDATE questions SET why = 'The fluid mosaic model was proposed in 1972 by the American biologists S. J. Singer and Garth Nicolson. It describes the membrane as a fluid lipid bilayer with a mosaic of proteins floating in it.', wrong = '{"0": "Schleiden and Schwann concluded in 1838 and 1839 that plants and animals are made of cells.", "1": "Watson and Crick proposed the double-helix model of DNA.", "2": "Margulis and Schwartz classified the prokaryotes into 16 phyla."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0844' AND answer = 3;
UPDATE questions SET why = 'Phospholipids have a hydrophilic (water-loving) phosphate head and hydrophobic (water-fearing) tails. In the bilayer the tails point inwards, away from water, while the heads face outwards toward the cytoplasm or the extracellular fluid.', wrong = '{"1": "This is the reverse. Heads facing inwards would put the water-fearing tails in contact with water on both sides.", "2": "The membrane is a bilayer of two layers, not a single flat layer.", "3": "The tails of both layers face each other in the middle of the bilayer. They do not face the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0845' AND answer = 0;
UPDATE questions SET why = 'In eukaryotic plasma membranes, cholesterol molecules are wedged between the phospholipids. They stop the phospholipids packing too tightly, which keeps the membrane fluid at low temperatures.', wrong = '{"0": "Receptor proteins, not cholesterol, bind messenger molecules such as hormones.", "2": "Channel proteins form passages that let ions cross the membrane.", "3": "Certain membrane proteins attach the membrane to the cytoskeleton and external fibres."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0846' AND answer = 1;
UPDATE questions SET why = 'On the outer surface of the membrane, sugars are attached to proteins (glycoproteins) and lipids (glycolipids). Together they are called the glycocalyx, and they act as identification marks that other cells recognise.', wrong = '{"0": "The cytoskeleton is a network of protein fibres inside the cell that gives support and shape.", "1": "The middle lamella is the pectin layer that holds neighbouring plant cell walls together.", "3": "The nuclear lamina is a protein lining on the inner side of the nuclear envelope."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0847' AND answer = 2;
UPDATE questions SET why = 'The plasma membrane is semi-permeable. Small molecules such as oxygen, carbon dioxide and water can pass freely across it, while the passage of larger molecules such as amino acids and sugars is carefully regulated.', wrong = '{"0": "Amino acids and sugars are larger molecules whose passage is carefully regulated by membrane proteins.", "1": "Proteins and nucleic acids are very large molecules. They cannot pass freely across the membrane.", "2": "Starch and glycogen are large polysaccharides, much too big to cross the membrane freely."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0848' AND answer = 3;
UPDATE questions SET why = 'This technique is fluorescence recovery after photobleaching (FRAP). A laser bleaches a labelled patch of membrane, and fluorescence returns as unbleached molecules move in, showing how mobile the membrane proteins and lipids are.', wrong = '{"1": "The atomic structure of membrane proteins is found by X-ray crystallography.", "2": "The surface topology of cells is studied with the scanning electron microscope or atomic force microscopy.", "3": "Analysing membrane lipids by mass spectrometry is lipidomics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0849' AND answer = 0;
UPDATE questions SET why = 'The cytoplasm provides space for organelles and is the site of many metabolic reactions. Glycolysis, the first stage of respiration in which glucose is broken down, takes place in the cytoplasm.', wrong = '{"0": "The Krebs cycle takes place in the matrix of mitochondria, not in the cytoplasm.", "1": "Photosynthesis takes place inside chloroplasts.", "3": "Mitochondrial DNA is replicated inside the mitochondrion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0850' AND answer = 2;
UPDATE questions SET why = 'The spherical nucleus typically occupies about 10 percent of the volume of a eukaryotic cell. It stores the DNA and controls the cell''s activities, such as growth, protein synthesis and cell division.', wrong = '{"0": "1 percent is too small for the nucleus, which is the most prominent organelle in the cell.", "2": "50 percent is far too large for the nucleus.", "3": "80 percent or more of a mature plant cell can be taken up by the central vacuole, not the nucleus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0851' AND answer = 1;
UPDATE questions SET why = 'The nuclear lamina is a protein lining on the inner side of the nuclear envelope. It binds to chromatin and gives the nucleus structural support.', wrong = '{"0": "The nucleolus is a dark-staining body inside the nucleus that makes ribosomal subunits.", "1": "The perinuclear space is the gap between the two membranes of the nuclear envelope.", "2": "The nuclear basket is made of fibrils on the nuclear side of the pore complex, not a lining of the envelope."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0852' AND answer = 3;
UPDATE questions SET why = 'The nuclear envelope has two membranes with a perinuclear space between them. This space is connected with the lumen of the rough endoplasmic reticulum, so the two form a single compartment.', wrong = '{"0": "The Golgi apparatus is a separate stack of sacs. Its lumen is not joined to the nuclear envelope.", "2": "The mitochondrial matrix is enclosed inside the mitochondrion, separate from the nuclear envelope.", "3": "The cytosol lies outside the nuclear envelope, not between its two membranes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0853' AND answer = 1;
UPDATE questions SET why = 'The nuclear pore complex has several subunits. The lumenal subunit anchors the whole complex into the nuclear envelope, while the others form the pore and its wall.', wrong = '{"1": "The annular subunit surrounds the inside of the pore.", "2": "The column subunit makes the wall of the complex.", "3": "The ring subunit is attached to the outer side of the column subunit."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0854' AND answer = 0;
UPDATE questions SET why = 'Nucleoli form at chromosome sites called nucleolus organizer regions (NORs). The DNA at NORs codes for ribosomal RNA (rRNA), which the nucleolus combines with proteins to make ribosomal subunits.', wrong = '{"0": "Histone proteins are made on ribosomes in the cytoplasm from mRNA. Their genes are not the NOR genes.", "2": "Transfer RNA genes are located elsewhere. NOR DNA codes for ribosomal RNA.", "3": "Nuclear pore proteins are not coded at NORs, which carry the genes for rRNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0855' AND answer = 1;
UPDATE questions SET why = 'Proteins are made on ribosomes, and the nucleolus makes the ribosomal subunits. A cell that produces large amounts of protein needs many ribosomes, so its nucleolus is large.', wrong = '{"0": "Such a cell needs a nucleolus more than most, to make the many ribosomes it uses.", "1": "A protein-making cell needs many ribosomes, not few.", "2": "Cells that make and export much protein usually have extensive rough ER, which is covered with ribosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0856' AND answer = 3;
UPDATE questions SET why = 'Chromatin is made of DNA and proteins arranged as a series of bead-like units called nucleosomes. In each nucleosome the DNA strand wraps around a group of small proteins called histones, which helps pack the long DNA.', wrong = '{"0": "The centromere is the central constricted point of a chromosome that joins its chromatids.", "1": "Chromatids are the arms of a chromosome, each a condensed DNA molecule.", "3": "Nucleoli are bodies in the nucleus that make ribosomal subunits."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0857' AND answer = 2;
UPDATE questions SET why = 'Chromatin exists in two forms. Euchromatin is loosely packed and genetically active, so its genes are transcribed into RNA to make proteins. Heterochromatin is tightly packed and its DNA is genetically inactive.', wrong = '{"1": "Heterochromatin is the tightly packed, genetically inactive form of chromatin.", "2": "The centromere is the central point of a chromosome that joins the chromatids, not a type of active chromatin.", "3": "The nucleolus organizer region is a chromosome site whose DNA codes for rRNA. It is not the general active form of chromatin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0858' AND answer = 0;
UPDATE questions SET why = 'Some ants and roundworms have as few as 2 chromosomes, while the Indian fern Ophioglossum reticulatum has 1,260, and humans have 46. A fern is not more complex than a human, so chromosome number does not correlate with an organism''s complexity.', wrong = '{"0": "Plants do not always have more chromosomes than animals. Many plants have fewer chromosomes than humans.", "1": "Ferns are not the most complex plants. A high chromosome number does not mean high complexity.", "2": "Chromosome number is species-specific. It differs between species, from 2 to more than 1,000."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0859' AND answer = 3;
UPDATE questions SET why = 'The endoplasmic reticulum is a network of flattened sacs and branching tubules called cisternae. All the cisternae are interconnected, so the ER has one large convoluted lumen called the cisternal space.', wrong = '{"0": "Cristae are the infoldings of the inner mitochondrial membrane.", "2": "Thylakoids are disc-shaped membrane compartments inside chloroplasts.", "3": "Grana are stacks of thylakoids in chloroplasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0860' AND answer = 1;
UPDATE questions SET why = 'Smooth ER lacks ribosomes and is chiefly involved in lipid production, carbohydrate metabolism and the detoxification of drugs and poisons. Liver cells detoxify many harmful substances, so their smooth ER is very extensive.', wrong = '{"0": "Ribosomal subunits are made in the nucleolus, not in the smooth ER.", "1": "Digestive enzymes are proteins, made on ribosomes of the rough ER in gland cells.", "3": "Photosynthesis takes place in chloroplasts, which liver cells do not have."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0861' AND answer = 2;
UPDATE questions SET why = 'Smooth ER stores calcium ions and controls their release. In muscle cells, the smooth ER releases calcium, and this calcium triggers muscle contraction.', wrong = '{"0": "Sodium is not the ion the smooth ER stores and releases to start contraction.", "1": "Potassium release from the smooth ER is not what triggers muscle contraction.", "3": "Glucose is a fuel for energy. It is not stored in the smooth ER to trigger contraction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0862' AND answer = 2;
UPDATE questions SET why = 'Ribosomes are tiny granular structures made of about 60 percent ribosomal RNA (rRNA) and 40 percent protein. They are not bound by a membrane and serve as the protein-making machinery of the cell.', wrong = '{"1": "This reverses the proportions. rRNA makes up the larger share, about 60 percent.", "2": "Ribosomes are not pure protein. About 60 percent of their mass is rRNA.", "3": "Ribosomes do not contain DNA. Their nucleic acid is ribosomal RNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0863' AND answer = 0;
UPDATE questions SET why = 'Proteins made by free ribosomes in the cytosol are mainly for the cell''s own internal use. Proteins made by ribosomes bound to the rough ER are processed and mainly transported outside the cell, as secretions.', wrong = '{"0": "Proteins for use inside the cytosol are made mainly by free ribosomes, not those on the rough ER.", "1": "The nucleolus makes ribosomal subunits. It is not where rough ER proteins are packed.", "2": "Bacteria have no endoplasmic reticulum, so RER-bound ribosomes cannot build bacterial walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0864' AND answer = 3;
UPDATE questions SET why = 'Svedberg (S) values measure how fast a particle sinks in a centrifuge. This rate depends on the particle''s size and shape, not simply on its molecular weight, so the S values of two subunits do not add up. For example, 40S + 60S gives an 80S ribosome.', wrong = '{"0": "The subunits do not lose RNA when they join. The values differ because S depends on size and shape.", "2": "Prokaryotic ribosomes also have two subunits, 30S and 50S, which form a 70S ribosome.", "3": "Svedberg units measure the rate of sedimentation, not volume."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0865' AND answer = 1;
UPDATE questions SET why = 'The complete ribosome in the cytoplasm of a eukaryotic cell is 80S. Its small subunit is 40S and its large subunit is 60S. Prokaryotes have smaller 70S ribosomes with 30S and 50S subunits.', wrong = '{"0": "A 70S ribosome with 30S and 50S subunits is found in prokaryotes, and in mitochondria and chloroplasts.", "1": "This mixes the two types. An 80S ribosome has 40S and 60S subunits.", "2": "This also mixes the types. A 70S ribosome has 30S and 50S subunits."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0866' AND answer = 3;
UPDATE questions SET why = 'Mitochondria and chloroplasts contain their own ribosomes. These differ in size and makeup from the 80S ribosomes of the cytoplasm and are more like the 70S ribosomes of prokaryotes, which supports the idea that these organelles came from prokaryotes.', wrong = '{"1": "They are not identical to cytoplasmic 80S ribosomes. They differ in size and makeup.", "2": "Mitochondria and chloroplasts do contain ribosomes, which they use to make some of their own proteins.", "3": "They lie inside the organelle, not on the rough ER, which is outside in the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0867' AND answer = 0;
UPDATE questions SET why = 'The inner surface of the cristae carries knob-like extensions into the matrix called F-1 particles. These particles are the enzyme ATP synthase, which makes ATP during cellular respiration.', wrong = '{"0": "Mitochondrial ribosomes are 70S particles lying in the matrix. They are not the F-1 knobs on the cristae.", "2": "Mitochondrial DNA is a circular molecule in the matrix, not a knob on the cristae.", "3": "Krebs cycle enzymes are dissolved in the matrix. F-1 particles are ATP synthase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0868' AND answer = 1;
UPDATE questions SET why = 'The matrix is the large internal space beneath the inner membrane of a mitochondrion. Enzymes in the matrix catalyse some steps of respiration, such as the Krebs cycle, while the electron transport proteins sit on the inner membrane.', wrong = '{"0": "The outer membrane is smooth and acts like a sieve, filtering out molecules that are too big.", "1": "The intermembrane space is the narrow gap between the two membranes, not where the Krebs cycle runs.", "3": "F-1 particles are ATP synthase enzymes on the cristae, not Krebs cycle enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0869' AND answer = 2;
UPDATE questions SET why = 'A mitochondrion has its own circular DNA, similar to the DNA of prokaryotes, along with all kinds of RNA and 70S ribosomes. It can also replicate independently, which supports the idea that mitochondria came from engulfed prokaryotes.', wrong = '{"0": "Mitochondria have no nucleus or nuclear envelope. Prokaryotes also have no nuclear envelope.", "1": "80S ribosomes are found in the eukaryotic cytoplasm. Mitochondria have 70S ribosomes like prokaryotes.", "2": "Linear chromosomes with histones are found in the eukaryotic nucleus, not in mitochondria or prokaryotes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0870' AND answer = 3;
UPDATE questions SET why = 'Plant cells have three types of plastids. Leucoplasts are colourless and store materials such as starch, chromoplasts give yellow to red colours to plant parts, and chloroplasts are green and carry out photosynthesis.', wrong = '{"1": "Chromoplasts are coloured, yellow to red, and give colour to flowers and fruits.", "2": "Chloroplasts are green because of chlorophyll and carry out photosynthesis.", "3": "Glyoxysomes are not plastids. They are small organelles that convert lipids into carbohydrates in seeds."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0871' AND answer = 0;
UPDATE questions SET why = 'Inside the inner membrane of a chloroplast is a semi-fluid called the stroma. It contains dissolved enzymes, makes up most of the chloroplast''s volume, and is where carbon dioxide is converted into sugars.', wrong = '{"0": "A thylakoid is a disc-shaped membrane compartment inside the stroma that holds chlorophyll.", "2": "A granum is a stack of thylakoids.", "3": "Matrix is the name for the fluid inside a mitochondrion, not a chloroplast."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0872' AND answer = 1;
UPDATE questions SET why = 'In a chloroplast, thylakoids are stacked into grana. The stroma lamellae are non-green membrane extensions that connect one granum to another.', wrong = '{"0": "Cristae are infoldings of the inner membrane of mitochondria.", "1": "Cisternae are the flattened sacs of the endoplasmic reticulum and Golgi apparatus.", "3": "The thylakoid lumen is the space inside a thylakoid, not a link between grana."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0873' AND answer = 2;
UPDATE questions SET why = 'A chloroplast is enclosed by two membranes with an intermembrane space between them. The outer membrane is much more permeable than the inner one, which controls what enters the stroma.', wrong = '{"0": "This reverses the permeability. The outer membrane is the more permeable one.", "1": "Cristae are folds of the inner membrane of mitochondria. Chloroplast membranes do not form cristae.", "2": "A chloroplast has two membranes, not one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0874' AND answer = 3;
UPDATE questions SET why = 'The Golgi apparatus was discovered by the Italian scientist Camillo Golgi. Using his new staining method on nervous tissue, he saw the structure, called it the reticular apparatus and announced it in 1898. The electron microscope later confirmed it was a real organelle.', wrong = '{"0": "Christian de Duve discovered lysosomes and peroxisomes.", "2": "Robert Brown discovered the nucleus in 1831.", "3": "Rudolf Virchow is known for the idea that all cells come from pre-existing cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0875' AND answer = 1;
UPDATE questions SET why = 'Each Golgi stack has two faces. The cis face lies near the endoplasmic reticulum and receives vesicles from it. The trans face lies near the plasma membrane and sends out processed products in vesicles.', wrong = '{"1": "The trans face, not the cis face, is positioned near the plasma membrane.", "2": "The Golgi apparatus lies in the cytoplasm, usually close to the nucleus but not inside it.", "3": "The Golgi apparatus is not inside the vacuole. It is a separate organelle in the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0876' AND answer = 0;
UPDATE questions SET why = 'Besides processing and packaging proteins and lipids, the Golgi apparatus in plant cells produces pectin and other polysaccharides. These are needed for plant structure and metabolism, including the cell wall.', wrong = '{"0": "Cellulose is not made in the nucleus. The nucleus stores DNA and controls the cell.", "1": "Chlorophyll is found in chloroplasts. It is not a Golgi product.", "3": "Lignin is not made in mitochondria, which are the sites of cellular respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0877' AND answer = 2;
UPDATE questions SET why = 'The number of Golgi stacks varies with a cell''s function. Animal cells generally contain between ten and twenty Golgi stacks, each made of five to eight cisternae.', wrong = '{"0": "Animal cells usually contain more than one Golgi stack, generally ten to twenty.", "2": "Sixty is the number of cisternae in the Golgi apparatus of some unicellular flagellates, not the number of stacks.", "3": "Thousands of stacks is far more than the number found in animal cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0878' AND answer = 1;
UPDATE questions SET why = 'Lysosomes are the digestive compartments of the cell. In animals they are most numerous in disease-fighting cells such as white blood cells, which must digest bacteria, viruses and other foreign intruders.', wrong = '{"0": "Mature red blood cells of mammals lose their organelles, including lysosomes, as they develop.", "1": "Bone cells are not the cells with the most lysosomes. Defence cells that digest invaders have more.", "2": "Fat cells mainly store lipid. They are not known for having many lysosomes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0879' AND answer = 3;
UPDATE questions SET why = 'Lysosomal enzymes work only in an acidic environment, about pH 4.8, as inside the lysosome. The cytosol is nearly neutral, so if a lysosome bursts its enzymes become inactive and the cell remains uninjured.', wrong = '{"0": "Ribosomes make proteins. They do not destroy released enzymes.", "1": "A burst lysosome does release its enzymes into the cytosol. They are safe only because they stop working there.", "3": "The cytosol contains many macromolecules, such as proteins. The cell is safe because the enzymes need acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0880' AND answer = 2;
UPDATE questions SET why = 'Lysosomes break down cell materials, including worn-out organelles, that have exceeded their lifetime or are no longer useful. This self-digestion is called autophagy, and the simple products are reused to build new materials.', wrong = '{"1": "Phagocytosis is the engulfing of solid particles such as bacteria from outside the cell.", "2": "Pinocytosis is the taking in of small droplets of fluid from outside the cell.", "3": "Exocytosis releases materials out of the cell in vesicles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0881' AND answer = 0;
UPDATE questions SET why = 'Christian de Duve was studying carbohydrate metabolism in liver cells. He noticed that cells damaged in the centrifuge released the enzyme acid phosphatase, suggested that it was normally enclosed in a membrane-bound organelle, and named that organelle the lysosome.', wrong = '{"0": "Catalase is the enzyme of peroxisomes that breaks down hydrogen peroxide.", "2": "ATP synthase is found as F-1 particles on mitochondrial cristae.", "3": "Acetylcholine is a neurotransmitter, not a lysosomal enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0882' AND answer = 1;
UPDATE questions SET why = 'Pompe''s disease is a lysosomal storage disease in which lysosomes lack the enzyme that digests glycogen. Undigested glycogen builds up to harmful levels in the cells, such as liver and muscle cells, and disturbs their function.', wrong = '{"0": "A missing lipid-digesting enzyme, with lipids building up in brain nerve cells, causes Tay-Sachs disease.", "1": "Hydrogen peroxide is broken down by catalase in peroxisomes, not by lysosomal enzymes.", "3": "The missing enzyme in Pompe''s disease digests glycogen, not proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0883' AND answer = 2;
UPDATE questions SET why = 'Multicellular organisms use selective cell death during development. When a tadpole becomes a frog, the cells of its tail are destroyed by the enzymes of lysosomes.', wrong = '{"1": "Peroxisomal catalase breaks down hydrogen peroxide into water and oxygen. It does not destroy whole cells.", "2": "Glyoxysomes are found only in plant cells, where they convert lipids into carbohydrates.", "3": "Ribosomes make proteins. They do not digest cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0884' AND answer = 0;
UPDATE questions SET why = 'Zellweger syndrome is the most serious disorder of peroxisomes. It is caused by the absence or reduced number of peroxisomes in cells. It is congenital, has no cure and usually causes death within the first year of life.', wrong = '{"0": "A missing glycogen-digesting enzyme in lysosomes causes Pompe''s disease.", "1": "Zellweger syndrome is not caused by defective ribosomes.", "2": "Centrioles are normally absent from most plant cells. Their absence is not the cause of this syndrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0885' AND answer = 3;
UPDATE questions SET why = 'Glyoxysomes are found only in plant cells and contain enzymes that convert lipids into carbohydrates. They are most abundant in lipid-rich seeds such as castor beans and soybeans, where they turn stored fat into sugar for germination.', wrong = '{"0": "Root hair cells absorb water and minerals. They do not store large amounts of lipid.", "2": "Guard cells control the opening of stomata. They are not lipid-storing cells.", "3": "Xylem vessels are dead, hollow conducting cells with no organelles."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0886' AND answer = 1;
UPDATE questions SET why = 'Many plant cells have a large central vacuole that can take up 80 percent or more of the cell. It is enclosed by a membrane called the tonoplast, and the fluid inside is called cell sap.', wrong = '{"0": "Plasmalemma is another name for the plasma membrane around the whole cell.", "1": "The nuclear envelope is the double membrane around the nucleus.", "3": "Thylakoid membranes are found inside chloroplasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0887' AND answer = 2;
UPDATE questions SET why = 'When a plant gets enough water, its central vacuoles swell as water collects in them. This builds up turgor pressure, which presses the cytoplasm against the cell wall and keeps the cells firm, so the plant stays upright along with support from the walls.', wrong = '{"0": "Storing and releasing calcium to trigger contraction is a function of smooth ER in muscle cells.", "1": "Cellulose for the cell wall is not made in the vacuole.", "2": "ATP is produced in mitochondria and chloroplasts, not in the vacuole."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0888' AND answer = 3;
UPDATE questions SET why = 'In ciliated and flagellated cells, centrioles help form cilia and flagella. Each cilium or flagellum is anchored at its base by a centriole, which is then called a basal body.', wrong = '{"1": "The centromere is the central point of a chromosome that joins its chromatids.", "2": "The axoneme is the 9+2 microtubule core of the cilium itself, not the structure anchoring it.", "3": "A nucleosome is a bead-like unit of chromatin with DNA wound around histones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0889' AND answer = 0;
UPDATE questions SET why = 'The cells of plants and fungi lack centrioles and basal bodies. Their microtubules and spindle fibres are organised by other structures in the cytoplasm instead.', wrong = '{"0": "Animal cells have a pair of centrioles at right angles near the nuclear envelope.", "2": "Most protists, like animals, have centrioles.", "3": "Ciliated cells of the trachea have a basal body (a centriole) at the base of each cilium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0890' AND answer = 1;
UPDATE questions SET why = 'Microfilaments are solid rods made of the globular protein actin. They disassemble and reassemble to help cells change shape and move, and with myosin they help in cell contraction and in pinching a dividing cell in two.', wrong = '{"1": "Tubulin (alpha and beta) builds microtubules, which are hollow tubes, not solid rods.", "2": "Vimentin is the most common protein of intermediate filaments.", "3": "Keratin forms the intermediate filaments of skin cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0891' AND answer = 0;
UPDATE questions SET why = 'Microtubules are straight, hollow cylinders made of subunits. Each subunit contains two different tubulin proteins, alpha-tubulin and beta-tubulin. Microtubules give the cell shape, act as tracks for organelles and form cilia, flagella and spindle fibres.', wrong = '{"0": "Actin forms microfilaments, and myosin works with them in contraction.", "1": "Vimentin is the usual protein of intermediate filaments.", "2": "Flagellin is the protein of prokaryotic flagella, not eukaryotic microtubules."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0892' AND answer = 3;
UPDATE questions SET why = 'Intermediate filaments are made of different proteins in different cells. The most common is vimentin, but skin cells have intermediate filaments made of keratin, which gives the skin strength.', wrong = '{"0": "Actin forms microfilaments, not intermediate filaments.", "1": "Tubulin forms microtubules.", "3": "Collagen is a fibrous protein found outside cells in connective tissue, not a cytoskeletal filament."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0893' AND answer = 2;
UPDATE questions SET why = 'The axoneme of a eukaryotic cilium has nine outer doublets of microtubules around two central microtubules (9+2). Dynein molecules around its circumference bridge the gaps between adjacent doublets and make them slide, which bends the cilium.', wrong = '{"0": "Flagellin is the protein of prokaryotic flagella. It is not found in eukaryotic cilia.", "2": "Histones are proteins that package DNA in the nucleus.", "3": "Actin forms microfilaments of the cytoskeleton. It does not bridge axoneme doublets."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0894' AND answer = 1;
UPDATE questions SET why = 'The basal body at the base of a cilium has the same outer ring of nine sets as the axoneme, but each set is a triplet of microtubules instead of a doublet, and there is no central pair. The basal body is actually a centriole.', wrong = '{"0": "Nine doublets with a central pair is the 9+2 pattern of the axoneme, not the basal body.", "1": "The nine sets are triplets of microtubules, not single microtubules.", "3": "Flagellin builds prokaryotic flagella. Basal bodies are made of tubulin microtubules."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0895' AND answer = 2;
UPDATE questions SET why = 'Both prokaryotic and eukaryotic cells have DNA as genetic material, a plasma membrane and ribosomes for making proteins. Prokaryotic ribosomes are smaller (70S) than eukaryotic ones (80S), but both kinds of cell have them.', wrong = '{"0": "The Golgi apparatus is a membrane-bounded organelle found only in eukaryotes.", "1": "Mitochondria are found only in eukaryotic cells. Prokaryotes respire using their cell membrane.", "2": "A nuclear envelope is found only in eukaryotes. Prokaryotic DNA lies in an unenclosed nucleoid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0896' AND answer = 3;
UPDATE questions SET why = 'Prokaryotic cells are much simpler and smaller than eukaryotic cells. Most range from about 2 to 8 µm in length, which is roughly one-tenth the size of a typical eukaryotic cell.', wrong = '{"1": "Prokaryotic cells are much smaller than eukaryotic cells, not the same size.", "2": "This reverses the comparison. Eukaryotic cells are about ten times larger.", "3": "20 to 250 nm is the size range of viruses, which are much smaller than cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0897' AND answer = 0;
UPDATE questions SET why = 'Prokaryotes have no membrane-bounded organelles, so they have no chloroplasts. In photosynthetic prokaryotes such as cyanobacteria, chlorophyll is not enclosed in chloroplasts but is scattered in the cytoplasm, often on internal membranes.', wrong = '{"0": "Chloroplasts are membrane-bounded organelles found only in eukaryotes such as plants and algae.", "1": "Prokaryotes do not keep their chlorophyll in a vacuole.", "2": "Prokaryotes have no mitochondria, and mitochondria do not hold chlorophyll anyway."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0898' AND answer = 3;
UPDATE questions SET why = 'After a signal molecule binds its receptor, small molecules inside the cell pass the signal on to target molecules. These are called second messengers, and examples are cAMP (cyclic AMP), calcium ions and IP₃.', wrong = '{"0": "The ligand is the first messenger, the signal molecule that binds to the receptor from outside.", "1": "The receptor is the protein that binds the ligand and starts the pathway.", "3": "Transcription factors control gene expression. They are not the small relay molecules such as cAMP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0899' AND answer = 2;
UPDATE questions SET why = 'Cell signalling has three steps. In reception, the ligand binds its receptor. In transduction, the activated receptor starts a cascade that relays and amplifies the signal. Finally comes the cellular response, such as a change in gene expression.', wrong = '{"0": "Transduction cannot come first. The signal must be received by the receptor before it is relayed.", "2": "The response is the final result of signalling, so it cannot come first.", "3": "The response comes last. Transduction must come before it to carry the signal inward."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0900' AND answer = 1;
UPDATE questions SET why = 'Protein and peptide signal molecules are water-soluble, so they cannot cross the hydrophobic core of the plasma membrane. They bind specific receptors on the cell surface, which then trigger second messengers such as cAMP inside the cell.', wrong = '{"1": "Lipophilic signals that diffuse freely through the membrane are steroid hormones, not proteins.", "2": "Size is not the problem. Their water solubility stops them crossing the lipid bilayer.", "3": "They act from receptors on the cell surface and do not enter the nucleus themselves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0901' AND answer = 0;
UPDATE questions SET why = 'Steroid hormones are lipophilic, so they diffuse through the plasma membrane. Inside, they bind receptors in the cytoplasm or nucleus, and the hormone-receptor complex binds specific DNA sequences to increase or decrease transcription of target genes.', wrong = '{"0": "Binding surface receptors that produce cAMP is the pathway of water-soluble protein or peptide signals.", "2": "Opening ion channels is not the way steroid hormones act. They work through intracellular receptors.", "3": "Steroids enter by diffusing through the lipid bilayer, not by phagocytosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0902' AND answer = 1;
UPDATE questions SET why = 'Aquaporins are channel proteins in the plasma membrane that allow rapid transport of water molecules. They help cells control their water content and volume during osmosis.', wrong = '{"0": "Pumping sodium out of nerve cells is done by the sodium-potassium pump, which uses ATP.", "1": "Carrying glucose against its gradient would be active transport. Glucose transporters usually move it down its gradient.", "3": "Binding LDL for uptake is done by LDL receptor proteins in receptor-mediated endocytosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0903' AND answer = 2;
UPDATE questions SET why = 'Carrier proteins bind the specific molecule they transport, change shape and move it across the membrane. Because there are only so many carriers, they can all become occupied, so transport reaches a maximum rate when they are saturated.', wrong = '{"0": "Facilitated diffusion is passive. It needs no ATP.", "1": "Facilitated diffusion moves substances down their concentration gradient, from higher to lower.", "2": "Carrier proteins are highly specific for the molecule they transport."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0904' AND answer = 3;
UPDATE questions SET why = 'In simple diffusion, molecules pass directly through the lipid bilayer down their concentration gradient. This works for small, nonpolar or lipid-soluble molecules such as oxygen and carbon dioxide, which can cross the hydrophobic core.', wrong = '{"1": "Glucose and amino acids are polar molecules that cross by facilitated diffusion through transport proteins.", "2": "Charged ions such as Na⁺ cannot cross the hydrophobic core and need channel proteins.", "3": "Proteins are far too large to pass through the bilayer. Bulky materials enter by endocytosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0905' AND answer = 0;
UPDATE questions SET why = 'A hypotonic solution has a lower solute concentration than the cell''s contents. Water always moves by osmosis from the hypotonic side to the hypertonic side, so water enters the red blood cell, which swells and may burst.', wrong = '{"0": "A cell loses water when placed in a hypertonic solution, which has more solute than the cell.", "1": "No net water movement happens only in an isotonic solution, with equal solute concentrations.", "2": "Osmosis is passive. Cells do not pump water out with energy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0906' AND answer = 3;
UPDATE questions SET why = 'In normal osmosis water moves from lower to higher solute concentration. Reverse osmosis applies external pressure to push water the other way, from higher to lower solute concentration, through a semi-permeable membrane, leaving salts and impurities behind.', wrong = '{"1": "Heating water until it evaporates and then condensing it is distillation, not reverse osmosis.", "2": "Adding solutes to the pure side would contaminate it, not purify the water.", "3": "Reverse osmosis is a water-treatment technology using artificial membranes, not aquaporins in living cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0907' AND answer = 0;
UPDATE questions SET why = 'The sodium-potassium pump is a carrier protein that uses ATP for active transport. In a resting nerve cell it moves Na⁺ out of the cell and K⁺ into it, keeping K⁺ high and Na⁺ low inside.', wrong = '{"0": "This reverses the direction. The pump moves Na⁺ out and K⁺ in.", "1": "The two ions move in opposite directions, Na⁺ out and K⁺ in.", "3": "The pump moves ions. Water moves by osmosis and is not pumped."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0908' AND answer = 2;
UPDATE questions SET why = 'Cholesterol travels in the blood as low-density lipoproteins (LDLs). Liver cells have specific receptor proteins for LDL in their plasma membrane, which pick up LDLs and pinch inward to form vesicles. This is receptor-mediated endocytosis.', wrong = '{"0": "LDL particles are far too large to pass through the membrane by simple diffusion.", "2": "Uptake of LDL depends on specific receptors. It is not general pinocytosis of droplets.", "3": "Exocytosis exports bulky materials out of the cell, the opposite direction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0909' AND answer = 1;
UPDATE questions SET why = 'Totipotent stem cells can differentiate into all possible cell types, including those of the placenta. The zygote and the cells from its first few divisions are totipotent.', wrong = '{"1": "Pluripotent cells, such as those of the early embryo, can become almost any cell, but not every possible type.", "2": "Multipotent cells form only a closely related family of cells, as haematopoietic stem cells do.", "3": "Unipotent cells produce only one cell type, their own, such as adult muscle stem cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0910' AND answer = 0;
UPDATE questions SET why = 'Multipotent stem cells can differentiate into a closely related family of cells. Haematopoietic (blood-forming) stem cells are an example, since they can become red blood cells, white blood cells or platelets.', wrong = '{"0": "Totipotent cells, such as the zygote, can form all cell types, not only blood cells.", "1": "Unipotent cells can make only one cell type, their own.", "3": "Oligopotent cells make only a few types, such as adult lymphoid or myeloid stem cells, which come from haematopoietic cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0911' AND answer = 2;
UPDATE questions SET why = 'Unipotent stem cells can produce only one kind of cell, their own type. They still count as stem cells because they can renew themselves. Adult muscle stem cells are an example.', wrong = '{"0": "Oligopotent cells can form a few different cell types, such as adult lymphoid or myeloid stem cells.", "2": "Pluripotent cells can become almost any cell type, like cells of the early embryo.", "3": "Totipotent cells can form every cell type, like the zygote."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0912' AND answer = 1;
UPDATE questions SET why = 'Embryonic stem cells (ESCs) come from the inner cell mass of the blastocyst, an early-stage embryo. They are pluripotent and can become nearly any cell type, but their use raises ethical concerns because embryos are used.', wrong = '{"0": "Bone marrow of adults is a source of adult stem cells, which are multipotent.", "1": "Reprogrammed skin cells give induced pluripotent stem cells (iPSCs), not embryonic stem cells.", "2": "Fat tissue is another source of adult stem cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0913' AND answer = 3;
UPDATE questions SET why = 'Induced pluripotent stem cells (iPSCs) are made in the laboratory by reprogramming adult somatic (body) cells, such as skin fibroblasts, to a pluripotent state using specific transcription factors.', wrong = '{"0": "Cells from the inner cell mass of a blastocyst are embryonic stem cells.", "2": "Fusing two gametes forms a zygote, which is fertilisation.", "3": "Isolating cells from bone marrow gives adult stem cells, which are not reprogrammed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0914' AND answer = 1;
UPDATE questions SET why = 'The reprogramming process can introduce genetic changes into iPSCs, and when transplanted into patients they could form tumours called teratomas. Getting them to become fully working cell types is also still difficult.', wrong = '{"0": "iPSCs do not need human embryos. Avoiding embryo destruction is one of their advantages.", "1": "iPSCs can be made from the patient''s own cells, which reduces the risk of immune rejection.", "3": "iPSCs are pluripotent, so they can become many other cell types."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0915' AND answer = 2;
UPDATE questions SET why = 'Metabolism has two parts. Catabolism breaks complex molecules down into simpler ones, usually releasing energy, as in respiration and digestion. Anabolism does the opposite, building complex substances from simpler ones.', wrong = '{"0": "Anabolism combines simple substances to build complex ones, the opposite of breaking them down.", "1": "Condensation joins monomers together and releases water. It builds larger molecules.", "2": "Polymerisation joins many monomers into a polymer, which is a building process."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0916' AND answer = 3;
UPDATE questions SET why = 'Carbohydrates, proteins, lipids and nucleic acids are the main organic molecules of living things and together make up 93% of the dry mass of organisms. The remaining 7% is small organic molecules such as vitamins and inorganic substances such as salts.', wrong = '{"0": "7% is the remaining share made of small organic molecules and inorganic molecules.", "1": "50% is roughly the share of proteins alone in the dry mass, not all four groups together.", "2": "At least 80% is roughly the share of water in the fresh mass of protoplasm, not the dry mass."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0917' AND answer = 3;
UPDATE questions SET why = 'A polymer is a large molecule made of many repeating monomers. Proteins are polymers of amino acids, carbohydrates (polysaccharides) are polymers of sugars, and nucleic acids are polymers of nucleotides.', wrong = '{"1": "The first two are swapped. Proteins are made of amino acids, and carbohydrates of sugars.", "2": "Proteins are not made of nucleotides, and nucleic acids are not made of amino acids.", "3": "Proteins are not made of fatty acids. Fatty acids are parts of lipids, and nucleic acids are made of nucleotides."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0918' AND answer = 0;
UPDATE questions SET why = 'Carbon-hydrogen (C-H) bonds hold a lot of chemical energy, which is released when they are broken in respiration. So the C-H bond is the potential source of chemical energy for cell activities, which is why fats and sugars rich in C-H bonds are good fuels.', wrong = '{"0": "C-O bonds in glycosidic linkages give stability to complex carbohydrates rather than serving as the energy source.", "1": "C-N bonds between amino acids form peptide bonds that build proteins.", "3": "Hydrogen bonds are weak attractions that hold large molecules in shape. They are not the main store of energy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0919' AND answer = 2;
UPDATE questions SET why = 'In water, nonpolar molecules cluster together to keep away from water molecules. These hydrophobic interactions are crucial for folding proteins, since nonpolar parts turn inward, and for forming the lipid bilayer of cell membranes.', wrong = '{"0": "Salts dissolve because of hydrophilic interactions between ions and polar water molecules.", "2": "Peptide bonds are covalent bonds formed between amino acids by condensation.", "3": "Ionisation of water involves breaking its covalent bonds into H⁺ and OH⁻ ions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0920' AND answer = 1;
UPDATE questions SET why = 'In condensation, an -OH group is removed from one monomer and an -H atom from the other. Together these form a water molecule, which is why the process is also called dehydration synthesis. The two monomers then join by a covalent bond.', wrong = '{"0": "Adding water to break a bond is hydrolysis, the reverse of condensation.", "2": "Only one -OH is removed. The other monomer loses an -H, so together they form H₂O.", "3": "No phosphate is released in condensation. The by-product is a water molecule."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0921' AND answer = 1;
UPDATE questions SET why = 'Hydrolysis breaks a larger molecule into smaller ones by adding water. The -OH from water joins one monomer and the -H joins the other. Breaking maltose into two glucose molecules this way is an example of hydrolysis.', wrong = '{"0": "Condensation joins two glucose molecules to make maltose and releases water, the reverse process.", "1": "Dehydration synthesis is another name for condensation, which builds molecules.", "2": "Ionisation is the splitting of water into H⁺ and OH⁻ ions, not the breaking of maltose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0922' AND answer = 3;
UPDATE questions SET why = 'Water content varies from tissue to tissue. Brain cells contain about 85 percent water, while bone cells contain only about 20 percent.', wrong = '{"1": "Bone cells contain only about 20 percent water, far less than brain cells.", "2": "Red blood cells are not the cells given as containing about 85 percent water.", "3": "Fat cells are mostly lipid, so they have a low water content."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0923' AND answer = 0;
UPDATE questions SET why = 'Water dissolves many substances because its molecules are polar, with partial charges at each end, and because they can form hydrogen bonds. These let water molecules surround ions and bond with polar molecules such as sugars.', wrong = '{"0": "Water has a high specific heat, not a low one, and its density is not what makes it a solvent.", "1": "Water is polar, not non-polar. Its polarity is the reason it dissolves so many substances.", "3": "Water molecules are held by covalent bonds, not ionic bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0924' AND answer = 2;
UPDATE questions SET why = 'Oxygen pulls the shared electrons more strongly than hydrogen does. So the oxygen end of a water molecule is partially negative and the hydrogen ends are partially positive, which makes water a polar molecule.', wrong = '{"0": "This reverses the partial charges. Oxygen is partially negative and hydrogen partially positive.", "2": "Water is polar, so its ends do carry partial charges.", "3": "The charges are only partial. Water is a covalent molecule, not made of ions with full charges."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0925' AND answer = 1;
UPDATE questions SET why = 'Hydrogen bonds hold water molecules together, so extra energy is needed to separate them. Without hydrogen bonding, water would boil at about -80 °C and freeze at about -100 °C, so it would be a gas at body temperature and life would be impossible.', wrong = '{"1": "0 °C is the actual freezing point of water, which hydrogen bonding helps produce.", "2": "4 °C is the temperature at which liquid water has its maximum density.", "3": "100 °C is the actual boiling point of water, with hydrogen bonding present."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0926' AND answer = 0;
UPDATE questions SET why = 'Charged or polar molecules such as salts, sugars and amino acids dissolve readily in water because water molecules can surround them or form hydrogen bonds with them. Such substances are called hydrophilic, meaning water-loving.', wrong = '{"0": "Hydrophobic (water-hating) molecules, such as lipids, do not dissolve in water.", "1": "Amphoteric describes substances that can act as both acid and base. It does not mean water-soluble.", "3": "Non-polar molecules do not dissolve in water. They are hydrophobic."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0927' AND answer = 2;
UPDATE questions SET why = 'Glucose has many polar hydroxyl (-OH) groups. Water molecules form hydrogen bonds with these groups and surround each glucose molecule, which spreads the glucose through the water so it dissolves.', wrong = '{"0": "Dissolving does not break the carbon ring of glucose. The molecule stays intact.", "1": "Splitting into Na⁺ and Cl⁻ ions is what happens when sodium chloride dissolves.", "2": "Glucose is polar and hydrophilic, so water does not exclude it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0928' AND answer = 3;
UPDATE questions SET why = 'Non-polar molecules cannot form hydrogen bonds with water, so water molecules push them out. The excluded molecules then associate with one another. This is why lipids cluster together in water and help form and maintain cell membranes.', wrong = '{"1": "Salts dissolve because polar water molecules surround their ions. That is hydrophilic, not hydrophobic, behaviour.", "2": "Ice floats because it is less dense than liquid water, an effect of hydrogen bonding.", "3": "High specific heat comes from the energy needed to break hydrogen bonds between water molecules."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0929' AND answer = 0;
UPDATE questions SET why = 'Water has a high specific heat, so it must absorb a lot of heat to rise by 1 °C, since much of the energy goes into breaking hydrogen bonds. It therefore heats up slowly and also holds its temperature longer when cooled, acting as a temperature stabiliser for organisms.', wrong = '{"1": "Evaporation is linked to heat of vaporisation. Water''s high specific heat does not make it evaporate at low temperature.", "2": "Water freezes from the top down, because ice is less dense and floats on the surface.", "3": "Water dissolves ions very well. This comes from its polarity, not its specific heat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0930' AND answer = 0;
UPDATE questions SET why = 'Water has a high heat of vaporisation, so it absorbs a lot of heat when it changes from liquid to vapour. As sweat or transpired water evaporates, each gram removes about 574 calories of heat from the body surface, cooling the organism.', wrong = '{"0": "Water has a high specific heat, not a low one, and specific heat is not what cools by evaporation.", "1": "Maximum density at 4 °C explains why ice floats. It has nothing to do with sweating.", "3": "Water has high cohesion, and cohesion explains water transport in xylem, not cooling."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0931' AND answer = 2;
UPDATE questions SET why = 'Hydrogen bonds make water molecules stick to one another, which is called cohesion. When water evaporates from a leaf, it pulls on the water in the xylem, and cohesion passes this pull all the way down to the roots, so water rises against gravity.', wrong = '{"0": "Water does not stick to lipids. Adhesion to lipids is not how water rises in xylem.", "1": "Ionisation is the splitting of water into H⁺ and OH⁻ ions. It does not lift water up the plant.", "2": "Hydrophobic exclusion is water pushing away non-polar molecules. It does not move water upward."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0932' AND answer = 3;
UPDATE questions SET why = 'Hydrogen bonds between water molecules at the surface give water a high surface tension, so the surface behaves like an invisible film. A light insect such as the water strider can walk on it without breaking through.', wrong = '{"0": "Heat of vaporisation concerns the heat absorbed during evaporation, not supporting objects on water.", "2": "Ionisation produces H⁺ and OH⁻ ions. It does not create a surface film.", "3": "Maximum density at 4 °C explains why ice floats, not why insects can stand on water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0933' AND answer = 1;
UPDATE questions SET why = 'Pure water ionises very slightly into H⁺ and OH⁻ ions. At 25 °C only about one molecule in 550 million is ionised, so the concentration of each ion is 10⁻⁷ moles per litre, which corresponds to a neutral pH of 7.', wrong = '{"1": "10⁻¹⁴ is the product of the H⁺ and OH⁻ concentrations (10⁻⁷ × 10⁻⁷), not the H⁺ concentration alone.", "2": "1 mole per litre of H⁺ would be a strong acid with pH 0, not pure water.", "3": "10⁻¹ moles per litre of H⁺ is pH 1, a strongly acidic solution."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0934' AND answer = 0;
UPDATE questions SET why = 'Liquid water is densest at 4 °C. Below this, hydrogen bonds hold the molecules further apart, and at 0 °C ice forms that is less dense than liquid water. So ice floats and insulates the water beneath, protecting aquatic life.', wrong = '{"0": "At -4 °C water is normally ice, which is less dense than liquid water at 4 °C.", "1": "At 0 °C water freezes into ice, which is less dense than liquid water and floats.", "3": "At 100 °C water boils. Hot water is less dense than water at 4 °C."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0935' AND answer = 2;
UPDATE questions SET why = 'Carbohydrates contain carbon, hydrogen and oxygen in the ratio 1:2:1, so they look like "hydrated carbon". Their empirical formula is C(H₂O)n, where n is the number of carbon atoms. Glucose, C₆H₁₂O₆, fits this with n = 6.', wrong = '{"0": "CnH2n+2 is the general formula of alkanes, which contain no oxygen.", "1": "(CH₂)nCOOH resembles a fatty acid, a component of lipids.", "2": "Carbohydrates contain no nitrogen. A formula with N fits compounds such as amino acids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0936' AND answer = 3;
UPDATE questions SET why = 'Monosaccharides are grouped by their number of carbon atoms. Pentoses have five carbons, and they include ribose, deoxyribose and ribulose. Ribulose occurs as a precursor in photosynthesis.', wrong = '{"0": "Trioses have three carbons, such as glyceraldehyde and dihydroxyacetone.", "1": "Hexoses have six carbons, such as glucose, fructose and galactose.", "3": "Ribulose is a single sugar unit (a monosaccharide), not two sugars joined together."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0937' AND answer = 2;
UPDATE questions SET why = 'Glucose and fructose share the formula C₆H₁₂O₆ but differ in structure. In glucose the double-bonded oxygen is on terminal carbon 1, while in fructose it is on internal carbon 2. A different arrangement of atoms with the same formula makes them structural isomers.', wrong = '{"0": "A different orientation of the OH on carbon 4 distinguishes glucose and galactose, which are stereoisomers.", "2": "Isomers have the same molecular formula. Both glucose and fructose are C₆H₁₂O₆.", "3": "Fructose is a hexose with six carbons, like glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0938' AND answer = 1;
UPDATE questions SET why = 'Glucose and galactose have the same structural formula except for the orientation of one hydroxyl (OH) group at carbon 4. Since only the spatial direction of a group differs, they are stereoisomers.', wrong = '{"0": "The direction of the OH on carbon 1 distinguishes alpha-glucose from beta-glucose.", "1": "Carbon 2 is where fructose has its carbonyl oxygen. It is not the glucose-galactose difference.", "3": "Carbon 5 forms the oxygen bridge in the ring of glucose and galactose. Its OH orientation is the same in both."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0939' AND answer = 2;
UPDATE questions SET why = 'In solution, a sugar forms a ring when an oxygen bridge links two of its carbons. In fructose, the bridge forms between carbon 2 and carbon 5, giving a five-cornered ring.', wrong = '{"0": "A bridge between carbons 1 and 5 giving a six-cornered ring is the ring of glucose and galactose.", "2": "A bridge between carbons 1 and 4 giving a five-cornered ring is the ring of ribose.", "3": "Fructose does not form its ring between carbons 2 and 6. Its bridge is between carbons 2 and 5."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0940' AND answer = 1;
UPDATE questions SET why = 'Alpha-D-glucose and beta-D-glucose differ only in the direction of the OH group on carbon 1. In alpha-glucose it points below the ring and in beta-glucose above it. Alpha units join to form starch, and beta units form cellulose.', wrong = '{"1": "Carbon 2 is not where the alpha and beta forms differ.", "2": "The OH orientation on carbon 4 distinguishes glucose from galactose.", "3": "Carbon 6 is the CH₂OH group outside the ring. It is not the alpha-beta difference."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0941' AND answer = 0;
UPDATE questions SET why = 'The Haworth projection, named after the British chemist Sir Norman Haworth, shows sugars in their cyclic (ring) forms. The Fischer projection, devised by Emil Fischer in 1891, shows the open-chain form instead.', wrong = '{"1": "The open-chain form of a sugar is shown by the Fischer projection.", "2": "Neither projection shows three-dimensional crystals. They are ways of drawing single molecules.", "3": "The Haworth projection can show any sugar ring, including single monosaccharides such as glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0942' AND answer = 0;
UPDATE questions SET why = 'Maltose (malt sugar) is made of two glucose molecules joined by condensation. The glycosidic bond links carbon 1 of one glucose to carbon 4 of the other, so it is a 1,4-glycosidic bond. Maltose is found in cereals and forms during starch digestion.', wrong = '{"0": "A 1,2-glycosidic bond joins glucose and fructose in sucrose, not two glucose units.", "1": "1,6-glycosidic bonds form the branch points in amylopectin and glycogen.", "3": "Peptide bonds join amino acids in proteins, not sugars."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0943' AND answer = 2;
UPDATE questions SET why = 'Lactose, the milk sugar, is a disaccharide of one galactose and one glucose joined by a 1,4-glycosidic bond (galactose 1-4 glucose). It is found only in mammalian milk and is the main energy source for young mammals.', wrong = '{"0": "Glucose and fructose joined together form sucrose (cane sugar).", "1": "Two glucose units joined together form maltose (malt sugar).", "2": "Galactose and fructose do not form any of the common disaccharides, maltose, lactose or sucrose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0944' AND answer = 3;
UPDATE questions SET why = 'Sucrose, made of glucose and fructose (glucose 1-2 fructose), is carried in the phloem of higher plants. It moves sugar to and from different parts of the plant, so it is called the transport disaccharide.', wrong = '{"0": "The sugar found only in milk is lactose, not sucrose.", "1": "Starch granules are made of starch, a polysaccharide of alpha-glucose.", "3": "Maltose is the disaccharide found in many cereals such as wheat and corn."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0945' AND answer = 2;
UPDATE questions SET why = 'Glucose from corn starch is only half as sweet as sucrose. In the 1980s a method was developed to convert this glucose into its isomer fructose, which is even sweeter than sucrose. The resulting high-fructose corn syrup is cheap, so it replaced sucrose in many foods and soft drinks.', wrong = '{"0": "Glucose is only about half as sweet as sucrose, not twice as sweet.", "2": "Fructose is a normal, digestible sugar that provides energy.", "3": "Corn syrup is a sugar syrup, rich in fructose and glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0946' AND answer = 1;
UPDATE questions SET why = 'Starch is the storage polysaccharide of plants and is insoluble in water. Because it does not dissolve, it does not change the water potential of plant cells, so storing it does not make the cells take up water by osmosis.', wrong = '{"0": "Branching (in amylopectin) affects how quickly starch is broken down, not whether it affects osmosis.", "1": "Starch is made of alpha-glucose. Beta-glucose builds cellulose.", "2": "Starch is a polysaccharide of many glucose units, not a disaccharide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0947' AND answer = 3;
UPDATE questions SET why = 'Starch is a mixture of amylose and amylopectin. Amylose is a straight, unbranched chain with 1,4-glycosidic links that coils into a helix. Amylopectin also has 1,4 links but adds branches through 1,6-glycosidic links, giving more ends for amylase to work on.', wrong = '{"1": "Beta-1,4 linkages are found in cellulose. Both parts of starch use alpha-glucose.", "2": "Both amylose and amylopectin are made of glucose units.", "3": "A straight, unbranched chain describes amylose, not amylopectin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0948' AND answer = 0;
UPDATE questions SET why = 'Glycogen, the storage polysaccharide of animals found mainly in liver and muscle, is very highly branched through 1,6-glycosidic links. Its many branch ends can be attacked by enzymes at once, so glycogen can be broken down to glucose very quickly.', wrong = '{"1": "Being insoluble helps storage, but it is the high branching that allows fast breakdown.", "2": "Glycogen is made of alpha-glucose, like starch. Beta-glucose builds cellulose.", "3": "Glycogen is highly branched, not a straight helix. A helical straight chain describes amylose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0949' AND answer = 0;
UPDATE questions SET why = 'Cellulose is made of beta-glucose joined by 1,4 links. In beta-glucose the OH on carbon 1 points up, so alternate glucose units are inverted and the chain stays straight. Hundreds of such chains are joined by hydrogen bonds into strong microfibrils.', wrong = '{"0": "Alpha-glucose with 1,6 branches describes amylopectin and glycogen, which are not straight chains.", "1": "Cellulose is a polymer of glucose, not fructose.", "2": "Glucose units carrying nitrogen-containing groups make up chitin, not cellulose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0950' AND answer = 3;
UPDATE questions SET why = 'The beta-glycosidic bonds of cellulose cannot be broken by amylase. They need the enzyme cellulase, which only some bacteria and protozoans possess. Cows and termites carry such bacteria in their guts, and these bacteria digest cellulose for them.', wrong = '{"0": "Salivary amylase breaks alpha bonds in starch. It cannot break the beta bonds of cellulose.", "2": "These animals do not make cellulase themselves. It comes from microbes living in their gut.", "3": "Stomach acid does not digest cellulose. Humans pass it out as dietary fibre."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0951' AND answer = 1;
UPDATE questions SET why = 'Chitin is a modified form of cellulose. Its glucose units are linked as in cellulose, but each glucose has an added nitrogen-containing group. Chitin forms the exoskeletons of insects and crabs and the cell walls of fungi.', wrong = '{"0": "No phosphate group is added to the glucose units of chitin.", "1": "Chitin''s glucose units do not carry an extra carbon ring.", "3": "Chitin''s linkages are like those of cellulose (beta), not alpha linkages."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0952' AND answer = 2;
UPDATE questions SET why = 'Agar is a polysaccharide found in the cell walls of red algae. It is used as a thickener in foods and as a medium on which bacteria and fungi are grown in laboratories.', wrong = '{"1": "Fungal cell walls are made of chitin, not agar.", "2": "Bacterial cell walls are made of murein (peptidoglycan), a sugar-peptide polymer.", "3": "Green plant cell walls contain cellulose, pectin and lignin, not agar."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0953' AND answer = 0;
UPDATE questions SET why = 'The Swedish chemist J. J. Berzelius coined the term protein from the Greek proteios, meaning "of the first rank". He chose it to stress how important these molecules are as the principal compounds of cells.', wrong = '{"0": "Emil Fischer devised the Fischer projection for drawing open-chain sugars.", "2": "Linus Pauling is known for the alpha helix of proteins and work on chemical bonds. He did not coin the word protein.", "3": "Erwin Chargaff discovered the base-pairing ratios in DNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0954' AND answer = 1;
UPDATE questions SET why = 'An amino acid has four groups attached to one central carbon atom called the alpha carbon: an amino group (NH₂), a carboxyl group (COOH), a hydrogen atom and a side group (R).', wrong = '{"0": "The nitrogen atom belongs to the amino group, which is itself attached to the alpha carbon.", "1": "The carboxyl carbon is part of the COOH group, which is attached to the alpha carbon.", "2": "The four groups are attached to the alpha carbon, not a beta carbon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0955' AND answer = 3;
UPDATE questions SET why = 'All amino acids share an amino group, a carboxyl group and a hydrogen on the alpha carbon. They differ only in the side group (R), which gives each its identity and properties. In glycine R is a hydrogen atom, and in alanine it is CH₃.', wrong = '{"0": "Every amino acid has the same amino group, so it cannot make one amino acid different from another.", "1": "Every amino acid has the same carboxyl group.", "3": "Every amino acid has the same hydrogen on its alpha carbon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0956' AND answer = 2;
UPDATE questions SET why = 'Essential amino acids cannot be made by the body and must come from food. They are methionine, valine, tryptophan, isoleucine, leucine, lysine, threonine, phenylalanine and histidine, so lysine is essential.', wrong = '{"0": "Alanine is a non-essential amino acid that the body can make.", "1": "Glycine is a non-essential amino acid that the body can make.", "3": "Serine is a non-essential amino acid that the body can make."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0957' AND answer = 2;
UPDATE questions SET why = 'Of the 20 amino acids used in proteins, the human body can make eleven, called non-essential amino acids, such as alanine, glycine and serine. The other nine are essential and must be obtained from food.', wrong = '{"0": "Five is too few. The body makes eleven of the twenty.", "1": "Nine is the number of essential amino acids that the body cannot make.", "3": "The body cannot make all twenty. Nine must come from the diet."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0958' AND answer = 2;
UPDATE questions SET why = 'When glycine and alanine are joined by a peptide bond through dehydration synthesis, they form glycylalanine. Since it contains just two amino acids, it is a dipeptide.', wrong = '{"0": "A disaccharide is made of two sugar units, not two amino acids.", "1": "Glycylalanine has only two amino acids, glycine and alanine, not twenty.", "2": "A nucleotide is the unit of nucleic acids, made of a sugar, phosphate and base."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0959' AND answer = 3;
UPDATE questions SET why = 'Insulin has two polypeptide chains. The smaller alpha chain has 21 amino acids and the longer beta chain has 30, giving 21 + 30 = 51 amino acids in all.', wrong = '{"1": "141 and 146 are the lengths of the alpha and beta chains of haemoglobin.", "2": "51 is the total number of amino acids in insulin, not the length of each chain.", "3": "Insulin''s chains are 21 and 30 amino acids long, not 20 and 20."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0960' AND answer = 0;
UPDATE questions SET why = 'Haemoglobin has four polypeptide chains: two alpha chains of 141 amino acids each and two beta chains of 146 each. So each beta chain has 146 amino acids, and the total is 2(141) + 2(146) = 574.', wrong = '{"0": "30 amino acids is the beta chain of insulin, not haemoglobin.", "1": "141 amino acids is the length of each alpha chain of haemoglobin.", "3": "574 is the total for all four chains of haemoglobin, not one beta chain."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0961' AND answer = 2;
UPDATE questions SET why = 'In sickle cell haemoglobin, a single amino acid is wrong: valine replaces glutamic acid at position six of each beta chain. This change makes red blood cells sickle-shaped, and the haemoglobin cannot carry enough oxygen.', wrong = '{"0": "This reverses the swap and names the wrong chain. Valine replaces glutamic acid in the beta chains.", "2": "Glycine and alanine are not involved. The change is glutamic acid to valine at position six.", "3": "Histidine and leucine are not involved. Glutamic acid is replaced by valine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0962' AND answer = 1;
UPDATE questions SET why = 'Secondary structure is the coiling (alpha helix) or folding (pleated sheet) of a polypeptide chain. Both shapes are held by hydrogen bonds between the amino and carboxyl groups of nearby amino acids in the chain.', wrong = '{"0": "Disulphide bonds help hold the tertiary (globular) structure, along with ionic and hydrogen bonds.", "2": "Peptide bonds link amino acids in a line, forming the primary structure.", "3": "Interactions between separate polypeptide chains give the quaternary structure."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0963' AND answer = 1;
UPDATE questions SET why = 'A globular protein folds so that it is most stable in water. Hydrophobic (non-polar) amino acids disrupt the hydrogen bonding of water, so they gather and are buried in the core. Hydrophilic (polar) amino acids turn outwards to face the surrounding water.', wrong = '{"1": "This reverses the arrangement. Polar, hydrophilic amino acids interact well with water, so they stay on the surface, not inside.", "2": "If all amino acids faced outwards, the non-polar ones would be exposed to water. Instead they are hidden in the core of the fold.", "3": "A straight chain is not a tertiary structure. In tertiary structure the chain folds further into a compact globular shape."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0964' AND answer = 0;
UPDATE questions SET why = 'Quaternary structure is formed when two or more polypeptide chains, each already folded into a tertiary structure, are held together. Hydrophobic interactions, hydrogen bonds and ionic bonds keep the chains joined. Haemoglobin, with two alpha and two beta chains, is an example.', wrong = '{"0": "Primary structure is only the sequence of amino acids in a chain. It says nothing about how separate chains are combined.", "1": "Secondary structure is the coiling (alpha helix) or folding (pleated sheet) within one chain, held by hydrogen bonds.", "2": "Tertiary structure is the globular folding of a single chain. Joining several folded chains goes one level further, to quaternary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0965' AND answer = 3;
UPDATE questions SET why = 'Fibrous proteins form long fibrils, are insoluble and do structural jobs. Keratin is a fibrous protein that makes nails, hair, beaks and the outer skin. Other fibrous proteins are silk, actin, fibrin and collagen.', wrong = '{"0": "Haemoglobin is a globular protein. It is soluble and carries oxygen in red blood cells, a functional rather than structural role.", "1": "Antibodies are globular proteins. They recognise and bind foreign antigens, so their role is functional.", "3": "Enzymes such as pepsin are globular proteins that act as biological catalysts. They are soluble and functional, not structural fibres."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0966' AND answer = 2;
UPDATE questions SET why = 'Globular proteins have a delicate tertiary or quaternary folding held by weak bonds. Changes in the environment, such as heat or pH, easily disorganise this shape. Fibrous proteins, with simple primary or secondary structure, do not disorganise easily.', wrong = '{"0": "Not disorganising easily is a feature of fibrous proteins, which have simple, stable structures. Globular proteins are the sensitive ones.", "1": "Silk and hair (keratin) are made of fibrous proteins. Globular proteins include enzymes, antibodies and haemoglobin.", "3": "Globular proteins are mainly functional, for example enzymes and hormones. Structural roles belong to fibrous proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0967' AND answer = 2;
UPDATE questions SET why = 'Ferritin is an ion-binding protein and the main store of iron inside cells. Blood ferritin level is measured to judge iron reserves: a high level means plenty of stored iron, and a low level warns of iron lack, which can later lead to anaemia.', wrong = '{"0": "Casein is a milk protein that stores calcium and potassium ions. It does not store iron inside cells.", "2": "Albumin is a blood plasma protein that maintains the osmotic concentration of blood and helps it flow. It is not an iron store.", "3": "Fibrinogen is a blood protein that is converted to fibrin fibres when blood clots after an injury."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0968' AND answer = 1;
UPDATE questions SET why = 'Repressors are proteins that control gene action. They prevent a gene from being transcribed, so its RNA is not made. This lets genes work only where and when the cell needs them.', wrong = '{"1": "Antibodies recognise and combine with foreign antigens and make them harmless. They do not control gene expression.", "2": "Cytochromes are proteins that carry electrons in the electron transport chain. They do not regulate RNA synthesis.", "3": "Hormones are chemical messengers that regulate body activities, such as insulin controlling blood glucose. They are not the proteins that block RNA synthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0969' AND answer = 0;
UPDATE questions SET why = 'Albumin is the main plasma protein. Because it stays in the blood, it holds water there by osmosis and keeps the osmotic concentration of blood steady. It also helps blood keep its normal ability to flow.', wrong = '{"0": "Fibrinogen is a clotting protein. After an injury it is changed into fibrin, which forms the fibres of a clot.", "1": "Myoglobin is an oxygen-carrying protein found in muscle, not a blood plasma protein that controls osmotic balance.", "2": "Ferritin is the main intracellular iron-storage protein. It does not maintain the osmotic concentration of blood."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0970' AND answer = 3;
UPDATE questions SET why = 'Lipids are a loosely defined group of non-polar molecules. Because they are non-polar, they do not dissolve in water, which is polar. They do dissolve in organic solvents such as ether and alcohol.', wrong = '{"0": "This reverses the solubility. Non-polar lipids are insoluble in water and soluble in organic solvents like ether.", "2": "Lipids are a very diverse group, including waxes, terpenes and steroids. They are not polymers of glycerol.", "3": "Amino acids are the building blocks of proteins. Lipids are built from units such as fatty acids, glycerol or isoprene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0971' AND answer = 1;
UPDATE questions SET why = 'Acylglycerols are esters of glycerol and fatty acids. Those that are liquid at room temperature are called oils, for example peanut, corn and castor oil. Most plant acylglycerols are oils, while most animal ones are solid fats.', wrong = '{"0": "Fats are acylglycerols that are solid at room temperature, as most animal acylglycerols are.", "1": "Waxes are a separate lipid group with high melting points. They are solid at room temperature and form protective coatings.", "3": "Steroids are lipids with four fused carbon rings, such as cholesterol. They are not acylglycerols."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0972' AND answer = 2;
UPDATE questions SET why = 'Triacylglycerols (triglycerides) are the most common acylglycerols, also called neutral lipids. Glycerol is a 3-carbon alcohol with an OH group on each carbon. Each OH forms an ester bond with one fatty acid, so three fatty acids join one glycerol.', wrong = '{"0": "This is reversed. There is only one glycerol backbone, and it carries three fatty acids.", "1": "Glycerol with two fatty acids and a phosphate is phosphatidic acid, the parent molecule of phospholipids.", "2": "Chains of isoprene units make terpenes, such as rubber and vitamin A, not triacylglycerols."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0973' AND answer = 3;
UPDATE questions SET why = 'Unsaturated fatty acids have one or more C=C double bonds, which replace some hydrogen atoms. So they hold fewer than the maximum number of hydrogens. The double bonds put bends in the chain, the chains cannot pack tightly, and the melting point is low.', wrong = '{"1": "No double bonds and straight chains describe saturated fatty acids, not unsaturated ones.", "2": "Saturated fatty acids carry the maximum number of hydrogens. In unsaturated ones some hydrogens are replaced by double bonds.", "3": "Higher melting points belong to saturated fatty acids, whose straight chains pack closely. Unsaturated ones melt at lower temperatures."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0974' AND answer = 0;
UPDATE questions SET why = 'The energy in acylglycerols is stored in their C-H bonds. Animal fats contain saturated fatty acids, which carry the maximum number of hydrogens and so have more C-H bonds. Plant oils contain unsaturated fatty acids with fewer C-H bonds, so they hold less energy.', wrong = '{"0": "Unsaturated fatty acids are typical of plant oils. Having fewer C-H bonds, they give less energy, not more.", "1": "Fats and oils are non-polar and insoluble in water. Solubility has nothing to do with energy content.", "2": "Each triacylglycerol, in fats or in oils, has just one glycerol. The difference lies in the fatty acids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0975' AND answer = 3;
UPDATE questions SET why = 'Waxes have no single well-defined structure. They are mixtures of long-chain alkanes (with an odd number of carbons, 25 to 35), alcohols other than glycerol, ketones and long-chain fatty acids. Their many carbons give high melting points, so they are solid at room temperature.', wrong = '{"0": "A single triacylglycerol molecule is a fat or oil. Waxes are mixtures of several kinds of compounds.", "2": "Polymers of isoprene units are terpenes, such as rubber and vitamin A, not waxes.", "3": "Four fused rings define the steroids, such as cholesterol. Waxes have no ring skeleton like this."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0976' AND answer = 1;
UPDATE questions SET why = 'Phosphatidic acid is built from one glycerol, two fatty acids and one phosphoric acid (phosphate). It is the parent molecule of phospholipids: when a nitrogenous base such as choline, ethanolamine or serine attaches to its phosphate, a phospholipid is formed.', wrong = '{"0": "One glycerol with three fatty acids is a triacylglycerol, the common fat or oil.", "1": "Four fused carbon rings make the skeleton of steroids, such as cholesterol.", "3": "Isoprene units build terpenes. Phosphatidic acid has no isoprene units."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0977' AND answer = 2;
UPDATE questions SET why = 'Lecithin is the common name of phosphatidyl choline, a phospholipid made when choline attaches to the phosphate of phosphatidic acid. Its polar head and two non-polar fatty acid tails let it arrange into the lipid bilayer of plasma membranes.', wrong = '{"1": "Phosphatidyl serine is also a phospholipid, but its base is serine. Lecithin is the one with choline.", "2": "Cholesterol is a steroid with four fused rings. It is found in animal membranes but it is not lecithin.", "3": "Prostaglandins are modified fatty acids that act as local chemical messengers. They do not form the membrane bilayer."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0978' AND answer = 0;
UPDATE questions SET why = 'Terpenes are a large lipid group built from isoprene units, each a branched unsaturated hydrocarbon, CH₂=C(CH₃)-CH=CH₂. Many important pigments are terpenes, such as chlorophyll and the retinal pigment of the eye. Vitamin A and rubber are terpenes too.', wrong = '{"0": "Steroids have four fused rings and include cholesterol and sex hormones, not chlorophyll or rubber.", "1": "Waxes are mixtures of long-chain alkanes, alcohols, ketones and fatty acids that form protective coatings.", "2": "Prostaglandins are modified fatty acids with a five-carbon ring. They act as local chemical messengers."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0979' AND answer = 3;
UPDATE questions SET why = 'Steroids are lipids whose carbon skeleton is bent into four fused rings. Every steroid has the same pattern: three six-cornered rings and one five-cornered ring. Cholesterol and the sex hormones share this skeleton.', wrong = '{"1": "There are four rings, but they are not all six-cornered. One of the four is a five-cornered ring.", "2": "Two rings is too few. The steroid skeleton has four fused rings, and only one of them is five-cornered.", "3": "Non-polar tails attached to a five-carbon ring describe prostaglandins, not steroids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0980' AND answer = 0;
UPDATE questions SET why = 'Prostaglandins are modified fatty acids that act as local chemical messengers in tissues. They take part in the inflammatory response. Aspirin inhibits prostaglandins, so it reduces inflammation, pain and fever.', wrong = '{"0": "Blocking cholesterol synthesis is how other drugs lower blood cholesterol. It is not how aspirin works.", "1": "Waxes are inert protective coatings and play no part in inflammation, pain or fever.", "3": "Terpenes such as chlorophyll and vitamin A are not involved in inflammation. Aspirin acts on prostaglandins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0981' AND answer = 2;
UPDATE questions SET why = 'Cholesterol is a steroid. Besides maintaining membranes and helping lipid transport, it is the starting material (precursor) from which the body makes vitamin D, bile acids and steroid hormones, such as androgens, oestrogens and adrenal corticosteroids.', wrong = '{"0": "Vitamin A and rubber are terpenes, built from isoprene units. They are not made from cholesterol.", "2": "Insulin and glucagon are protein (peptide) hormones made from amino acids, not from cholesterol.", "3": "Haemoglobin is a globular protein made of four polypeptide chains. Cholesterol is not its precursor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0982' AND answer = 1;
UPDATE questions SET why = 'A nucleoside has two parts: a nitrogenous base attached to carbon 1 of a pentose sugar. When a phosphoric acid forms an ester bond with carbon 5 of that sugar, the nucleoside becomes a nucleotide. Memory hook: nucleoTide has the phosphaTe.', wrong = '{"0": "Base, pentose and phosphate together make a nucleotide. The nucleoside lacks the phosphate.", "1": "Two nucleotides joined by a phosphodiester bond form a dinucleotide, not a nucleoside.", "2": "A phosphate and a sugar alone lack the nitrogenous base. They form the sugar-phosphate backbone, not a nucleoside."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0983' AND answer = 3;
UPDATE questions SET why = 'Nucleic acids contain three pyrimidine bases. Cytosine is present in both DNA and RNA, thymine only in DNA, and uracil only in RNA. In RNA, uracil takes the place of thymine and pairs with adenine.', wrong = '{"1": "Thymine is found only in DNA. In RNA its place is taken by uracil.", "2": "Cytosine is a pyrimidine present in both DNA and RNA, so it is not unique to RNA.", "3": "Adenine is a purine present in both DNA and RNA, so it is not unique to RNA."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0984' AND answer = 0;
UPDATE questions SET why = 'Nitrogenous bases are of two kinds. Purines, adenine and guanine, have a double ring. Pyrimidines, cytosine, thymine and uracil, have a single ring. Both DNA and RNA contain the two purines.', wrong = '{"0": "A single ring is the feature of pyrimidines (C, T and U). Purines have two fused rings.", "1": "The purines adenine and guanine are found in both DNA and RNA, not only in RNA.", "3": "Purines and pyrimidines are both nitrogenous bases, so both contain nitrogen in their rings."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0985' AND answer = 2;
UPDATE questions SET why = 'In a nucleotide, the nitrogenous base is attached to carbon 1 of the pentose sugar. The phosphoric acid forms an ester linkage with carbon 5 of the same sugar. This is why one end of a nucleic acid strand is called the 5′ end.', wrong = '{"0": "Carbon 1 of the pentose carries the nitrogenous base, not the phosphate.", "2": "Carbon 2 is where ribose and deoxyribose differ (OH or H). It does not carry the phosphate.", "3": "Carbon 4 is not a site for the phosphate ester bond. The phosphate attaches at carbon 5."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0986' AND answer = 1;
UPDATE questions SET why = 'A nucleotide''s phosphate is already linked by an ester bond to C-5 of its own sugar. It then forms a second ester bond with C-3 of the sugar of the next nucleotide. These two ester bonds together are the phosphodiester linkage that joins nucleotides into a chain.', wrong = '{"0": "Carbon 1 of each sugar holds the nitrogenous base, so it is not used in the phosphodiester bond.", "1": "Bases of the two DNA strands are paired by hydrogen bonds. Phosphodiester bonds link sugars, not bases.", "2": "The phosphate links two different sugars, at C-5 and C-3. C-2 and C-4 of one sugar are not involved."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0987' AND answer = 3;
UPDATE questions SET why = 'NAD, nicotinamide adenine dinucleotide, is a coenzyme made of two nucleotides. It works in oxidation-reduction reactions as a hydrogen acceptor, picking up hydrogen to become NADH and passing it on later. This makes it a key carrier in respiration.', wrong = '{"1": "The energy currency of the cell is ATP, which releases energy as its phosphate groups are removed.", "2": "Ribosomes are built from rRNA and ribosomal proteins. NAD is not a structural part of them.", "3": "The hereditary molecule is DNA (RNA in some viruses). NAD is a coenzyme, not a carrier of genes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0988' AND answer = 0;
UPDATE questions SET why = 'Chargaff found that in DNA the amount of adenine equals the amount of thymine, and guanine equals cytosine. This hinted that A pairs with T and G pairs with C. Watson and Crick used this rule in building their double helix model.', wrong = '{"0": "DNA is a double helix of two strands, as Watson and Crick showed. Chargaff''s rule supports pairing between two strands.", "1": "Uracil is found in RNA, not DNA. Chargaff''s rule concerns A, T, G and C in DNA.", "3": "The two strands run anti-parallel, in opposite directions. Also, this was not Chargaff''s observation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0989' AND answer = 2;
UPDATE questions SET why = 'In the Watson and Crick model the two strands are held together by hydrogen bonds between paired bases. Adenine and thymine are joined by two hydrogen bonds, while guanine and cytosine are joined by three. So G-C pairs hold the strands more firmly.', wrong = '{"0": "One hydrogen bond is too few for any base pair in DNA. G-C has three.", "1": "Two hydrogen bonds join adenine and thymine. Guanine and cytosine share three.", "3": "No DNA base pair has four hydrogen bonds. G and C form three."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0990' AND answer = 2;
UPDATE questions SET why = 'Watson and Crick compared DNA to a twisted ladder. The two poles (sides) are made of alternating sugar and phosphate groups, the sugar-phosphate backbone. The rungs are the pairs of nitrogenous bases joined by hydrogen bonds.', wrong = '{"0": "Nitrogenous base pairs form the rungs of the ladder, not the poles.", "2": "Histones are proteins around which DNA wraps in chromosomes. They are not part of the DNA ladder itself.", "3": "Amino acids make proteins. DNA is built only from nucleotides: sugar, phosphate and base."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0991' AND answer = 1;
UPDATE questions SET why = 'A gene is a sequence of DNA nucleotides that codes for the formation of a polypeptide. When a gene is turned on, its sequence is transcribed into RNA, which is then translated into a protein. In this way genes direct the activities of the cell.', wrong = '{"1": "A chromosome is much larger than a gene. One DNA molecule in a chromosome carries many genes.", "2": "mRNA is a copy made from a gene during transcription. It carries the message but is not the gene itself.", "3": "Proteins that switch genes on or off are products of genes. A gene is a DNA sequence, not a protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0992' AND answer = 0;
UPDATE questions SET why = 'Ribosomal RNA (rRNA) makes up about 80% of all RNA in a cell. It is made by the DNA of the nucleolus and joins with ribosomal proteins to form ribosomes. Transfer RNA forms about 10 to 15%, and messenger RNA only about 3 to 4%.', wrong = '{"0": "Messenger RNA is only about 3 to 4% of total RNA. It carries the genetic message to ribosomes.", "2": "Transfer RNA forms about 10 to 15% of total RNA. It carries amino acids to the ribosome.", "3": "Viral RNA is not one of the three types of RNA found in all living cells (mRNA, tRNA and rRNA)."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0993' AND answer = 1;
UPDATE questions SET why = 'Transfer RNA (tRNA) is a fairly small RNA. Its single strand folds back on itself, so the molecule looks like a clover leaf. During protein synthesis each tRNA carries a specific amino acid to the ribosome and mRNA.', wrong = '{"0": "Messenger RNA is a single strand that carries the genetic message from DNA to ribosomes. It does not bring amino acids.", "1": "Ribosomal RNA joins with proteins to form ribosomes, the machinery of protein synthesis. It does not carry amino acids.", "2": "DNA is not RNA at all. It stays in the nucleus and holds the genetic code."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0994' AND answer = 3;
UPDATE questions SET why = 'The central dogma describes how genetic information flows. In transcription, information passes from DNA to RNA. In translation, the information in RNA is used to direct the synthesis of a protein. So RNA to protein is translation.', wrong = '{"0": "Transcription is the first step, the making of an RNA copy of a gene from DNA.", "1": "Replication is the copying of DNA to make more DNA before cell division. No protein is made.", "3": "Reverse transcription makes DNA from an RNA template, as in some viruses. It does not make protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0995' AND answer = 2;
UPDATE questions SET why = 'Conjugated molecules form when molecules from different classes combine. Glycolipids are made by a covalent linkage between a lipid and a carbohydrate. They are an integral part of cell membranes.', wrong = '{"0": "Hydrophobic interactions between lipids and proteins form lipoproteins, not glycolipids.", "1": "Ionic bonds between chromosomal DNA and proteins form nucleoproteins, such as nucleosomes.", "3": "Covalent linkage between a protein and a carbohydrate forms glycoproteins, found in membranes, blood serum and cartilage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0996' AND answer = 2;
UPDATE questions SET why = 'Lipoproteins are formed when lipids and proteins associate through hydrophobic interactions, not through covalent or ionic bonds. They form the basic framework of plasma membranes, and lipids travel in the blood as very low-density lipoproteins.', wrong = '{"0": "Covalent bonds join the parts of glycoproteins and glycolipids. Lipoproteins are held by weaker hydrophobic interactions.", "1": "Ionic bonds hold nucleoproteins, between negatively charged DNA and proteins such as histones.", "2": "Glycosidic bonds join sugar units to each other, as in starch. They do not link lipids to proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0997' AND answer = 3;
UPDATE questions SET why = 'Nucleoproteins are formed by ionic bonds between chromosomal DNA and proteins. DNA is negatively charged because of its phosphates, and histone proteins carry positive charges. Histones bound to DNA form nucleosomes, which stabilise chromosomes and help regulate genes.', wrong = '{"1": "Nucleoproteins contain DNA and protein. RNA linked covalently to lipids is not a nucleoprotein.", "2": "Lipids are not part of nucleoproteins, and hydrophobic interactions hold lipoproteins, not nucleoproteins.", "3": "Peptide bonds join amino acids within a protein. DNA and histones are held by ionic bonds."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0998' AND answer = 0;
UPDATE questions SET why = 'Every reaction needs some activation energy to break existing bonds and get started. Enzymes, the biocatalysts of the cell, lower this activation energy, so the reaction runs much faster. The enzyme itself comes out of the reaction unchanged and can be used again.', wrong = '{"0": "Raising the activation energy would slow a reaction down. Enzymes do the opposite and lower it.", "1": "Enzymes do not change what is made. Sucrose gives glucose and fructose with or without sucrase.", "2": "Enzymes are not used up. They leave the reaction unaltered and can catalyse it again and again."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0999' AND answer = 3;
UPDATE questions SET why = 'Not all cells have the same set of enzymes. The reactions inside a cell depend on which enzymes it contains. Red blood cells and nerve cells carry different sets of enzymes, so the chemical reactions going on in them are very different.', wrong = '{"0": "Body cells of one person carry the same genetic code. The difference lies in which enzymes each cell type contains and uses.", "2": "Both red blood cells and nerve cells depend on enzymes for their metabolism. No living cell works without enzymes.", "3": "Each cell runs many reactions, so it needs many different enzymes, not just one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1000' AND answer = 1;
UPDATE questions SET why = 'Inside a cell, enzymes are found in different places according to the job they do. Many are dissolved in the cytoplasm, such as the enzymes of glycolysis. Others are bound to organelle membranes, such as those of the Krebs and Calvin cycles, and some are part of ribosomes.', wrong = '{"0": "Enzymes that are an integral part of ribosomes are those of protein synthesis, not glycolysis.", "1": "Glycolysis does not take place in the nucleus. It happens in the cytoplasm (cytosol).", "3": "The cell wall is outside the cell membrane and is not the site of glycolysis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1001' AND answer = 2;
UPDATE questions SET why = 'Pepsin is a protein-digesting enzyme. If it were active inside the cell that makes it, it could digest that cell''s own protein structures. So it is made and secreted as inactive pepsinogen, and it is activated to pepsin only when it reaches its site of action in the stomach.', wrong = '{"1": "Pepsin, like all enzymes, is made on ribosomes. Being made in an inactive form protects the cell, not the ribosome.", "2": "Pepsinogen is the inactive form of a protease. It does not digest fats.", "3": "Pepsinogen is in fact activated in the stomach, which is its target site. That is the whole point of secreting it inactive."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1002' AND answer = 0;
UPDATE questions SET why = 'Enzymes are globular proteins. On the surface of each there is a small cleft or depression made of only a few amino acids. This is the active site, the place where the substrate binds and catalysis occurs.', wrong = '{"0": "A prosthetic group is a non-protein cofactor joined covalently to the enzyme, such as hematin. It is not the cleft itself.", "1": "An allosteric site is a different site away from the active site, where regulators bind. Catalysis takes place at the active site.", "3": "The apoenzyme is the whole protein part of an enzyme without its cofactor, not just the small catalytic cleft."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1003' AND answer = 2;
UPDATE questions SET why = 'The active site has two distinct regions. The binding site holds the substrate in place by weak chemical forces such as hydrogen bonds. The catalytic site then acts on the bound substrate and transforms it into products.', wrong = '{"0": "Apoenzyme and holoenzyme are names for the protein part alone and the complete enzyme with its cofactor. They are not regions of the active site.", "2": "Cofactors and coenzymes are non-protein helpers of an enzyme. They are not the two regions of the active site.", "3": "Substrate and product are the starting material and the result of the reaction, not parts of the enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1004' AND answer = 1;
UPDATE questions SET why = 'The substrate must be held only briefly and then released as product. So it fits into the binding site by weak chemical forces, such as hydrogen bonds. Weak bonds let the enzyme bind, act and then let go, staying unchanged.', wrong = '{"1": "Covalent bonds are strong. They are how irreversible inhibitors and prosthetic groups attach, not how a substrate is held.", "2": "Peptide bonds join amino acids inside a protein chain. They do not hold a substrate in the active site.", "3": "Metal ions can act as cofactors, but substrate binding is described as weak forces such as hydrogen bonds, not ionic bonds only."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1005' AND answer = 0;
UPDATE questions SET why = 'Many enzymes need a non-protein helper called a cofactor. The protein part alone is called the apoenzyme, and it is inactive. The apoenzyme together with its cofactor forms the complete, active enzyme, called the holoenzyme.', wrong = '{"0": "The apoenzyme is only the protein part, without its cofactor. It is not the complete enzyme.", "1": "A coenzyme is one kind of cofactor, a non-protein organic molecule loosely attached to the enzyme.", "2": "A prosthetic group is a cofactor bound covalently to the enzyme. It is a part of the enzyme, not the whole."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1006' AND answer = 3;
UPDATE questions SET why = 'Many enzymes use metal ions such as Ca²⁺, Mg²⁺, Mn²⁺, Cu²⁺ and Zn²⁺ as cofactors. These ions change a non-functional active site into a functional one. Attaching the ion changes the enzyme''s shape so that it can combine with its substrate.', wrong = '{"0": "A substrate is the molecule the enzyme changes into product. Metal ion cofactors help the enzyme and are not themselves converted.", "1": "Metal ion cofactors act on the enzyme''s active site. They do not form covalent bonds with the products.", "2": "Carrying hydrogen from one enzyme to another is the job of coenzymes such as NAD⁺, not metal ions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1007' AND answer = 3;
UPDATE questions SET why = 'Cofactors are of three kinds: metal ions, prosthetic groups and coenzymes. A prosthetic group is the cofactor that is attached to the enzyme by covalent bonds, so it is held firmly. Hematin is an example of an organic prosthetic group.', wrong = '{"1": "A coenzyme is a non-protein organic cofactor that is only loosely attached to the enzyme, not covalently bonded.", "2": "Metal ions such as Mg²⁺ and Zn²⁺ are a separate kind of cofactor that activates the active site.", "3": "The substrate is the molecule the enzyme acts on. It is not a cofactor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1008' AND answer = 0;
UPDATE questions SET why = 'A prosthetic group is a cofactor bound to the enzyme by covalent bonds. It may be an organic compound, and hematin, an iron-containing haem compound, is the example given. Because it is covalently attached, it stays with the enzyme permanently.', wrong = '{"0": "NAD⁺ is a coenzyme, loosely attached, that accepts hydrogen in redox reactions. It is not a prosthetic group.", "2": "Mg²⁺ is a metal ion cofactor. Metal ions form a separate class from prosthetic groups.", "3": "Riboflavin is a vitamin that works as, or forms part of, a coenzyme. It is not the example of a prosthetic group."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1009' AND answer = 1;
UPDATE questions SET why = 'When a cofactor is a non-protein organic molecule that is only loosely attached to the enzyme, it is called a coenzyme. Coenzymes often carry electrons or hydrogen atoms from one enzyme to another. NAD⁺ is the most important coenzyme in the cell.', wrong = '{"0": "Metal ions such as Cu²⁺ are a separate, inorganic kind of cofactor. Coenzymes are organic molecules.", "1": "A cofactor bonded covalently to the enzyme is a prosthetic group. Coenzymes are loosely attached.", "3": "Cofactors, including coenzymes, are non-protein parts. They are not part of the polypeptide chain."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1010' AND answer = 2;
UPDATE questions SET why = 'Many vitamins function as coenzymes or form part of coenzymes. The examples named are niacin and riboflavin, both B-group vitamins. Niacin is used to make NAD⁺, the main hydrogen-carrying coenzyme of the cell.', wrong = '{"0": "Vitamins A and D are fat-soluble vitamins. They are not the examples given of vitamins that act as coenzymes.", "1": "Vitamins C and E are not the vitamins named as coenzymes in this section.", "3": "Vitamins K and B12 are not the examples named here. The named coenzyme vitamins are niacin and riboflavin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1011' AND answer = 2;
UPDATE questions SET why = 'When food is oxidised, enzymes remove hydrogen atoms (electrons) from food molecules and hand them to NAD⁺. NAD⁺ accepts the hydrogen and is reduced to NADH. The energy of the electrons is carried by NADH to later steps of respiration.', wrong = '{"1": "Losing a phosphate group is how ATP becomes ADP and releases energy. NAD⁺ changes by gaining hydrogen.", "2": "Binding a metal ion is how some enzymes are activated. It is not how NAD⁺ becomes NADH.", "3": "Hydrolysis splits a molecule using water. NAD⁺ is reduced, not hydrolysed, when it becomes NADH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1012' AND answer = 0;
UPDATE questions SET why = 'Activation energy is the energy needed to destabilise the existing chemical bonds of the reactants so that a reaction can start. The more activation energy a reaction needs, the slower it goes. Enzymes speed up reactions by lowering this energy barrier.', wrong = '{"0": "Energy stored in products is their chemical energy content. Activation energy is the push needed to start the reaction.", "1": "Enzymes do not break or release energy themselves. They come out of the reaction unchanged.", "2": "An enzyme''s folded shape is held by its own bonds, such as hydrogen and ionic bonds. That is not activation energy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1013' AND answer = 3;
UPDATE questions SET why = 'An enzyme only speeds up a reaction; it does not change what the reaction makes. Sucrose is always hydrolysed into glucose and fructose, whether sucrase is present or not. Sucrase just makes this happen much faster.', wrong = '{"0": "Enzymes are not consumed. They leave the reaction unaltered, but this example is about the products, not the enzyme.", "2": "The sucrose example says nothing about pH. Optimum pH differs from one enzyme to another.", "3": "The example does not concern reversibility. It shows that the products are the same with or without the enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1014' AND answer = 1;
UPDATE questions SET why = 'In complex pathways such as respiration and photosynthesis, many enzymes act one after another. The product of one enzyme''s reaction becomes the substrate for the enzyme of the next step. At the end, the final product can inhibit the first enzyme by feedback.', wrong = '{"1": "Products normally feed the next step. Only the end product of the pathway inhibits, and it acts on an early enzyme.", "2": "Intermediate products are not excreted. They are used straight away by the next enzyme in the sequence.", "3": "The pathway moves forward. Each product is passed on to the next step, not turned back into the first substrate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1015' AND answer = 0;
UPDATE questions SET why = 'In 1894 the German chemist Emil Fischer proposed the lock-and-key model. Just as a specific key opens only one lock, a specific enzyme acts on only one specific substrate. The model treats the active site as rigid.', wrong = '{"0": "Daniel Koshland, an American biochemist, proposed the induced fit model in 1958, not the lock-and-key model.", "2": "Hans Krebs is known for the Krebs (citric acid) cycle of respiration, not for a model of enzyme action.", "3": "Christian de Duve is known for discovering lysosomes, not for the lock-and-key model."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1016' AND answer = 1;
UPDATE questions SET why = 'In Fischer''s lock-and-key model, the active site is a rigid structure with an exact shape, like a lock. Only a substrate of matching shape fits, like the right key. The site shows no change or flexibility before, during or after catalysis.', wrong = '{"0": "A change of shape when the substrate binds is the idea of Koshland''s induced fit model.", "1": "In both models the active site already exists on the enzyme before the substrate arrives.", "2": "The lock-and-key model stresses specificity. Only one specific substrate fits, as only one key fits a lock."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1017' AND answer = 3;
UPDATE questions SET why = 'Koshland''s induced fit model (1958) says the active site is flexible, not rigid. When the substrate binds, it induces changes in the enzyme''s structure that let it catalyse more effectively, like a glove moulding to a hand. After the reaction the enzyme regains its original shape.', wrong = '{"0": "A rigid active site is the assumption of Fischer''s lock-and-key model, which induced fit replaced.", "1": "The enzyme is not permanently changed. It returns to its original shape after releasing the products.", "3": "In induced fit it is the enzyme''s active site that changes shape when the substrate binds."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1018' AND answer = 2;
UPDATE questions SET why = 'Every enzyme works fastest at a particular temperature, its optimum temperature. For human enzymes this is 37 °C, which is normal body temperature. Below it the reaction slows, and well above it the enzyme is denatured.', wrong = '{"0": "At 25 °C human enzymes work, but more slowly, because their bonds are less flexible below the optimum.", "2": "50 °C is well above body temperature. Human enzymes start to lose their shape and activity at such temperatures.", "3": "70 °C or more suits only enzymes of thermophilic bacteria in hot springs. Human enzymes would be denatured."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1019' AND answer = 1;
UPDATE questions SET why = 'Thermophilic bacteria live in hot springs. Their proteins have stronger bonding between their polypeptide chains, so the chains stay in place even when atoms vibrate strongly. This lets their enzymes keep their shape and work at 70 °C or higher.', wrong = '{"0": "Without hydrogen bonds proteins would lose their shape more easily. Heat stability comes from stronger bonding, not fewer bonds.", "1": "These enzymes, like almost all enzymes, are proteins, not nucleic acids.", "3": "Cold does not denature them. The point is that their strong bonding resists denaturation by heat."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1020' AND answer = 2;
UPDATE questions SET why = 'Below the optimum temperature, the bonds that set the enzyme''s shape become less flexible. The active site cannot make the induced change needed for catalysis, as described by the induced fit model. Molecules also move more slowly, so the reaction rate falls.', wrong = '{"0": "Denaturation happens well above the optimum, when strong vibrations break bonds. Cold only slows the enzyme.", "2": "Low temperature does not destroy the substrate. It slows its reaction with the enzyme.", "3": "Product inhibition is feedback control, not the reason for slow action at low temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1021' AND answer = 1;
UPDATE questions SET why = 'Raising the temperature well above the optimum makes the atoms of the enzyme vibrate more and more. When the vibrations become too violent, the bonds can no longer hold the polypeptide chains in position, and the globular shape is lost. This is denaturation, and enzyme action falls sharply or stops.', wrong = '{"1": "Losing a cofactor can make an enzyme inactive, but heat denaturation is the loss of the protein''s own folded shape.", "2": "Heat does not add amino acids. It breaks the bonds that hold the existing chains in shape.", "3": "A competitive inhibitor blocks the active site but leaves the enzyme''s structure intact. That is inhibition, not denaturation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1022' AND answer = 0;
UPDATE questions SET why = 'Most enzymes work only in a narrow pH range. Papain, an enzyme from green papaya, is unusual because it can work in both acidic and alkaline media. By contrast, pepsin needs an acidic medium and trypsin an alkaline one.', wrong = '{"0": "Pepsin works in a strongly acidic medium, with an optimum around pH 1.5 to 1.6 in the stomach.", "1": "Trypsin works best in an alkaline medium, around pH 7.8 to 8.7 in the small intestine.", "2": "Salivary amylase works in a narrow pH range near neutral in the mouth. It is not described as working in both acidic and alkaline media."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1023' AND answer = 3;
UPDATE questions SET why = 'Each enzyme works best at its own optimum pH. Trypsin, a protease that acts in the small intestine, shows its optimum activity in an alkaline medium, about pH 7.8 to 8.7. Pepsin, by contrast, works in the acidic stomach.', wrong = '{"0": "A strongly acidic medium suits pepsin (optimum about pH 1.5 to 1.6), not trypsin.", "1": "Pure water is neutral (pH 7). Trypsin''s optimum lies on the alkaline side, above pH 7.", "3": "Enzymes work at their maximum rate only in a narrow pH range. Activity drops when the pH moves away from the optimum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1024' AND answer = 2;
UPDATE questions SET why = 'An enzyme''s chains are held partly by bonds between oppositely charged amino acids, such as glutamic acid (−) and lysine (+). These charges depend on the H⁺ concentration. A change in pH alters the ionisation of amino acids at the active site and of the substrate, so binding and catalysis suffer.', wrong = '{"1": "Adding energy to molecules is the effect of raising the temperature, not of changing pH.", "2": "pH does not change the order of amino acids, which is fixed by the gene. It changes their charges.", "3": "Losing cofactors is not the mechanism given. pH acts by changing the ionisation of charged groups."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1025' AND answer = 0;
UPDATE questions SET why = 'Enzymes are very efficient, and each active site can convert many substrate molecules. If substrate is unlimited, adding more enzyme provides more active sites, so more substrate is converted per unit time. The rate depends directly on the amount of enzyme present.', wrong = '{"0": "More enzyme means more active sites, so the rate rises, not falls, when substrate is plentiful.", "1": "With unlimited substrate, the rate goes on rising as enzyme is added. It levels off only when substrate runs short.", "2": "Denaturation is caused by heat or extreme pH. Adding more enzyme does not denature it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1026' AND answer = 3;
UPDATE questions SET why = 'At low substrate levels, free active sites are available, so adding substrate speeds up the reaction. At high substrate levels, all active sites are occupied and the enzyme is saturated. Extra substrate molecules find no free active site, so the rate stays at its maximum.', wrong = '{"0": "Substrate concentration does not denature an enzyme. Heat or extreme pH does.", "2": "The substrate is converted to product. It does not act as an inhibitor here.", "3": "Products are still formed, at the highest rate the enzyme can manage. The rate simply cannot rise further."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1027' AND answer = 1;
UPDATE questions SET why = 'Cyanide is an irreversible enzyme inhibitor. It combines with the copper and iron in the active site of cytochrome oxidase, the enzyme at the end of the electron transport chain. This blocks cellular respiration, so cells cannot make enough ATP.', wrong = '{"0": "Cyanide does not compete with glucose for hexokinase. Its target is cytochrome oxidase in respiration.", "1": "Cyanide is a chemical inhibitor of one enzyme. It does not denature proteins by heat.", "3": "Inhibiting the enzymes that make prostaglandins is the action of aspirin, a drug, not cyanide."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1028' AND answer = 2;
UPDATE questions SET why = 'A competitive inhibitor has a shape similar to the enzyme''s substrate. It competes with the substrate for the same binding site. When the inhibitor occupies the active site, the substrate cannot attach, so the enzyme cannot act.', wrong = '{"0": "Binding away from the active site and changing the enzyme''s shape describes non-competitive inhibition.", "1": "Competitive inhibitors such as malonate bind by weak bonds and are reversible. Covalent binding marks irreversible inhibitors.", "2": "The final product of a pathway acts in feedback inhibition, usually non-competitively on an early enzyme."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1029' AND answer = 3;
UPDATE questions SET why = 'Succinic dehydrogenase oxidises succinic acid to fumaric acid. Malonic acid has a structure similar to succinic acid, so both compete for the same active site. When malonic acid is selected, it blocks the site. This is competitive inhibition.', wrong = '{"1": "Binding away from the active site is non-competitive inhibition. Malonic acid enters the active site itself.", "2": "Malonic acid does not destroy the enzyme''s shape. It only occupies the active site, and the effect can be reversed.", "3": "A cofactor helps an enzyme work. Malonic acid blocks the enzyme, so it is an inhibitor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1030' AND answer = 0;
UPDATE questions SET why = 'Succinic dehydrogenase (succinate dehydrogenase) is an enzyme of the Krebs cycle. It removes hydrogen from succinic acid, oxidising it to fumaric acid. Malonic acid competitively inhibits this reaction because it resembles succinic acid.', wrong = '{"0": "Malonic acid is the competitive inhibitor of this enzyme, not its substrate.", "2": "Pyruvic acid is changed to acetyl CoA by a different enzyme system, before the Krebs cycle begins.", "3": "Glucose is converted to fructose by an isomerase, hexose isomerase, not by a dehydrogenase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1031' AND answer = 1;
UPDATE questions SET why = 'A non-competitive inhibitor does not resemble the substrate, so it does not enter the active site. Instead it binds the enzyme at another place. This binding changes the enzyme''s shape so the active site no longer fits the substrate, and the enzyme is inhibited.', wrong = '{"0": "Entering and blocking the active site is how a competitive inhibitor works.", "1": "Resembling the substrate is the feature of competitive inhibitors, such as malonic acid.", "2": "A coenzyme helps an enzyme work. A non-competitive inhibitor does the opposite."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1032' AND answer = 3;
UPDATE questions SET why = 'Succinic acid and CoA react to form succinyl CoA, a reaction catalysed by succinyl-CoA synthetase. The product, succinyl CoA, then binds to this enzyme as a non-competitive inhibitor. The enzyme is switched off, so no more succinyl CoA is made.', wrong = '{"1": "Competing with succinic acid for succinic dehydrogenase describes malonic acid, a competitive inhibitor.", "2": "Covalently disabling the enzyme that builds bacterial cell walls describes penicillin, an irreversible inhibitor.", "3": "A cofactor assists an enzyme. Here succinyl CoA shuts the enzyme down."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1033' AND answer = 0;
UPDATE questions SET why = 'Irreversible inhibitors form covalent bonds with the enzyme. Covalent bonds are strong, so the inhibitor cannot be released by dilution, dialysis or by adding more substrate. Penicillin, which disables the enzyme that builds bacterial cell walls, is an example.', wrong = '{"0": "Weak bonds such as hydrogen bonds are made by reversible inhibitors, which can be released.", "2": "Being overcome by more substrate is a feature of reversible (competitive) inhibition, not irreversible.", "3": "Irreversible inhibition depends on covalent bonding, not on temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1034' AND answer = 1;
UPDATE questions SET why = 'Bacteria need a particular enzyme to build their cell walls. Penicillin forms a permanent (covalent) bond with this enzyme and disables it. Without a proper wall, the bacteria cannot grow and are killed. Because the effect is permanent, penicillin is an irreversible inhibitor.', wrong = '{"0": "Blocking succinate dehydrogenase is the action of malonate, a reversible competitive inhibitor.", "1": "Inhibiting the enzymes that make prostaglandins is how aspirin reduces pain and inflammation.", "3": "Stopping cytochrome oxidase is the action of the poison cyanide, which blocks respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1035' AND answer = 2;
UPDATE questions SET why = 'Enzyme inhibitors are used to manage many medical conditions. Blood clotting depends on a chain of enzymes. Drugs that inhibit some of these enzymes slow clot formation, so they are used as anticoagulants (anti-clotting drugs).', wrong = '{"0": "Antibiotics inhibit enzymes needed by bacteria, such as the cell wall enzyme blocked by penicillin, not clotting enzymes.", "1": "Biopesticides are living organisms or their products used to control pests, not clotting inhibitors.", "3": "Coenzymes help enzymes to work. They are not inhibitors of clotting enzymes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1036' AND answer = 2;
UPDATE questions SET why = 'In feedback inhibition, the final product of a pathway controls its own production. When enough product builds up, it binds to an early enzyme of the pathway and changes its shape. That enzyme can no longer bind its substrate, so the whole pathway slows or stops.', wrong = '{"0": "It is the final product, not the first substrate, that inhibits, and it acts on an early enzyme, not the last.", "1": "Feedback inhibition is a chemical control by the end product, not an effect of heat.", "2": "The end product acts on an enzyme of its own pathway in the same cell, not on another cell."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1037' AND answer = 3;
UPDATE questions SET why = 'Transferases catalyse the transfer of a functional group, such as methyl, acyl, amino or phosphate, from one substrate to another. Hexokinase moves a phosphate group from ATP to glucose, so it is a transferase.', wrong = '{"1": "Hydrolases break substrates by adding water, as digestive enzymes do. Hexokinase moves a phosphate group.", "2": "Isomerases rearrange atoms within one molecule. Hexokinase moves a group between two molecules.", "3": "Lyases add or remove groups such as CO₂ without water. Hexokinase transfers a group to another substrate."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1038' AND answer = 0;
UPDATE questions SET why = 'Lyases catalyse the non-hydrolytic addition or removal of groups, such as CO₂ or NH₂, from a substrate. Pyruvate decarboxylase removes CO₂ from pyruvic acid without using water, so it is a lyase.', wrong = '{"0": "Ligases join two molecules with new bonds using energy from ATP. Removing CO₂ is not joining.", "2": "Hydrolases split molecules by adding water. A decarboxylase removes CO₂ without water.", "3": "Oxidoreductases add or remove hydrogen or electrons. Pyruvate decarboxylase removes a CO₂ group."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1039' AND answer = 1;
UPDATE questions SET why = 'Isomerases catalyse rearrangements within a single molecule, changing one isomer into another. Glucose and fructose have the same formula, C₆H₁₂O₆, but a different arrangement of atoms. Hexose isomerase converts glucose to fructose, so it is an isomerase.', wrong = '{"0": "Transferases move a group such as phosphate from one substrate to another. Here no group moves between molecules.", "1": "Lyases remove or add groups like CO₂ without water. Glucose to fructose is a rearrangement.", "3": "Hydrolases split molecules with water. Glucose is not split; it is rearranged into fructose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1040' AND answer = 2;
UPDATE questions SET why = 'Oxidoreductases catalyse oxidation and reduction, adding or removing H⁺ ions or electrons. Cytochrome oxidase oxidises cytochrome by removing its electrons, so it belongs to the oxidoreductases.', wrong = '{"0": "Transferases move functional groups such as phosphate between substrates, not electrons in redox.", "1": "Isomerases convert one isomer into another, such as glucose into fructose.", "2": "Ligases join two molecules with new bonds using energy from ATP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1041' AND answer = 3;
UPDATE questions SET why = 'Proteins are digested in steps by proteases. Pepsin and trypsin break large polypeptides into smaller ones, aminopeptidases break these into dipeptides, and erepsin finally breaks dipeptides into amino acids, which can be absorbed.', wrong = '{"0": "Breaking large polypeptides into smaller ones is done by pepsin and trypsin.", "2": "Breaking small polypeptides into dipeptides is done by aminopeptidases.", "3": "Breaking lipids into fatty acids and glycerol is the work of lipases, such as pancreatic lipase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1042' AND answer = 1;
UPDATE questions SET why = 'Cellulase is a carbohydrase that acts on cellulose. It breaks cellulose into cellobiose, a disaccharide of two glucose units, or all the way into glucose. Both products come from cellulose because cellulose is a polymer of glucose.', wrong = '{"1": "Maltose is produced when amylase acts on starch or glycogen, not when cellulase acts on cellulose.", "2": "Glucose and fructose are the products of sucrase acting on sucrose.", "3": "Glucose and galactose are the products of lactase acting on lactose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1043' AND answer = 0;
UPDATE questions SET why = 'Lactase is a carbohydrase that hydrolyses lactose, the sugar of milk. Lactose is a disaccharide made of one glucose and one galactose, so its breakdown gives glucose and galactose.', wrong = '{"0": "Two glucose molecules come from maltose, broken down by maltase.", "1": "Glucose and fructose come from sucrose, broken down by sucrase.", "3": "Cellobiose is a disaccharide produced from cellulose by cellulase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1044' AND answer = 2;
UPDATE questions SET why = 'Classified by substrate, nucleases are enzymes that act on nucleic acids and nucleotides and catalyse their breakdown. RNAase breaks down RNA, DNAase breaks down DNA, and ATPase breaks down ATP, a nucleotide. So all three are grouped as nucleases.', wrong = '{"0": "Proteases act on proteins, for example pepsin, trypsin and erepsin.", "2": "Lipases act on lipids, for example pancreatic lipase splitting fats into fatty acids and glycerol.", "3": "Carbohydrases act on carbohydrates, for example amylase, maltase and lactase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1045' AND answer = 1;
UPDATE questions SET why = 'Ligases catalyse reactions in which two molecules are joined by forming new C-C, C-N, C-O or C-S bonds. Joining needs energy, which comes from ATP. Polymerase enzymes, which join monomers into polymers using ATP, are an example.', wrong = '{"0": "Adding water to split a molecule is hydrolysis, catalysed by hydrolases.", "1": "Converting one isomer into another is the job of isomerases, such as hexose isomerase.", "2": "Removing CO₂ without water is done by lyases, such as pyruvate decarboxylase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1046' AND answer = 3;
UPDATE questions SET why = 'ATP (adenosine triphosphate) is a nucleotide with three subunits. Adenine is the nitrogen-containing base, ribose is the five-carbon sugar, and three phosphate groups are attached in a row. The bonds between the phosphates are the high-energy bonds.', wrong = '{"0": "Deoxyribose is the sugar of DNA nucleotides. The sugar in ATP is ribose.", "1": "Glucose is not part of ATP, and ATP has three phosphates, not two. Adenosine with two phosphates is ADP.", "3": "Guanine with ribose and three phosphates makes GTP. The base in ATP is adenine."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1047' AND answer = 2;
UPDATE questions SET why = 'ATP was discovered in 1929 by Karl Lohmann. Later, in 1941, the Nobel prize winner Fritz Lipmann proposed that ATP is the main energy-transfer molecule of the cell. Keep the two straight: Lohmann found it, Lipmann explained its role.', wrong = '{"1": "Fritz Lipmann did not discover ATP. In 1941 he proposed that it is the cell''s main energy-transfer molecule.", "2": "Melvin Calvin worked out the steps of the light-independent reactions, the Calvin cycle.", "3": "Hans Krebs worked out the citric acid (Krebs) cycle of aerobic respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1048' AND answer = 0;
UPDATE questions SET why = 'Karl Lohmann discovered ATP in 1929. In 1941 Fritz Lipmann proposed that ATP is the main energy-transfer molecule in the cell. Cells make ATP when they release energy from food and break it when they need energy, so it links the two kinds of reactions.', wrong = '{"0": "ATP is made in both mitochondria and chloroplasts, and in the cytoplasm too. Lipmann''s idea concerned its role, not its site.", "1": "ATP contains ribose, not deoxyribose. Deoxyribose is the sugar of DNA.", "2": "Genetic information is stored in DNA. ATP is an energy carrier."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1049' AND answer = 3;
UPDATE questions SET why = 'The bonds between phosphate groups in ATP are high-energy bonds. When the terminal phosphate is removed by hydrolysis, ATP + H₂O → ADP + Pi, about 7.3 kcal (7,300 calories) of energy is released per mole of ATP.', wrong = '{"0": "3.65 kcal is half the correct value, as if only half the bond energy were released.", "2": "14.6 kcal is double the value, the energy from breaking two phosphate bonds (or two moles of ATP).", "3": "36 is a count of ATP molecules from aerobic respiration of one glucose, not the energy of one bond in kcal."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1050' AND answer = 1;
UPDATE questions SET why = 'In common energy-releasing reactions, only the outer high-energy bond between the last two phosphates breaks. ATP then becomes ADP (adenosine diphosphate) and one inorganic phosphate (Pi) is released, along with about 7.3 kcal per mole.', wrong = '{"0": "AMP forms only in some cases, when ADP is broken down further. The common reaction stops at ADP.", "2": "Only one phosphate is removed in the common reaction. Losing all three would leave adenosine.", "3": "NADP is a separate coenzyme used in photosynthesis. It is not a breakdown product of ATP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1051' AND answer = 1;
UPDATE questions SET why = 'Cells get energy by oxidising food and store it by joining ADP with Pi to make ATP. So ATP is made during energy-releasing processes. When cells need energy, they break ATP back to ADP and Pi. In this way ATP carries energy from one reaction to another.', wrong = '{"0": "This reverses the relationship. ATP is made when energy is released and used up when energy is consumed.", "1": "The high-energy bonds of ATP are between the phosphate groups, not between adenine and ribose.", "2": "ATP is broken down in almost every energy-using process, such as muscle contraction and active transport, not just photosynthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1052' AND answer = 3;
UPDATE questions SET why = 'The overall equation is 6CO₂ + 12H₂O + light → C₆H₁₂O₆ + 6O₂ + 6H₂O. Water is used as a reactant in some steps, where it is split, and released as a product in others. Water is shown on both sides, but there is no net yield of water.', wrong = '{"1": "A catalyst is not changed in a reaction. Water is actually split in some steps and formed in others.", "2": "Glucose is C₆H₁₂O₆. It does not contain water molecules inside it.", "3": "The equation shows chemistry, not how much water a plant absorbs from soil. Water appears on both sides because it is used and also formed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1053' AND answer = 0;
UPDATE questions SET why = 'Respiration goes on day and night, but photosynthesis needs light. At dawn and dusk, when light is weak, the two rates may be equal for a short time. Oxygen made equals oxygen used, and CO₂ released equals CO₂ fixed, so there is no net gas exchange. This is the compensation point.', wrong = '{"0": "At the compensation point photosynthesis is still running. It just balances respiration exactly.", "1": "Respiration never stops in living cells. It continues day and night.", "3": "At noon light is strong and photosynthesis is much faster than respiration, so there is a net release of oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1054' AND answer = 2;
UPDATE questions SET why = 'At noon, light is strong and photosynthesis runs much faster than respiration. The leaf needs more CO₂ than respiration can supply, and it makes more O₂ than its cells use. So overall the leaf takes in CO₂ and releases O₂.', wrong = '{"0": "No net gas exchange happens at the compensation point, at dawn or dusk when light is weak.", "2": "Net release of CO₂ happens in darkness, when only respiration takes place.", "3": "Net uptake of O₂ happens in darkness, when cells respire but do not photosynthesise."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1055' AND answer = 1;
UPDATE questions SET why = 'Plants convert only about 1 to 2% of the solar energy they receive into chemical energy during photosynthesis. Even with this low efficiency, the energy stored is enough to sustain almost all life on Earth.', wrong = '{"0": "10% is a different figure: about 10% of total photosynthesis is carried out by land plants, the rest in water.", "1": "25 to 50% is the share of fixed carbon that C3 plants can lose to photorespiration, not the energy efficiency.", "3": "About 40% is far too high. Plants store only 1 to 2% of the light they receive."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1056' AND answer = 2;
UPDATE questions SET why = 'The German biologist T. W. Engelmann made the first action spectrum in 1883. He worked on the filamentous green alga Spirogyra, shining different colours of light on different cells of a filament and seeing where most oxygen was produced.', wrong = '{"0": "Chlamydomonas is a unicellular green alga. It was not the organism Engelmann used.", "1": "Corn (maize) is used as an example of a C4 plant, not in Engelmann''s experiment.", "2": "Cyanobacteria are mentioned for their phycobilin pigments, not for the first action spectrum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1057' AND answer = 3;
UPDATE questions SET why = 'Engelmann lit the cells of a Spirogyra filament with different wavelengths. The cells receiving blue and red light photosynthesised most, so they released the most oxygen. This matches the fact that chlorophyll absorbs mainly violet-blue and orange-red light.', wrong = '{"1": "Green and yellow light are poorly absorbed by chlorophyll, so cells receiving them gave little oxygen.", "2": "Green light is the least absorbed. It is mostly reflected or transmitted, so it drives little photosynthesis.", "3": "Infrared is outside the range used in photosynthesis. Peaks were in blue and red."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1058' AND answer = 0;
UPDATE questions SET why = 'To make an action spectrum, a plant is lit with one colour at a time and the rate of photosynthesis is measured, usually as oxygen released. Plotting rate against wavelength shows how effective each wavelength is in driving photosynthesis.', wrong = '{"0": "The wavelengths absorbed by a single pigment are shown by its absorption spectrum, not the action spectrum.", "2": "A spectrum is a graph against wavelength. It cannot show the chemical structure of chlorophyll.", "3": "An action spectrum measures photosynthesis under coloured light, not respiration in darkness."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1059' AND answer = 1;
UPDATE questions SET why = 'About 90% of photosynthesis takes place in oceans, lakes and ponds. Aquatic photosynthetic organisms take their carbon from dissolved CO₂, bicarbonates and soluble carbonates in the water. Land plants use CO₂ from the atmosphere.', wrong = '{"0": "Atmospheric CO₂ is the carbon source of land plants. Aquatic organisms use carbon dissolved in water.", "2": "Photosynthetic organisms make glucose themselves. They do not take it in as their carbon source.", "3": "Methane is not used as a carbon source in photosynthesis. CO₂ and its dissolved forms are."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1060' AND answer = 1;
UPDATE questions SET why = 'Carbon dioxide enters the leaf through the stomata, which are present in large numbers on leaves. It then dissolves in the film of water held by the walls of mesophyll cells and diffuses in. So CO₂ entry depends on the stomata being open.', wrong = '{"0": "Roots take up water and minerals. The CO₂ for photosynthesis comes from air through the stomata.", "1": "CO₂ is a raw material that is fixed in the chloroplast, not made there.", "3": "The waxy cuticle is largely impermeable to gases. CO₂ enters mainly through the stomata."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1061' AND answer = 2;
UPDATE questions SET why = 'Van Niel studied photosynthetic bacteria that make carbohydrate from CO₂ but release no oxygen, because they do not use water as their hydrogen source. From this he proposed in the 1930s that plants split water to get hydrogen, giving off oxygen as a by-product.', wrong = '{"0": "Yeast does not photosynthesise. Its fermentation tells nothing about where photosynthetic oxygen comes from.", "1": "Animal muscle cells do not photosynthesise, so they could not suggest the splitting of water.", "2": "Fungi cannot photosynthesise. Van Niel''s idea came from photosynthetic bacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1062' AND answer = 3;
UPDATE questions SET why = 'In the 1940s, one group of plants got heavy water (H₂¹⁸O) with normal CO₂, and another got C¹⁸O₂ with normal water. The first group released heavy oxygen (¹⁸O) and the second released normal oxygen. So the oxygen released in photosynthesis comes from water, not from CO₂.', wrong = '{"1": "Normal oxygen was released by the other group, the one given labelled CO₂ and normal water.", "2": "No mixture was found. The group given H₂¹⁸O released only heavy oxygen, since all O₂ comes from water.", "3": "Heavy oxygen does not block photosynthesis. Both groups photosynthesised normally."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1063' AND answer = 0;
UPDATE questions SET why = 'In photosynthesis, water is split and its hydrogen reduces the coenzyme NADP to NADPH. NADPH then supplies the hydrogen (electrons) needed to reduce CO₂ to sugar, so it is called the reducing power. ATP supplies the energy for the same step.', wrong = '{"0": "ATP supplies energy for the Calvin cycle, but it carries no hydrogen. The reducing power is NADPH.", "2": "FADH₂ is a reduced coenzyme of respiration, formed in the Krebs cycle. It is not used to reduce CO₂.", "3": "Oxygen is a by-product of splitting water. It is an oxidising agent, not a reducing power."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1064' AND answer = 1;
UPDATE questions SET why = 'Oxidation is loss of electrons (and hydrogen) and reduction is their gain. In photosynthesis, water is split, losing electrons and H⁺, so it is oxidised and O₂ is released. These electrons and H⁺ are added to CO₂, which is reduced to sugar.', wrong = '{"0": "This reverses the roles. Water loses electrons (oxidised) and CO₂ gains them (reduced).", "1": "Oxygen being reduced to water happens at the end of the electron transport chain in respiration.", "3": "Glucose being oxidised to CO₂ is respiration, the reverse of photosynthesis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1065' AND answer = 2;
UPDATE questions SET why = 'The light-dependent reactions need pigments and electron carriers, which are built into the thylakoid membranes of the grana. So they take place on the thylakoid membranes. The light-independent reactions (Calvin cycle) take place in the stroma.', wrong = '{"1": "The stroma is the fluid around the thylakoids, where the light-independent (Calvin cycle) reactions occur.", "2": "The outer chloroplast membrane is an envelope. It does not contain the photosystems.", "3": "The cytosol is outside the chloroplast. It is where glycolysis happens, not the light reactions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1066' AND answer = 0;
UPDATE questions SET why = 'Light travels as photons, and a photon''s energy depends on its wavelength: the shorter the wavelength, the higher the energy. Blue light has a shorter wavelength than red light, so blue photons carry more energy and can raise electrons to higher energy levels.', wrong = '{"0": "Red photons are the ones with less energy, because red light has the longer wavelength.", "1": "Every photon carries energy. That is why light can drive photosynthesis.", "2": "Blue light has a shorter wavelength than red light, not a longer one."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1067' AND answer = 3;
UPDATE questions SET why = 'Chlorophylls are of different kinds. Chlorophylls a, b, c and d are found in plants and algae. The other kinds, found in photosynthetic bacteria, are called bacteriochlorophylls.', wrong = '{"0": "Red algae use chlorophyll a along with phycobilin pigments, not bacteriochlorophylls.", "1": "Flowering plants use chlorophylls a and b, with carotenoids as accessory pigments.", "2": "Green algae, like land plants, use chlorophylls a and b."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1068' AND answer = 3;
UPDATE questions SET why = 'A chlorophyll molecule has a hydrophilic head and a hydrophobic tail. The head is a porphyrin ring made of four pyrrole rings (five-sided rings containing nitrogen). The four pyrroles are held together by a magnesium atom at the centre. The head is the part that absorbs light.', wrong = '{"1": "Iron sits at the centre of haem in haemoglobin. Chlorophyll has magnesium at its centre.", "2": "The porphyrin ring has four pyrrole rings, not six.", "3": "The long hydrocarbon chain is the tail of chlorophyll. The head is the porphyrin ring."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1069' AND answer = 0;
UPDATE questions SET why = 'The tail of chlorophyll is a long hydrocarbon chain, which is hydrophobic. Like a lipid tail it sits in the lipid layer of the thylakoid membrane and anchors the molecule there. Light is absorbed by the porphyrin head, not by the tail.', wrong = '{"0": "Light is absorbed by the porphyrin ring of the head, not by the hydrocarbon tail.", "2": "The magnesium atom is at the centre of the porphyrin head, not in the tail.", "3": "The tail is a hydrocarbon chain, so it is hydrophobic. The head is the hydrophilic part."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1070' AND answer = 1;
UPDATE questions SET why = 'Chlorophylls absorb mainly violet-blue and orange-red wavelengths. Green wavelengths are absorbed least, so they are reflected or transmitted. This reflected green light is why leaves look green to us.', wrong = '{"0": "Violet-blue light is one of the two bands that chlorophylls absorb most strongly.", "1": "Orange-red light is strongly absorbed by chlorophylls. It is the other main absorption band.", "3": "Blue light is strongly absorbed by chlorophylls, as part of the violet-blue band."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1071' AND answer = 2;
UPDATE questions SET why = 'Carotenoids such as beta-carotene absorb light in wavelengths that chlorophyll misses, broadening the range used for photosynthesis. They also protect the photosynthetic apparatus, including chlorophyll, from damage caused by too much light.', wrong = '{"1": "Water is split at photosystem II by an enzyme complex, not by carotenoids.", "2": "CO₂ is fixed in the stroma by the enzyme rubisco during the Calvin cycle, not by carotenoids.", "3": "The reaction centre of PS-I is a special chlorophyll a molecule, P700, not a carotenoid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1072' AND answer = 0;
UPDATE questions SET why = 'Chlorophyll a is the main photosynthetic pigment; it forms the reaction centres of the photosystems. Accessory pigments are the other pigments, such as chlorophyll b, carotenoids (including xanthophylls) and phycobilins. They absorb extra wavelengths and pass the energy to chlorophyll a.', wrong = '{"0": "Chlorophyll b is an accessory pigment. It absorbs light and passes the energy on to chlorophyll a.", "2": "Xanthophylls are yellow carotenoids that act as accessory pigments in the light-harvesting antenna.", "3": "Phycobilins are accessory pigments of red algae and cyanobacteria that pass energy to chlorophyll a."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1073' AND answer = 1;
UPDATE questions SET why = 'Accessory pigments differ between groups. Chlorophyll b and carotenoids are found in plants, while phycobilins are found in red algae and cyanobacteria. Phycobilins absorb wavelengths that chlorophyll misses and pass the energy on to chlorophyll a.', wrong = '{"0": "Flowering plants use chlorophyll b and carotenoids as accessory pigments, not phycobilins.", "1": "Fungi are not photosynthetic, so they have no photosynthetic pigments at all.", "2": "Mosses are plants and use chlorophylls a and b with carotenoids. Phycobilins belong to red algae and cyanobacteria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1074' AND answer = 3;
UPDATE questions SET why = 'Accessory pigments pass the light energy they absorb towards chlorophyll a, which sits in the reaction centre. In plants the energy is generally believed to flow from carotenoids to chlorophyll b and then to chlorophyll a. Chlorophyll a is always the final receiver.', wrong = '{"0": "This is the exact reverse. Energy flows towards chlorophyll a, not away from it.", "1": "Carotenoids start the chain, not chlorophyll b. Energy goes from carotenoids to chlorophyll b.", "3": "Chlorophyll a must be last, because it is in the reaction centre that receives the energy."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1075' AND answer = 2;
UPDATE questions SET why = 'An absorption spectrum plots how much light a pigment absorbs at each wavelength. For chlorophylls, absorption is maximum in the blue at about 430 nm and in the red at about 670 nm. Green wavelengths in between are absorbed least.', wrong = '{"0": "500 to 550 nm is the green region, which chlorophylls absorb least and reflect.", "1": "680 and 700 nm name the reaction-centre chlorophylls of PS-II (P680) and PS-I (P700), not the absorption peaks.", "3": "300 nm is ultraviolet and 800 nm is infrared. Both lie outside the chlorophyll peaks."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1076' AND answer = 2;
UPDATE questions SET why = 'The action spectrum shows how well each wavelength drives photosynthesis, and the absorption spectrum shows which wavelengths the pigments absorb. Both peak in the blue and red. Their close match shows that the light absorbed by the pigments is what drives photosynthesis.', wrong = '{"0": "Green light is absorbed least and is the least effective, so it does not drive photosynthesis best.", "1": "Chlorophylls are the main absorbers and are fully involved. Carotenoids only add to the range of light used.", "2": "The match of the two spectra shows light is essential. It drives the light-dependent reactions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1077' AND answer = 3;
UPDATE questions SET why = 'Chlorophyll a and chlorophyll b have slightly different absorption peaks. Some wavelengths that chlorophyll a absorbs poorly are taken up well by chlorophyll b, and vice versa. Together they absorb a wider range of light, so the plant captures more energy.', wrong = '{"1": "Both chlorophylls absorb blue light strongly. The difference adds wavelengths; it does not remove blue.", "2": "The reaction centres of both photosystems contain chlorophyll a (P680 and P700), not chlorophyll b.", "3": "CO₂ is fixed by the enzyme rubisco in the stroma. Pigments only absorb light."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1078' AND answer = 0;
UPDATE questions SET why = 'Pigments in the thylakoid membrane are grouped into photosystems. Each has a light-gathering antenna complex, with many pigment molecules that capture light, and a reaction centre with chlorophyll a. The antenna passes the energy to the reaction centre.', wrong = '{"0": "The stroma and the lumen are compartments of the chloroplast, not parts of a photosystem.", "2": "Rubisco and RuBP take part in the Calvin cycle in the stroma, not in the photosystems.", "3": "ATP synthase and ferredoxin are separate proteins of the light reactions. They are not the two parts of a photosystem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1079' AND answer = 1;
UPDATE questions SET why = 'In each photosystem, the antenna pigments pass energy to the reaction centre. The chlorophyll a there becomes excited and passes its high-energy electrons to a primary electron acceptor. The acceptor then hands them on to the electron transport chain.', wrong = '{"1": "Energy flows from the antenna complex to the reaction centre, not back the other way.", "2": "Rubisco is the enzyme that fixes CO₂ in the stroma. It does not receive electrons from photosystems.", "3": "Oxygen is the final electron acceptor in respiration. In photosynthesis oxygen is released from water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1080' AND answer = 0;
UPDATE questions SET why = 'The two photosystems were named PS-I and PS-II in the order they were discovered. This numbering does not follow the electron flow: in non-cyclic photophosphorylation electrons pass through PS-II first and then PS-I.', wrong = '{"0": "Electrons pass from PS-II to PS-I, which is the opposite of the numbering. So electron order is not the basis.", "2": "PS-I absorbs best at 700 nm and PS-II at 680 nm, but the numbers I and II do not come from these wavelengths.", "3": "The photosystems are not numbered by size. The names follow the order of discovery."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1081' AND answer = 1;
UPDATE questions SET why = 'Each reaction centre has a special chlorophyll a named after the wavelength it absorbs best. In photosystem II this is P680, which absorbs best at 680 nm. In photosystem I it is P700, absorbing best at 700 nm.', wrong = '{"0": "430 nm is the blue absorption peak of chlorophylls. There is no P430 reaction centre.", "1": "670 nm is the red absorption peak of chlorophylls in general, not the PS-II reaction centre.", "3": "P700 is the reaction-centre chlorophyll of photosystem I."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1082' AND answer = 2;
UPDATE questions SET why = 'In the light-dependent reactions, light energy is absorbed, electrons are excited, and the energy is stored as ATP (assimilating power) and NADPH (reducing power). The light-independent reactions then use this ATP and NADPH to reduce CO₂ to sugar.', wrong = '{"0": "Glucose is built in the Calvin cycle in the stroma. Oxygen is only a by-product of splitting water.", "1": "RuBP and CO₂ are the starting materials of the Calvin cycle, not stores of light energy.", "3": "FADH₂ and NADH are reduced coenzymes of respiration, made in mitochondria."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1083' AND answer = 2;
UPDATE questions SET why = 'Non-cyclic photophosphorylation is the usual way ATP is made in the light reactions. Both photosystems take part: electrons flow from water to PS-II, then along a chain to PS-I, and finally to NADP⁺. Two electron transport chains are involved, and ATP, NADPH and O₂ are produced.', wrong = '{"0": "Only PS-I takes part in cyclic photophosphorylation, where electrons return to P700.", "1": "PS-II alone cannot reduce NADP⁺. Its electrons must pass on to PS-I in non-cyclic flow.", "2": "Two electron transport chains are used, one between PS-II and PS-I and one after PS-I."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1084' AND answer = 3;
UPDATE questions SET why = 'When P680 passes its excited electrons to the primary acceptor, an electron hole is left in it. This makes P680 a very strong oxidising agent, strong enough to pull electrons from water. Splitting water in this way refills the hole and releases oxygen.', wrong = '{"1": "NADP⁺ is reduced by electrons that come from PS-I through ferredoxin, not directly by P680.", "2": "P680 is not inactivated. Its hole is filled by electrons from water and it keeps working.", "3": "H⁺ pumping happens as electrons move along the chain of carriers, not by P680 itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1085' AND answer = 0;
UPDATE questions SET why = 'In photolysis, a water molecule reacts with the oxidised P680 of PS-II and breaks into two hydrogen ions, two electrons and one oxygen atom. The electrons fill the hole in P680, and the oxygen atom joins another to form O₂.', wrong = '{"0": "One water molecule has only one oxygen atom. Two water molecules are needed to give one O₂ molecule.", "1": "Photolysis releases electrons, which refill P680. It does not just form H⁺ and a hydroxide ion.", "2": "Glucose is made later in the stroma by the Calvin cycle, not by splitting water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1086' AND answer = 3;
UPDATE questions SET why = 'Excited electrons from PS-II pass to PS-I along an electron transport chain. In order, the carriers are plastoquinone (PQ), the cytochrome complex and plastocyanin (PC). As the electrons lose energy along the way, it is used to make ATP by chemiosmosis.', wrong = '{"0": "This lists the right carriers in reverse. Plastoquinone comes first and plastocyanin last.", "2": "Ferredoxin and NADP reductase work after PS-I, passing electrons to NADP⁺.", "3": "Coenzyme Q and cytochromes b and c are carriers of the mitochondrial chain in respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1087' AND answer = 1;
UPDATE questions SET why = 'After PS-I, the excited electrons pass through a second chain and reach ferredoxin (FD). The enzyme NADP reductase then transfers them from ferredoxin to NADP⁺. With two electrons and one H⁺, NADP⁺ is reduced to NADPH.', wrong = '{"0": "ATP synthase uses the flow of H⁺ ions to make ATP. It does not reduce NADP⁺.", "1": "Rubisco fixes CO₂ to RuBP in the Calvin cycle. It does not handle electrons from ferredoxin.", "3": "Plastocyanin carries electrons between the cytochrome complex and PS-I, before ferredoxin."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1088' AND answer = 2;
UPDATE questions SET why = 'In non-cyclic flow, electrons are lifted to a high energy level at PS-II, fall along a chain, are lifted again at PS-I, and fall again to NADP⁺. Drawn on an energy diagram this path looks like a zigzag, so it is called the Z-scheme.', wrong = '{"1": "The Calvin cycle is the light-independent fixation of CO₂ in the stroma, not an electron path.", "2": "The Krebs cycle is a stage of aerobic respiration in the mitochondrial matrix.", "3": "The C4 pathway fixes CO₂ first into a four-carbon acid. It is not an electron path."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1089' AND answer = 0;
UPDATE questions SET why = 'In cyclic photophosphorylation only PS-I is used. Its excited electrons pass to the primary acceptor and then cycle back to P700 through the electron transport chain. ATP is made on the way, but no NADPH is formed and no water is split, so no oxygen is released.', wrong = '{"0": "ATP, NADPH and oxygen together are the products of non-cyclic photophosphorylation.", "2": "No NADPH and no oxygen are made in cyclic flow, and this choice leaves out ATP, its only product.", "3": "Glucose is made in the Calvin cycle, not directly by any light reaction."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1090' AND answer = 1;
UPDATE questions SET why = 'The Calvin cycle uses more ATP than NADPH. When it slows down, NADPH builds up and little NADP⁺ is free to accept electrons. The excited electrons of PS-I then cycle back to P700, making extra ATP without making more NADPH.', wrong = '{"0": "Water supply and dim light are not the condition named. Cyclic flow is linked to NADPH building up.", "1": "Cyclic flow uses PS-I itself, so a damaged PS-I could not carry it out.", "3": "Plenty of NADP⁺ lets electrons flow on to NADP⁺, which favours the non-cyclic pathway."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1091' AND answer = 2;
UPDATE questions SET why = 'As electrons pass along the thylakoid carriers, the energy released is used to actively pump H⁺ ions from the stroma into the thylakoid lumen. The H⁺ gradient stores potential energy. H⁺ then diffuses back to the stroma through ATP synthase, which uses that flow to make ATP.', wrong = '{"0": "Lumen to stroma is the downhill direction in which H⁺ diffuses back through ATP synthase, not the pumping.", "1": "The cytosol is outside the chloroplast. Pumping happens across the thylakoid membrane.", "2": "Pumping from the matrix to the intermembrane space happens in mitochondria during respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1092' AND answer = 3;
UPDATE questions SET why = 'Melvin Calvin and his colleagues at the University of California worked out the details of the light-independent (dark) reactions. That is why these reactions are called the Calvin cycle. Calvin received the Nobel Prize in 1961 for this work.', wrong = '{"0": "ATP was discovered by Karl Lohmann in 1929, not by Calvin.", "1": "The first action spectrum was made by T. W. Engelmann in 1883 using Spirogyra.", "2": "The citric acid cycle is the Krebs cycle, named after Hans Krebs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1093' AND answer = 3;
UPDATE questions SET why = 'The light-independent reactions do not use light directly. They use ATP and NADPH made in the light reactions. So they can run in the dark as well as in light, as long as ATP and NADPH are available. That is why they are also called dark reactions.', wrong = '{"0": "The absence of oxygen is not the condition. These reactions need ATP and NADPH, not darkness or lack of oxygen.", "2": "All photosynthetic plants, C3 and C4, use the Calvin cycle. It is not limited to C4 plants.", "3": "They can occur in the dark for as long as ATP and NADPH from the light reactions last."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1094' AND answer = 1;
UPDATE questions SET why = 'In carbon fixation, the enzyme rubisco joins three CO₂ molecules to three molecules of the five-carbon sugar RuBP. The unstable products split at once, giving six molecules of the three-carbon compound 3-phosphoglyceric acid (3-PGA). Check: 3 × 5 + 3 × 1 = 18 carbons = 6 × 3.', wrong = '{"0": "Glucose is not formed in fixation. It is made later from G3P that leaves the cycle.", "1": "G3P is formed in the next phase, reduction, when 3-PGA is phosphorylated by ATP and reduced by NADPH.", "3": "Oxaloacetic acid, a four-carbon acid, is the first product of CO₂ fixation in C4 plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1095' AND answer = 2;
UPDATE questions SET why = 'Rubisco (ribulose biphosphate carboxylase) is the enzyme that fixes CO₂ onto RuBP in the Calvin cycle. It is present in huge amounts in the chloroplasts of every plant, so it is probably the most abundant protein on Earth.', wrong = '{"1": "Rubisco is a large enzyme made of several subunits. It is not described as the smallest enzyme.", "2": "Rubisco is an enzyme of the stroma, not a light-absorbing pigment of PS-I.", "3": "Rubisco works in the Calvin cycle in chloroplasts, not in glycolysis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1096' AND answer = 0;
UPDATE questions SET why = 'In the Calvin cycle, the first stable product of carbon fixation is 3-phosphoglyceric acid, which has three carbon atoms. Plants that fix carbon only by this route are therefore called C3 plants. In C4 plants the first product is a four-carbon acid.', wrong = '{"0": "Chloroplasts have two photosystems, PS-I and PS-II. The name has nothing to do with photosystems.", "1": "About three ATP are used per CO₂ fixed, but this is not why the plants are called C3.", "2": "Carbon is fixed continuously while ATP and NADPH are available. C3 refers to a three-carbon product."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1097' AND answer = 3;
UPDATE questions SET why = 'Three CO₂ fixed give six 3-PGA. In the reduction phase, six ATP add a phosphate to each 3-PGA, forming 1,3-biphosphoglyceric acid. Six NADPH then supply the hydrogen that reduces these to six G3P. So six ATP and six NADPH are used.', wrong = '{"1": "Three is only half of what is needed. Each of the six 3-PGA needs one ATP and one NADPH.", "2": "Reduction cannot happen without NADPH. Total ATP for three CO₂ is nine (six here, three to regenerate RuBP).", "3": "NADH and FADH₂ are coenzymes of respiration. The Calvin cycle uses ATP and NADPH."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1098' AND answer = 0;
UPDATE questions SET why = 'For every three CO₂ fixed, six G3P are made. Only one G3P leaves the cycle as the net product. The other five are used to regenerate three RuBP so the cycle can continue. Two such G3P can combine to form one glucose.', wrong = '{"0": "Two G3P are needed to make one glucose, but only one G3P leaves per three CO₂ fixed.", "2": "Three is the number of RuBP regenerated, not the number of G3P that leave.", "3": "Five G3P stay in the cycle and are recycled to RuBP. Only one leaves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1099' AND answer = 1;
UPDATE questions SET why = 'In the regeneration phase, five G3P (5 × 3 = 15 carbons) are rearranged into three molecules of ribulose phosphate, RuP (3 × 5 = 15 carbons). Three ATP then add one phosphate to each RuP, giving three RuBP that can accept CO₂ again.', wrong = '{"0": "Five G3P have 15 carbons, enough for only three five-carbon sugars, not five.", "1": "Glucose is made from the G3P that leaves the cycle, not from the five recycled ones.", "3": "3-PGA is formed in the fixation phase, when CO₂ joins RuBP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1100' AND answer = 2;
UPDATE questions SET why = 'Glyceraldehyde 3-phosphate (G3P) made in the Calvin cycle is the same three-carbon sugar formed in glycolysis when glucose is split. This shows a direct link between photosynthesis and respiration, since G3P can be built into glucose or broken down for energy.', wrong = '{"0": "The CO₂ acceptor of the Calvin cycle is RuBP, a five-carbon sugar, not G3P.", "2": "G3P has three carbon atoms. RuBP and RuP are the five-carbon sugars.", "3": "G3P is made in the stroma by the Calvin cycle. The light reactions produce ATP, NADPH and O₂."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1101' AND answer = 1;
UPDATE questions SET why = 'Cellular respiration breaks down carbon compounds to release usable energy. Almost all cells in all organisms use glucose as their main energy source, and its breakdown starts with glycolysis in every cell. That is why glucose is called the respiratory fuel.', wrong = '{"0": "Glucose is made in photosynthesis, not in mitochondria. Respiration breaks it down.", "1": "Glucose has many C-H bonds, and these store the energy released in respiration.", "3": "Fats and proteins can also be oxidised for energy. Glucose is simply the fuel used by almost all cells."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1102' AND answer = 2;
UPDATE questions SET why = 'The energy of a fuel is stored in its C-H bonds. Glucose has many C-H bonds, while CO₂ and H₂O have none. So the arrangement of atoms in glucose holds much more energy, and respiration releases this energy as glucose is oxidised to CO₂ and water.', wrong = '{"0": "CO₂ and water are actually richer in oxygen. Oxygen-rich, fully oxidised molecules hold little energy.", "1": "Glucose has no phosphate groups. Phosphate bonds are found in ATP.", "2": "Glucose contains only C, H and O. It has no nitrogen ring."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1103' AND answer = 3;
UPDATE questions SET why = 'The word respiration is used at two levels. The exchange of O₂ and CO₂ between an organism and its surroundings is external respiration, or breathing. The step-by-step oxidation of food inside cells to release energy is cellular respiration.', wrong = '{"1": "Cellular respiration is the oxidation of food inside cells to release energy, not gas exchange with the environment.", "2": "Photorespiration is a process in green cells in light, where rubisco adds O₂ to RuBP and CO₂ is released.", "3": "Fermentation is anaerobic respiration, in which glucose is partly broken down without oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1104' AND answer = 0;
UPDATE questions SET why = 'In anaerobic respiration glucose is not fully oxidised. Glycolysis gives a net of only 2 ATP per glucose, which is about 2% of the energy in glucose. The energy in these 2 ATP is 2 × 7.3 = 14.6 kcal.', wrong = '{"0": "36 ATP is the net yield of aerobic respiration, when glucose is fully oxidised to CO₂ and water.", "1": "4 ATP are made in glycolysis, but 2 are spent in the preparatory phase, so the net yield is only 2 ATP.", "3": "Glycolysis does produce ATP even without oxygen, a net gain of 2 ATP per glucose."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1105' AND answer = 2;
UPDATE questions SET why = 'Anaerobic respiration is glycolysis followed by the reduction of pyruvic acid. NADH made in glycolysis gives its hydrogen to pyruvic acid, forming lactic acid, or alcohol and CO₂. This turns NADH back into NAD⁺ so that glycolysis can keep going.', wrong = '{"0": "FADH₂ is made in the Krebs cycle, which needs oxygen. It is not used in fermentation.", "1": "NADPH is the reducing power of photosynthesis, used in the Calvin cycle, not in fermentation.", "2": "Anaerobic respiration happens without oxygen. Oxygen is the electron acceptor only in aerobic respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1106' AND answer = 3;
UPDATE questions SET why = 'During extreme physical activity, muscles use energy faster than blood can deliver oxygen to them. The muscle cells then switch to lactic acid fermentation, in which pyruvic acid is reduced to lactic acid, so that glycolysis can still make some ATP.', wrong = '{"0": "At rest, enough oxygen reaches the muscles, so they respire aerobically.", "2": "Glucose is needed for glycolysis. Lactic acid fermentation starts from glucose, so glucose must be present.", "3": "When oxygen is plentiful, cells carry out aerobic respiration, not lactic acid fermentation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1107' AND answer = 1;
UPDATE questions SET why = 'In alcoholic fermentation, which happens in yeast and some bacteria, each pyruvic acid is broken down into ethyl alcohol (C₂H₅OH) and carbon dioxide. The NADH from glycolysis supplies the hydrogen. This is why yeast makes bread dough rise.', wrong = '{"1": "Lactic acid alone is the product of lactic acid fermentation, as in muscle cells.", "2": "Lactic acid fermentation releases no CO₂. Carbon dioxide comes with alcohol, not with lactic acid.", "3": "Acetyl CoA and NADH are made when pyruvic acid is oxidised in the mitochondria during aerobic respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1108' AND answer = 0;
UPDATE questions SET why = 'When life first evolved on Earth, there was no free oxygen in the atmosphere, so only anaerobic respiration was possible. After photosynthesis evolved, oxygen slowly built up in the air. Free oxygen then made aerobic respiration possible.', wrong = '{"1": "Glucose was used in early anaerobic respiration. What was missing was free oxygen.", "2": "The reason given is the lack of oxygen, not any feature of mitochondria.", "3": "ATP is made by glycolysis even without oxygen, so it was available to early life."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1109' AND answer = 0;
UPDATE questions SET why = 'Glycolysis takes place in the cytosol and does not need oxygen. The other three stages of aerobic respiration, pyruvic acid oxidation, the Krebs cycle and the electron transport chain, take place inside mitochondria, where oxygen is essential.', wrong = '{"0": "Pyruvic acid oxidation takes place inside the mitochondrion, after pyruvic acid enters it.", "1": "The Krebs cycle takes place in the mitochondrial matrix, not in the cytosol.", "2": "The electron transport chain is built into the inner membrane of the mitochondrion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1110' AND answer = 3;
UPDATE questions SET why = 'Glycolysis begins with an energy investment. In the first step a phosphate group is transferred from ATP to glucose, forming glucose 6-phosphate. This makes glucose more reactive and keeps it inside the cell.', wrong = '{"0": "Fructose 6-phosphate forms in the second step, by rearranging glucose 6-phosphate. NAD⁺ is not used in the preparatory phase.", "1": "Pyruvic acid is the end product of glycolysis, made only after many steps.", "3": "G3P forms later, when fructose 1,6-biphosphate splits into two three-carbon sugars."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1111' AND answer = 2;
UPDATE questions SET why = 'Fructose 1,6-biphosphate is highly reactive and splits into two three-carbon sugars: glyceraldehyde 3-phosphate (G3P) and dihydroxyacetone phosphate (DAP). These two are interconverted, so in effect one glucose gives two molecules of G3P.', wrong = '{"0": "Pyruvic acid is formed only at the very end of glycolysis, after the oxidative phase.", "2": "Glucose and fructose are six-carbon sugars. The split gives two three-carbon sugars.", "3": "3-PGA and 2-PGA form later, in the oxidative phase, from 1,3-biphosphoglyceric acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1112' AND answer = 1;
UPDATE questions SET why = 'The preparatory phase spends energy. One ATP adds a phosphate to glucose to form glucose 6-phosphate, and a second ATP adds another phosphate to fructose 6-phosphate to form fructose 1,6-biphosphate. So two ATP are spent per glucose.', wrong = '{"0": "There are two phosphorylation steps in the preparatory phase, each using one ATP.", "1": "Four ATP are produced in the oxidative phase, not spent in the preparatory phase.", "2": "The preparatory phase is an energy investment. It uses two ATP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1113' AND answer = 3;
UPDATE questions SET why = 'In the first step of the oxidative phase, two hydrogen atoms (with high-energy electrons) are removed from G3P and passed to NAD⁺, which becomes NADH. At the same time an inorganic phosphate is added. G3P becomes 1,3-biphosphoglyceric acid (1,3-BPGA).', wrong = '{"1": "3-PGA forms in the next step, when 1,3-BPGA gives one phosphate to ADP to make ATP.", "2": "No CO₂ is released anywhere in glycolysis. CO₂ is first released when pyruvic acid is oxidised.", "3": "PEP is formed later by removing water from 2-phosphoglyceric acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1114' AND answer = 0;
UPDATE questions SET why = 'In the oxidative phase, 3-PGA is first converted to 2-phosphoglyceric acid (2-PGA). Then water is removed from 2-PGA (dehydration), producing phosphoenol pyruvic acid (PEP). PEP then gives its high-energy phosphate to ADP and becomes pyruvic acid.', wrong = '{"0": "Adding CO₂ to PEP happens in C4 plants and gives oxaloacetic acid, not PEP.", "1": "Oxidising G3P gives 1,3-biphosphoglyceric acid, an earlier step.", "3": "Glycolysis runs from PEP to pyruvic acid, with ATP made. Adding phosphate to pyruvic acid would be the reverse."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1115' AND answer = 2;
UPDATE questions SET why = 'Glycolysis can be run in reverse. Pyruvic acid can be turned back into glucose by reversing glycolysis, a process called gluconeogenesis. The name means making new glucose.', wrong = '{"0": "The breakdown of glycogen into glucose is called glycogenolysis, not gluconeogenesis.", "2": "Fats are hydrolysed into glycerol and fatty acids. This is digestion of fat, not making glucose.", "3": "Converting glucose to ethanol and CO₂ is alcoholic fermentation, a form of anaerobic respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1116' AND answer = 1;
UPDATE questions SET why = 'Glucose moves from tissue fluid into cells by passive transport, so no ATP is spent. It needs a specific glucose carrier protein in the membrane. This carrier can be controlled (gated) by hormones such as insulin.', wrong = '{"0": "Glucose enters cells by passive transport, down its concentration gradient. ATP is not used.", "2": "Glucose is too large and polar to cross the lipid bilayer by simple diffusion. It needs a specific carrier.", "3": "Endocytosis takes in large particles or droplets. Glucose uses a carrier protein instead."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1117' AND answer = 1;
UPDATE questions SET why = 'Pyruvic acid cannot enter the Krebs cycle directly. First a CO₂ is removed, leaving acetaldehyde. Next, acetaldehyde is oxidised (NAD⁺ is reduced to NADH) to an acetyl group. Finally the acetyl group joins coenzyme A to form acetyl CoA.', wrong = '{"0": "The order is wrong. Acetaldehyde forms first, and its oxidation gives the acetyl group.", "1": "Lactic acid is a product of fermentation without oxygen. It is not an intermediate in forming acetyl CoA.", "2": "Citric acid forms only after acetyl CoA enters the Krebs cycle and joins oxaloacetic acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1118' AND answer = 3;
UPDATE questions SET why = 'When one pyruvic acid is changed to acetyl CoA, one CO₂ is removed and acetaldehyde is oxidised, which reduces one NAD⁺ to NADH. So each pyruvic acid gives one CO₂ and one NADH, or two of each per glucose.', wrong = '{"1": "No ATP is made at this stage. ATP comes from glycolysis, the Krebs cycle and chemiosmosis.", "2": "FADH₂ is made in the Krebs cycle, when succinic acid is oxidised to fumaric acid.", "3": "Oxygen is consumed at the end of the electron transport chain, never produced in respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1119' AND answer = 0;
UPDATE questions SET why = 'In the first step of the Krebs cycle, acetyl CoA releases its two-carbon acetyl group. This joins the four-carbon oxaloacetic acid to form the six-carbon citric acid (2 + 4 = 6). The cycle is also named the citric acid cycle after this product.', wrong = '{"0": "Pyruvic acid (3C) is first converted to acetyl CoA. It does not combine with the acetyl group.", "1": "Alpha-ketoglutaric acid (5C) is formed from citric acid later in the cycle.", "3": "Malic acid (4C) is near the end of the cycle. It is oxidised to regenerate oxaloacetic acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1120' AND answer = 2;
UPDATE questions SET why = 'Citric acid (6C) undergoes oxidative decarboxylation: it loses one CO₂ (decarboxylation) and is oxidised, reducing NAD⁺ to NADH. The product is the five-carbon alpha-ketoglutaric acid (6 − 1 = 5 carbons).', wrong = '{"1": "Succinic acid (4C) forms from alpha-ketoglutaric acid after a second CO₂ is removed.", "2": "Fumaric acid (4C) forms when succinic acid is oxidised and FAD is reduced.", "3": "Oxaloacetic acid (4C) is regenerated at the end of the cycle from malic acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1121' AND answer = 0;
UPDATE questions SET why = 'When two hydrogen atoms are removed from succinic acid, the free energy released is too small to reduce NAD⁺. So a different electron acceptor, the coenzyme FAD (flavin adenine dinucleotide), is used and is reduced to FADH₂.', wrong = '{"0": "NAD⁺ is constantly regenerated and is used in later steps of the cycle, so it is not used up.", "1": "FAD carries hydrogen atoms and electrons, not oxygen.", "2": "No CO₂ is released when succinic acid becomes fumaric acid; both have four carbons."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1122' AND answer = 3;
UPDATE questions SET why = 'To regenerate oxaloacetic acid, the cycle continues from fumaric acid. A molecule of water is added to fumaric acid, changing it into malic acid. Malic acid is then oxidised to oxaloacetic acid, reducing NAD⁺ to NADH.', wrong = '{"0": "No CO₂ is removed at this step. Fumaric acid and malic acid both have four carbons.", "1": "FAD is reduced in the step before this, when succinic acid is oxidised to fumaric acid.", "3": "This step uses no ATP. It is only the addition of water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1123' AND answer = 2;
UPDATE questions SET why = 'CO₂ is released in the Krebs cycle only where a carbon is removed: when citric acid (6C) becomes alpha-ketoglutaric acid (5C), and when alpha-ketoglutaric acid (5C) becomes the four-carbon succinic acid, via succinyl CoA. Of the steps listed, only the second loses a carbon.', wrong = '{"0": "Malic acid and oxaloacetic acid both have four carbons. This oxidation reduces NAD⁺ but removes no carbon.", "2": "Fumaric acid to malic acid is the addition of water. No carbon is lost.", "3": "Succinic acid to fumaric acid reduces FAD to FADH₂. Both have four carbons, so no CO₂ is released."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1124' AND answer = 1;
UPDATE questions SET why = 'In respiration, CO₂ is released during pyruvic acid oxidation and the Krebs cycle, before oxygen is used. Its carbon comes from glucose. Oxygen is used only at the end of the electron transport chain, where it takes up electrons and H⁺ to form water. So respiration turns glucose into CO₂ and oxygen into water.', wrong = '{"0": "The carbon of CO₂ comes from glucose, and the CO₂ is released before oxygen is involved. Oxygen becomes water.", "1": "Splitting water to release oxygen is photolysis in photosynthesis, the reverse of what respiration does.", "2": "Turning carbon dioxide into glucose is photosynthesis, not respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1125' AND answer = 3;
UPDATE questions SET why = 'Much of this cycle was worked out by the British biochemist Sir Hans Krebs, so it is called the Krebs cycle. It is also called the citric acid cycle, after the six-carbon citric acid formed in its first step.', wrong = '{"0": "The six-carbon citric acid gives the cycle its other name, the citric acid cycle, not the name Krebs cycle.", "2": "Melvin Calvin worked out the light-independent reactions of photosynthesis, the Calvin cycle.", "3": "Naming after a plant family applies to CAM (Crassulacean acid metabolism), not to the Krebs cycle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1126' AND answer = 1;
UPDATE questions SET why = 'The electron transport chain of respiration is built into the inner membrane of the mitochondrion. Its carriers pass electrons from NADH and FADH₂ to oxygen and pump H⁺ across this membrane. The folds of the inner membrane (cristae) give room for many chains.', wrong = '{"0": "The outer mitochondrial membrane is a smooth outer covering. It does not hold the electron carriers.", "1": "The matrix holds the enzymes of pyruvic acid oxidation and the Krebs cycle, not the electron transport chain.", "3": "The cytosol is where glycolysis takes place, outside the mitochondrion."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1127' AND answer = 2;
UPDATE questions SET why = 'NADH is oxidised at the start of the chain and its electrons are taken up by coenzyme Q. Reduced CoQ passes them to cytochrome b, which passes them to cytochrome c. Cytochrome c hands them to the cytochrome a complex, which finally gives them to oxygen.', wrong = '{"1": "This is the chain in reverse. Electrons flow from coenzyme Q towards oxygen, ending at the cytochrome a complex.", "2": "Cytochrome b comes before cytochrome c, not after it.", "3": "Plastoquinone, cytochrome complex and plastocyanin form the chain between PS-II and PS-I in chloroplasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1128' AND answer = 0;
UPDATE questions SET why = 'At the end of the respiratory chain, the cytochrome a complex passes electrons to an oxygen atom. Having taken two electrons, the oxygen also takes up two H⁺ ions and forms water. Without oxygen as the final acceptor, the chain stops.', wrong = '{"0": "NAD⁺ accepts hydrogen in glycolysis and the Krebs cycle. Its reduced form NADH feeds electrons into the chain.", "2": "Coenzyme Q is the first carrier of the chain. It passes electrons on, it is not the final acceptor.", "3": "NADP⁺ is the final electron acceptor in the light reactions of photosynthesis, not in respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1129' AND answer = 1;
UPDATE questions SET why = 'NADH is oxidised at the start of the chain and its electrons go to coenzyme Q. When FADH₂ is oxidised, its electrons also move to coenzyme Q. Because FADH₂ electrons skip the first step, they drive the making of fewer ATP: two instead of three.', wrong = '{"1": "Cytochrome c is further along the chain, after cytochrome b. FADH₂ electrons enter earlier, at coenzyme Q.", "2": "The cytochrome a complex is the last carrier, which passes electrons to oxygen.", "3": "Oxygen is the final acceptor. Electrons must pass through the carriers before reaching it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1130' AND answer = 0;
UPDATE questions SET why = 'As electrons move along the respiratory chain, the energy released is used to actively pump H⁺ ions from the mitochondrial matrix into the intermembrane space. The H⁺ gradient stores potential energy. H⁺ then flows back to the matrix through ATP synthase, driving ATP synthesis.', wrong = '{"0": "Intermembrane space to matrix is the direction in which H⁺ flows back through ATP synthase, not the pumping.", "1": "Stroma to lumen is the pumping direction in chloroplasts during photosynthesis.", "3": "The cytosol is outside the mitochondrion and is not part of this H⁺ gradient."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1131' AND answer = 2;
UPDATE questions SET why = 'When NADH passes its electrons into the chain, enough H⁺ is pumped to make three ATP by chemiosmosis. FADH₂ enters later, at coenzyme Q, so its oxidation yields only two ATP.', wrong = '{"0": "One ATP is too low. Each NADH oxidised in the chain gives three ATP.", "1": "Two ATP come from each FADH₂ (and from each NADH of glycolysis after transport costs), not from an ordinary NADH.", "3": "Four ATP is too high. The figure for one NADH is three."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1132' AND answer = 2;
UPDATE questions SET why = 'In substrate-level phosphorylation an enzyme transfers a phosphate group directly from an organic substrate to ADP, making ATP. No membrane or electron transport chain is involved. An example is the last step of glycolysis, where PEP gives its phosphate to ADP and becomes pyruvic acid.', wrong = '{"0": "Substrate-level phosphorylation does not need light. It happens in glycolysis and the Krebs cycle.", "1": "An H⁺ gradient across a membrane drives chemiosmosis, not substrate-level phosphorylation.", "2": "Substrate-level phosphorylation makes only a small share of the cell''s ATP. Chemiosmosis makes most of it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1133' AND answer = 3;
UPDATE questions SET why = 'Substrate-level phosphorylation makes ATP without a membrane or electron transport chain. In the last step of glycolysis, an enzyme transfers the high-energy phosphate from phosphoenol pyruvic acid (PEP) directly to ADP. ADP becomes ATP, and PEP becomes pyruvic acid.', wrong = '{"0": "ATP synthase makes ATP using the flow of H⁺ ions across a membrane. That is chemiosmosis, not substrate-level phosphorylation.", "1": "Reduction of NADP⁺ by electrons from ferredoxin makes NADPH. No ATP is formed in this step.", "2": "Passing electrons from NADH to coenzyme Q is part of the electron transport chain, which leads to chemiosmosis."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1134' AND answer = 3;
UPDATE questions SET why = 'NADH from glycolysis is made in the cytoplasm, but the electron transport chain is inside the mitochondrion. Moving each NADH across the mitochondrial membrane costs one ATP. So each glycolytic NADH gives 3 − 1 = 2 ATP in the final balance, instead of three.', wrong = '{"1": "NADH is oxidised by the electron transport chain, passing its electrons to coenzyme Q. It is not oxidised by FAD.", "2": "Electrons do not enter at cytochrome c. The lower yield is explained by the cost of transport into the mitochondrion.", "3": "In aerobic respiration this NADH goes to the electron transport chain. Fermentation happens only without oxygen."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1135' AND answer = 0;
UPDATE questions SET why = 'Adding up glycolysis, pyruvic acid oxidation, the Krebs cycle and the electron transport chain, aerobic oxidation of one glucose gives a net 36 ATP in the standard FSc balance sheet. Anaerobic respiration gives only 2 ATP, so aerobic respiration is 36 ÷ 2 = 18 times more efficient.', wrong = '{"0": "2 ATP is the net yield of anaerobic respiration, which uses glycolysis alone.", "1": "18 is the efficiency ratio, 36 ÷ 2, not the number of ATP made.", "3": "38 ATP is the figure obtained when the cost of moving glycolytic NADH into the mitochondrion is ignored. After that cost, the net figure is 36."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1136' AND answer = 2;
UPDATE questions SET why = 'Proteins are first digested into amino acids. Most amino acids are used to build the cell''s own proteins. Those used as fuel are first deaminated (the amino group is removed), and the rest of the molecule is converted to pyruvic acid, acetyl CoA or Krebs cycle acids, which then release energy as ATP.', wrong = '{"0": "Glycerol comes from the hydrolysis of fats, not from amino acids.", "1": "Amino acids are not converted directly to glucose in the cytosol before respiration. They enter at pyruvic acid, acetyl CoA or the Krebs cycle.", "3": "Storing amino acids as fat is not how they are used as respiratory fuel. They are deaminated and fed into respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1137' AND answer = 2;
UPDATE questions SET why = 'Fats are first hydrolysed into glycerol and fatty acids. Glycerol is converted to glyceraldehyde 3-phosphate (G3P), an intermediate of glycolysis, and enters there. Fatty acids are changed into acetyl CoA and enter the Krebs cycle.', wrong = '{"0": "Acetyl CoA is the entry point of the fatty acids, not of glycerol.", "2": "Glycerol enters glycolysis at G3P, before pyruvic acid. It is not converted straight to pyruvic acid.", "3": "Citric acid is formed inside the Krebs cycle when acetyl CoA joins oxaloacetic acid. Glycerol does not enter as citric acid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1138' AND answer = 1;
UPDATE questions SET why = 'The energy of a fuel lies in its C-H bonds. Lipids contain many carbon-hydrogen bonds, more per gram than carbohydrates or proteins, so they release a lot of energy. Before use they are hydrolysed into glycerol and fatty acids, which then enter respiration.', wrong = '{"0": "Lipids are non-polar and insoluble in water. Their value as fuel comes from their C-H bonds.", "1": "Fats are made of carbon, hydrogen and oxygen only. They contain no nitrogen.", "2": "Lipids must first be hydrolysed into glycerol and fatty acids before they can enter respiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1139' AND answer = 3;
UPDATE questions SET why = 'Photorespiration takes place in green cells in light. Like aerobic respiration, it uses oxygen and releases CO₂. Unlike aerobic respiration, it produces no ATP, so the carbon lost is simply wasted.', wrong = '{"0": "Photorespiration does use oxygen. Rubisco adds O₂ to RuBP, and O₂ is used again in the peroxisome.", "2": "Photorespiration does release CO₂. That is why it reduces the carbon fixed by the plant.", "3": "Photorespiration occurs in green cells in light, when photosynthesis is going on."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1140' AND answer = 1;
UPDATE questions SET why = 'Rubisco can bind either CO₂ or O₂ at the same active site. When the CO₂ level in the leaf falls and the O₂ level rises, for example when stomata close on a hot day, rubisco adds O₂ to RuBP instead of CO₂. This starts photorespiration.', wrong = '{"0": "Low light is not the condition named. The switch depends on the relative levels of CO₂ and O₂ in the leaf.", "1": "High CO₂ helps rubisco fix carbon and reduces photorespiration.", "3": "Low temperature favours carbon fixation. High temperature increases rubisco''s oxidative activity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1141' AND answer = 2;
UPDATE questions SET why = 'When rubisco adds CO₂ to RuBP, two molecules of phosphoglycerate are formed. When it adds O₂ instead, RuBP breaks into one phosphoglycerate (three carbons) and one phosphoglycolate (two carbons). Phosphoglycolate then starts the photorespiration pathway.', wrong = '{"1": "Two phosphoglycerates are made when rubisco adds CO₂, in normal carbon fixation.", "2": "Oxaloacetate and pyruvate belong to C4 metabolism and respiration, not to the oxygenase reaction of rubisco.", "3": "No glucose is made by adding O₂. Photorespiration actually loses fixed carbon as CO₂."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1142' AND answer = 0;
UPDATE questions SET why = 'Phosphoglycolate is converted to glycolate, which moves from the chloroplast to the peroxisome. There glycolate is converted to glyoxylate using O₂. This reaction also produces toxic hydrogen peroxide (H₂O₂), which the peroxisome breaks down.', wrong = '{"1": "The mitochondrion is where two glycines form serine. No ATP is made anywhere in photorespiration.", "2": "Glycolate leaves the chloroplast before it is oxidised. No NADPH is made by this step.", "3": "This oxidation happens in the peroxisome, not the cytosol, and it produces H₂O₂."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1143' AND answer = 0;
UPDATE questions SET why = 'In photorespiration, glyoxylate is changed to glycine in the peroxisome, and glycine is transported to the mitochondrion. There two molecules of glycine combine to form one serine, and CO₂ is released. Serine then returns to the peroxisome.', wrong = '{"0": "The peroxisome turns glycolate into glyoxylate and glycine, and later serine into glycerate. Serine is formed in the mitochondrion.", "2": "The chloroplast is where glycerate is finally changed back to phosphoglycerate for the Calvin cycle.", "3": "The nucleus plays no part in the photorespiration pathway."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1144' AND answer = 1;
UPDATE questions SET why = 'C3 plants fix carbon only by the Calvin cycle, so rubisco is exposed to oxygen. When photorespiration occurs, they can lose between 25% and 50% of the carbon they have fixed. This lowers their yield, especially in hot climates.', wrong = '{"0": "1 to 2% is the share of solar energy that plants convert into chemical energy, not the carbon lost.", "1": "About 10% is too low. The loss in C3 plants can be a quarter to a half of fixed carbon.", "3": "About 90% is too high. Plants could not survive losing almost all their fixed carbon."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1145' AND answer = 2;
UPDATE questions SET why = 'As temperature rises, rubisco''s oxidative activity increases more than its carbon-fixing activity, and stomata tend to close to save water. So photorespiration rises with heat. In tropical climates, where temperatures are often above 28 °C, it becomes a severe problem for crop yields.', wrong = '{"0": "Cold climates reduce rubisco''s oxidative activity, so photorespiration is less of a problem there.", "1": "Photorespiration needs light. It happens in green cells while they photosynthesise.", "2": "High CO₂ makes rubisco fix carbon rather than add oxygen, so photorespiration falls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1146' AND answer = 3;
UPDATE questions SET why = 'When photosynthesis first evolved, the atmosphere had very little oxygen, so rubisco nearly always met CO₂ and there was little or no photorespiration. Over millions of years free O₂ built up, and CO₂ and O₂ began to compete for rubisco''s active site.', wrong = '{"1": "Rubisco was already present and fixing carbon. The problem arose only later, as oxygen accumulated.", "2": "Temperature is not the reason given. The key factor was the low level of oxygen in the early atmosphere.", "3": "Stomata are not the reason given. Photorespiration was rare because oxygen was scarce."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1147' AND answer = 0;
UPDATE questions SET why = 'Some plants run C4 photosynthesis in addition to the Calvin cycle, to reduce photorespiration in hot climates. Examples are grasses such as corn (maize), sugarcane and sorghum, along with about two dozen other plant groups.', wrong = '{"0": "Wheat, rice and peas are common examples of C3 plants, which fix carbon by the Calvin cycle alone.", "1": "Cacti and pineapple are examples of CAM plants, not C4 plants.", "2": "Mosses and ferns are not given as C4 examples. They fix carbon by the C3 route."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1148' AND answer = 3;
UPDATE questions SET why = 'In C4 plants, CO₂ entering a mesophyll cell is first attached to the three-carbon phosphoenol pyruvic acid (PEP). This forms the four-carbon oxaloacetic acid (3 + 1 = 4). Because the first product has four carbons, the process is called C4 photosynthesis.', wrong = '{"0": "Adding CO₂ to RuBP to give 3-PGA is the C3 route, carried out by rubisco. In C4 plants this happens later, in bundle-sheath cells.", "2": "Malic acid is made from oxaloacetic acid, not formed directly by adding CO₂ to pyruvic acid.", "3": "Glycerate and serine are intermediates of photorespiration, not of C4 fixation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1149' AND answer = 1;
UPDATE questions SET why = 'Malic acid made in mesophyll cells moves to an adjacent bundle-sheath cell. There it breaks down into pyruvic acid and CO₂. Bundle-sheath cells hold CO₂ in, so the CO₂ concentration rises, and rubisco runs the Calvin cycle instead of photorespiration.', wrong = '{"0": "Mesophyll cells are where CO₂ is first fixed. Pyruvic acid returns there to be turned back into PEP.", "1": "Guard cells control the opening of stomata. They are not the site of the Calvin cycle in C4 plants.", "3": "The peroxisome takes part in photorespiration, which C4 plants are trying to avoid."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1150' AND answer = 2;
UPDATE questions SET why = 'In the bundle-sheath cell, malic acid releases CO₂ and becomes pyruvic acid. This pyruvic acid returns to the mesophyll cell, where it is converted back to phosphoenol pyruvic acid (PEP) using energy from ATP. PEP can then fix another CO₂.', wrong = '{"0": "NADPH supplies hydrogen for reduction. Turning pyruvic acid back into PEP needs energy from ATP.", "1": "Oxygen is not used to regenerate PEP. C4 plants actually avoid letting oxygen interfere with carbon fixation.", "2": "Rubisco works in the bundle-sheath cells, fixing CO₂ in the Calvin cycle. It does not make PEP."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1151' AND answer = 3;
UPDATE questions SET why = 'Succulent CAM plants such as cacti and pineapple open their stomata at night, when it is cooler, and close them during the day. Closing them in the hot day prevents water loss. The CO₂ needed by day comes from organic acids made the night before.', wrong = '{"0": "Opening stomata at noon, the hottest time, would cause the most water loss.", "2": "CAM plants do have stomata. They just open them at night instead of in the day.", "3": "Keeping stomata open all the time would waste water, which hot-climate succulents cannot afford."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1152' AND answer = 1;
UPDATE questions SET why = 'CAM stands for Crassulacean acid metabolism. It is named after the plant family Crassulaceae, the stonecrop family of succulents, in which this way of fixing CO₂ was first discovered.', wrong = '{"1": "CAM is not named after a scientist. Its name comes from a plant family.", "2": "CAM does not come from cactus and maize. Maize is in fact a C4 plant, not a CAM plant.", "3": "The name does not refer to the carbon atoms of malic acid. It refers to the family Crassulaceae."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1153' AND answer = 0;
UPDATE questions SET why = 'Both C4 and CAM plants first fix CO₂ into four-carbon acids and later release it to the Calvin cycle. C4 plants separate these steps in space: mesophyll cells fix CO₂ and bundle-sheath cells run the Calvin cycle. CAM plants separate them in time: CO₂ is fixed at night and used by day.', wrong = '{"0": "Both C4 and CAM plants run the Calvin cycle. They just supply it with CO₂ from organic acids.", "1": "Both groups first fix CO₂ to PEP, forming four-carbon acids. PEP is not unique to CAM plants.", "3": "Opening stomata only at night is the CAM pattern, not the C4 pattern."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1154' AND answer = 2;
UPDATE questions SET why = 'Structural biology is the study of the three-dimensional (3D) structures of macromolecules, such as proteins and nucleic acids, at the level of atoms. It shows how a molecule is built, how it works and moves, and how it interacts with ligands and other macromolecules.', wrong = '{"1": "Classifying organisms into groups is taxonomy, not structural biology.", "2": "The anatomy of bones is studied at the level of organs and tissues. Structural biology works at the atomic level of molecules.", "3": "The distribution of species in ecosystems is a topic of ecology."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1155' AND answer = 0;
UPDATE questions SET why = 'Domains are distinct structural units of a protein with their own functions. Structural studies of the HIV-1 enzyme reverse transcriptase revealed a polymerase domain, which synthesises DNA, and an RNase H domain, which breaks down the RNA strand of RNA-DNA hybrids.', wrong = '{"0": "A spike protein that binds human receptors belongs to the coronavirus (SARS-CoV-2), not to HIV reverse transcriptase.", "1": "A protease domain that digests capsid proteins is not one of the two domains described for this enzyme.", "3": "The viral envelope is a separate outer layer. The two domains are parts of the reverse transcriptase enzyme itself."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1156' AND answer = 2;
UPDATE questions SET why = 'Structural biology showed the exact location and shape of the polymerase and RNase H domains of HIV-1 reverse transcriptase. Knowing these shapes, scientists could design antiviral drugs that fit and block these domains specifically, stopping the virus from copying itself.', wrong = '{"0": "The purpose of studying the enzyme is to stop the virus, not to help it grow faster.", "1": "HIV is a virus. Studying its enzyme''s structure does not change its classification.", "2": "Insulin production has nothing to do with the structure of HIV reverse transcriptase."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1157' AND answer = 3;
UPDATE questions SET why = 'Serine proteases are protein-digesting enzymes. Their 3D structure, worked out by structural biology, reveals a well-defined active site, and this site is responsible for breaking down peptide bonds in proteins.', wrong = '{"0": "A domain that synthesises DNA is the polymerase domain of HIV-1 reverse transcriptase.", "2": "The receptor for the coronavirus spike protein is a protein on human cells, not a serine protease example.", "3": "Misfolded proteins causing disease is a separate application, linked to Parkinson''s and Alzheimer''s diseases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1158' AND answer = 1;
UPDATE questions SET why = 'In COVID-19, scientists used structural biology to study the spike protein of SARS-CoV-2, which sticks out from the virus and helps it enter human cells. Knowing its 3D shape, they identified it as a drug target and designed vaccines and medicines that block it.', wrong = '{"0": "Human haemoglobin is an oxygen-carrying protein. It was not the target in COVID-19 research.", "1": "SARS-CoV-2 is a virus and has no cell wall. Bacterial cell walls are targets of antibiotics like penicillin.", "3": "The RNase H domain belongs to HIV-1 reverse transcriptase, not to the coronavirus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1159' AND answer = 2;
UPDATE questions SET why = 'A drug works by attaching to a particular place on a disease-causing molecule and stopping it from working. These places, which are usually proteins, are called drug targets. Studying their 3D shape shows exactly where a drug can bind.', wrong = '{"0": "Ligands are any molecules that bind to a macromolecule. The disease molecule where a drug acts is called the drug target.", "1": "Antigens are substances that trigger an immune response. Not all drug targets are antigens, and that is not the term used.", "2": "Vectors carry genes (in gene cloning) or pathogens (like mosquitoes). They are not the sites where drugs act."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1160' AND answer = 3;
UPDATE questions SET why = 'The coronavirus enters human cells when its spike protein binds a receptor protein on the cell surface. A drug that binds this receptor occupies it, so the spike protein cannot interact with it. The virus is therefore blocked from entering host cells.', wrong = '{"1": "Binding the receptor stops the spike protein from attaching, so it prevents entry rather than helping it.", "2": "The drug acts on a surface receptor protein. It does not attack human DNA.", "3": "Blocking the receptor does nothing to increase spike production. It only blocks the spike from binding."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1161' AND answer = 0;
UPDATE questions SET why = 'Host-pathogen interaction is the study of how a pathogen, such as a virus or bacterium, interacts with the cells of its host. By studying the 3D structures of both pathogen and host proteins, scientists see how the pathogen attaches, enters and which molecules are involved.', wrong = '{"0": "Protein misfolding is about proteins folding into wrong shapes, which causes diseases like Parkinson''s.", "2": "Gene duplication is a copying of a gene within a genome that gives rise to paralogs.", "3": "Speciation is the formation of new species. Genes separated by speciation become orthologs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1162' AND answer = 1;
UPDATE questions SET why = 'A protein can work only when it is folded into its correct 3D shape. Several diseases, including cystic fibrosis, Parkinson''s disease and Alzheimer''s disease, arise from incorrect folding of proteins. Structural biology helps explain how misfolding leads to them.', wrong = '{"0": "Tuberculosis is an infection caused by the bacterium Mycobacterium tuberculosis, not by protein misfolding.", "2": "Malaria is caused by the protist Plasmodium, spread by mosquitoes.", "3": "Scurvy is caused by a deficiency of vitamin C in the diet."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1163' AND answer = 1;
UPDATE questions SET why = 'X-ray crystallography was developed in 1912 by the father and son William Henry Bragg and William Lawrence Bragg. They received the 1915 Nobel Prize in Physics for this work. The method has since been used to study minerals, metals, proteins and nucleic acids.', wrong = '{"0": "Watson and Crick proposed the double helix model of DNA in 1953, using X-ray data but not inventing the method.", "1": "Melvin Calvin worked out the light-independent reactions of photosynthesis.", "3": "Engelmann made the first action spectrum in 1883 using Spirogyra."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1164' AND answer = 2;
UPDATE questions SET why = 'William Henry Bragg and William Lawrence Bragg developed X-ray crystallography in 1912. Three years later, in 1915, they were awarded the Nobel Prize in Physics for this work.', wrong = '{"1": "1912 is the year the technique was developed, and the prize was in Physics, not Chemistry.", "2": "1961 is the year Melvin Calvin received the Nobel Prize in Chemistry for the Calvin cycle.", "3": "1929 is the year Karl Lohmann discovered ATP, not a Nobel Prize for crystallography."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1165' AND answer = 0;
UPDATE questions SET why = 'When an X-ray beam strikes a crystal, its atoms diffract the beam in particular directions. From the angles and intensities of the diffracted beams, a 3D picture of electron density in the crystal is calculated, and this is used to build the 3D structure of the molecule.', wrong = '{"0": "The colour of a crystal gives no information about where its atoms are.", "1": "The weight of the crystal tells nothing about how its atoms are arranged in space.", "2": "Light absorbed by chlorophyll gives an absorption spectrum. It has nothing to do with X-ray crystallography."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1166' AND answer = 3;
UPDATE questions SET why = 'A purified protein is turned into a solid crystal because a crystal arranges its molecules in a regular, repeating pattern. Many identical molecules lined up in the same way diffract X-rays together, which gives a clear image of the structure.', wrong = '{"0": "Crystallisation is done to get a clear X-ray image, not to make the protein enzymatically active.", "2": "Crystallisation is done in the lab on purified protein, not to remove water from cells.", "3": "Crystallising a protein does not change it chemically. It stays a protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1167' AND answer = 1;
UPDATE questions SET why = 'Proteins are crystallised by slowly mixing them with special solutions so that the molecules stick together in an orderly way. This can take hours, days or weeks. It needs careful control of temperature, pH and salt concentration to get a clear, stable crystal.', wrong = '{"0": "Light intensity and CO₂ are factors for photosynthesis, not for growing protein crystals.", "1": "Oxygen and glucose levels matter for respiration, not for protein crystallisation.", "3": "Magnetic fields and voltage are not the conditions controlled when growing protein crystals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1168' AND answer = 2;
UPDATE questions SET why = 'First the purified protein is crystallised. The crystal is then hit by X-rays, which gives a diffraction pattern of spots. The angles and intensities of the spots are used to make an electron density map. Finally computer programs turn this data into the 3D structure.', wrong = '{"1": "A crystal must be grown before X-rays can be diffracted, so crystallisation comes first.", "2": "The density map is calculated from the diffraction pattern, so it cannot come first.", "3": "The diffraction pattern must come before the density map, because the map is made from it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1169' AND answer = 0;
UPDATE questions SET why = 'When the X-ray beam hits the crystal at various angles, the atoms diffract it in specific directions. These diffracted beams fall on the detector as a diffraction pattern, which is a series of spots. The angles and intensities of the spots hold the information about the arrangement of atoms.', wrong = '{"0": "A continuous rainbow spectrum is produced when white light is split by a prism, not by X-ray diffraction.", "1": "Coloured bands of DNA are seen in gel electrophoresis, not in X-ray crystallography.", "2": "The pattern is made of many separate spots, not a single straight line."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1170' AND answer = 3;
UPDATE questions SET why = 'Computational biology is an interdisciplinary field that uses computer techniques to solve biological problems. It combines knowledge from biology, computer science, mathematics and statistics to handle large data sets, find patterns and build predictive models.', wrong = '{"0": "Chemistry alone is not the combination. Computational biology relies on computer science, mathematics and statistics.", "1": "Physics alone is not the combination described. The field joins biology with computing, maths and statistics.", "2": "Geology and astronomy are not part of computational biology."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1171' AND answer = 3;
UPDATE questions SET why = 'A genome is the complete set of DNA in a single cell of an organism. Genomics is the study of genomes: sequencing them, assembling the sequences and analysing their structure and function. It helps explain genetic variation, gene function and evolution.', wrong = '{"0": "Proteomics is the large-scale study of proteins, the proteome, not of DNA.", "1": "Bioinformatics is the use of computers to store and analyse biological data. It is a tool, not the study of the genome itself.", "3": "Crystallography is a method for finding the 3D structure of molecules using X-rays."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1172' AND answer = 2;
UPDATE questions SET why = 'The proteome is the entire set of proteins produced by an organism. Proteomics, the large-scale study of proteins, aims to map the proteome and understand the interactions and roles of these proteins in cell processes.', wrong = '{"0": "The genome is the complete set of DNA in a cell, not the set of proteins.", "2": "Phenotype is the set of observable traits of an organism, produced by its genes and environment.", "3": "A karyotype is the number and appearance of the chromosomes of a cell."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1173' AND answer = 1;
UPDATE questions SET why = 'Bioinformatics is the application of computer technology to manage and analyse biological data. Its tools are used to store, retrieve and analyse DNA, RNA and protein sequences, for example through databases like GenBank and programs like BLAST.', wrong = '{"1": "Growing protein crystals is the first step of X-ray crystallography, done in the lab.", "2": "The large-scale study of proteins and their roles is proteomics, which maps the proteome.", "3": "The study of fossils is palaeontology, not bioinformatics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1174' AND answer = 0;
UPDATE questions SET why = 'By analysing DNA sequences, computational biology identifies genetic variations linked with diseases. This explains the genetic basis of a disease in each person and can lead to personalised medicine, where treatment is matched to a patient''s genes.', wrong = '{"1": "Growing crystals is part of X-ray crystallography, not of personalised medicine.", "2": "Measuring blood pressure is a routine clinical test. It is not a computational biology application.", "3": "Counting bacteria in samples is a laboratory microbiology task, not the role described."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1175' AND answer = 0;
UPDATE questions SET why = 'GenBank is a comprehensive public database of nucleotide sequences, along with bibliographic and biological notes about them. It gives access to DNA sequences from many organisms, supporting genetic research and comparative genomics.', wrong = '{"0": "3D structures of proteins and nucleic acids are stored in the Protein Data Bank (PDB).", "1": "Ensembl is the genome browser. GenBank stores the nucleotide sequences themselves.", "2": "GenBank holds DNA sequence data, not fossil records."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1176' AND answer = 3;
UPDATE questions SET why = 'The Protein Data Bank (PDB) provides 3D structural data of large biological molecules such as proteins and nucleic acids. Scientists use it to study structures, understand functions and design drugs that fit specific protein shapes.', wrong = '{"0": "A public database of nucleotide sequences with annotations is GenBank.", "2": "Sequence alignment is done by tools such as BLAST and FASTA, not by PDB.", "3": "PDB holds molecular structures, not clinical records of patients."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1177' AND answer = 1;
UPDATE questions SET why = 'Ensembl is a genome browser. It provides information on genome sequences, gene models and comparative genomics for various species. It helps scientists access and view genomic data for studies in genomics and evolutionary biology.', wrong = '{"0": "3D protein structures are stored in the Protein Data Bank (PDB).", "1": "BLAST and FASTA are the sequence alignment tools. Ensembl is a browser of genome data.", "3": "Ensembl is an online database and browser, not a machine for X-ray work."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1178' AND answer = 2;
UPDATE questions SET why = 'BLAST (Basic Local Alignment Search Tool) compares primary sequences of DNA or proteins. FASTA compares a query sequence with a database to find regions of similarity. Both are used to find homologous sequences and predict the function of unknown genes.', wrong = '{"0": "3D structures are stored in databases such as the Protein Data Bank. BLAST and FASTA are search tools.", "2": "Crystals are grown in the laboratory for X-ray work. BLAST and FASTA are computer programs.", "3": "Ensembl is the genome browser. BLAST and FASTA are alignment tools."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1179' AND answer = 1;
UPDATE questions SET why = 'Sequence homology is similarity between DNA, RNA or protein sequences that exists because they evolved from a common ancestral sequence. Homologous sequences are of two kinds: orthologs, separated by speciation, and paralogs, formed by gene duplication.', wrong = '{"1": "Similarity by chance alone is not homology. Homology means the sequences share an ancestor.", "2": "Living in identical environments does not make sequences homologous. Shared ancestry does.", "3": "Crystal shapes have nothing to do with sequence homology."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1180' AND answer = 0;
UPDATE questions SET why = 'Orthologs are homologous genes found in different species that came from one ancestral gene when the species split apart (speciation). Orthologs often keep the same function in each species, such as human and chimpanzee histone H1.1.', wrong = '{"0": "Paralogs arise by gene duplication within the same species, not by speciation.", "1": "Analogs are similar in function but not due to shared ancestry, so they are not homologous genes.", "3": "Alleles are alternative forms of the same gene in one species, not genes in different species."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1181' AND answer = 2;
UPDATE questions SET why = 'Paralogs are homologous sequences within the same species that came from duplication of one ancestral gene. Human histone H1.1 and H1.2 arose by such a duplication in the human lineage, so they are paralogs. Paralogs can evolve new functions.', wrong = '{"0": "Orthologs are in different species, separated by speciation. H1.1 and H1.2 are both human genes.", "1": "Analogs are similar without shared ancestry. These two genes share an ancestral gene, so they are homologous.", "2": "They are related: both came from one ancestral histone gene by duplication."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1182' AND answer = 3;
UPDATE questions SET why = 'Human histone H1.1 and chimpanzee histone H1.1 are the same gene found in two different species. They come from one ancestral gene that was separated when the human and chimpanzee lineages split (speciation). So they are orthologs.', wrong = '{"1": "Paralogs are found in the same species after gene duplication. These genes are in two species.", "2": "Gene duplication within humans gave H1.1 and H1.2. Human and chimpanzee H1.1 are in different species.", "3": "They are closely related, since both come from the same ancestral gene."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1183' AND answer = 0;
UPDATE questions SET why = 'Homologous sequences come from a common ancestor and often keep similar roles. So if an unknown gene or protein is homologous to one whose function is known, it is likely to have a similar function. Tools like BLAST are used to find such matches.', wrong = '{"0": "Homologous proteins can be in different species (orthologs) or the same species (paralogs).", "1": "Homology gives a clue to the function. It does not suggest that the protein has none.", "3": "Homology says nothing about misfolding. It points to a likely function."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1184' AND answer = 2;
UPDATE questions SET why = 'Structural homology is similarity in 3D structure due to shared ancestry. Because a protein''s shape largely decides its function, proteins with similar structures often do similar jobs, even when their amino acid sequences are not very similar. This helps predict the function of new proteins.', wrong = '{"0": "Structurally homologous proteins can have quite different sequences. Shape is kept better than sequence.", "1": "Structural homology is found in proteins of all organisms, not only bacteria.", "2": "Structural homology is very useful in drug design, since similar shapes can be targeted by similar drugs."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1185' AND answer = 3;
UPDATE questions SET why = 'Macronutrients are needed by plants in relatively large amounts. There are nine of them: carbon, hydrogen, oxygen, nitrogen, potassium, calcium, phosphorus, magnesium and sulphur. Carbon, hydrogen and oxygen come from CO₂ and water.', wrong = '{"0": "Seven is the number of micronutrients: iron, manganese, zinc, molybdenum, copper, chlorine and boron.", "1": "Sixteen is the total of both groups, nine macronutrients plus seven micronutrients.", "2": "Five is too few. The macronutrient list has nine elements."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1186' AND answer = 3;
UPDATE questions SET why = 'Micronutrients are needed only in very small amounts. The seven micronutrients are iron, manganese, zinc, molybdenum, copper, chlorine and boron. Molybdenum is one of them, and it is critical for nitrogen fixation.', wrong = '{"0": "Magnesium is a macronutrient. It forms the core of the chlorophyll molecule.", "2": "Sulphur is a macronutrient, important in nitrogen metabolism.", "3": "Calcium is a macronutrient that stabilises and builds the cell wall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1187' AND answer = 1;
UPDATE questions SET why = 'Nitrogen is needed for plant growth because it is part of proteins and plays a key role in energy metabolism. When nitrogen is short, the plant cannot make enough protein, so it loses leaves and its growth is stunted.', wrong = '{"1": "Chlorine deficiency is described only in general terms, as harming health and growth. Leaf loss with stunting points to nitrogen.", "2": "Phosphorus deficiency shows as delayed flowering and browning and wrinkling of leaves.", "3": "Potassium deficiency shows as dark patches on the leaves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1188' AND answer = 0;
UPDATE questions SET why = 'Phosphorus is a part of ATP, the energy carrier of the cell, and it is needed for growth of roots and for flowering. So when phosphorus is short, flowering is delayed, and the leaves turn brown and become wrinkled.', wrong = '{"0": "Calcium shortage causes yellow and brown patches on the leaves.", "1": "Sulphur shortage makes the whole plant lighter in colour.", "3": "Nitrogen shortage causes leaf loss and stunted growth."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1189' AND answer = 2;
UPDATE questions SET why = 'Potassium is involved in water regulation and in transporting the plant''s reserve substances. It also improves photosynthesis, strengthens tissues and stimulates the uptake of nitrates. A shortage of potassium causes dark patches on the leaves.', wrong = '{"1": "Calcium stabilises and builds the cell wall and helps seed development.", "2": "Magnesium forms the core of chlorophyll and helps absorb and transport phosphorus.", "3": "Sulphur is a key element in nitrogen metabolism, but it is not described as regulating water or nitrate uptake."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1190' AND answer = 0;
UPDATE questions SET why = 'Calcium provides stability to the cell wall and promotes its development. It also helps in cell division and maturation, and aids the development of seeds. A shortage of calcium causes yellow and brown patches on the leaves.', wrong = '{"0": "Potassium regulates water, moves reserve substances and stimulates nitrate uptake.", "1": "Copper is needed for lignin synthesis, which strengthens cell walls, but it is not the nutrient that stabilises the wall and aids seed growth.", "2": "Iron is needed for chlorophyll synthesis and acts as an enzyme cofactor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1191' AND answer = 3;
UPDATE questions SET why = 'Magnesium forms the core of the chlorophyll molecule, so it is essential for photosynthesis. When magnesium is short, the oldest leaves lose their green colour, stalks become weak, and yellow and brown spots appear.', wrong = '{"0": "Sulphur deficiency makes the whole plant lighter in colour, not specifically the oldest leaves with weak stalks.", "1": "Zinc deficiency is described as causing stunted growth.", "3": "Boron is a micronutrient, but these symptoms are not described for it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1192' AND answer = 2;
UPDATE questions SET why = 'Iron is essential for the synthesis of chlorophyll, and it acts as a cofactor for enzymes of energy transfer and nitrogen metabolism. Its deficiency causes interveinal chlorosis: the leaf tissue between the veins turns yellow while the veins stay green.', wrong = '{"0": "Manganese deficiency causes premature leaf fall and delayed maturity.", "2": "Chlorine deficiency is described only as harming the health and growth of plants.", "3": "Calcium deficiency causes yellow and brown patches on the leaves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1193' AND answer = 1;
UPDATE questions SET why = 'Copper is necessary for the synthesis of lignin, which gives strength and rigidity to cell walls. Copper also takes part in nitrogen metabolism and reproductive development and acts as an enzyme cofactor. Its deficiency causes chlorosis, twisted leaves and stunted growth.', wrong = '{"1": "Zinc helps chlorophyll synthesis, root development and nutrient uptake, not lignin synthesis.", "2": "Molybdenum is critical for nitrogen fixation and nitrogen reduction.", "3": "Iron is needed for chlorophyll synthesis and as an enzyme cofactor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1194' AND answer = 0;
UPDATE questions SET why = 'Molybdenum is a micronutrient that is critical for nitrogen fixation and nitrogen reduction. It also takes part in sulphur and phosphorus metabolism and iron use. Its deficiency causes chlorosis of older leaves and stunted growth.', wrong = '{"0": "Chlorine is involved in stomatal regulation, osmotic adjustment and nutrient transport.", "1": "Copper is needed for lignin synthesis and acts as an enzyme cofactor.", "3": "Manganese works in photosynthesis, nitrogen and carbohydrate metabolism and enzyme activation, but it is not the one named critical for nitrogen fixation."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1195' AND answer = 2;
UPDATE questions SET why = 'Manganese is involved in photosynthesis, nitrogen and carbohydrate metabolism, and the activation of enzymes. When it is deficient, leaves fall early (premature leaf fall) and the plant takes longer to mature.', wrong = '{"0": "Copper deficiency causes chlorosis, twisted leaves and stunted growth.", "2": "Magnesium deficiency causes weak stalks, loss of green colour in the oldest leaves, and yellow-brown spots.", "3": "Nitrogen deficiency causes leaf loss and stunted growth, not delayed maturity."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1196' AND answer = 1;
UPDATE questions SET why = 'Insectivorous plants are true autotrophs: they make their own food by photosynthesis. They often grow in soils poor in nitrogen. By trapping and digesting insects, they gain nitrogenous compounds from the animal bodies, which speeds up their growth.', wrong = '{"0": "These plants take CO₂ from the air through their stomata like other plants.", "1": "They make their own glucose by photosynthesis, so they do not need insects for energy.", "2": "They make their own chlorophyll. Insects do not supply it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1197' AND answer = 3;
UPDATE questions SET why = 'In the pitcher plant, the leaf is modified into a sac partly filled with water, with a hood that partly covers the opening. The inside of the pitcher has many stiff hairs. Once a small insect falls in, these hairs stop it from crawling out.', wrong = '{"1": "Sticky drops of dew on leaf hairs are the trap of the sundew.", "2": "Two hinged lobes that snap shut form the trap of the Venus flytrap.", "3": "Sticky tentacle-like hairs are found on the sundew, not the pitcher plant."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1198' AND answer = 0;
UPDATE questions SET why = 'Each leaf of the Venus flytrap ends in a trap of two hinged lobes. Their inner surfaces carry trichomes, hair-like projections that make the lobes close rapidly when prey touches them. Bristles on the edges then interlock so the prey cannot escape.', wrong = '{"0": "A hood over the opening belongs to the pitcher plant, not the Venus flytrap.", "1": "Dew-covered, tentacle-like hairs form the trap of the sundew, not the flytrap.", "3": "The trap is a modified leaf above ground. Roots do not touch the prey."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1199' AND answer = 2;
UPDATE questions SET why = 'The sundew''s leaves are covered with tiny tentacle-like hairs. Each hair has a gland with a shiny drop of sticky dew at its tip, which gives the plant its name. Insects attracted by its odour are trapped by the tentacles and digested by enzymes.', wrong = '{"0": "The pitcher plant traps insects in a water-filled sac with stiff hairs inside, not with dew drops.", "2": "The Venus flytrap uses two hinged lobes that snap shut, not sticky drops.", "3": "Cacti are not insectivorous. They are succulent CAM plants of dry places."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1200' AND answer = 1;
UPDATE questions SET why = 'Each stoma is surrounded by a pair of guard cells. These cells are bean-shaped and contain chloroplasts. By taking up or losing water they change shape and open or close the stomatal pore, controlling gas exchange and transpiration.', wrong = '{"0": "Guard cells are living cells. Dead, lignified cells are found in sclerenchyma and xylem.", "1": "Guard cells contain chloroplasts, unlike most other epidermal cells.", "2": "Guard cells are bean-shaped, not star-shaped, and they are green because of chloroplasts."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1201' AND answer = 3;
UPDATE questions SET why = 'The starch-sugar hypothesis was proposed in 1856 by the German botanist H. von Mohl. It says that guard cells make sugar in daylight, which lowers their water potential. Water enters, the guard cells become turgid and the stoma opens. At night sugar becomes starch and the stoma closes.', wrong = '{"0": "Ernst Münch proposed the pressure flow hypothesis of phloem transport, not the starch-sugar hypothesis.", "1": "Garner and Allard studied photoperiodism, the response of flowering to day length.", "3": "Engelmann made the first action spectrum in 1883 using Spirogyra."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1202' AND answer = 2;
UPDATE questions SET why = 'The starch-sugar hypothesis links stomatal opening to slow changes: sugar made by photosynthesis in the day and turned to starch at night. But guard cells change their turgor very quickly. The hypothesis does not fully explain these rapid turgor changes, which the K⁺ influx idea explains better.', wrong = '{"1": "The hypothesis explains closure at night, when there is no light. It does not require light to close stomata.", "2": "Movement of potassium ions belongs to the other hypothesis, K⁺ influx.", "3": "It does give a mechanism for opening, through sugar lowering water potential. Its weakness is speed."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1203' AND answer = 0;
UPDATE questions SET why = 'Guard cells actively pump K⁺ ions in. This lowers their osmotic (solute) potential, so water enters them by osmosis. The guard cells become turgid and bow apart, opening the stoma. At night K⁺ diffuses out, water follows, and the stoma closes.', wrong = '{"0": "K⁺ diffusing out of guard cells makes them lose water and become flaccid, which closes the stoma.", "2": "Starch building up removes free sugar, which raises water potential and favours closing.", "3": "Guard cells that lose water become flaccid, and the stoma closes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1204' AND answer = 1;
UPDATE questions SET why = 'Blue light speeds up stomatal opening. It acidifies the surroundings of the guard cells, which promotes the uptake of K⁺ into them. Water then follows by osmosis, the guard cells swell, and the stoma opens.', wrong = '{"0": "Green light is not named as promoting K⁺ uptake. It is the colour least absorbed by plants.", "1": "Far-red light acts on phytochrome in photoperiodism, not on K⁺ uptake by guard cells.", "2": "Infrared light is not named as affecting K⁺ uptake."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1205' AND answer = 3;
UPDATE questions SET why = 'At high temperature, when leaf cells start wilting, mesophyll cells release the hormone abscisic acid. It stops the active transport of K⁺ into guard cells, overriding the effects of light and CO₂. Without K⁺, guard cells lose water and the stomata close, saving water.', wrong = '{"0": "More sugar in guard cells would lower their water potential and favour opening, not closing.", "2": "Pumping K⁺ into guard cells is what opens stomata. The hormone stops this pumping.", "3": "Softening of guard cell walls is not the mechanism described. The hormone acts on K⁺ transport."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1206' AND answer = 1;
UPDATE questions SET why = 'The palisade mesophyll lies just beneath the upper epidermis of the leaf. Its cells are elongated, tightly packed and rich in chloroplasts. This arrangement catches as much light as possible, so most photosynthesis happens here.', wrong = '{"0": "Loosely packed cells with large air spaces form the spongy mesophyll, below the palisade layer.", "1": "Palisade cells lie under the upper epidermis, where light falls, not in the lower epidermis.", "3": "Palisade cells are living, photosynthetic cells. Dead lignified cells are sclerenchyma."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1207' AND answer = 2;
UPDATE questions SET why = 'Carbon dioxide diffuses into the leaf through the stomata, mostly on the lower surface. It then moves through the air spaces of the spongy mesophyll and into the palisade cells, where it is used in photosynthesis. Oxygen leaves by the reverse route.', wrong = '{"1": "Xylem vessels carry water and minerals from the roots, not CO₂ from the stomata.", "2": "Phloem sieve tubes carry sugars and other food, not CO₂.", "3": "The waxy cuticle reduces gas exchange. CO₂ enters through stomata, not through the cuticle."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1208' AND answer = 0;
UPDATE questions SET why = 'The membrane around the plant cell vacuole is the tonoplast. It has many active transport systems that pump ions into the vacuole, even against a concentration gradient. The high ion concentration then draws water into the vacuole, making the cell turgid.', wrong = '{"0": "The plasmalemma is the cell (plasma) membrane around the whole cytoplasm, not the vacuole membrane.", "1": "The middle lamella is the layer of pectin that cements the walls of neighbouring cells together.", "2": "The Casparian strip is a band in the walls of root endodermis cells that blocks the apoplast pathway."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1209' AND answer = 3;
UPDATE questions SET why = 'Herbaceous plants have little wood. Their parenchyma cells in the epidermis, cortex and pith absorb water, which builds an internal hydrostatic pressure called turgor pressure. Turgor keeps the cells rigid and so supports the soft tissues.', wrong = '{"0": "Thick lignified secondary walls belong to sclerenchyma, the support tissue of harder plant parts, not the main support of soft tissues.", "2": "Cork cells form the protective outer bark of woody stems and roots. They do not support herbaceous plants.", "3": "Annual rings are layers of secondary xylem in woody trees. Herbaceous plants do not form them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1210' AND answer = 1;
UPDATE questions SET why = 'Collenchyma cells are living and lack secondary walls. Their primary walls are thickened at the corners by extra cellulose, which gives support while still letting the cells stretch as young organs grow. Sclerenchyma cells, by contrast, have thick lignified secondary walls and are mostly dead.', wrong = '{"1": "Thick secondary walls soaked in lignin are the feature of sclerenchyma, not collenchyma.", "2": "Most sclerenchyma cells are non-living at maturity. Collenchyma cells stay alive.", "3": "Seed coats and nut shells contain sclereids, a type of sclerenchyma, not collenchyma."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1211' AND answer = 0;
UPDATE questions SET why = 'Collenchyma occurs as strands or cylinders beneath the epidermis of young stems and leaf stalks, and along the veins of leaves. Its cells can elongate as these organs grow, so it supports young parts that have not yet formed secondary tissues.', wrong = '{"0": "Seed coats and nut shells contain sclereids, a type of sclerenchyma.", "1": "Collenchyma is mainly found in young stems, leaf stalks and leaf veins, not only in roots.", "3": "The bark of old trees is made of cork and secondary phloem. Collenchyma supports young parts without secondary growth."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1212' AND answer = 2;
UPDATE questions SET why = 'Sclerenchyma cells have thick secondary walls saturated with lignin. Lignin is an organic compound that gives the walls strength and rigidity. Most sclerenchyma cells are dead at maturity and serve only for support.', wrong = '{"0": "Pectin cements cells together in the middle lamella. It does not make sclerenchyma walls rigid.", "1": "Suberin is the waterproof substance of cork and the Casparian strip. Sclerenchyma secondary walls are strengthened by lignin.", "2": "Chitin is found in fungal cell walls and the exoskeleton of arthropods, not in plants."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1213' AND answer = 3;
UPDATE questions SET why = 'Sclereids are a type of sclerenchyma cell, smaller than fibres, with thick lignified walls. They are found in seed coats and the hard shells of nuts, where they give protection. The gritty texture of pear flesh is also due to sclereids.', wrong = '{"0": "Root tips contain the apical meristem, covered by the root cap. They have dividing cells, not sclereids.", "2": "Leaf stalks of young stems are supported by collenchyma, which can stretch as they grow.", "3": "Sieve plates are the perforated end walls of phloem sieve tube elements."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1214' AND answer = 1;
UPDATE questions SET why = 'Water potential (Ψ) measures the tendency of water to move. Pure water at atmospheric pressure has the highest possible water potential, which is defined as zero. Any solute lowers it, so all solutions have negative water potentials.', wrong = '{"0": "Negative values belong to solutions, where dissolved solutes lower the water potential below that of pure water.", "1": "At atmospheric pressure pure water is set at zero, not a positive value.", "2": "Pure water has the maximum water potential, not the minimum."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1215' AND answer = 3;
UPDATE questions SET why = 'Water always moves from a region of higher water potential to a region of lower water potential. Osmosis is this movement across a partially permeable membrane. For example, water moves from dilute soil water into a root hair cell, whose water potential is lower.', wrong = '{"0": "This is the reverse. Water moves down the water potential gradient, from higher to lower.", "1": "Water can move into or out of a cell. The direction depends on which side has the higher water potential.", "3": "Osmosis happens whenever there is a water potential difference. Pressure potential need not be zero."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1216' AND answer = 2;
UPDATE questions SET why = 'In a plant cell, water potential depends on two factors: solute potential (Ψs) due to dissolved solutes, and pressure potential (Ψp) due to pressure on the water. Total water potential is their sum: Ψw = Ψs + Ψp.', wrong = '{"1": "The two parts are added, not subtracted. Pressure raises water potential, so Ψp has a plus sign.", "2": "Water potential is a sum of the two parts, not their product.", "3": "Subtracting Ψs is wrong. Ψs is already negative, and it is simply added to Ψp."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1217' AND answer = 0;
UPDATE questions SET why = 'Solute potential (osmotic potential) is the change in water potential caused by dissolved solutes. Solutes always lower water potential, so Ψs is always negative. The more solute molecules present, the lower (more negative) Ψs becomes.', wrong = '{"1": "Solute potential is never positive. Solutes can only lower the water potential.", "2": "Solute potential is zero only for pure water. Living cells contain solutes, so their Ψs is negative.", "3": "Adding solute makes solute potential more negative, so it decreases, not increases."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1218' AND answer = 0;
UPDATE questions SET why = 'As water enters a plant cell by osmosis, the protoplast swells and presses against the cell wall. The wall pushes back, building up pressure inside the cell. This makes the cell turgid and increases its pressure potential (Ψp).', wrong = '{"0": "Solute potential always stays negative. Water entering only dilutes it slightly.", "1": "As water enters and pressure builds, water potential rises towards zero, not more negative.", "2": "The cell wall is strong and resists the pressure. That resistance is what creates turgor."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1219' AND answer = 3;
UPDATE questions SET why = 'Root hairs are tiny extensions of the epidermal cells of the root. They greatly increase the surface area in contact with soil water. Most of the uptake of water and minerals by roots takes place through these root hairs.', wrong = '{"0": "The root cap protects the growing tip of the root as it pushes through soil. It does not absorb most water.", "1": "The endodermis is an inner layer that controls entry into the xylem. Water is first absorbed at the surface by root hairs.", "3": "Lateral roots extend the root system, but most absorption happens through the root hairs on them."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1220' AND answer = 2;
UPDATE questions SET why = 'In the apoplast pathway, water moves through the continuous system of adjacent cell walls and the spaces between them, without entering the cytoplasm. This route is broken at the endodermis by Casparian strips.', wrong = '{"0": "Movement through protoplasts connected by plasmodesmata is the symplast pathway.", "2": "Movement from vacuole to vacuole, crossing membranes, is the vacuolar pathway.", "3": "Sieve tubes are part of the phloem and carry sugars, not water across the root."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1221' AND answer = 1;
UPDATE questions SET why = 'The walls of endodermal cells carry Casparian strips (segments), bands that water cannot pass through. Water moving in the cell walls is stopped here, so the apoplast pathway becomes discontinuous. Water and minerals must then pass through the cytoplasm of endodermal cells.', wrong = '{"0": "Plasmodesmata connect the protoplasts of cells and form the symplast route. They do not block the apoplast.", "2": "Root hairs are on the outer surface of the root, where water is first absorbed.", "3": "The tonoplast surrounds the vacuole. It is part of the vacuolar pathway, not a barrier in cell walls."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1222' AND answer = 1;
UPDATE questions SET why = 'In the symplast pathway, water and minerals move through the living protoplasts of root cells. Neighbouring protoplasts are connected by plasmodesmata, strands of cytoplasm that pass through pores in the cell walls. This route is important for minerals at the endodermis.', wrong = '{"0": "Movement through cell walls only is the apoplast pathway.", "1": "Casparian strips block the apoplast pathway at the endodermis. They are not channels between cells.", "2": "Bordered pits link xylem tracheids for lateral water flow. They are not the symplast connections."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1223' AND answer = 3;
UPDATE questions SET why = 'In the vacuolar pathway, water moves from vacuole to vacuole, crossing cell membranes, cytoplasm and tonoplasts each time. With so many membranes to cross, this route is very slow, and its contribution to water movement is negligible.', wrong = '{"1": "The vacuolar pathway is not the main route. Its contribution is negligible.", "2": "At the endodermis the symplast pathway is the important one, not the vacuolar.", "3": "The vacuolar pathway carries water as well as minerals, though only a negligible amount."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1224' AND answer = 0;
UPDATE questions SET why = 'Tracheids are long, thin xylem cells with thick lignified walls and tapered ends. They are linked to one another by bordered pits, thin areas in their walls that let water move sideways from one tracheid to the next.', wrong = '{"0": "Sieve plates are perforated end walls of phloem sieve tube elements.", "1": "Plasmodesmata link the cytoplasm of living cells. Mature tracheids are dead and connected by pits.", "3": "Perforation plates, open end walls, are a feature of xylem vessels, not tracheids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1225' AND answer = 2;
UPDATE questions SET why = 'Vessel elements are shorter and broader than tracheids. They are joined end to end, with perforation plates at their ends, forming long continuous channels. This lets water flow through them more efficiently than through tracheids.', wrong = '{"0": "Longer and narrower cells with tapered ends describe tracheids, not vessels.", "2": "Mature vessels are dead, empty tubes. Only xylem parenchyma is living.", "3": "Vessel walls are thickened with lignin, which stops them collapsing under tension."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1226' AND answer = 1;
UPDATE questions SET why = 'Xylem has four components: tracheids, vessels, xylem fibres and xylem parenchyma. Only xylem parenchyma is living. Its thin-walled cells store water and nutrients, move them sideways, and help heal and regenerate xylem.', wrong = '{"1": "Xylem fibres have thick lignified walls and are dead at maturity. They give support.", "2": "Tracheids are dead at maturity. Their empty, lignified tubes conduct water.", "3": "Vessels are dead at maturity, forming hollow pipes for water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1227' AND answer = 0;
UPDATE questions SET why = 'TACT stands for transpiration, adhesion, cohesion and tension. Transpiration, the evaporation of water through stomata, creates negative pressure in the leaf. This pull draws water up from the roots, so transpiration is the primary driving force; the other three keep the column intact and transmit the pull.', wrong = '{"0": "Root pressure is not part of the TACT mechanism. TACT describes water being pulled from above.", "1": "Adhesion helps keep the water column from breaking, but it does not drive the flow.", "2": "Water moves passively in xylem. Xylem vessels are dead and do no active transport."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1228' AND answer = 3;
UPDATE questions SET why = 'Cohesion is the attraction between water molecules themselves, caused by hydrogen bonding. It holds the water molecules together as an unbroken column from roots to leaves, so the pull of transpiration at the top is passed down the whole column.', wrong = '{"0": "Attraction between water and xylem walls is adhesion, not cohesion.", "1": "The pull created by transpiration is tension, the negative pressure in the xylem.", "3": "Evaporation of water from leaves through stomata is transpiration."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1229' AND answer = 2;
UPDATE questions SET why = 'Adhesion is the attraction between water molecules and the walls of xylem vessels. It makes water stick to the walls as it moves up. This helps prevent breaks in the water column, which is especially important in tall plants.', wrong = '{"0": "Cohesion is the attraction of water molecules to each other, by hydrogen bonds.", "1": "Tension is the negative pressure, or pull, set up by transpiration at the leaves.", "2": "Osmosis is the movement of water across a partially permeable membrane down a water potential gradient."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1230' AND answer = 3;
UPDATE questions SET why = 'Phloem lies on the outer side of the xylem in vascular tissue. In plants with secondary growth, the secondary phloem lies just outside the vascular cambium and forms the inner bark, while the wood inside is secondary xylem.', wrong = '{"0": "Wood is made of secondary xylem, which lies inside the vascular cambium.", "2": "The pith is the central soft tissue of the stem, inside the vascular tissue.", "3": "Annual rings are seen in secondary xylem (wood), not in phloem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1231' AND answer = 1;
UPDATE questions SET why = 'Mature sieve tube elements lack a nucleus and most organelles, so they depend on companion cells. Each sieve tube element is linked to its companion cells by plasmodesmata, through which the companion cells supply it with ATP and proteins.', wrong = '{"0": "Lignin strengthens xylem and sclerenchyma walls. Companion cells do not supply it.", "1": "Companion cells supply ATP and proteins, not just water.", "3": "Chlorophyll is not supplied to sieve tubes. They transport sugars made in the leaves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1232' AND answer = 2;
UPDATE questions SET why = 'Phloem parenchyma consists of living cells that store substances such as sugars, resins, latex and mucilage. These stored materials help in plant defence and in keeping tissues moist.', wrong = '{"1": "Storing water and nutrients is a role of xylem parenchyma. Phloem parenchyma stores a wider range of substances.", "2": "Lignin is not a stored substance. It is deposited in walls of xylem and sclerenchyma for strength.", "3": "Phloem parenchyma stores several substances, not only starch, and is not limited to roots."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1233' AND answer = 0;
UPDATE questions SET why = 'Sugar moves through phloem at an average of about 1 metre per hour. Diffusion over the same distance would take about eight years for 1 metre. Diffusion is far too slow to explain the speed of phloem transport, so a mass flow mechanism is needed.', wrong = '{"0": "Sieve tube elements are living cells, kept alive by companion cells. Dead conducting cells are found in xylem.", "2": "Sugar dissolves readily in water. Sucrose is carried in solution in the phloem sap.", "3": "Diffusion is far slower than phloem flow, not faster. That is exactly why it cannot explain it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1234' AND answer = 1;
UPDATE questions SET why = 'The pressure-flow theory, also called the mass-flow hypothesis, was proposed by Ernst Münch in 1930. It is the most widely accepted explanation of how sugars move through phloem from a source, where they are made, to a sink, where they are used or stored.', wrong = '{"0": "H. von Mohl proposed the starch-sugar hypothesis of stomatal opening in 1856.", "1": "Garner and Allard studied photoperiodism, the effect of day length on flowering.", "2": "The Braggs developed X-ray crystallography in 1912."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1235' AND answer = 3;
UPDATE questions SET why = 'Glucose made in mesophyll cells is partly used in respiration. The excess is converted into sucrose, a non-reducing sugar. Sucrose is loaded into the phloem and carried in solution from source to sink. Being non-reducing, it is less reactive on the journey.', wrong = '{"0": "Glucose is first converted to sucrose before it is loaded into the phloem.", "1": "Starch is insoluble, so it cannot flow in the phloem sap. It is a storage form, not a transport form.", "3": "Fructose is part of sucrose, but it is not the form in which sugar is loaded and carried."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1236' AND answer = 2;
UPDATE questions SET why = 'At the source, sucrose is loaded into the sieve tubes, so their solute concentration rises and their water potential falls. Water then moves in by osmosis from the nearby xylem. This builds up a high pressure at the source end, which pushes the sap towards the sink.', wrong = '{"1": "Xylem does not pump water actively. Water moves into phloem passively by osmosis.", "2": "Sugar is unloaded at the sink, not at the source. At the source it is loaded.", "3": "Transpiration pulls water up the xylem. Water enters the phloem by osmosis because of sucrose loading."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1237' AND answer = 0;
UPDATE questions SET why = 'Sucrose made in mesophyll cells is actively transported into the companion cells of the phloem, using energy. From the companion cells it diffuses into the sieve tubes through plasmodesmata. This raises the sucrose concentration in the sieve tubes.', wrong = '{"0": "Simple diffusion carries sucrose from companion cells into sieve tubes, but the step from mesophyll needs active transport.", "1": "Osmosis moves water, not sucrose. Water follows sucrose into the sieve tubes by osmosis.", "2": "Transpiration pull moves water up the xylem. It does not load sucrose into phloem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1238' AND answer = 3;
UPDATE questions SET why = 'Intercalary meristems are separated from the apex by permanent tissue. They lie at the bases of internodes in many plants, such as grasses, and help in producing leaves and flowers. They are temporary meristems.', wrong = '{"0": "Meristems at root and shoot tips are apical meristems, which cause growth in length.", "1": "The meristem between xylem and phloem is the vascular cambium, a lateral meristem.", "3": "The meristem in the outer layer that forms bark is the cork cambium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1239' AND answer = 2;
UPDATE questions SET why = 'Lateral meristems are cylinders of dividing cells along the sides of stems and roots. The vascular cambium and cork cambium are lateral meristems. They cause secondary growth, which increases the thickness or girth of stems and roots in woody plants.', wrong = '{"0": "Apical meristems at the tips cause primary growth, an increase in length.", "2": "Intercalary meristems at the bases of internodes help produce leaves and flowers, not girth.", "3": "Root hairs absorb water and minerals. They are not meristems."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1240' AND answer = 1;
UPDATE questions SET why = 'Cork cambium is a lateral meristem formed in the outer layer of stems and roots. It divides to produce cork cells. These cork cells replace the epidermis as the stem thickens and form the outer protective bark.', wrong = '{"1": "Secondary xylem is produced by the vascular cambium on its inner side.", "2": "Secondary phloem is produced by the vascular cambium on its outer side.", "3": "Root hairs are outgrowths of root epidermal cells, not products of cork cambium."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1241' AND answer = 0;
UPDATE questions SET why = 'The zone of cell division lies at the very tip of the root apical meristem. Its cells keep dividing, so they are small and non-vacuolated, with spherical nuclei in the centre of the cytoplasm. They have not yet started to enlarge.', wrong = '{"0": "Large, vacuolated cells with nuclei at the edges are found in the zone of elongation.", "1": "Fully differentiated cells are found in the zone of differentiation, further from the tip.", "2": "Meristem cells are living and actively dividing, not dead and lignified."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1242' AND answer = 3;
UPDATE questions SET why = 'In the zone of elongation, new cells grow mainly by taking up water. The plasticity of the cell wall increases and wall pressure falls, so the wall can stretch. The cells become large and vacuolated, reaching their final size.', wrong = '{"0": "Rapid division happens in the zone of cell division, at the tip. Elongating cells enlarge rather than divide.", "1": "Walls thicken and may be lignified during differentiation, after elongation has stopped.", "3": "Elongating cells keep their nuclei, which move to the edges of the cytoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1243' AND answer = 2;
UPDATE questions SET why = 'The vascular cambium lies between xylem and phloem and divides on both sides. Cells cut off on its inner side become secondary xylem, while cells cut off on its outer side become secondary phloem. Secondary xylem builds up to form the wood.', wrong = '{"0": "Cells made on the outer side of the vascular cambium become secondary phloem, not xylem.", "2": "The vascular cambium acts in stems and roots, where it causes secondary growth, not in leaves.", "3": "Cork cells are made by the cork cambium. They do not give rise to xylem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1244' AND answer = 1;
UPDATE questions SET why = 'In a mature woody stem, bark is everything outside the vascular cambium. It includes the secondary phloem, the cork cambium and the cork. The wood, made of secondary xylem, lies inside the vascular cambium.', wrong = '{"1": "Cork is only the outermost part of the bark. Bark also includes secondary phloem and cork cambium.", "2": "Secondary xylem and pith lie inside the vascular cambium. They form the wood and centre, not the bark.", "3": "In a mature woody stem the epidermis has been replaced by cork, so it is not the bark."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1245' AND answer = 0;
UPDATE questions SET why = 'In spring, conditions are favourable and the cambium is highly active. It produces a large amount of xylem with wide vessels, which looks lighter in colour. In autumn its activity slows, producing fewer, narrower, denser elements, which form darker autumn wood.', wrong = '{"0": "The cambium is most active in spring, not inactive.", "1": "Narrow, dense xylem is formed in autumn and makes the darker autumn wood.", "3": "The rings are made of xylem. The cambium forms xylem in spring, not only phloem."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1246' AND answer = 2;
UPDATE questions SET why = 'Dendrochronology is the scientific method of dating and studying tree rings. Since one ring forms each year, counting rings gives a tree''s age, and the width and nature of each ring record the climate and events of that year.', wrong = '{"0": "Dendrology is the study of trees and woody plants in general, not specifically the dating of rings.", "2": "Palynology is the study of pollen grains and spores.", "3": "Phenology is the study of the timing of seasonal events, such as flowering and leaf fall."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1247' AND answer = 1;
UPDATE questions SET why = 'Within one year, the cambium slows gradually, so spring wood merges slowly into autumn wood. After winter, growth restarts suddenly, so the dense autumn wood of one year meets the light spring wood of the next at a sharp line. This abrupt boundary marks each annual ring.', wrong = '{"0": "The change from spring wood to autumn wood within a year is gradual, not abrupt.", "1": "Secondary phloem and cork are in the bark. Annual rings are seen in the wood (xylem).", "2": "Pith and primary xylem are at the centre of the stem and do not form a ring boundary."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1248' AND answer = 3;
UPDATE questions SET why = 'Auxins are plant hormones that are chemically indole acetic acid (IAA) or its variants. They promote cell enlargement behind the shoot apex, cell division in the cambium, root formation in cuttings and apical dominance.', wrong = '{"1": "Gibberellic acid is the chemical found in gibberellins, a different group of plant hormones.", "2": "The plant hormone that is a gas is ethylene, which ripens fruit. Auxin is not a gas.", "3": "Purine-derived hormones are cytokinins, not auxins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1249' AND answer = 0;
UPDATE questions SET why = 'Auxins produced at the shoot tip keep lateral buds from growing, an effect called apical dominance. Auxins also promote fruit growth, may cause parthenocarpy, delay leaf aging in a few species and inhibit abscission, the falling of leaves and fruits.', wrong = '{"1": "Abscisic acid promotes abscission and dormancy. It does not inhibit leaf fall.", "2": "Ethylene promotes fruit ripening and flowering in pineapple. It is not linked with apical dominance.", "3": "Cytokinins promote lateral bud growth, the opposite of apical dominance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1250' AND answer = 0;
UPDATE questions SET why = 'Some plants grow as a rosette, a flat circle of leaves with a very short stem. Gibberellins promote bolting, the sudden lengthening of the stem before flowering in such plants. They also break bud and seed dormancy.', wrong = '{"0": "Abscisic acid inhibits stem growth and promotes dormancy, so it does not cause bolting.", "1": "Cytokinins promote cell division and lateral bud growth, not bolting.", "3": "Ethylene inhibits stem growth, especially under stress."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1251' AND answer = 2;
UPDATE questions SET why = 'Gibberellins can sometimes substitute for red light. As a result they promote flowering in long-day plants and inhibit it in short-day plants. Abscisic acid has the opposite effect on flowering.', wrong = '{"0": "Abscisic acid has the opposite effect: it promotes flowering in short-day plants and inhibits it in long-day plants.", "1": "Auxin is not described as replacing red light or promoting flowering in long-day plants.", "2": "Ethylene promotes flowering in pineapple, but it is not said to substitute for red light."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1252' AND answer = 3;
UPDATE questions SET why = 'Cytokinins get their name because they promote cytokinesis, the division of the cytoplasm during cell division. They also increase the rate of DNA replication and of RNA and protein synthesis. They are made mainly in roots, young fruits and seeds.', wrong = '{"0": "Closing stomata under water stress is a role of abscisic acid. Cytokinins promote stomatal opening.", "2": "Fruit ripening is promoted by ethylene, not cytokinins.", "3": "Cytokinins promote cell division, not inhibit it, which is how they got their name."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1253' AND answer = 1;
UPDATE questions SET why = 'Cytokinins promote the growth of lateral buds and break bud dormancy, working against the apical dominance caused by auxin. They also delay leaf aging and promote the opening of stomata.', wrong = '{"0": "Auxin causes apical dominance, which suppresses lateral bud growth.", "1": "Abscisic acid closes stomata under water stress and promotes bud dormancy.", "2": "Ethylene is linked with fruit ripening and inhibiting growth, not stomatal opening."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1254' AND answer = 3;
UPDATE questions SET why = 'Abscisic acid (ABA) is made mainly in mature leaves, fruits and root caps. It promotes bud and seed dormancy, promotes abscission, and closes stomata during water stress. In general it slows growth when conditions are hard.', wrong = '{"1": "Gibberellins break bud and seed dormancy, the opposite of promoting it.", "2": "Cytokinins break bud dormancy and promote lateral bud growth.", "3": "Auxins are not described as promoting dormancy. They promote cell enlargement and apical dominance."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1255' AND answer = 0;
UPDATE questions SET why = 'Ethylene is a gaseous hormone produced by plant metabolism. It promotes fruit ripening and flowering in pineapple, and breaks bud dormancy. It also inhibits stem growth, especially under stress, and inhibits root growth.', wrong = '{"0": "Ethylene inhibits stem growth during physiological stress, it does not promote it.", "2": "Seed dormancy is promoted by abscisic acid, not ethylene.", "3": "Ethylene inhibits root growth, it does not promote it."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1256' AND answer = 1;
UPDATE questions SET why = 'A hypertonic solution has a higher solute concentration than the cell''s contents. Water therefore moves out of the cell by osmosis. The protoplast shrinks and pulls away from the cell wall, a condition called plasmolysis.', wrong = '{"0": "Gaining water and swelling happens in a hypotonic solution, which is more dilute than the cell.", "1": "No net water movement happens in an isotonic solution, which matches the cell''s concentration.", "3": "A plant cell loses water in a hypertonic solution. Even in a hypotonic one, its wall stops it from bursting."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1257' AND answer = 2;
UPDATE questions SET why = 'Many marine organisms have cells with the same osmotic pressure as sea water, so they are isotonic with their surroundings. Water enters and leaves equally, so there is no net osmotic movement and they need no special osmoregulation.', wrong = '{"1": "Sea water is not hypotonic to them. Their cells are isotonic with it.", "2": "All living cells have cell membranes. Their lack of osmoregulation is due to being isotonic.", "3": "Drinking fresh water is not the reason given. They are already in osmotic balance with sea water."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1258' AND answer = 0;
UPDATE questions SET why = 'Sea water is hypertonic, so water tends to leave the cells of marine plants. These plants excrete extra salt through salt glands and make organic solutes such as proline, glycine betaine and sugars. These solutes lower their internal water potential so they keep water. Thick cuticles also cut water loss.', wrong = '{"0": "Thin or absent cuticles are a feature of freshwater hydrophytes. Marine hydrophytes have thick cuticles.", "1": "Expelling water through hydathodes is how freshwater plants get rid of extra water.", "2": "In hypertonic water, water tends to leave the plant, so it cannot simply absorb more through its leaves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1259' AND answer = 3;
UPDATE questions SET why = 'Fresh water is hypotonic to the cells of water plants, so water keeps entering them by osmosis. Freshwater hydrophytes avoid overhydration by expelling excess water through structures such as hydathodes, or through vacuoles. They also actively absorb ions such as K⁺ and Ca²⁺.', wrong = '{"0": "Making proline to hold water is an adaptation of marine hydrophytes living in hypertonic sea water.", "2": "Freshwater hydrophytes have thin or absent cuticles. Thick cuticles reduce water loss in marine plants and xerophytes.", "3": "Storing water in fleshy stems is how succulent xerophytes survive dry conditions."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1260' AND answer = 1;
UPDATE questions SET why = 'Xerophytes are plants adapted to dry conditions. Some of them store water in fleshy stems and use it when needed. Plants that store water like this are called succulents, for example many cacti.', wrong = '{"0": "Mesophytes live in moderate conditions and need no special water-storing adaptations.", "1": "Hydrophytes live in water, so they do not need to store water in fleshy stems.", "3": "Epiphytes are plants that grow on other plants for support. The term does not mean water storage."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1261' AND answer = 2;
UPDATE questions SET why = 'Mesophytes live in moderate environments that are neither too dry nor too wet, with moderate salt and humidity. They have well-developed roots, shoots and vascular tissue and flat, broad leaves. Rose, tomato and daisy are examples.', wrong = '{"0": "Blue agave is a xerophyte, adapted to dry conditions.", "1": "Water lily is a freshwater hydrophyte that floats on water.", "3": "Sea lavender is a halophyte, growing in salty soil."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1262' AND answer = 2;
UPDATE questions SET why = 'Halophytes live in saline soil or water with high concentrations of salts such as NaCl, MgCl₂ and MgSO₄. They often have succulent leaves, and sometimes succulent stems or spines. Sea arrowgrass and sea lavender are examples, and mangroves are halophytes of seashore marshes.', wrong = '{"0": "Plants of fresh water are hydrophytes, such as water lily and lotus.", "2": "Plants of moderate habitats are mesophytes, such as rose and tomato.", "3": "Plants that trap insects are insectivorous plants, such as the pitcher plant and sundew."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1263' AND answer = 1;
UPDATE questions SET why = 'High temperature can denature enzymes and upset metabolism. Under heat stress, plant cells make large amounts of heat-shock proteins. These proteins wrap around enzymes and other proteins and help prevent them from being denatured.', wrong = '{"0": "Raising unsaturated fatty acids in membranes is a response to cold, not heat.", "1": "Abscisic acid closes stomata under water stress. It does not protect enzymes from heat.", "2": "Phytochrome is a light receptor involved in photoperiodism, not a heat-protection protein."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1264' AND answer = 3;
UPDATE questions SET why = 'At low temperature, membrane lipids tend to lock into crystal-like structures, which reduces membrane fluidity and disturbs transport. Plants respond by increasing the proportion of unsaturated fatty acids, whose bent chains resist crystal formation and keep membranes fluid.', wrong = '{"1": "Saturated fatty acids have straight chains that pack and crystallise easily, so more of them would make cold damage worse.", "2": "Heat-shock proteins are made in response to high temperature, not cold.", "3": "Adding lignin to walls is not the cold response described. The change is in membrane lipids."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1265' AND answer = 0;
UPDATE questions SET why = 'Plants protect their membranes from cold by raising the share of unsaturated fatty acids. Changing membrane lipid composition takes time. A gradual drop in temperature gives the plant this time, but rapid chilling does not, so it is more stressful.', wrong = '{"0": "Heat-shock proteins are a response to heat, not to chilling.", "1": "Ice can form in cell walls during freezing. That is not why rapid chilling is worse.", "2": "Stomatal closing speed is not the reason given. The issue is the time needed to adjust membranes."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1266' AND answer = 3;
UPDATE questions SET why = 'At freezing temperatures ice crystals form. If ice stays confined around the cell walls, the plant usually survives. But ice crystals forming within the protoplasm pierce membranes and organelles, and this kills the cells.', wrong = '{"0": "Ice confined around cell walls does less harm, and many plants survive it.", "2": "Ice in the soil is outside the plant''s cells and is not the cause of cell death described.", "3": "Frost on the leaf surface is outside the cells. Damage comes from ice inside the protoplasm."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1267' AND answer = 1;
UPDATE questions SET why = 'Roots grow downward, towards gravity, which is positive geotropism. They also grow away from light, which is negative phototropism. Shoots do the opposite, growing up against gravity and towards light.', wrong = '{"0": "Negative geotropism with positive phototropism is the pattern of shoots, not roots.", "1": "Roots grow towards gravity, but they grow away from light, not towards it.", "3": "Roots clearly show tropisms, responding to both gravity and light."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1268' AND answer = 2;
UPDATE questions SET why = 'Thigmotropism is a growth movement in response to touch. When a tendril of a climbing vine touches a support, growth increases on the side opposite the contact. The faster-growing outer side makes the tendril curl and coil around the support.', wrong = '{"1": "Chemotropism is growth in response to chemicals, as shown by fungal hyphae.", "2": "Geotropism is growth in response to gravity, as in roots growing downward.", "3": "Phototropism is growth in response to light, as in shoots bending towards a window."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1269' AND answer = 0;
UPDATE questions SET why = 'Chemotropism is a growth movement of a plant part, or of a fungus, in response to chemicals. Fungal hyphae are chemotropic: they grow towards certain chemicals, which helps them reach and spread through their food sources.', wrong = '{"0": "Thigmotropism is a response to touch, as in tendrils coiling around a support.", "2": "Phototropism is a response to light, as in shoots growing towards light.", "3": "Photoperiodism is the flowering response to the length of day and night, not a growth movement towards chemicals."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1270' AND answer = 1;
UPDATE questions SET why = 'In 1920 Garner and Allard first studied photoperiodism. They found that the tobacco plant flowers only after exposure to a series of short days. It normally flowers in autumn, but flowering could be induced at other times by giving it short days artificially.', wrong = '{"0": "Spirogyra was used by Engelmann in 1883 to make the first action spectrum.", "1": "Pineapple is mentioned because ethylene promotes its flowering, not in Garner and Allard''s work.", "3": "Henbane is given as an example of a long-day plant, not the plant Garner and Allard first studied."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1271' AND answer = 2;
UPDATE questions SET why = 'Later studies showed that the length of the dark period, not the day, is critical. If short-day plants get short days but their long night is broken by a brief flash of light, they do not flower. So they really need an unbroken long night, and are better called long-night plants.', wrong = '{"1": "They do not flower in total darkness. They need light for photosynthesis and a cycle of day and night.", "2": "They are very sensitive to light, since a short light break in the night stops their flowering.", "3": "The light-break experiments show that the length of the night, not the day, controls their flowering."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1272' AND answer = 0;
UPDATE questions SET why = 'Phytochrome is a photoreceptor protein with two forms. The inactive form, P660, absorbs red light at 660 nm and is converted to the active form, P730. P730 absorbs far-red light at 730 nm and returns to P660. In nature P660 becomes P730 by day, and P730 reverts in the dark.', wrong = '{"0": "730 nm far-red light is absorbed by the active form, P730, which is then converted back to the inactive form.", "1": "430 nm is the blue absorption peak of chlorophyll. Phytochrome is not destroyed by it.", "2": "P680 is the reaction centre of photosystem II, which splits water. It is not phytochrome."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1273' AND answer = 3;
UPDATE questions SET why = 'Red light converts phytochrome to its active form, P730. Red light given during the night inhibits flowering in short-day plants but promotes it in long-day plants. This is like breaking the long night with light, which short-day plants cannot tolerate.', wrong = '{"1": "Red light at night inhibits flowering in short-day plants, it does not promote it.", "2": "Red light at night promotes flowering in long-day plants, it does not inhibit it.", "3": "Red light has a clear effect: it acts through phytochrome and changes flowering."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1274' AND answer = 0;
UPDATE questions SET why = 'Leaves detect the photoperiod. Once the biological clock is stimulated, the leaves produce the flowering hormone florigen. Florigen travels through the phloem to the floral buds, where it starts flowering.', wrong = '{"0": "Florigen is made in the leaves, which sense day length, and it travels in phloem, not xylem.", "1": "Floral buds receive florigen. They do not make it.", "2": "The shoot apex or seed embryo receives the cold stimulus in vernalisation. Florigen comes from leaves."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1275' AND answer = 3;
UPDATE questions SET why = 'Day-neutral plants flower regardless of the length of day or night. Examples are cucumber, tomato, garden pea, maize and cotton. They flower once they reach a certain stage of growth.', wrong = '{"0": "Cocklebur is a short-day plant, with a critical night length of about 8.5 hours.", "2": "Henbane is a long-day plant, flowering when nights are shorter than about 13 hours.", "3": "Chrysanthemum is a short-day plant that flowers as nights lengthen in autumn."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1276' AND answer = 1;
UPDATE questions SET why = 'Long-day plants flower when the dark period is shorter than a critical length. Henbane (Hyoscyamus niger) has a critical night length of about 13 hours and flowers only when nights are shorter than this. So it is a long-day plant.', wrong = '{"0": "Short-day plants need nights longer than a critical length, such as cocklebur, tobacco and chrysanthemum.", "1": "Day-neutral plants, such as cucumber and tomato, flower regardless of photoperiod.", "3": "Every green plant needs light. Henbane needs long days, meaning short nights, to flower."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1277' AND answer = 2;
UPDATE questions SET why = 'Vernalisation is the stimulation of flowering by a period of low temperature. The cold stimulus is received by the shoot apex of a mature stem or by the embryo of a seed. In photoperiodism, by contrast, the stimulus is received by the leaves.', wrong = '{"0": "Leaves receive the day-length stimulus in photoperiodism, not the cold stimulus of vernalisation.", "1": "Roots are not the site that receives the cold stimulus.", "3": "Flowers are produced after vernalisation, so they cannot receive the stimulus."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1278' AND answer = 2;
UPDATE questions SET why = 'Vernalisation needs a period of chilling, lasting from about four days to three months depending on the plant. A temperature of about 4 °C is very effective. The cold is thought to stimulate production of a hormone called vernalin, which induces flowering.', wrong = '{"0": "−20 °C is well below freezing. Ice crystals would form in the cells and could kill them.", "2": "28 °C is warm. It is the temperature above which photorespiration becomes a severe problem.", "3": "40 °C is a heat-stress temperature that triggers heat-shock proteins."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1279' AND answer = 1;
UPDATE questions SET why = 'Photoperiodism and vernalisation tie flowering to seasonal signals such as day length and winter cold. So all members of a species in an area flower at about the same time. Flowering together allows pollen to pass between plants, encouraging cross-pollination and genetic variation.', wrong = '{"1": "They regulate the timing of flowering. They do not stop it.", "2": "They encourage cross-pollination between plants, not self-pollination.", "3": "They synchronise flowering. If every plant flowered at a different time, cross-pollination would be harder."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1280' AND answer = 0;
UPDATE questions SET why = 'The digestive system has two parts. The GI tract is a continuous tube from mouth to anus: oral cavity, pharynx, oesophagus, stomach, small intestine and large intestine. The accessory organs, the salivary glands, liver, gallbladder and pancreas, lie outside the tube and pour secretions into it.', wrong = '{"0": "The pharynx is part of the GI tract, lying between the oral cavity and the oesophagus.", "2": "The oesophagus is part of the GI tract, carrying food from the pharynx to the stomach.", "3": "The duodenum is the first part of the small intestine, so it belongs to the GI tract."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1281' AND answer = 1;
UPDATE questions SET why = 'The lips are made of highly vascularised skeletal muscle tissue with many sensory nerve endings. Being skeletal muscle, they can be moved voluntarily, which lets them hold food in the mouth during chewing and shape sounds during speech (phonation).', wrong = '{"1": "The lips are skeletal muscle under voluntary control, with many sensory nerve endings.", "2": "The lips contain no cartilage. Their bulk is skeletal muscle.", "3": "Cardiac muscle is found only in the wall of the heart."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1282' AND answer = 0;
UPDATE questions SET why = 'Mastication, or chewing, is the mechanical digestion of food by the teeth in the mouth. It breaks food into smaller, more manageable pieces. This increases the surface area on which digestive enzymes can act.', wrong = '{"0": "Peristalsis is the wave of muscle contraction that pushes food along the GI tract.", "1": "Emulsification is the breaking of fats into small droplets by bile salts in the small intestine.", "2": "Segmentation is a mixing movement of the intestine that churns food with digestive juices."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1283' AND answer = 3;
UPDATE questions SET why = 'There are three pairs of salivary glands. The sublingual glands lie below the tongue, the submaxillary glands behind the jaws, and the parotid glands in front of the ears. All pour saliva into the oral cavity.', wrong = '{"0": "The glands below the tongue are the sublingual glands.", "1": "The glands behind the jaws are the submaxillary glands.", "3": "None of the three pairs of salivary glands is in the wall of the pharynx."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1284' AND answer = 2;
